# --- JWT ---
def _carregar_ou_gerar_jwt_secret() -> str:
    secret_file = os.path.join(PASTA_INFO, "jwt_secret.key")
    if os.path.exists(secret_file):
        with open(secret_file, "r") as f:
            s = f.read().strip()
        if s:
            return s
    s = secrets.token_hex(64)
    with open(secret_file, "w") as f:
        f.write(s)
    return s

JWT_SECRET = _carregar_ou_gerar_jwt_secret()
JWT_ALGORITHM = "HS256"
JWT_EXPIRE_HOURS = 8

def criar_access_token(username: str, client_id: str) -> str:
    expire = datetime.utcnow() + timedelta(hours=JWT_EXPIRE_HOURS)
    payload = {"sub": username, "client_id": client_id, "exp": expire}
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGORITHM)

