def _favoritos_ranking_extrair_campos_tecnicos(*textos: str) -> dict:
    texto = _favoritos_ranking_texto_norm(*textos)
    marcas = sorted({marca for marca in FAVORITOS_RANKING_MARCAS if re.search(rf"\b{re.escape(marca)}\b", texto)})
    if "GM" in marcas and "CHEVROLET" not in marcas:
        marcas.append("CHEVROLET")
    if "VW" in marcas and "VOLKSWAGEN" not in marcas:
        marcas.append("VOLKSWAGEN")

    modelos = sorted({modelo for modelo in FAVORITOS_RANKING_MODELOS if re.search(rf"\b{re.escape(modelo)}\b", texto)})

    pecas = []
    for chave, padroes in FAVORITOS_RANKING_PECAS.items():
        if any(padrao in texto for padrao in padroes):
            pecas.append(chave)

    posicoes = {}
    if re.search(r"\b(DIREITO|DIREITA|LD|LADO DIREITO)\b", texto):
        posicoes["lado"] = "DIREITO"
    if re.search(r"\b(ESQUERDO|ESQUERDA|LE|LADO ESQUERDO)\b", texto):
        posicoes["lado"] = "ESQUERDO" if "lado" not in posicoes else "AMBOS"
    if re.search(r"\b(DIANTEIRO|DIANTEIRA|FRENTE|FRONTAL)\b", texto):
        posicoes["eixo"] = "DIANTEIRO"
    if re.search(r"\b(TRASEIRO|TRASEIRA)\b", texto):
        posicoes["eixo"] = "TRASEIRO" if "eixo" not in posicoes else "AMBOS"
    if re.search(r"\b(SUPERIOR|CIMA)\b", texto):
        posicoes["altura"] = "SUPERIOR"
    if re.search(r"\b(INFERIOR|BAIXO)\b", texto):
        posicoes["altura"] = "INFERIOR" if "altura" not in posicoes else "AMBOS"

    return {
        "codigos": _favoritos_ranking_extrair_codigos(*textos),
        "anos": _favoritos_ranking_extrair_anos(*textos),
        "marcas": sorted(set(marcas)),
        "modelos": modelos,
        "pecas": sorted(set(pecas)),
        "posicoes": posicoes,
    }


def _favoritos_ranking_assinatura_decisao(sku: str, base: dict, anuncio: dict) -> str:
    payload = {
        "versao": FAVORITOS_RANKING_DECISAO_VERSAO,
        "sku": str(sku or "").strip(),
        "base_titulo": str(base.get("titulo_sku") or base.get("produto_cadastro") or "")[:700],
        "base_descricao": str(base.get("descricao_sku") or base.get("descricao_cadastro") or "")[:1600],
        "id": str(anuncio.get("id") or ""),
        "titulo": str(anuncio.get("titulo") or "")[:400],
        "descricao": str(anuncio.get("descricao") or "")[:1600],
    }
    bruto = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return hashlib.sha256(bruto.encode("utf-8", errors="ignore")).hexdigest()


def _favoritos_ranking_decisao_cache_valida(item: dict, assinatura: str) -> bool:
    if not isinstance(item, dict):
        return False
    if item.get("versao") != FAVORITOS_RANKING_DECISAO_VERSAO:
        return False
    if str(item.get("assinatura") or "") != assinatura:
        return False
    decisao = str(item.get("decisao") or "").lower()
    return decisao in {"manter", "remover"}


def _favoritos_ranking_preavaliar(base_campos: dict, anuncio_campos: dict) -> dict:
    base_codigos = set(base_campos.get("codigos") or [])
    anuncio_codigos = set(anuncio_campos.get("codigos") or [])
    codigos_iguais = sorted(base_codigos & anuncio_codigos)
    if codigos_iguais:
        return {
            "decisao": "manter",
            "motivo": "codigo de peca coincidente",
            "confianca": 100,
            "codigos": codigos_iguais[:5],
        }

    motivos = []

    base_pecas = set(base_campos.get("pecas") or [])
    anuncio_pecas = set(anuncio_campos.get("pecas") or [])
    if base_pecas and anuncio_pecas and not (base_pecas & anuncio_pecas):
        motivos.append("tipo de peca diferente")

    base_marcas = set(base_campos.get("marcas") or [])
    anuncio_marcas = set(anuncio_campos.get("marcas") or [])
    if base_marcas and anuncio_marcas and not (base_marcas & anuncio_marcas):
        motivos.append("marca de veiculo diferente")

    base_modelos = set(base_campos.get("modelos") or [])
    anuncio_modelos = set(anuncio_campos.get("modelos") or [])
    if base_modelos and anuncio_modelos and not (base_modelos & anuncio_modelos):
        motivos.append("modelo de veiculo diferente")

    base_anos = set(base_campos.get("anos") or [])
    anuncio_anos = set(anuncio_campos.get("anos") or [])
    if base_anos and anuncio_anos and not (base_anos & anuncio_anos):
        motivos.append("intervalo de ano diferente")

    base_pos = base_campos.get("posicoes") or {}
    anuncio_pos = anuncio_campos.get("posicoes") or {}
    for grupo, valor_base in base_pos.items():
        valor_anuncio = anuncio_pos.get(grupo)
        if valor_base and valor_anuncio and "AMBOS" not in {valor_base, valor_anuncio} and valor_base != valor_anuncio:
            motivos.append(f"posicao diferente ({grupo})")

    if motivos:
        conflitos_fortes = [
            motivo for motivo in motivos
            if motivo.startswith("posicao diferente")
        ]
        if conflitos_fortes:
            return {
                "decisao": "remover",
                "motivo": "; ".join(conflitos_fortes[:3]),
                "confianca": 95,
            }
        return {
            "decisao": "ia",
            "motivo": "possivel diferenca de aplicacao; validar com IA",
            "confianca": 0,
            "alertas": motivos[:4],
        }

    return {"decisao": "ia", "motivo": "sem conflito deterministico", "confianca": 0}


FAVORITOS_BUSCA_CACHE_LOCK = threading.Lock()


def _favoritos_busca_externa_limpar_texto(valor: object, limite: int = 360) -> str:
    texto = re.sub(r"\s+", " ", str(valor or "")).strip()
    if len(texto) > limite:
        return texto[:limite].rstrip() + "..."
    return texto


def _favoritos_busca_externa_cache_path(client_id: str, sku: str) -> str:
    sku_norm = _normalizar_sku_match_favoritos(str(sku or "")).strip() or "sku"
    nome_seguro = re.sub(r"[^A-Za-z0-9_-]+", "_", sku_norm).strip("_")[:80] or "sku"
    digest = hashlib.sha1(sku_norm.encode("utf-8", errors="ignore")).hexdigest()[:10]
    pasta = os.path.join(get_tenant_path(client_id), "favoritos_busca_cache")
    os.makedirs(pasta, exist_ok=True)
    return os.path.join(pasta, f"{nome_seguro}_{digest}.json")


def _favoritos_busca_externa_ler_cache(client_id: str, sku: str) -> dict:
    caminho = _favoritos_busca_externa_cache_path(client_id, sku)
    if not os.path.exists(caminho):
        return {"sku": str(sku or "").strip(), "consultas": {}}
    try:
        with open(caminho, "r", encoding="utf-8") as f:
            dados = json.load(f) or {}
        if not isinstance(dados, dict):
            return {"sku": str(sku or "").strip(), "consultas": {}}
        if not isinstance(dados.get("consultas"), dict):
            dados["consultas"] = {}
        return dados
    except Exception:
        return {"sku": str(sku or "").strip(), "consultas": {}}


def _favoritos_busca_externa_salvar_cache(client_id: str, sku: str, dados: dict) -> None:
    caminho = _favoritos_busca_externa_cache_path(client_id, sku)
    tmp = caminho + ".tmp"
    dados = dados if isinstance(dados, dict) else {}
    dados["sku"] = str(sku or "").strip()
    dados["updated_at"] = datetime.now().isoformat(timespec="seconds")
    dados.setdefault("consultas", {})
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(dados, f, ensure_ascii=False, indent=2)
    os.replace(tmp, caminho)


def _favoritos_busca_externa_cache_key(query: str) -> str:
    normalizada = re.sub(r"\s+", " ", str(query or "").strip().lower())
    return hashlib.sha256(normalizada.encode("utf-8", errors="ignore")).hexdigest()


def _favoritos_busca_externa_cache_valido(item: dict) -> bool:
    if not isinstance(item, dict):
        return False
    ttl_dias = int(os.getenv("FAVORITOS_BUSCA_EXTERNA_CACHE_TTL_DIAS", "30") or "30")
    criado = str(item.get("created_at") or "").strip()
    if not criado:
        return False
    try:
        criado_dt = datetime.fromisoformat(criado)
    except Exception:
        return False
    return datetime.now() - criado_dt <= timedelta(days=max(1, ttl_dias))


def _favoritos_busca_externa_normalizar_resultados(resultados: list[dict], provider: str, query: str, max_results: int) -> dict:
    itens = []
    for item in resultados or []:
        if not isinstance(item, dict):
            continue
        titulo = _favoritos_busca_externa_limpar_texto(item.get("titulo") or item.get("title"), 160)
        url = _favoritos_busca_externa_limpar_texto(item.get("url") or item.get("link"), 260)
        trecho = _favoritos_busca_externa_limpar_texto(
            item.get("trecho") or item.get("snippet") or item.get("description") or item.get("content"),
            360,
        )
        if not (titulo or trecho or url):
            continue
        itens.append({"titulo": titulo, "url": url, "trecho": trecho})
        if len(itens) >= max_results:
            break
    return {
        "provider": provider,
        "query": query,
        "created_at": datetime.now().isoformat(timespec="seconds"),
        "resultados": itens,
    }


def _favoritos_busca_externa_chamar_api(query: str, max_results: int = 4) -> dict:
    query = re.sub(r"\s+", " ", str(query or "").strip())
    if not query:
        return _favoritos_busca_externa_normalizar_resultados([], "none", query, max_results)

    tavily_key = os.getenv("TAVILY_API_KEY", "").strip()
    if tavily_key:
        resp = requests.post(
            "https://api.tavily.com/search",
            headers={"Content-Type": "application/json"},
            json={
                "api_key": tavily_key,
                "query": query,
                "search_depth": "basic",
                "max_results": max_results,
                "include_answer": False,
            },
            timeout=18,
            verify=False,
        )
        resp.raise_for_status()
        data = resp.json() or {}
        return _favoritos_busca_externa_normalizar_resultados(data.get("results") or [], "tavily", query, max_results)

    brave_key = os.getenv("BRAVE_SEARCH_API_KEY", "").strip()
    if brave_key:
        resp = requests.get(
            "https://api.search.brave.com/res/v1/web/search",
            headers={"Accept": "application/json", "X-Subscription-Token": brave_key},
            params={"q": query, "count": max_results, "country": "br", "search_lang": "pt-br"},
            timeout=18,
            verify=False,
        )
        resp.raise_for_status()
        data = resp.json() or {}
        return _favoritos_busca_externa_normalizar_resultados(
            (data.get("web") or {}).get("results") or [],
            "brave",
            query,
            max_results,
        )

    serpapi_key = os.getenv("SERPAPI_KEY", "").strip()
    if serpapi_key:
        resp = requests.get(
            "https://serpapi.com/search.json",
            params={"engine": "google", "q": query, "hl": "pt-br", "gl": "br", "num": max_results, "api_key": serpapi_key},
            timeout=18,
            verify=False,
        )
        resp.raise_for_status()
        data = resp.json() or {}
        return _favoritos_busca_externa_normalizar_resultados(data.get("organic_results") or [], "serpapi", query, max_results)

    resp = requests.get(
        "https://duckduckgo.com/html/",
        params={"q": query},
        headers={"User-Agent": "Mozilla/5.0 JK-Sistema/1.0"},
        timeout=18,
        verify=False,
    )
    resp.raise_for_status()
    soup = BeautifulSoup(resp.text or "", "lxml")
    resultados = []
    for node in soup.select(".result"):
        link = node.select_one(".result__a")
        snippet = node.select_one(".result__snippet")
        if not link:
            continue
        href = link.get("href") or ""
        if "duckduckgo.com/y.js" in href or "ad_domain=" in href:
            continue
        resultados.append({
            "titulo": link.get_text(" ", strip=True),
            "url": href,
            "trecho": snippet.get_text(" ", strip=True) if snippet else "",
        })
        if len(resultados) >= max_results:
            break
    return _favoritos_busca_externa_normalizar_resultados(resultados, "duckduckgo_html", query, max_results)


def _favoritos_busca_externa_cached(client_id: str, sku: str, query: str, max_results: int = 4) -> dict:
    query = re.sub(r"\s+", " ", str(query or "").strip())
    if not query:
        return {}
    chave = _favoritos_busca_externa_cache_key(query)
    with FAVORITOS_BUSCA_CACHE_LOCK:
        cache = _favoritos_busca_externa_ler_cache(client_id, sku)
        item_cache = (cache.get("consultas") or {}).get(chave)
        if item_cache and _favoritos_busca_externa_cache_valido(item_cache):
            return item_cache

    try:
        resultado = _favoritos_busca_externa_chamar_api(query, max_results=max_results)
    except Exception as exc:
        logger.warning("[Favoritos IA] Falha na busca externa para SKU %s: %s", sku, exc)
        if item_cache:
            return item_cache
        resultado = {
            "provider": "unavailable",
            "query": query,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "resultados": [],
            "erro": str(exc)[:240],
        }

    with FAVORITOS_BUSCA_CACHE_LOCK:
        cache = _favoritos_busca_externa_ler_cache(client_id, sku)
        cache.setdefault("consultas", {})[chave] = resultado
        _favoritos_busca_externa_salvar_cache(client_id, sku, cache)
    return resultado


def _favoritos_busca_externa_extrair_codigos(*textos: str) -> list[str]:
    bruto = " ".join(str(item or "") for item in textos)
    candidatos = re.findall(r"\b(?=[A-Z0-9-]*\d)[A-Z0-9]{2,}(?:[-./][A-Z0-9]{2,})+\b|\b(?=[A-Z0-9]*\d)[A-Z]{1,5}[0-9][A-Z0-9]{4,}\b", bruto.upper())
    codigos = []
    for codigo in candidatos:
        codigo = codigo.strip("-./ ")
        if not codigo or re.fullmatch(r"(19|20)\d{2}", codigo):
            continue
        if codigo not in codigos:
            codigos.append(codigo)
        if len(codigos) >= 6:
            break
    return codigos


def _favoritos_busca_externa_query(*partes: str) -> str:
    texto = " ".join(str(parte or "").strip() for parte in partes if str(parte or "").strip())
    texto = re.sub(r"\s+", " ", texto).strip()
    return texto[:220]


def _favoritos_ranking_contexto_busca_externa(
    client_id: str,
    sku: str,
    titulo: str,
    descricao: str,
    pesquisas: list[str],
    anuncios_norm: list[dict],
) -> dict:
    if str(os.getenv("FAVORITOS_EXTERNAL_SEARCH_ENABLED", "1")).strip().lower() in {"0", "false", "no", "nao"}:
        return {}

    sku_norm = _normalizar_sku_match_favoritos(str(sku or "")).strip() or str(sku or "").strip()
    max_ads = int(os.getenv("FAVORITOS_EXTERNAL_SEARCH_MAX_ADS", "12") or "12")
    max_results = int(os.getenv("FAVORITOS_EXTERNAL_SEARCH_RESULTS", "4") or "4")
    max_ads = max(0, min(max_ads, 40))
    max_results = max(1, min(max_results, 8))

    try:
        codigos_base = _favoritos_busca_externa_extrair_codigos(titulo, descricao, " ".join(pesquisas or []))
        query_base = _favoritos_busca_externa_query(
            "autopeca aplicacao veiculo",
            " ".join(codigos_base[:3]),
            titulo,
            (pesquisas or [""])[0] if pesquisas else "",
        )
        contexto = {
            "cache": "info/<cliente>/favoritos_busca_cache por SKU",
            "produto_cadastro": [],
            "anuncios": [],
        }
        if query_base:
            base = _favoritos_busca_externa_cached(client_id, sku_norm, query_base, max_results=max_results)
            if base.get("resultados"):
                contexto["produto_cadastro"].append(base)

        consultas_vistas = {query_base.lower()} if query_base else set()
        for anuncio in anuncios_norm[:max_ads]:
            codigos = _favoritos_busca_externa_extrair_codigos(anuncio.get("titulo"), anuncio.get("descricao"))
            query = _favoritos_busca_externa_query(
                "autopeca aplicacao veiculo",
                " ".join(codigos[:3]),
                anuncio.get("titulo") or "",
            )
            chave_query = query.lower()
            if not query or chave_query in consultas_vistas:
                continue
            consultas_vistas.add(chave_query)
            resultado = _favoritos_busca_externa_cached(client_id, sku_norm, query, max_results=max_results)
            if resultado.get("resultados"):
                contexto["anuncios"].append({
                    "id": anuncio.get("id"),
                    "query": query,
                    "provider": resultado.get("provider"),
                    "resultados": resultado.get("resultados") or [],
                })

        if not contexto["produto_cadastro"] and not contexto["anuncios"]:
            return {}
        return contexto
    except Exception as exc:
        logger.warning("[Favoritos IA] Falha ao montar contexto de busca externa do SKU %s: %s", sku, exc)
        return {}


def _favoritos_ranking_json_obj(texto: str) -> dict:
    limpo = str(texto or "").strip()
    if not limpo:
        return {}
    limpo = re.sub(r"^```(?:json)?\s*", "", limpo, flags=re.IGNORECASE).strip()
    limpo = re.sub(r"\s*```$", "", limpo, flags=re.IGNORECASE).strip()
    for candidato in (limpo, limpo[limpo.find("{"):limpo.rfind("}") + 1] if "{" in limpo and "}" in limpo else ""):
        candidato = str(candidato or "").strip()
        if not candidato:
            continue
        try:
            data = json.loads(candidato)
        except Exception:
            continue
        return data if isinstance(data, dict) else {}
    return {}


def _favoritos_ranking_lista_ids(valor) -> set[str]:
    ids: set[str] = set()
    if not isinstance(valor, list):
        return ids
    for item in valor:
        if isinstance(item, dict):
            bruto = item.get("id") or item.get("mlb") or item.get("item_id") or item.get("anuncio")
        else:
            bruto = item
        item_id = _extrair_item_id(str(bruto or "")) or str(bruto or "").strip().upper().replace("-", "")
        if item_id:
            ids.add(item_id)
    return ids


def _favoritos_ranking_chamar_ia_json(
    client_id: str,
    mensagem: str,
    system_prompt: str,
    model: str | None = None,
) -> dict:
    model_name = _normalizar_ia_modelo_padrao(model or _ia_modelo_favoritos_configurado())
    if _modelo_eh_vertex_ai(model_name):
        model_curto = _vertex_modelo_nome_curto(model_name) or _vertex_ai_modelo_padrao()
        headers, project_id = _vertex_ai_headers_e_project()
        location = _vertex_ai_location()
        host = "aiplatform.googleapis.com" if location == "global" else f"{location}-aiplatform.googleapis.com"
        payload_json = {
            "systemInstruction": {"parts": [{"text": system_prompt}]},
            "contents": [{"role": "user", "parts": [{"text": mensagem}]}],
            "generationConfig": _vertex_generation_config(model_curto, json_mode=True),
        }
        resp = requests.post(
            f"https://{host}/v1/projects/{project_id}/locations/{location}/publishers/google/models/{model_curto}:generateContent",
            headers=headers,
            json=payload_json,
            verify=False,
            timeout=75,
        )
        if not resp.ok and resp.status_code == 400:
            payload_json["generationConfig"].pop("responseMimeType", None)
            resp = requests.post(
                f"https://{host}/v1/projects/{project_id}/locations/{location}/publishers/google/models/{model_curto}:generateContent",
                headers=headers,
                json=payload_json,
                verify=False,
                timeout=75,
            )
        if not resp.ok:
            raise RuntimeError(f"Vertex Gemini HTTP {resp.status_code}: {resp.text[:300]}")
        partes = resp.json().get("candidates", [{}])[0].get("content", {}).get("parts", [])
        texto = "\n".join(str(parte.get("text") or "").strip() for parte in partes if str(parte.get("text") or "").strip())
        return _favoritos_ranking_json_obj(texto)

    resposta = _favoritos_ia_texto_resposta(
        client_id,
        f"{system_prompt}\n\n{mensagem}",
        model=model_name,
    )
    return _favoritos_ranking_json_obj(resposta)


def _favoritos_ranking_filtrar_com_ia(
    client_id: str,
    sku: str,
    titulo: str,
    descricao: str,
    pesquisas: list[str],
    anuncios: list[dict],
    meus_anuncios: list[dict] | None = None,
    max_confirmados: int | None = None,
    usar_imagem: bool | None = None,
    model: str | None = None,
) -> dict:
    anuncios_norm = []
    usar_imagem_comparacao = bool(usar_imagem) or _ia_favoritos_usar_imagem_configurado()
    alvo_confirmados = None
    if max_confirmados is not None:
        try:
            alvo_confirmados = max(1, min(int(max_confirmados), 20))
        except Exception:
            alvo_confirmados = 8

    def _normalizar_anuncio_ia(anuncio: dict) -> dict | None:
        item_id = _favoritos_ranking_anuncio_id(anuncio)
        if not item_id:
            return None
        item_norm = {
            "id": item_id,
            "titulo": str((anuncio or {}).get("titulo") or (anuncio or {}).get("title") or "")[:240],
            "descricao": _favoritos_ranking_descricao_anuncio(anuncio)[:1800],
            "vendedor": str((anuncio or {}).get("vendedor") or "")[:120],
            "loja": str((anuncio or {}).get("loja") or (anuncio or {}).get("loja_sync") or "")[:120],
            "sku": str((anuncio or {}).get("sku") or (anuncio or {}).get("seller_sku") or "")[:120],
        }
        if usar_imagem_comparacao:
            imagem = str(
                (anuncio or {}).get("imagem")
                or (anuncio or {}).get("foto")
                or (anuncio or {}).get("thumbnail")
                or (anuncio or {}).get("thumbnail_url")
                or (anuncio or {}).get("secure_thumbnail")
                or ""
            ).strip()
            if imagem:
                item_norm["imagem"] = imagem[:700]
        return item_norm

    for anuncio in anuncios or []:
        item_norm = _normalizar_anuncio_ia(anuncio)
        if item_norm:
            anuncios_norm.append(item_norm)

    if not anuncios_norm:
        return {"manter_ids": [], "remover_ids": [], "removidos": []}

    _favoritos_ranking_completar_descricoes(anuncios_norm)
    meus_anuncios_norm = [
        item for item in (_normalizar_anuncio_ia(anuncio) for anuncio in (meus_anuncios or []))
        if item
    ][:12]
    if meus_anuncios_norm:
        _favoritos_ranking_completar_descricoes(meus_anuncios_norm)

    system_prompt = (
        "Voce e um especialista em catalogacao de autopecas e inteligencia de mercado automotivo. "
        "Sua tarefa e comparar anuncios de concorrentes com o MEU ANUNCIO e classificar cada item como "
        "mesmo produto, duvidoso ou nao e o mesmo produto. "
        "Quando houver duvida real por falta de dados, nao elimine o anuncio: marque como duvidoso. "
        "Retorne somente JSON valido. "
        "Nao use Markdown, explicacoes ou texto fora do JSON."
    )
    base = {
        "sku": str(sku or "").strip(),
        "titulo_sku": str(titulo or "").strip()[:700],
        "descricao_sku": str(descricao or "").strip()[:2400],
        "produto_cadastro": str(titulo or "").strip()[:700],
        "descricao_cadastro": str(descricao or "").strip()[:2400],
        "pesquisas_usadas": [str(item or "").strip() for item in (pesquisas or []) if str(item or "").strip()][:3],
        "meus_anuncios": meus_anuncios_norm,
        "max_confirmados": alvo_confirmados,
    }
    base_campos = _favoritos_ranking_extrair_campos_tecnicos(
        base["titulo_sku"],
        base["descricao_sku"],
        " ".join(base["pesquisas_usadas"]),
    )
    base["campos_tecnicos_sku"] = base_campos

    with FAVORITOS_RANKING_DECISOES_LOCK:
        decisoes_cache = _favoritos_ranking_ler_decisoes_cache(client_id, sku)
    decisoes_cache_alterado = False
    manter_ids: set[str] = set()
    remover_ids: set[str] = set()
    removidos_map: dict[str, str] = {}
    anuncios_para_ia: list[dict] = []

    def _registrar_remocao(item_id: str, motivo: str) -> None:
        if not item_id:
            return
        remover_ids.add(item_id)
        removidos_map[item_id] = str(motivo or "nao confirmado como mesmo produto").strip()[:180]

    def _registrar_decisao_cache(item: dict, decisao: str, motivo: str, origem: str, confianca: int = 0) -> None:
        nonlocal decisoes_cache_alterado
        item_id = str(item.get("id") or "").strip()
        assinatura = str(item.get("_assinatura_decisao") or "").strip()
        if not item_id or not assinatura:
            return
        decisoes_cache.setdefault("decisoes", {})[item_id] = {
            "versao": FAVORITOS_RANKING_DECISAO_VERSAO,
            "assinatura": assinatura,
            "decisao": decisao,
            "motivo": str(motivo or "").strip()[:180],
            "origem": origem,
            "confianca": int(confianca or 0),
            "campos_sku": base_campos,
            "campos_anuncio": item.get("campos_tecnicos") or {},
            "created_at": datetime.now().isoformat(timespec="seconds"),
        }
        decisoes_cache_alterado = True

    def _atingiu_alvo_confirmados() -> bool:
        return alvo_confirmados is not None and len(manter_ids - remover_ids) >= alvo_confirmados

    for item in anuncios_norm:
        if _atingiu_alvo_confirmados():
            break
        item_id = str(item.get("id") or "").strip()
        item["campos_tecnicos"] = _favoritos_ranking_extrair_campos_tecnicos(
            item.get("titulo"),
            item.get("descricao"),
        )
        item["_assinatura_decisao"] = _favoritos_ranking_assinatura_decisao(sku, base, item)
        item_cache = (decisoes_cache.get("decisoes") or {}).get(item_id)
        if _favoritos_ranking_decisao_cache_valida(item_cache, item["_assinatura_decisao"]):
            decisao_cache = str(item_cache.get("decisao") or "").lower()
            motivo_cache = str(item_cache.get("motivo") or "decisao em cache").strip()
            if decisao_cache == "manter":
                manter_ids.add(item_id)
            else:
                _registrar_remocao(item_id, motivo_cache)
            continue

        pre = _favoritos_ranking_preavaliar(base_campos, item["campos_tecnicos"])
        item["pre_analise"] = pre
        if pre.get("decisao") == "manter":
            manter_ids.add(item_id)
            _registrar_decisao_cache(item, "manter", pre.get("motivo") or "codigo coincidente", "regra", pre.get("confianca") or 100)
            continue
        if pre.get("decisao") == "remover":
            motivo = pre.get("motivo") or "divergencia tecnica objetiva"
            _registrar_remocao(item_id, motivo)
            _registrar_decisao_cache(item, "remover", motivo, "regra", pre.get("confianca") or 95)
            continue

        anuncios_para_ia.append(item)

    contexto_busca_externa = _favoritos_ranking_contexto_busca_externa(
        client_id=client_id,
        sku=sku,
        titulo=titulo,
        descricao=descricao,
        pesquisas=pesquisas or [],
        anuncios_norm=anuncios_para_ia,
    )
    contexto_anuncios_por_id = {
        str(item.get("id") or ""): item
        for item in (contexto_busca_externa.get("anuncios") or [])
        if isinstance(item, dict) and item.get("id")
    } if contexto_busca_externa else {}

    chunk_tamanho = 18
    for inicio in range(0, len(anuncios_para_ia), chunk_tamanho):
        if _atingiu_alvo_confirmados():
            break
        chunk = anuncios_para_ia[inicio:inicio + chunk_tamanho]
        payload = dict(base)
        payload["anuncios"] = [
            {
                "id": item.get("id"),
                "titulo": item.get("titulo"),
                "descricao": item.get("descricao"),
                "vendedor": item.get("vendedor"),
                "campos_tecnicos": item.get("campos_tecnicos") or {},
                "pre_analise": item.get("pre_analise") or {},
                **({"imagem": item.get("imagem")} if usar_imagem_comparacao and item.get("imagem") else {}),
            }
            for item in chunk
        ]
        if contexto_busca_externa:
            payload["contexto_busca_externa"] = {
                "produto_cadastro": contexto_busca_externa.get("produto_cadastro") or [],
                "anuncios": [
                    contexto_anuncios_por_id.get(str(item.get("id") or ""))
                    for item in chunk
                    if contexto_anuncios_por_id.get(str(item.get("id") or ""))
                ],
            }
        mensagem = (
            "Analise e compare cada anuncio concorrente com o MEU ANUNCIO informado em produto_cadastro, "
            "descricao_cadastro, titulo_sku, descricao_sku, sku, pesquisas_usadas e, principalmente, meus_anuncios "
            "quando estiverem presentes. meus_anuncios sao os anuncios da nossa loja para o mesmo SKU; use titulo, "
            "descricao, SKU, loja e imagem deles como referencia principal. Cada item em anuncios contem titulo, "
            "descricao, imagem e posicao do anuncio rankeado quando disponivel. O objetivo e remover somente anuncios "
            "que claramente nao vendem a mesma peca/produto; anuncios compativeis ou duvidosos devem permanecer "
            "para revisao no ranking.\n\n"
            "DIRETRIZES DE COMPARACAO, em ordem de prioridade obrigatoria:\n"
            "1. Codigo do Produto (Part Number / SKU): se o codigo for identico, trate como o mesmo produto. "
            "Tenha atencao a codigos equivalentes de marcas diferentes, por exemplo Bosch vs Magneti Marelli, "
            "e nao considere codigo parecido como identico sem evidencia.\n"
            "2. Modelo da Peca: valide o componente exato. Exemplo: pastilha de freio dianteira nao e a mesma "
            "coisa que pastilha traseira; sensor, valvula, tampa, filtro, bico, junta e suporte nao devem ser "
            "misturados se a peca nao for exatamente a mesma.\n"
            "3. Titulo do Anuncio: analise palavras-chave essenciais e ignore apenas diferencas comerciais "
            "irrelevantes como frete, novo, original, promocao ou envio rapido.\n"
            "4. Aplicacao Veicular: valide marca, modelo, motorizacao e ano. A peca deve servir rigorosamente "
            "para a mesma frota quando essa informacao estiver clara. Se o MEU ANUNCIO serve para Gol 2010 "
            "a 2014 e o concorrente afirma somente Gol 2015 a 2020, remova. Se o concorrente listar apenas "
            "parte da aplicacao, omitir anos/modelos ou usar titulo mais generico, classifique como duvidoso "
            "em vez de remover, a menos que exista conflito objetivo.\n\n"
            + (
                "COMPARACAO POR IMAGEM:\n"
                "Quando o campo imagem estiver presente em meus_anuncios ou anuncios, use a foto como pista auxiliar "
                "para validar formato, componente, lado, kit e aparencia geral. Compare visualmente nossas fotos com "
                "as fotos dos anuncios rankeados quando isso ajudar a diferenciar produtos parecidos. "
                "A imagem nunca deve prevalecer contra codigo, titulo, descricao ou aplicacao veicular objetiva; "
                "ela serve apenas para reduzir duvidas quando os textos forem incompletos.\n\n"
                if usar_imagem_comparacao else ""
            )
            + "RECONHECIMENTO DE DUVIDAS E PESQUISA ATIVA:\n"
            "Quando existir contexto_busca_externa nos dados, use esses resultados de internet como apoio "
            "para pesquisar codigo da peca, modelo e aplicacao veicular antes de decidir. Se as informacoes "
            "do concorrente forem escassas, confusas ou se voce nao tiver certeza sobre a compatibilidade "
            "do codigo da peca, compare os resultados externos com as especificacoes do MEU ANUNCIO. "
            "Se o contexto externo nao estiver disponivel ou nao for conclusivo, seja conservador a favor "
            "de nao perder concorrentes corretos: use duvidoso quando faltar dado, e remova apenas quando "
            "houver divergencia tecnica evidente.\n\n"
            "REGRAS DE DECISAO:\n"
            "- MANTER: somente quando for o mesmo produto/peca, com codigo, modelo ou aplicacao veicular "
            "compativeis de forma clara com o MEU ANUNCIO.\n"
            "- DUVIDOSO: parece a mesma peca ou pode ser a mesma aplicacao, mas o concorrente omite codigo, "
            "anos, modelos, motorizacao ou descricao completa. Tambem use duvidoso quando a diferenca de "
            "ano/modelo puder ser apenas aplicacao parcial da mesma peca.\n"
            "- REMOVER: outra peca, outro lado/posicao, outra medida, outro kit, outro produto, codigo conflitante "
            "ou aplicacao explicitamente incompativel.\n\n"
            "Retorne no formato exato:\n"
            '{"manter":["MLB123"],"duvidosos":["MLB789"],"remover":[{"id":"MLB456","motivo":"produto diferente","confianca":95}]}\n\n'
            "Tudo que estiver em manter ou duvidosos ficara no ranking. Use remover apenas para incompatibilidade clara.\n\n"
            f"Dados:\n{json.dumps(payload, ensure_ascii=False)}"
        )
        data = _favoritos_ranking_chamar_ia_json(client_id, mensagem, system_prompt, model=model)
        ids_chunk = {item["id"] for item in chunk}
        ids_manter = _favoritos_ranking_lista_ids(
            data.get("manter") or data.get("manter_ids") or data.get("ids_manter") or data.get("mantidos")
        )
        ids_duvidosos = _favoritos_ranking_lista_ids(
            data.get("duvidosos") or data.get("duvidoso") or data.get("incertos") or data.get("revisar") or data.get("possiveis")
        )
        ids_remover = _favoritos_ranking_lista_ids(
            data.get("remover") or data.get("remover_ids") or data.get("ids_remover") or data.get("removidos")
        )
        tem_manter = any(chave in data for chave in ("manter", "manter_ids", "ids_manter", "mantidos"))
        tem_duvidosos = any(chave in data for chave in ("duvidosos", "duvidoso", "incertos", "revisar", "possiveis"))
        motivos_ia = {}
        for item in data.get("remover") or data.get("removidos") or []:
            if not isinstance(item, dict):
                continue
            item_id = _extrair_item_id(str(item.get("id") or item.get("mlb") or "")) or str(item.get("id") or "").strip().upper().replace("-", "")
            if item_id:
                motivos_ia[item_id] = str(item.get("motivo") or item.get("reason") or "removido pela IA").strip()[:180]

        if tem_manter or tem_duvidosos:
            ids_rejeitados = (ids_remover & ids_chunk) if ids_remover else set()
            ids_confirmados = ids_chunk - ids_rejeitados
            manter_ids.update(ids_confirmados)
            for item_id in ids_rejeitados:
                _registrar_remocao(item_id, motivos_ia.get(item_id) or "IA nao confirmou como mesmo produto")
        elif ids_remover:
            ids_rejeitados = ids_remover & ids_chunk
            ids_confirmados = ids_chunk - ids_rejeitados
            manter_ids.update(ids_confirmados)
            for item_id in ids_rejeitados:
                _registrar_remocao(item_id, motivos_ia.get(item_id) or "removido pela IA")
        else:
            ids_confirmados = set(ids_chunk)
            ids_rejeitados = set()
            manter_ids.update(ids_confirmados)

        itens_por_id = {str(item.get("id") or ""): item for item in chunk}
        for item_id in ids_confirmados:
            item = itens_por_id.get(item_id)
            if item:
                motivo = "duvidoso mantido pela IA" if item_id in ids_duvidosos else "confirmado pela IA"
                _registrar_decisao_cache(item, "manter", motivo, "ia", 80)
        for item_id in ids_rejeitados:
            item = itens_por_id.get(item_id)
            if item:
                _registrar_decisao_cache(item, "remover", removidos_map.get(item_id) or motivos_ia.get(item_id) or "removido pela IA", "ia", 80)
        if _atingiu_alvo_confirmados():
            break

    if decisoes_cache_alterado:
        with FAVORITOS_RANKING_DECISOES_LOCK:
            _favoritos_ranking_salvar_decisoes_cache(client_id, sku, decisoes_cache)

    removidos = [
        {"id": item_id, "motivo": motivo}
        for item_id, motivo in sorted(removidos_map.items())
    ]

    for item in anuncios_norm:
        item.pop("_assinatura_decisao", None)
        item.pop("campos_tecnicos", None)
        item.pop("pre_analise", None)

    return {
        "manter_ids": sorted(manter_ids - remover_ids),
        "remover_ids": sorted(remover_ids),
        "removidos": removidos,
        "interrompido_apos_confirmados": _atingiu_alvo_confirmados(),
        "confirmados_total": len(manter_ids - remover_ids),
    }


ML_FAVORITOS_STATUS_SKUS = ("active", "paused")


def _ml_favoritos_buscar_itens_por_sku(
    client_id: str,
    nome_loja: str,
    cfg: dict,
    sku_norm: str,
) -> tuple[list[dict], dict]:
    """Busca atÃƒÂ© 2 pÃƒÂ¡ginas do endpoint de itens do seller por seller_sku, com fallback por termo."""
    sku_norm = _normalizar_sku_match_favoritos(sku_norm)
    if not sku_norm:
        return [], cfg

    cfg_local = dict(cfg or {})
    user_id = str(cfg_local.get("user_id") or "").strip()
    if not user_id:
        raise HTTPException(status_code=400, detail="ID do usuÃƒÂ¡rio do Mercado Livre nÃ£o encontrado para esta loja.")

    url = f"https://api.mercadolibre.com/users/{user_id}/items/search"
    itens_por_id: dict[str, dict] = {}
    encontrou_por_seller_sku = False

    def _coletar_ids(resp_json: object, apenas_desta_chamada: bool = False) -> list[str]:
        ids = []
        if not isinstance(resp_json, dict):
            return ids
        for item in resp_json.get("results") or []:
            if isinstance(item, dict):
                item_id = str(item.get("id") or "").strip()
            else:
                item_id = str(item or "").strip()
            if not item_id:
                continue
            if apenas_desta_chamada and item_id in itens_por_id:
                continue
            itens_por_id[item_id] = item if isinstance(item, dict) else {"id": item_id}
            ids.append(item_id)
        return ids

    # 1) Busca direcionada pelo seller_sku (mais precisa)
    for sku_busca in _ml_favoritos_variantes_busca_sku(sku_norm):
        encontrou_nesta_variante = False
        for status_item in ML_FAVORITOS_STATUS_SKUS:
            try:
                resp, cfg_local = _ml_favoritos_api_request(
                    client_id,
                    nome_loja,
                    cfg_local,
                    "GET",
                    url,
                    params={"offset": 0, "limit": 100, "status": status_item, "seller_sku": sku_busca},
                    timeout=15,
                )
            except HTTPException:
                raise
            except Exception as exc:
                logger.warning("[Favoritos] Falha na busca seller_sku=%s loja=%s: %s", sku_busca, nome_loja, exc)
                continue

            if resp.status_code == 200:
                ids_chamada = _coletar_ids(resp.json())
                if ids_chamada:
                    encontrou_por_seller_sku = True
                    encontrou_nesta_variante = True
        if encontrou_nesta_variante:
            break

    # 2) Fallback: varre parte do catÃƒÂ¡logo do usuÃƒÂ¡rio e filtra por SKU quando nÃ£o houver match exato.
    if not itens_por_id:
        for status_item in ML_FAVORITOS_STATUS_SKUS:
            for scan_offset in range(0, 600, 100):
                for sku_busca in _ml_favoritos_variantes_busca_sku(sku_norm):
                    try:
                        resp_scan, cfg_local = _ml_favoritos_api_request(
                            client_id,
                            nome_loja,
                            cfg_local,
                            "GET",
                            url,
                            params={"offset": scan_offset, "limit": 100, "status": status_item, "q": sku_busca},
                            timeout=15,
                        )
                    except Exception:
                        continue
                    if resp_scan.status_code != 200:
                        continue

                    data = resp_scan.json()
                    _coletar_ids(data, apenas_desta_chamada=True)
                    if not isinstance(data, dict) or "paging" not in data:
                        continue
                    paging = data.get("paging") or {}
                    total = int(paging.get("total", 0) or 0)
                    if total and scan_offset + 100 >= total:
                        break

    ids = list(itens_por_id.keys())
    if not ids:
        return [], cfg_local

    itens_detalhados, cfg_local = _ml_favoritos_buscar_itens_batch(client_id, nome_loja, cfg_local, ids)

    # Filtra por correspondÃªncia de SKU para reduzir falsos positivos em busca por termo.
    out = []
    for item in itens_detalhados:
        if not isinstance(item, dict):
            continue
        if _ml_favoritos_item_corresponde_sku(item, sku_norm):
            out.append(item)

    if not out and encontrou_por_seller_sku:
        # A busca direta por seller_sku e confiavel mesmo quando o detalhe do item
        # nao devolve o atributo SKU da variacao.
        return itens_detalhados, cfg_local
    return out, cfg_local


def _ml_favoritos_buscar_primeiros_itens_por_skus(
    client_id: str,
    nome_loja: str,
    cfg: dict,
    skus: set[str],
    max_por_sku: int = 3,
) -> tuple[dict[str, list[dict]], dict]:
    """Busca poucos itens por SKU para enriquecer descriÃƒÂ§ÃƒÂµes em lote."""
    skus_limpos = [str(sku or "").strip() for sku in (skus or []) if str(sku or "").strip()]
    skus_limpos = list(dict.fromkeys(skus_limpos))
    if not skus_limpos:
        return {}, cfg

    resultado: dict[str, list[dict]] = {}

    def _buscar(sku_norm: str):
        itens, novo_cfg = _ml_favoritos_buscar_itens_por_sku(client_id, nome_loja, cfg_local_cache, sku_norm)
        limite = max(1, int(max_por_sku))
        return sku_norm, itens[:limite], novo_cfg

    cfg_local_cache = dict(cfg or {})
    if len(skus_limpos) == 1:
        sku_norm = _normalizar_sku_match_favoritos(skus_limpos[0])
        itens, cfg_local_cache = _ml_favoritos_buscar_itens_por_sku(client_id, nome_loja, cfg_local_cache, sku_norm)
        if itens:
            resultado[sku_norm] = itens[:max(1, int(max_por_sku))]
        return resultado, cfg_local_cache

    max_workers = min(len(skus_limpos), 4)
    if max_workers <= 1:
        for sku in skus_limpos:
            sku_norm = _normalizar_sku_match_favoritos(sku)
            itens, cfg_local_cache = _ml_favoritos_buscar_itens_por_sku(
                client_id,
                nome_loja,
                cfg_local_cache,
                sku_norm,
            )
            if itens:
                resultado[sku_norm] = itens[: max(1, int(max_por_sku))]
        return resultado, cfg_local_cache

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futuras = {
            executor.submit(
                _ml_favoritos_buscar_itens_por_sku,
                client_id,
                nome_loja,
                dict(cfg_local_cache),
                _normalizar_sku_match_favoritos(sku),
            ): _normalizar_sku_match_favoritos(sku)
            for sku in skus_limpos
        }
        for futura in as_completed(futuras):
            sku_norm = futuras[futura]
            try:
                itens, cfg_novo = futura.result()
            except Exception as exc:
                logger.warning("[Favoritos] Falha ao buscar itens do SKU %s: %s", sku_norm, exc)
                continue
            if cfg_novo:
                cfg_local_cache = cfg_novo
            if itens:
                resultado[sku_norm] = itens[: max(1, int(max_por_sku))]

    return resultado, cfg_local_cache


def _ml_favoritos_listar_itens_ativos_loja(
    client_id: str,
    nome_loja: str,
    cfg: dict,
    limite: int = 3000,
) -> tuple[list[dict], dict]:
    cfg_local = dict(cfg or {})
    user_id = str(cfg_local.get("user_id") or "").strip()
    if not user_id:
        raise HTTPException(status_code=400, detail="ID do usuario do Mercado Livre nao encontrado para esta loja.")

    cache_key = f"favoritos:v5:ml_itens_ativos_pausados:{client_id}:{nome_loja}:{int(limite or 0)}"
    cached = _ml_cache_get(cache_key, ttl=900)
    if cached is not None:
        return cached, cfg_local

    url = f"https://api.mercadolibre.com/users/{user_id}/items/search"
    ids: list[str] = []
    vistos: set[str] = set()
    offset = 0
    page_limit = 100
    # O endpoint de busca por usuÃ¡rio do ML rejeita offset/limit acima da janela 1000.
    # Para os SKUs que ficarem fora da varredura, Favoritos usa busca direta por seller_sku.
    limite = max(100, min(int(limite or 3000), 2000))

    while len(ids) < limite:
        if offset >= 1000:
            break
        limite_chamada = min(page_limit, limite - len(ids), 1000 - offset)
        if limite_chamada <= 0:
            break
        resp, cfg_local = _ml_favoritos_api_request(
            client_id,
            nome_loja,
            cfg_local,
            "GET",
            url,
            params={"offset": offset, "limit": limite_chamada, "status": "active"},
            timeout=15,
        )
        if resp.status_code != 200:
            raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao listar anuncios ativos do Mercado Livre"))

        data = resp.json() or {}
        batch = data.get("results") or []
        if not batch:
            break
        for item_id_raw in batch:
            item_id = str(item_id_raw or "").strip()
            if item_id and item_id not in vistos:
                vistos.add(item_id)
                ids.append(item_id)
                if len(ids) >= limite:
                    break

        paging = data.get("paging") or {}
        total = int(paging.get("total", len(ids)) or len(ids))
        offset += limite_chamada
        if offset >= total:
            break

    if len(ids) < limite:
        offset = 0
        while len(ids) < limite:
            if offset >= 1000:
                break
            limite_chamada = min(page_limit, limite - len(ids), 1000 - offset)
            if limite_chamada <= 0:
                break
            resp, cfg_local = _ml_favoritos_api_request(
                client_id,
                nome_loja,
                cfg_local,
                "GET",
                url,
                params={"offset": offset, "limit": limite_chamada, "status": "paused"},
                timeout=15,
            )
            if resp.status_code != 200:
                raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao listar anuncios pausados do Mercado Livre"))

            data = resp.json() or {}
            batch = data.get("results") or []
            if not batch:
                break
            for item_id_raw in batch:
                item_id = str(item_id_raw or "").strip()
                if item_id and item_id not in vistos:
                    vistos.add(item_id)
                    ids.append(item_id)
                    if len(ids) >= limite:
                        break

            paging = data.get("paging") or {}
            total = int(paging.get("total", len(ids)) or len(ids))
            offset += limite_chamada
            if offset >= total:
                break

    itens, cfg_local = _ml_favoritos_buscar_itens_batch(client_id, nome_loja, cfg_local, ids)
    _ml_cache_set(cache_key, itens)
    return itens, cfg_local


def _ml_favoritos_listar_todos_itens_ativos_loja(
    client_id: str,
    nome_loja: str,
    cfg: dict,
    limite: int = 10000,
) -> tuple[list[dict], dict]:
    """Lista os anÃºncios ativos da loja usando scan quando disponÃ­vel para nÃ£o parar na janela de 1000."""
    cfg_local = dict(cfg or {})
    user_id = str(cfg_local.get("user_id") or "").strip()
    if not user_id:
        raise HTTPException(status_code=400, detail="ID do usuario do Mercado Livre nao encontrado para esta loja.")

    limite = max(100, min(int(limite or 10000), 20000))
    cache_key = f"favoritos:v5:ml_todos_itens_ativos_pausados:{client_id}:{nome_loja}:{limite}"
    cached = _ml_cache_get(cache_key, ttl=900)
    if cached is not None:
        return cached, cfg_local

    url = f"https://api.mercadolibre.com/users/{user_id}/items/search"
    ids: list[str] = []
    vistos: set[str] = set()

    def _registrar_ids(batch) -> int:
        adicionados = 0
        for item_raw in batch or []:
            item_id = str((item_raw or {}).get("id") if isinstance(item_raw, dict) else item_raw or "").strip()
            if item_id and item_id not in vistos:
                vistos.add(item_id)
                ids.append(item_id)
                adicionados += 1
                if len(ids) >= limite:
                    break
        return adicionados

    scan_ok = False
    scroll_id = ""
    try:
        params = {"search_type": "scan", "limit": 100, "status": "active"}
        for _pagina in range(max(1, math.ceil(limite / 100))):
            if scroll_id:
                params = {"search_type": "scan", "scroll_id": scroll_id, "limit": 100}
            resp, cfg_local = _ml_favoritos_api_request(
                client_id,
                nome_loja,
                cfg_local,
                "GET",
                url,
                params=params,
                timeout=20,
            )
            if resp.status_code != 200:
                break
            data = resp.json() or {}
            batch = data.get("results") or []
            if not batch:
                scan_ok = True
                break
            _registrar_ids(batch)
            scan_ok = True
            scroll_id = str(data.get("scroll_id") or "").strip()
            if not scroll_id or len(ids) >= limite:
                break
    except Exception as exc:
        logger.warning("[Favoritos ML] Falha no scan de itens ativos da loja %s: %s", nome_loja, exc)

    if scan_ok and len(ids) < limite:
        scroll_id = ""
        try:
            params = {"search_type": "scan", "limit": 100, "status": "paused"}
            for _pagina in range(max(1, math.ceil((limite - len(ids)) / 100))):
                if scroll_id:
                    params = {"search_type": "scan", "scroll_id": scroll_id, "limit": 100}
                resp, cfg_local = _ml_favoritos_api_request(
                    client_id,
                    nome_loja,
                    cfg_local,
                    "GET",
                    url,
                    params=params,
                    timeout=20,
                )
                if resp.status_code != 200:
                    break
                data = resp.json() or {}
                batch = data.get("results") or []
                if not batch:
                    break
                _registrar_ids(batch)
                scroll_id = str(data.get("scroll_id") or "").strip()
                if not scroll_id or len(ids) >= limite:
                    break
        except Exception as exc:
            logger.warning("[Favoritos ML] Falha no scan de itens pausados da loja %s: %s", nome_loja, exc)

    if not scan_ok or not ids:
        ids = []
        vistos = set()
        page_limit = 100
        for status_item in ML_FAVORITOS_STATUS_SKUS:
            offset = 0
            while len(ids) < limite and offset < 1000:
                limite_chamada = min(page_limit, limite - len(ids), 1000 - offset)
                if limite_chamada <= 0:
                    break
                resp, cfg_local = _ml_favoritos_api_request(
                    client_id,
                    nome_loja,
                    cfg_local,
                    "GET",
                    url,
                    params={"offset": offset, "limit": limite_chamada, "status": status_item},
                    timeout=15,
                )
                if resp.status_code != 200:
                    raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao listar anuncios ativos/pausados do Mercado Livre"))
                data = resp.json() or {}
                batch = data.get("results") or []
                if not batch:
                    break
                _registrar_ids(batch)
                paging = data.get("paging") or {}
                total = int(paging.get("total", len(ids)) or len(ids))
                offset += limite_chamada
                if offset >= total:
                    break

    itens, cfg_local = _ml_favoritos_buscar_itens_batch(client_id, nome_loja, cfg_local, ids)
    _ml_cache_set(cache_key, itens)
    return itens, cfg_local


def _favoritos_ml_dividir_skus(valor: str) -> list[str]:
    return [
        str(sku or "").strip()
        for sku in re.split(r"[,;|\n]+", str(valor or ""))
        if str(sku or "").strip()
    ]


def _favoritos_ml_imagem_item(item: dict) -> str:
    if not isinstance(item, dict):
        return ""
    imagem = str(item.get("secure_thumbnail") or item.get("thumbnail") or "").strip()
    if imagem:
        return imagem
    pictures = item.get("pictures") if isinstance(item.get("pictures"), list) else []
    for picture in pictures:
        if not isinstance(picture, dict):
            continue
        imagem = str(picture.get("secure_url") or picture.get("url") or picture.get("thumbnail") or "").strip()
        if imagem:
            return imagem
    return ""


def _favoritos_ml_url_item_id(item_id: str) -> str:
    item_id_txt = re.sub(r"[^A-Za-z0-9]", "", str(item_id or "").strip()).upper()
    digitos = item_id_txt[3:] if item_id_txt.startswith("MLB") else ""
    if not item_id_txt.startswith("MLB") or len(digitos) < 8:
        return ""
    return f"https://produto.mercadolivre.com.br/{item_id_txt.replace('MLB', 'MLB-')}-_JM"


def _favoritos_ml_resumo_anuncio_sku(item: dict) -> dict:
    if not isinstance(item, dict):
        return {}
    item_id = str(item.get("id") or "").strip()
    permalink = str(item.get("permalink") or "").strip()
    if not permalink and item_id:
        permalink = _favoritos_ml_url_item_id(item_id)
    imagem = _favoritos_ml_imagem_item(item)
    return {
        "id": item_id,
        "mlb": item_id,
        "titulo": str(item.get("title") or "").strip(),
        "title": str(item.get("title") or "").strip(),
        "url": permalink,
        "permalink": permalink,
        "link": permalink,
        "imagem": imagem,
        "thumbnail": imagem,
        "status": str(item.get("status") or "").strip(),
    }


def _favoritos_ml_skus_unicos_itens(itens: list[dict]) -> list[dict]:
    mapa: dict[str, dict] = {}
    for item in itens or []:
        if not isinstance(item, dict):
            continue
        item_id = str(item.get("id") or "").strip()
        titulo = str(item.get("title") or "").strip()
        permalink = str(item.get("permalink") or "").strip()
        imagem_item = _favoritos_ml_imagem_item(item)
        resumo_anuncio = _favoritos_ml_resumo_anuncio_sku(item)
        status_item = str(item.get("status") or "").strip()
        try:
            estoque_item = int(float(str(item.get("available_quantity") or 0).replace(",", ".")))
        except Exception:
            estoque_item = 0
        skus_item = _favoritos_ml_dividir_skus(_ml_extrair_sku(item))
        for sku_extra in _ml_favoritos_extrair_skus_item(item):
            sku_extra_txt = str(sku_extra or "").strip()
            if sku_extra_txt and not any(sku_extra_txt.lower() == sku_existente.lower() for sku_existente in skus_item):
                skus_item.append(sku_extra_txt)
        for sku in skus_item:
            chave = _normalizar_sku_compacto_favoritos(sku) or sku.lower()
            if not chave:
                continue
            atual = mapa.get(chave)
            if not atual:
                atual = {
                    "sku": sku,
                    "titulo": titulo,
                    "produto": titulo,
                    "loja": "",
                    "saldo_loja": 0,
                    "estoque_loja": 0,
                    "item_ids": [],
                    "links": [],
                    "url": permalink,
                    "permalink": permalink,
                    "link": permalink,
                    "imagem": imagem_item,
                    "thumbnail": imagem_item,
                    "anuncios": [],
                    "total_anuncios": 0,
                    "status_anuncio": status_item,
                    "status_anuncios": [],
                    "fonte": "mercadolivre_api",
                }
                mapa[chave] = atual
            if item_id and item_id not in atual["item_ids"]:
                atual["item_ids"].append(item_id)
                atual["total_anuncios"] = len(atual["item_ids"])
                atual["saldo_loja"] = int(atual.get("saldo_loja") or 0) + estoque_item
                atual["estoque_loja"] = atual["saldo_loja"]
                if resumo_anuncio and len(atual.get("anuncios") or []) < 12:
                    atual["anuncios"].append(resumo_anuncio)
            if permalink and permalink not in atual["links"]:
                atual["links"].append(permalink)
            if permalink and not atual.get("url"):
                atual["url"] = permalink
                atual["permalink"] = permalink
                atual["link"] = permalink
            if imagem_item and not atual.get("imagem"):
                atual["imagem"] = imagem_item
                atual["thumbnail"] = imagem_item
            if status_item and status_item not in atual["status_anuncios"]:
                atual["status_anuncios"].append(status_item)
                if not atual.get("status_anuncio") or atual.get("status_anuncio") != "active":
                    atual["status_anuncio"] = status_item
            if not atual.get("titulo") and titulo:
                atual["titulo"] = titulo
                atual["produto"] = titulo

    def _numero_sku(sku: str):
        grupos = re.findall(r"\d+", str(sku or ""))
        if not grupos:
            return None
        try:
            return int("".join(grupos)[:15])
        except Exception:
            return None

    def _sort_key(item: dict):
        numero = _numero_sku(item.get("sku") or "")
        return (0 if numero is not None else 1, numero or 0, str(item.get("sku") or "").lower())

    return sorted(mapa.values(), key=_sort_key)


def _favoritos_ml_garantir_sku_busca(skus: list[dict], sku_busca: str, itens: list[dict]) -> list[dict]:
    sku_txt = str(sku_busca or "").strip()
    if not sku_txt or not itens:
        return skus
    chave_busca = _normalizar_sku_compacto_favoritos(sku_txt) or sku_txt.lower()
    for item in skus or []:
        if (_normalizar_sku_compacto_favoritos(item.get("sku") or "") or str(item.get("sku") or "").lower()) == chave_busca:
            return skus

    item_ids = []
    titulo = ""
    permalink = ""
    imagem = ""
    anuncios = []
    for item in itens or []:
        if not isinstance(item, dict):
            continue
        item_id = str(item.get("id") or "").strip()
        if item_id and item_id not in item_ids:
            item_ids.append(item_id)
            resumo = _favoritos_ml_resumo_anuncio_sku(item)
            if resumo and len(anuncios) < 12:
                anuncios.append(resumo)
        if not titulo:
            titulo = str(item.get("title") or "").strip()
        if not permalink:
            permalink = str(item.get("permalink") or "").strip() or _favoritos_ml_url_item_id(item_id)
        if not imagem:
            imagem = _favoritos_ml_imagem_item(item)

    if not item_ids:
        return skus

    extra = {
        "sku": sku_txt,
        "titulo": titulo,
        "item_ids": item_ids,
        "links": [permalink] if permalink else [],
        "url": permalink,
        "permalink": permalink,
        "link": permalink,
        "imagem": imagem,
        "thumbnail": imagem,
        "anuncios": anuncios,
        "total_anuncios": len(item_ids),
        "sku_forcado_busca": True,
    }
    return sorted([extra, *(skus or [])], key=lambda item: (
        0 if (_normalizar_sku_compacto_favoritos(item.get("sku") or "") or "").isdigit() else 1,
        int(_normalizar_sku_compacto_favoritos(item.get("sku") or "")[:15] or 0)
        if (_normalizar_sku_compacto_favoritos(item.get("sku") or "") or "").isdigit() else 0,
        str(item.get("sku") or "").lower(),
    ))


def _ml_favoritos_mapear_itens_ativos_por_skus(
    client_id: str,
    nome_loja: str,
    cfg: dict,
    skus: set[str],
    max_por_sku: int = 3,
) -> tuple[dict[str, list[dict]], dict]:
    alvos = {_normalizar_sku_match_favoritos(sku) for sku in (skus or []) if str(sku or "").strip()}
    alvos = {sku for sku in alvos if sku}
    if not alvos:
        return {}, cfg

    itens, cfg_local = _ml_favoritos_listar_itens_ativos_loja(client_id, nome_loja, cfg)
    resultado: dict[str, list[dict]] = {sku: [] for sku in alvos}
    limite = max(1, int(max_por_sku or 3))

    def _adicionar(sku_norm: str, item: dict):
        lista = resultado.setdefault(sku_norm, [])
        item_id = str((item or {}).get("id") or "").strip()
        if not item_id or any(str(x.get("id") or "").strip() == item_id for x in lista):
            return
        if len(lista) < limite:
            lista.append(item)

    alvos_compactos = {_normalizar_sku_compacto_favoritos(sku): sku for sku in alvos}
    for item in itens:
        if not isinstance(item, dict):
            continue
        for sku_raw in _ml_favoritos_extrair_skus_item(item):
            sku_norm = _normalizar_sku_match_favoritos(sku_raw)
            if sku_norm in alvos:
                _adicionar(sku_norm, item)
                continue
            sku_comp = _normalizar_sku_compacto_favoritos(sku_norm)
            sku_alvo = alvos_compactos.get(sku_comp)
            if sku_alvo:
                _adicionar(sku_alvo, item)

    pendentes = [sku for sku in alvos if not resultado.get(sku)]
    if pendentes:
        for item in itens:
            if not isinstance(item, dict):
                continue
            for sku_norm in list(pendentes):
                if _ml_favoritos_item_corresponde_sku(item, sku_norm):
                    _adicionar(sku_norm, item)
                    if resultado.get(sku_norm):
                        pendentes.remove(sku_norm)
                if not pendentes:
                    break
            if not pendentes:
                break

    return {sku: lista for sku, lista in resultado.items() if lista}, cfg_local


def _ml_favoritos_extrair_texto_descricao(payload: object) -> str:
    def _normalizar_texto(valor: str) -> str:
        if not valor:
            return ""
        txt = str(valor).strip().replace("\\\\n", " ").replace("\\n", " ")
        txt = html_lib.unescape(txt)
        if "<" in txt and ">" in txt:
            try:
                soup = BeautifulSoup(txt, "lxml")
                txt = soup.get_text(" ", strip=True)
            except Exception:
                pass
        return re.sub(r"\s+", " ", txt).strip()

    if payload is None:
        return ""
    if isinstance(payload, str):
        return _normalizar_texto(payload)
    if not isinstance(payload, dict):
        return ""

    # Formato padrÃ£o da API de descriÃ§Ã£o do ML.
    for campo in ("plain_text", "text", "content"):
        valor = payload.get(campo)
        if isinstance(valor, str):
            texto = _normalizar_texto(valor)
            if texto:
                return texto

    # Alguns retornos podem vir aninhados em `description`.
    descricao = payload.get("description")
    if isinstance(descricao, str):
        texto = _normalizar_texto(descricao)
        if texto:
            return texto
    if isinstance(descricao, dict):
        for campo in ("plain_text", "text", "content"):
            subvalor = descricao.get(campo)
            if isinstance(subvalor, str):
                texto = _normalizar_texto(subvalor)
                if texto:
                    return texto

    # Algumas estruturas retornam lista dentro desses campos.
    for campo in ("text", "plain_text", "content"):
        valor = payload.get(campo)
        if isinstance(valor, list):
            for item in valor:
                if not isinstance(item, dict):
                    continue
                for subcampo in ("plain_text", "text", "content"):
                    subvalor = item.get(subcampo)
                    if isinstance(subvalor, str):
                        texto = _normalizar_texto(subvalor)
                        if texto:
                            return texto
        elif isinstance(valor, str):
            texto = _normalizar_texto(valor)
            if texto:
                return texto

    # Fallback para texto serializado (Ãºltimo recurso).
    if isinstance(payload.get("text"), dict):
        texto = _normalizar_texto(json.dumps(payload.get("text")))
        if texto:
            return texto
    return ""


def _ml_favoritos_montar_descricao_por_item(item_payload: dict) -> str:
    item = item_payload if isinstance(item_payload, dict) else {}
    if not item:
        return ""

    partes: list[str] = []
    titulo = str(item.get("title") or item.get("name") or "").strip()
    if titulo:
        partes.append(f"Produto: {titulo}.")

    vistos: set[str] = set()

    def _valor_attr(attr: dict) -> str:
        if not isinstance(attr, dict):
            return ""
        valor = attr.get("value_name")
        if isinstance(valor, str) and valor.strip():
            return valor.strip()
        valores = attr.get("values")
        if isinstance(valores, list):
            saida = []
            for v in valores:
                if isinstance(v, dict):
                    txt = str(v.get("name") or v.get("value_name") or "").strip()
                    if txt and txt not in saida:
                        saida.append(txt)
            if saida:
                return ", ".join(saida[:4])
        valor_id = attr.get("value_id")
        return str(valor_id or "").strip()

    def _add_attr(attr: dict):
        nome = str((attr or {}).get("name") or (attr or {}).get("id") or "").strip()
        valor = _valor_attr(attr or {})
        if not nome or not valor:
            return
        chave = f"{_favoritos_normalizar_sem_acentos(nome).lower()}:{_favoritos_normalizar_sem_acentos(valor).lower()}"
        if chave in vistos:
            return
        vistos.add(chave)
        partes.append(f"{nome}: {valor}.")

    for attr in item.get("attributes") or []:
        _add_attr(attr)
        if len(partes) >= 18:
            break

    for variacao in item.get("variations") or []:
        if len(partes) >= 22:
            break
        if not isinstance(variacao, dict):
            continue
        for attr in (variacao.get("attribute_combinations") or []):
            _add_attr(attr)
            if len(partes) >= 22:
                break

    descricao = " ".join(partes)
    descricao = re.sub(r"\s+", " ", descricao).strip()
    return descricao[:3000]


def _ml_favoritos_obter_descricao_item(
    client_id: str,
    nome_loja: str,
    cfg: dict,
    item_id: str,
) -> dict[str, object]:
    item_id = str(item_id or "").strip()
    if not item_id:
        return {"success": False, "descricao": "", "description_info": {}, "erro": "Item id vazio."}

    cfg_local = dict(cfg or {})
    info = {"success": False, "descricao": "", "description_info": {}, "erro": ""}
    item_url = f"https://api.mercadolivre.com/items/{item_id}"
    descricao_url = f"https://api.mercadolibre.com/items/{item_id}/description"

    try:
        resp_item, cfg_local = _ml_favoritos_api_request(
            client_id,
            nome_loja,
            cfg_local,
            "GET",
            item_url,
            timeout=12,
        )
    except HTTPException as exc:
        info["erro"] = str(exc.detail or exc)
        return info
    except Exception as exc:
        info["erro"] = f"Falha ao consultar anuncio: {exc}"
        return info

    if resp_item.status_code == 404:
        info["erro"] = "Anuncio nÃ£o encontrado."
        return info
    if resp_item.status_code != 200:
        info["erro"] = f"Erro ao consultar anuncio ({resp_item.status_code})."
        return info

    try:
        item_payload = resp_item.json() or {}
    except Exception:
        item_payload = {}

    descricao_info = {}
    descricao = ""
    try:
        resp_desc, cfg_local = _ml_favoritos_api_request(
            client_id,
            nome_loja,
            cfg_local,
            "GET",
            descricao_url,
            timeout=12,
        )
        if resp_desc.status_code == 200:
            descricao_info = resp_desc.json() or {}
            descricao = _ml_favoritos_extrair_texto_descricao(descricao_info)
        elif resp_desc.status_code == 404:
            if isinstance(item_payload, dict):
                bloco = item_payload.get("description")
                if isinstance(bloco, dict):
                    descricao_info = bloco
                    descricao = _ml_favoritos_extrair_texto_descricao(bloco)
                elif isinstance(bloco, str):
                    descricao = bloco.strip()
                    descricao_info = {"content": descricao}
        else:
            descricao = ""
    except Exception as exc:
        logger.warning("[Favoritos] Falha ao buscar descricao do item %s: %s", item_id, exc)

    if not descricao and isinstance(item_payload, dict):
        descricao_fallback = _ml_favoritos_montar_descricao_por_item(item_payload)
        if descricao_fallback:
            descricao = descricao_fallback
            descricao_info = {"fonte": "item_payload", "fallback": True}

    descricao = (descricao or "").strip()
    if descricao:
        info["success"] = True
        info["descricao"] = descricao
        info["description_info"] = descricao_info
    else:
        info["erro"] = "Anuncio encontrado, mas sem descricao publicada e sem atributos suficientes no Mercado Livre."

    return info


def _ml_favoritos_obter_descricao_item_rapida(
    client_id: str,
    nome_loja: str,
    cfg: dict,
    item_id: str,
) -> dict[str, object]:
    item_id = str(item_id or "").strip()
    if not item_id:
        return {"success": False, "descricao": "", "description_info": {}, "erro": "Item id vazio."}

    cfg_local = dict(cfg or {})
    descricao_url = f"https://api.mercadolibre.com/items/{item_id}/description"
    try:
        resp_desc, cfg_local = _ml_favoritos_api_request(
            client_id,
            nome_loja,
            cfg_local,
            "GET",
            descricao_url,
            timeout=12,
        )
        if resp_desc.status_code == 200:
            descricao_info = resp_desc.json() or {}
            descricao = _ml_favoritos_extrair_texto_descricao(descricao_info)
            if descricao:
                return {"success": True, "descricao": descricao, "description_info": descricao_info, "erro": ""}
            fallback = _ml_favoritos_obter_descricao_item(client_id, nome_loja, cfg_local, item_id)
            if fallback.get("success"):
                return fallback
            return {"success": False, "descricao": "", "description_info": descricao_info, "erro": fallback.get("erro") or "Anuncio encontrado, mas sem descricao publicada na API do Mercado Livre."}
        if resp_desc.status_code == 404:
            return _ml_favoritos_obter_descricao_item(client_id, nome_loja, cfg_local, item_id)
        return {"success": False, "descricao": "", "description_info": {}, "erro": f"Erro ao consultar descricao ({resp_desc.status_code})."}
    except Exception as exc:
        return {"success": False, "descricao": "", "description_info": {}, "erro": str(exc)}


def _permissao_exigida_por_rota(path: str, method: str = "GET") -> Optional[str]:
    """Mapeia cada grupo de rotas ao mÃƒÂ³dulo correspondente da planilha de usuÃƒÂ¡rios."""
    rota = str(path or "").lower()
    metodo = str(method or "GET").upper()

    if rota.startswith("/api/promo/"):
        return "analise_promo"
    if rota.startswith("/api/renovacao/"):
        return "renovacao_fixa"
    if rota.startswith("/api/mercadolivre/perguntas"):
        return "perguntas_pos_venda"
    if rota.startswith("/api/mercadolivre/pos-venda"):
        return "perguntas_pos_venda"
    if rota.startswith("/api/mercadolivre/ia-treinamento"):
        return "perguntas_pos_venda"
    if rota.startswith("/api/mercadolivre/"):
        return "anuncios_ml"
    if rota.startswith("/api/etiquetas/"):
        return "etiquetas"
    if rota.startswith("/api/integracoes/"):
        return "integracao"
    if rota.startswith("/api/lojas") and metodo in {"POST", "PUT", "PATCH", "DELETE"}:
        return "integracao"
    if rota.startswith("/api/cadastro/"):
        return "cadastro"
    if rota.startswith("/api/impostos/"):
        return "impostos"
    if rota.startswith("/api/configuracoes"):
        return "configuracoes"
    if rota.startswith("/api/importacoes"):
        return "importacoes"
    if rota.startswith("/api/ia/"):
        return None
    if rota == "/api/estoque" or rota.startswith("/api/estoque/"):
        return "estoque"
    if (
        rota.startswith("/api/vendas")
        or rota.startswith("/api/notas-entrada")
        or rota.startswith("/api/unidades-negocios")
        or rota.startswith("/api/debug/notas-entrada-itens")
    ):
        return "vendas"
    if rota.startswith("/api/medias-compras/"):
        return "medias_compras"
    if rota.startswith("/api/full/"):
        return "mercado_full"
    if rota.startswith("/api/favoritos/"):
        return "favoritos"
    if rota.startswith("/api/admin/"):
        return "admin_usuarios"
    return None

def _extrair_texto_openai_response(payload: dict) -> str:
    texto = payload.get("output_text")
    if isinstance(texto, str) and texto.strip():
        return texto.strip()

    partes = []
    for item in payload.get("output") or []:
        for content in item.get("content") or []:
            if isinstance(content, dict):
                valor = content.get("text")
                if isinstance(valor, str) and valor.strip():
                    partes.append(valor.strip())
    return "\n".join(partes).strip()

def _extrair_b64_openai_image_response(payload: dict) -> str:
    try:
        data = payload.get("data")
        if isinstance(data, list):
            for item in data:
                if isinstance(item, dict) and isinstance(item.get("b64_json"), str) and item.get("b64_json").strip():
                    return item.get("b64_json").strip()
                if isinstance(item, dict) and isinstance(item.get("url"), str) and item.get("url").strip():
                    try:
                        resp_img = requests.get(item.get("url"), timeout=60)
                        if resp_img.ok and resp_img.content:
                            return base64.b64encode(resp_img.content).decode("ascii")
                    except Exception:
                        pass
    except Exception:
        pass
    return ""

def _ia_estoque_texto(client_id: str) -> str:
    """LÃƒÂª produtos_compilado.csv e retorna texto compacto com estoque de todos os SKUs (apenas os com saldo > 0)."""
    try:
        caminho = os.path.join(get_tenant_path(client_id), "produtos_compilado.csv")
        if not os.path.exists(caminho):
            return ""
        df = pd.read_csv(caminho, dtype=str).fillna("")
        linhas = []
        for _, row in df.iterrows():
            sku = str(row.get("sku") or "").strip()
            if not sku:
                continue
            saldo_loja = float(row.get("saldo_loja") or 0)
            if saldo_loja <= 0:
                continue
            nome = str(row.get("nome_bling") or row.get("produto") or "").strip()[:100]
            linhas.append(f"{sku} | {nome} | loja:{int(saldo_loja)}")
        if not linhas:
            return ""
        header = "Estoque atual (SKU | produto | saldo loja):\n"
        return header + "\n".join(linhas)
    except Exception as exc:
        logger.warning(f"[IA] Falha ao ler estoque para contexto: {exc}")
        return ""


def _ia_carregar_produtos_tool_df(client_id: str) -> Optional[pd.DataFrame]:
    try:
        arquivo_estoque = _migrar_arquivo_legado_para_tenant(client_id, "produtos_compilado.csv", ARQUIVO_DB_PRODUTOS)
        arquivo_cadastro = _migrar_arquivo_legado_para_tenant(client_id, "cadastro_produtos.csv", ARQUIVO_DB_CADASTRO_PRODUTOS)

        df_estoque = None
        df_cadastro = None
        if os.path.exists(arquivo_estoque):
            df_estoque = pd.read_csv(arquivo_estoque, dtype=str).fillna("")
        if os.path.exists(arquivo_cadastro):
            df_cadastro = pd.read_csv(arquivo_cadastro, dtype=str).fillna("")

        if df_estoque is None and df_cadastro is None:
            return None

        if df_estoque is None:
            df_base = df_cadastro.copy()
        elif df_cadastro is None:
            df_base = df_estoque.copy()
        else:
            cols_cadastro = [
                col for col in (
                    "sku",
                    "nome",
                    "categoria",
                    "marca",
                    "custo",
                    "imposto",
                    "preco",
                    "descricao",
                    "description",
                    "foto",
                    "link aliexpress",
                    "produto_bling",
                    "ncm",
                    "cest",
                    "categoria_fiscal",
                    "classificacao_autopeca",
                    "mlb_principal",
                    "titulos_anuncios_mlb",
                    "updated_at",
                    "qtd",
                )
                if col in df_cadastro.columns
            ]
            df_base = df_estoque.merge(df_cadastro[cols_cadastro], on="sku", how="outer")

        if "sku" not in df_base.columns:
            return None

        df_base = df_base.fillna("")
        df_base["sku_norm"] = df_base["sku"].astype(str).str.strip().str.upper()
        nome_principal = df_base.get("nome_bling", "").astype(str) if "nome_bling" in df_base.columns else ""
        nome_secundario = df_base.get("nome", "").astype(str) if "nome" in df_base.columns else ""
        df_base["nome_tool"] = nome_principal.where(nome_principal.str.strip() != "", nome_secundario)
        df_base["nome_tool"] = df_base["nome_tool"].astype(str).fillna("")
        df_base["nome_tool_norm"] = df_base["nome_tool"].map(_normalizar_texto)
        return df_base
    except Exception as exc:
        logger.warning(f"[IA TOOLS] Falha ao carregar base de produtos: {exc}")
        return None


def _ia_extrair_referencia_produto_mensagem(mensagem: str) -> dict:
    texto_original = str(mensagem or "").strip()
    texto_norm = _normalizar_texto(texto_original)
    if not texto_norm:
        return {"sku": "", "termo": ""}

    stopwords_sku = {
        "MAIS", "MENOS", "TOP", "LIDER", "LIDEROU", "VENDEU", "VENDIDO", "VENDIDA",
        "PRODUTO", "SKU", "LOJA", "MES", "MESMO", "PERIODO", "ONTEM", "HOJE",
        "VAI", "CADA", "TODOS", "TODAS", "QUANDO", "ACABA", "ACABAR",
        "APARECE", "APARECER", "CODIGO", "CÃ“DIGO", "EXATO",
    }

    def _token_parece_data(valor: str) -> bool:
        token = str(valor or "").strip().upper()
        if not token:
            return False
        if re.match(r"^\d{4}[/-]\d{1,2}[/-]\d{1,2}$", token):
            return True
        if re.match(r"^\d{1,2}[/-]\d{1,2}[/-]\d{4}$", token):
            return True
        return False

    def _sku_curto_valido(valor: str) -> bool:
        token = str(valor or "").strip()
        return bool(
            re.fullmatch(r"[A-Z0-9][A-Z0-9._/-]{1,40}", token)
            and token not in stopwords_sku
            and not _token_parece_data(token)
            and re.search(r"\d", token)
            and (len(token) >= 3 or re.search(r"[-_/]", token) or re.fullmatch(r"0\d", token))
        )

    texto_primeira_linha = _normalizar_texto(texto_original.split("\n", 1)[0]).strip()
    for texto_sku_curto in (texto_primeira_linha, texto_norm.strip()):
        if _sku_curto_valido(texto_sku_curto):
            return {"sku": texto_sku_curto, "termo": ""}

    match_sku = re.search(r"\bSKU\s+([A-Z0-9][A-Z0-9._/-]{0,40})\b", texto_norm)
    if match_sku:
        sku_match = match_sku.group(1).strip()
        if sku_match not in stopwords_sku and not _token_parece_data(sku_match):
            return {"sku": sku_match, "termo": ""}

    match_sku_como = re.search(r"\bSKU\b.{0,60}\b(?:COMO|CODIGO|CÃ“DIGO|COD)\s+([A-Z0-9][A-Z0-9._/-]{0,40})\b", texto_norm)
    if match_sku_como:
        sku_match = match_sku_como.group(1).strip()
        if sku_match not in stopwords_sku and not _token_parece_data(sku_match) and re.search(r"\d", sku_match):
            return {"sku": sku_match, "termo": ""}

    match_sku_solto = re.search(r"\b(MLB\d{6,}|[A-Z0-9]{2,}(?:[-_/][A-Z0-9]{1,})+)\b", texto_norm)
    if match_sku_solto:
        sku_match = match_sku_solto.group(1).strip()
        if sku_match not in stopwords_sku and not _token_parece_data(sku_match):
            return {"sku": sku_match, "termo": ""}

    match_aspas = re.search(r'"([^"]{3,80})"', texto_original)
    if not match_aspas:
        match_aspas = re.search(r"'([^']{3,80})'", texto_original)
    if match_aspas:
        return {"sku": "", "termo": match_aspas.group(1).strip()}

    match_produto = re.search(r"\bPRODUTO\s+([A-Z0-9 ]{3,80})", texto_norm)
    if match_produto:
        termo = match_produto.group(1).strip()
        for stop in (" ONTEM", " HOJE", " NO MES", " NO MÃƒÅ S", " EM ", " DE ", " DA ", " DO ", " NA ", " NO ", " LOJA "):
            if stop in termo:
                termo = termo.split(stop, 1)[0].strip()
                break
        return {"sku": "", "termo": termo}

    return {"sku": "", "termo": ""}


def _ia_normalizar_imagem_cadastro_url(imagem_ref: str) -> str:
    ref = str(imagem_ref or "").replace("\\", "/").strip()
    if not ref:
        return ""
    if re.match(r"^https?://", ref, re.IGNORECASE):
        return ref
    if ref.startswith("/api/cadastro/foto-arquivo/") or ref.startswith("/api/cadastro/foto/") or ref.startswith("/img/"):
        return ref
    if ref.lower().startswith("cadastro_fotos/"):
        ref = ref.split("/", 1)[1]
    nome = os.path.basename(ref)
    if not nome:
        return ""
    if re.search(r"\.(png|jpe?g|gif|webp|bmp)$", nome, re.IGNORECASE):
        return f"/api/cadastro/foto-arquivo/{quote_plus(nome)}"
    return ref


def _ia_tool_get_product_data(client_id: str, mensagem: str, limite: int = 5) -> Optional[dict]:
    ref = _ia_extrair_referencia_produto_mensagem(mensagem)
    sku_ref = _normalizar_sku_mes(str(ref.get("sku") or "").strip()).upper()
    termo_ref = str(ref.get("termo") or "").strip()
    if not sku_ref and not termo_ref:
        return None

    df = _ia_carregar_produtos_tool_df(client_id)
    if df is None or df.empty:
        return None

    candidatos = df
    argumentos = {}
    if sku_ref:
        argumentos["sku_ou_termo"] = sku_ref
        candidatos = df[df["sku_norm"] == sku_ref]
    else:
        termo_norm = _normalizar_texto(termo_ref)
        argumentos["sku_ou_termo"] = termo_ref
        candidatos = df[
            df["nome_tool_norm"].str.contains(termo_norm, na=False)
            | df["sku_norm"].str.contains(termo_norm, na=False)
        ]

    if candidatos.empty:
        return {
            "function": "get_product_data",
            "arguments": argumentos,
            "result": {"matches": [], "found": False},
        }

    registros = []
    mapa_fotos_locais = _cadastro_mapa_fotos_locais(client_id)
    for _, row in candidatos.head(limite).iterrows():
        imagem_url = ""
        for col_img in ("foto", "imagem", "imagem_url", "image_url", "url_imagem", "link_imagem"):
            if col_img in row.index:
                valor = str(row.get(col_img) or "").strip()
                if valor:
                    imagem_url = _ia_normalizar_imagem_cadastro_url(valor)
                    break
        if not imagem_url:
            foto_local = _cadastro_resolver_foto_local(mapa_fotos_locais, str(row.get("sku") or "").strip())
            if foto_local:
                imagem_url = _ia_normalizar_imagem_cadastro_url(foto_local)
        registros.append({
            "sku": str(row.get("sku") or "").strip(),
            "nome": str(row.get("nome_tool") or row.get("nome") or row.get("nome_bling") or "").strip(),
            "marca": str(row.get("marca") or "").strip(),
            "categoria": str(row.get("categoria") or "").strip(),
            "saldo_loja": float(row.get("saldo_loja") or 0),
            "saldo_full": float(row.get("saldo_full") or 0),
            "preco": str(row.get("preco") or "").strip(),
            "custo": str(row.get("custo") or "").strip(),
            "imposto": str(row.get("imposto") or "").strip(),
            "mlb_principal": str(row.get("mlb_principal") or "").strip(),
            "mlb_ids": str(row.get("mlb_ids") or "").strip(),
            "imagem_url": imagem_url,
        })

    return {
        "function": "get_product_data",
        "arguments": argumentos,
        "result": {
            "found": True,
            "matches": registros,
            "canonical_sku": registros[0].get("sku") if registros else "",
        },
    }


def _ia_tool_get_product_registry_info(client_id: str, mensagem: str, produto_tool: Optional[dict] = None, limite: int = 3) -> Optional[dict]:
    try:
        base_produto = produto_tool or _ia_tool_get_product_data(client_id, mensagem, limite=1)
        ref = _ia_extrair_referencia_produto_mensagem(mensagem)
        sku_ref = _normalizar_sku_mes(str(ref.get("sku") or "").strip()).upper()
        termo_ref = str(ref.get("termo") or "").strip()
        if not sku_ref and base_produto:
            sku_ref = _normalizar_sku_mes(str(((base_produto.get("result") or {}).get("canonical_sku") or "")).strip()).upper()

        df = _ia_carregar_produtos_tool_df(client_id)
        if df is None or df.empty:
            return None

        candidatos = df
        args = {}
        if sku_ref:
            candidatos = df[df["sku_norm"] == sku_ref]
            args["sku_ou_termo"] = sku_ref
        elif termo_ref:
            termo_norm = _normalizar_texto(termo_ref)
            candidatos = df[
                df["nome_tool_norm"].str.contains(termo_norm, na=False)
                | df["sku_norm"].str.contains(termo_norm, na=False)
            ]
            args["sku_ou_termo"] = termo_ref
        else:
            return None

        if candidatos.empty:
            return {
                "function": "get_product_registry_info",
                "arguments": args,
                "result": {"found": False, "matches": []},
            }

        if "sku_norm" in candidatos.columns:
            candidatos = candidatos.drop_duplicates(subset=["sku_norm"], keep="first")

        registros = []
        mapa_fotos_locais = _cadastro_mapa_fotos_locais(client_id)
        for _, row in candidatos.head(limite).iterrows():
            imagem_url = ""
            for col_img in ("foto", "imagem", "imagem_url", "image_url", "url_imagem", "link_imagem"):
                if col_img in row.index:
                    valor = str(row.get(col_img) or "").strip()
                    if valor:
                        imagem_url = _ia_normalizar_imagem_cadastro_url(valor)
                        break
            if not imagem_url:
                foto_local = _cadastro_resolver_foto_local(mapa_fotos_locais, str(row.get("sku") or "").strip())
                if foto_local:
                    imagem_url = _ia_normalizar_imagem_cadastro_url(foto_local)

            registros.append({
                "sku": str(row.get("sku") or "").strip(),
                "nome": str(row.get("nome_tool") or row.get("nome") or row.get("nome_bling") or "").strip(),
                "descricao": str(row.get("descricao") or row.get("description") or "").strip(),
                "marca": str(row.get("marca") or "").strip(),
                "categoria": str(row.get("categoria") or "").strip(),
                "preco": str(row.get("preco") or "").strip(),
                "custo": str(row.get("custo") or "").strip(),
                "imposto": str(row.get("imposto") or "").strip(),
                "ncm": str(row.get("ncm") or "").strip(),
                "cest": str(row.get("cest") or "").strip(),
                "categoria_fiscal": str(row.get("categoria_fiscal") or "").strip(),
                "classificacao_autopeca": str(row.get("classificacao_autopeca") or "").strip(),
                "mlb_principal": str(row.get("mlb_principal") or "").strip(),
                "mlb_ids": str(row.get("mlb_ids") or "").strip(),
                "titulos_anuncios_mlb": str(row.get("titulos_anuncios_mlb") or "").strip(),
                "link_aliexpress": str(row.get("link aliexpress") or "").strip(),
                "imagem_url": imagem_url,
                "updated_at": str(row.get("updated_at") or "").strip(),
            })

        return {
            "function": "get_product_registry_info",
            "arguments": args,
            "result": {
                "found": True,
                "matches": registros,
                "canonical_sku": registros[0].get("sku") if registros else "",
            },
        }
    except Exception as exc:
        logger.warning(f"[IA TOOLS] Falha ao obter cadastro do produto: {exc}")
        return None


def _ia_tool_get_days_without_sale(client_id: str, mensagem: str, produto_tool: Optional[dict] = None, loja: Optional[str] = None) -> Optional[dict]:
    try:
        sku = _ia_tool_resolver_sku(client_id, mensagem, produto_tool)
        if not sku:
            return None

        loja_filtro = loja if (loja and str(loja).strip() not in ("", "__todas", "Todas as lojas")) else None
        dbs = _listar_bancos_vendas_tenant(client_id, loja_filtro)
        if not dbs:
            return None

        sql_loja, params_loja = _sql_filtro_loja_vendas(loja_filtro)
        ultima_venda = ""
        primeira_venda = ""
        produto_nome = ""

        for db_path in dbs:
            if not os.path.exists(db_path):
                continue
            try:
                conn = sqlite3.connect(db_path, timeout=5)
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                row = cur.execute(
                    f"""
                    SELECT
                        MIN(CASE WHEN COALESCE(devolucao, 0) = 0
                                  AND LOWER(COALESCE(situacao,'')) NOT IN ('cancelado','cancelada','cancelamento','cancelamento solicitado')
                                 THEN data END) AS primeira_venda,
                        MAX(CASE WHEN COALESCE(devolucao, 0) = 0
                                  AND LOWER(COALESCE(situacao,'')) NOT IN ('cancelado','cancelada','cancelamento','cancelamento solicitado')
                                 THEN data END) AS ultima_venda,
                        MAX(produto) AS produto
                    FROM vendas
                    WHERE UPPER(TRIM(COALESCE(sku, ''))) = ?
                      {sql_loja}
                    """,
                    [sku, *params_loja],
                ).fetchone()
                conn.close()
                if row:
                    prod = str(row["produto"] or "").strip()
                    if prod and not produto_nome:
                        produto_nome = prod
                    p = str(row["primeira_venda"] or "").strip()
                    u = str(row["ultima_venda"] or "").strip()
                    if p and (not primeira_venda or p < primeira_venda):
                        primeira_venda = p
                    if u and (not ultima_venda or u > ultima_venda):
                        ultima_venda = u
            except Exception as exc:
                logger.warning(f"[IA TOOLS] Erro ao consultar dias sem venda para SKU {sku} em {db_path}: {exc}")
                continue

        data_ref = _ia_obter_data_referencia_vendas(client_id, loja_filtro) or dt.date.today()
        status = "nunca_vendeu"
        dias_sem_vender = None
        if ultima_venda:
            try:
                ultima_venda_data = str(ultima_venda).strip().replace("T", " ").split(" ", 1)[0]
                dias_sem_vender = max(0, (data_ref - dt.date.fromisoformat(ultima_venda_data)).days)
                ultima_venda = ultima_venda_data
                status = "sem_venda_recente" if dias_sem_vender > 0 else "vendeu_no_dia"
            except Exception:
                dias_sem_vender = None
                status = "sem_dado"

        return {
            "function": "get_days_without_sale",
            "arguments": {"sku": sku, "loja": loja_filtro or ""},
            "result": {
                "sku": sku,
                "produto": produto_nome,
                "loja": loja_filtro or "",
                "data_referencia": data_ref.isoformat(),
                "primeira_venda": primeira_venda,
                "ultima_venda": ultima_venda,
                "dias_sem_vender": dias_sem_vender,
                "status": status,
            },
        }
    except Exception as exc:
        logger.warning(f"[IA TOOLS] Falha ao calcular dias sem venda: {exc}")
        return None


def _ia_tool_get_days_without_sale_top(
    client_id: str,
    loja: Optional[str] = None,
    limite: int = 20,
    apenas_com_estoque: bool = False,
    apenas_ja_vendidos: bool = False,
) -> Optional[dict]:
    try:
        limite = max(1, min(int(limite or 20), 200))
        loja_filtro = loja if (loja and str(loja).strip() not in ("", "__todas", "Todas as lojas")) else None

        df = _ia_carregar_produtos_tool_df(client_id)
        if df is None or df.empty:
            return None

        mapa_produtos: dict[str, str] = {}
        mapa_saldos: dict[str, float] = {}
        for _, row in df.iterrows():
            sku = str(row.get("sku_norm") or "").strip().upper()
            if not sku:
                continue
            if not any(ch.isalnum() for ch in sku):
                continue
            if sku not in mapa_produtos:
                mapa_produtos[sku] = str(row.get("nome_tool") or row.get("nome") or row.get("nome_bling") or "").strip()
            saldo_total = _ia_tool_float(row.get("saldo_total"))
            if saldo_total <= 0:
                saldo_total = _ia_tool_float(row.get("saldo_loja")) + _ia_tool_float(row.get("saldo_full"))
            mapa_saldos[sku] = max(mapa_saldos.get(sku, 0.0), float(saldo_total or 0.0))

        if not mapa_produtos:
            return None

        dbs = _listar_bancos_vendas_tenant(client_id, loja_filtro)
        if not dbs:
            return None

        sql_loja, params_loja = _sql_filtro_loja_vendas(loja_filtro)
        ultimas_vendas: dict[str, str] = {}

        for db_path in dbs:
            if not os.path.exists(db_path):
                continue
            try:
                conn = sqlite3.connect(db_path, timeout=5)
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                rows = cur.execute(
                    f"""
                    SELECT UPPER(TRIM(COALESCE(sku, ''))) AS sku,
                           MAX(data) AS ultima_venda
                    FROM vendas
                    WHERE COALESCE(devolucao, 0) = 0
                      AND LOWER(COALESCE(situacao,'')) NOT IN ('cancelado','cancelada','cancelamento','cancelamento solicitado')
                      {sql_loja}
                    GROUP BY UPPER(TRIM(COALESCE(sku, '')))
                    """,
                    [*params_loja],
                ).fetchall()
                conn.close()
                for row in rows or []:
                    sku = str(row["sku"] or "").strip().upper()
                    data_ref = str(row["ultima_venda"] or "").strip().replace("T", " ").split(" ", 1)[0]
                    if not sku or not data_ref:
                        continue
                    anterior = ultimas_vendas.get(sku)
                    if (anterior is None) or (data_ref > anterior):
                        ultimas_vendas[sku] = data_ref
            except Exception as exc:
                logger.warning(f"[IA TOOLS] Erro ao buscar ÃƒÂºltimas vendas em {db_path}: {exc}")
                continue

        data_referencia = _ia_obter_data_referencia_vendas(client_id, loja_filtro) or dt.date.today()
        itens = []
        for sku, nome in mapa_produtos.items():
            saldo_total = float(mapa_saldos.get(sku) or 0.0)
            if apenas_com_estoque and saldo_total <= 0:
                continue
            ultima = str(ultimas_vendas.get(sku) or "").strip()
            if not ultima:
                if apenas_ja_vendidos:
                    continue
                itens.append({
                    "sku": sku,
                    "produto": nome,
                    "saldo_total": saldo_total,
                    "ultima_venda": "",
                    "dias_sem_vender": None,
                    "status": "nunca_vendeu",
                })
                continue
            try:
                dias = max(0, (data_referencia - dt.date.fromisoformat(ultima)).days)
                itens.append({
                    "sku": sku,
                    "produto": nome,
                    "saldo_total": saldo_total,
                    "ultima_venda": ultima,
                    "dias_sem_vender": dias,
                    "status": "sem_venda_recente" if dias > 0 else "vendeu_no_dia",
                })
            except Exception:
                itens.append({
                    "sku": sku,
                    "produto": nome,
                    "saldo_total": saldo_total,
                    "ultima_venda": ultima,
                    "dias_sem_vender": None,
                    "status": "sem_dado",
                })

        if not itens:
            return None

        # SKUs sem histÃƒÂ³rico vÃƒÂªm primeiro; depois maior quantidade de dias sem vender.
        itens_ordenados = sorted(
            itens,
            key=lambda x: (
                0 if x.get("dias_sem_vender") is None else 1,
                -(int(x.get("dias_sem_vender") or 0)),
                str(x.get("sku") or ""),
            ),
        )

        return {
            "function": "get_days_without_sale_top",
            "arguments": {
                "loja": loja_filtro or "",
                "limite": limite,
                "apenas_com_estoque": bool(apenas_com_estoque),
                "apenas_ja_vendidos": bool(apenas_ja_vendidos),
            },
            "result": {
                "loja": loja_filtro or "",
                "data_referencia": data_referencia.isoformat(),
                "total_skus_avaliados": len(itens_ordenados),
                "itens": itens_ordenados[:limite],
            },
        }
    except Exception as exc:
        logger.warning(f"[IA TOOLS] Falha ao listar SKUs sem venda: {exc}")
        return None


def _ia_tool_float(value: Any) -> float:
    try:
        texto = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not texto:
            return 0.0
        if "," in texto and "." in texto:
            texto = texto.replace(".", "").replace(",", ".")
        elif "," in texto:
            texto = texto.replace(",", ".")
        return float(texto)
    except Exception:
        return 0.0


def _ia_tool_resolver_sku(client_id: str, mensagem: str, produto_tool: Optional[dict] = None) -> str:
    ref = _ia_extrair_referencia_produto_mensagem(mensagem)
    sku = str(ref.get("sku") or "").strip().upper()
    if sku:
        return sku
    if produto_tool:
        return str(((produto_tool.get("result") or {}).get("canonical_sku") or "")).strip().upper()
    return ""


def _ia_tool_get_stock_data(client_id: str, mensagem: str, produto_tool: Optional[dict] = None) -> Optional[dict]:
    base_produto = produto_tool or _ia_tool_get_product_data(client_id, mensagem)
    if not base_produto:
        return None
    resultado = base_produto.get("result") or {}
    matches = resultado.get("matches") or []
    if not matches:
        return {
            "function": "get_stock_data",
            "arguments": {"sku_ou_termo": (base_produto.get("arguments") or {}).get("sku_ou_termo") or ""},
            "result": {"found": False, "items": []},
        }

    sku = str(resultado.get("canonical_sku") or matches[0].get("sku") or "").strip().upper()
    saldo_loja_total = sum(_ia_tool_float(item.get("saldo_loja")) for item in matches)
    saldo_full_total = sum(_ia_tool_float(item.get("saldo_full")) for item in matches)
    return {
        "function": "get_stock_data",
        "arguments": {"sku_ou_termo": (base_produto.get("arguments") or {}).get("sku_ou_termo") or sku},
        "result": {
            "found": True,
            "sku": sku,
            "nome": str(matches[0].get("nome") or "").strip(),
            "saldo_loja_total": saldo_loja_total,
            "saldo_full_total": saldo_full_total,
            "saldo_total": saldo_loja_total + saldo_full_total,
            "linhas_origem": len(matches),
        },
    }


def _ia_tool_get_product_margin(client_id: str, mensagem: str, produto_tool: Optional[dict] = None) -> Optional[dict]:
    base_produto = produto_tool or _ia_tool_get_product_data(client_id, mensagem)
    if not base_produto:
        return None
    resultado = base_produto.get("result") or {}
    matches = resultado.get("matches") or []
    if not matches:
        return {
            "function": "get_product_margin",
            "arguments": {"sku_ou_termo": (base_produto.get("arguments") or {}).get("sku_ou_termo") or ""},
            "result": {"found": False},
        }

    item = matches[0]
    preco = _ia_tool_float(item.get("preco"))
    custo = _ia_tool_float(item.get("custo"))
    imposto_pct = _ia_tool_float(item.get("imposto"))
    imposto_valor = preco * (imposto_pct / 100.0) if preco > 0 and imposto_pct > 0 else 0.0
    margem_valor = preco - custo - imposto_valor if preco > 0 else 0.0
    margem_pct = ((margem_valor / preco) * 100.0) if preco > 0 else 0.0
    return {
        "function": "get_product_margin",
        "arguments": {"sku_ou_termo": (base_produto.get("arguments") or {}).get("sku_ou_termo") or item.get("sku") or ""},
        "result": {
            "found": True,
            "sku": str(item.get("sku") or "").strip(),
            "nome": str(item.get("nome") or "").strip(),
            "preco": preco,
            "custo": custo,
            "imposto_percentual": imposto_pct,
            "imposto_valor_estimado": imposto_valor,
            "margem_valor_estimada": margem_valor,
            "margem_percentual_estimada": margem_pct,
            "estimativa": True,
        },
    }


def _ia_tool_get_sales_by_period(client_id: str, data_inicio: str, data_fim: str, loja: Optional[str] = None, limite: int = 5) -> Optional[dict]:
    try:
        if not data_inicio or not data_fim:
            return None
        loja_filtro = loja if (loja and str(loja).strip() not in ("", "__todas", "Todas as lojas")) else None
        dbs = _listar_bancos_vendas_tenant(client_id, loja_filtro)
        if not dbs:
            return None
        sql_loja, params_loja = _sql_filtro_loja_vendas(loja_filtro)
        total_qtd = 0.0
        total_valor = 0.0
        total_pedidos = 0
        for db_path in dbs:
            if not os.path.exists(db_path):
                continue
            try:
                conn = sqlite3.connect(db_path, timeout=5)
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                row = cur.execute(
                    f"""
                    SELECT SUM(quantidade) AS qtd, SUM(valor) AS valor, COUNT(DISTINCT numero) AS pedidos
                    FROM vendas
                    WHERE data BETWEEN ? AND ?
                      AND COALESCE(devolucao, 0) = 0
                      AND LOWER(COALESCE(situacao,'')) NOT IN ('cancelado','cancelada','cancelamento','cancelamento solicitado')
                      {sql_loja}
                    """,
                    [data_inicio, data_fim, *params_loja],
                ).fetchone()
                if row:
                    total_qtd += float(row["qtd"] or 0)
                    total_valor += float(row["valor"] or 0)
                    total_pedidos += int(row["pedidos"] or 0)
                conn.close()
            except Exception as exc:
                logger.warning(f"[IA TOOLS] Erro ao resumir vendas em {db_path}: {exc}")
                continue
        top_skus = _ia_vendas_db_top_skus(client_id, data_inicio, data_fim, loja_filtro, limite=limite)
        return {
            "function": "get_sales_by_period",
            "arguments": {"data_inicio": data_inicio, "data_fim": data_fim, "loja": loja_filtro or ""},
            "result": {
                "data_inicio": data_inicio,
                "data_fim": data_fim,
                "loja": loja_filtro or "",
                "quantidade_total": total_qtd,
                "valor_total": total_valor,
                "pedidos_total": total_pedidos,
                "top_skus": top_skus,
            },
        }
    except Exception as exc:
        logger.warning(f"[IA TOOLS] Falha ao obter vendas por perÃƒÂ­odo: {exc}")
        return None


