class IASalvarConversaRequest(BaseModel):
    conversa_id: str
    modulo: str
    titulo: str
    mensagens: list[dict]

@app.post("/api/ia/conversas/salvar")
async def ia_salvar_conversa(payload: IASalvarConversaRequest, request: Request, client_id: str = Depends(get_tenant_id)):
    """Salva uma conversa no servidor."""
    username = _extrair_username_do_request(request)
    sucesso = _ia_conversas_salvar(
        client_id,
        username,
        payload.modulo,
        payload.conversa_id,
        payload.titulo,
        payload.mensagens
    )
    return {
        "success": sucesso,
        "conversa_id": payload.conversa_id,
    }

@app.get("/api/ia/conversas/listar")
async def ia_listar_conversas(request: Request, modulo: str = None, client_id: str = Depends(get_tenant_id)):
    """Lista conversas salvas do cliente, opcionalmente filtradas por mÃƒÂ³dulo."""
    username = _extrair_username_do_request(request)
    conversas = _ia_conversas_listar(client_id, username, modulo)
    return {
        "success": True,
        "conversas": conversas,
    }

@app.get("/api/ia/conversas/{conversa_id}")
async def ia_carregar_conversa(conversa_id: str, request: Request, client_id: str = Depends(get_tenant_id)):
    """Carrega uma conversa completa com suas mensagens."""
    username = _extrair_username_do_request(request)
    conversa = _ia_conversas_carregar(client_id, conversa_id, username)
    if not conversa:
        raise HTTPException(status_code=404, detail="Conversa nÃ£o encontrada")
    return {
        "success": True,
        "conversa": conversa,
    }

@app.delete("/api/ia/conversas/{conversa_id}")
async def ia_deletar_conversa(conversa_id: str, request: Request, client_id: str = Depends(get_tenant_id)):
    """Deleta uma conversa e suas mensagens."""
    username = _extrair_username_do_request(request)
    sucesso = _ia_conversas_deletar(client_id, conversa_id, username)
    return {
        "success": sucesso,
        "conversa_id": conversa_id,
    }

@app.get("/api/ia/rag/status")
async def ia_rag_status(client_id: str = Depends(get_tenant_id)):
    cfg = _ia_rag_config()
    status = {
        **cfg,
        "client_id": client_id,
        "ollama_ok": False,
        "postgres_ok": False,
        "pgvector_ok": False,
    }

    try:
        requests.get(f"{cfg['ollama_base_url']}/api/tags", timeout=5).raise_for_status()
        status["ollama_ok"] = True
    except Exception as exc:
        status["ollama_error"] = str(exc)

    try:
        if psycopg is not None and _ia_rag_pg_dsn():
            with _ia_rag_conectar() as conn:
                with conn.cursor() as cur:
                    cur.execute("SELECT 1")
                    status["postgres_ok"] = True
                    cur.execute("SELECT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'vector') AS ok")
                    row = cur.fetchone() or {}
                    status["pgvector_ok"] = bool(row.get("ok"))
    except Exception as exc:
        status["postgres_error"] = str(exc)

    with IA_RAG_REINDEX_LOCK:
        status["reindex_active"] = bool(IA_RAG_REINDEX_ACTIVE.get(client_id))
        status["reindex_status"] = dict(IA_RAG_REINDEX_META.get(client_id) or {})

    return status

@app.post("/api/ia/rag/indexar")
async def ia_rag_indexar(payload: IARagIndexRequest, client_id: str = Depends(get_tenant_id)):
    if not _ia_rag_ativo():
        raise HTTPException(
            status_code=503,
            detail="RAG nao configurado. Defina IA_RAG_ENABLED=true e IA_VECTOR_DATABASE_URL no .env."
        )
    try:
        inseridos = _ia_rag_indexar_documentos(client_id, payload.documents or [])
    except Exception as exc:
        logger.exception(f"[IA RAG] Falha ao indexar documentos: {exc}")
        raise HTTPException(status_code=502, detail=str(exc))
    return {"success": True, "inseridos": inseridos}

@app.post("/api/ia/rag/reindexar")
async def ia_rag_reindexar(payload: IARagReindexRequest = IARagReindexRequest(), client_id: str = Depends(get_tenant_id)):
    if not _ia_rag_ativo():
        raise HTTPException(
            status_code=503,
            detail="RAG nao configurado. Defina IA_RAG_ENABLED=true e IA_VECTOR_DATABASE_URL no .env."
        )

    try:
        info = _ia_rag_iniciar_reindex_async(client_id, force=payload.force)
        return {
            "success": True,
            "background": True,
            **info,
        }
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception(f"[IA RAG] Falha ao iniciar reindex em background: {exc}")
        raise HTTPException(status_code=502, detail=str(exc))

def atualizar_api_loja(client_id: str, nome_loja: str, api_nome: str, dados_api: dict):
    """Cria ou atualiza uma loja e sua integraÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o para um cliente especÃƒÆ’Ã‚Â­fico."""
    lojas = carregar_lojas(client_id)
    encontrou = False
    for l in lojas:
        if l['nome'] == nome_loja:
            if 'integracoes' not in l:
                l['integracoes'] = {}
            atual = l['integracoes'].get(api_nome)
            if isinstance(atual, dict) and isinstance(dados_api, dict):
                merged = dict(atual)
                merged.update(dados_api)
                l['integracoes'][api_nome] = merged
            else:
                l['integracoes'][api_nome] = dados_api
            encontrou = True
            break
    if not encontrou:
        nova_loja = {"nome": nome_loja, "integracoes": {api_nome: dados_api}}
        lojas.append(nova_loja)
    salvar_lojas(client_id, lojas)

def desconectar_api_loja(client_id: str, nome_loja: str, api_nome: str) -> dict:
    lojas = carregar_lojas(client_id)
    for loja in lojas:
        if loja.get("nome") != nome_loja:
            continue
        integracoes = loja.setdefault("integracoes", {})
        integracoes[api_nome] = {"connected": False}
        salvar_lojas(client_id, lojas)
        return loja
    raise HTTPException(status_code=404, detail="Loja nao encontrada.")

def salvar_temp_auth(dados):
    with open(ARQUIVO_TEMP_AUTH, "w", encoding="utf-8") as f: 
        json.dump(dados, f, ensure_ascii=False)

def ler_temp_auth():
    if os.path.exists(ARQUIVO_TEMP_AUTH):
        try:
            with open(ARQUIVO_TEMP_AUTH, "r", encoding="utf-8") as f: return json.load(f)
        except: return None
    return None

def limpar_temp_auth():
    if os.path.exists(ARQUIVO_TEMP_AUTH):
        try: os.remove(ARQUIVO_TEMP_AUTH)
        except: pass

def auth_bling_get_link(client_id, state, redirect_uri=None):
    redirect_final = _resolver_redirect_uri_publica(saved_redirect_uri=redirect_uri)
    redirect = quote_plus(redirect_final)
    state_final = quote_plus(str(state or ""))
    return f"https://www.bling.com.br/Api/v3/oauth/authorize?response_type=code&client_id={client_id}&redirect_uri={redirect}&state={state_final}"

def auth_bling_exchange(client_id, client_secret, code, redirect_uri=None):
    url = "https://www.bling.com.br/Api/v3/oauth/token"
    credential = f"{client_id}:{client_secret}"
    headers = {
        "Authorization": f"Basic {base64.b64encode(credential.encode()).decode()}",
        "Content-Type": "application/x-www-form-urlencoded",
        "Accept": "application/json",
        "enable-jwt": "1",
    }
    redirect_final = _resolver_redirect_uri_bling(saved_redirect_uri=redirect_uri)
    payload = {"grant_type": "authorization_code", "code": code, "redirect_uri": redirect_final}
    try:
        resp = BLING_SESSION.post(url, headers=headers, data=payload, timeout=20)
        if resp.status_code == 200: return True, resp.json()
        return False, resp.text
    except Exception as e: return False, str(e)

def auth_ml_get_link(app_id, state, redirect_uri=None):
    redirect_final = _resolver_redirect_uri_publica(saved_redirect_uri=redirect_uri)
    params = {
        "response_type": "code",
        "client_id": app_id,
        "redirect_uri": redirect_final,
        "state": str(state or ""),
        "scope": "offline_access read write",
    }
    return "https://auth.mercadolivre.com.br/authorization?" + urlencode(params, quote_via=quote)

def auth_ml_exchange(app_id, client_secret, code, redirect_uri=None):
    url = "https://api.mercadolibre.com/oauth/token"
    headers = {"Content-Type": "application/x-www-form-urlencoded", "Accept": "application/json"}
    redirect_final = _resolver_redirect_uri_publica(saved_redirect_uri=redirect_uri)
    payload = {
        "grant_type": "authorization_code",
        "client_id": app_id,
        "client_secret": client_secret,
        "code": code,
        "redirect_uri": redirect_final
    }
    try:
        logger.info(f"[ML EXCHANGE] Iniciando...")
        logger.info(f"[ML EXCHANGE] URL: {url}")
        logger.info(f"[ML EXCHANGE] App ID: {app_id}")
        logger.info(f"[ML EXCHANGE] Redirect URI: {redirect_final}")
        logger.info(f"[ML EXCHANGE] Code (primeiros 20 chars): {code[:20] if code else 'VAZIO'}...")
        logger.info(f"[ML EXCHANGE] Headers: {headers}")
        
        resp = requests.post(url, headers=headers, data=payload, timeout=10)

        logger.info(f"[ML EXCHANGE] Status Code: {resp.status_code}")
        logger.info(f"[ML EXCHANGE] Response Headers: {dict(resp.headers)}")
        try:
            response_preview = resp.json()
            if isinstance(response_preview, dict):
                for token_key in ("access_token", "refresh_token"):
                    if response_preview.get(token_key):
                        response_preview[token_key] = str(response_preview[token_key])[:18] + "..."
                logger.info(f"[ML EXCHANGE] Response Body: {json.dumps(response_preview, ensure_ascii=False)[:1000]}")
            else:
                logger.info(f"[ML EXCHANGE] Response Body: {str(response_preview)[:1000]}")
        except Exception:
            logger.info(f"[ML EXCHANGE] Response Body (raw): {resp.text[:1000]}")
        
        if resp.status_code == 200:
            result = resp.json()
            logger.info(f"[ML EXCHANGE] Ã¢Å“â€¦ SUCCESS")
            logger.info(f"[ML EXCHANGE] Access Token: {result.get('access_token', 'N/A')[:30]}...")
            logger.info(f"[ML EXCHANGE] User ID: {result.get('user_id', 'N/A')}")
            return True, result
        
        logger.error(f"[ML EXCHANGE] Ã¢ÂÅ’ Erro {resp.status_code}")
        logger.error(f"[ML EXCHANGE] Response: {resp.text}")
        return False, resp.text
        
    except Exception as e:
        logger.exception(f"[ML EXCHANGE] Ã¢ÂÅ’ Exception: {e}")
        return False, str(e)

# --- BLING ESTOQUE HELPERS ---

def _bling_refresh_token(client_id, client_secret, refresh_token):
    url = "https://www.bling.com.br/Api/v3/oauth/token"
    credential = f"{client_id}:{client_secret}"
    headers = {
        "Authorization": f"Basic {base64.b64encode(credential.encode()).decode()}",
        "Content-Type": "application/x-www-form-urlencoded",
        "Accept": "application/json",
        "enable-jwt": "1",
    }
    payload = {"grant_type": "refresh_token", "refresh_token": refresh_token}
    try:
        resp = BLING_SESSION.post(url, headers=headers, data=payload, timeout=20)
    except requests.RequestException:
        logger.exception("[BLING] Erro de conexao ao atualizar token")
        raise HTTPException(
            status_code=503,
            detail="Nao foi possivel conectar ao Bling para renovar token no momento. Tente novamente em alguns minutos.",
        )

    if resp.status_code == 200:
        return resp.json()

    erro_tipo = ""
    erro_msg = ""
    erro_desc = ""
    try:
        payload_erro = resp.json() or {}
        err = payload_erro.get("error")
        if isinstance(err, dict):
            erro_tipo = str(err.get("type") or "").strip().lower()
            erro_msg = str(err.get("message") or "").strip().lower()
            erro_desc = str(err.get("description") or "").strip().lower()
        else:
            erro_msg = str(payload_erro.get("error") or "").strip().lower()
            erro_desc = str(payload_erro.get("error_description") or "").strip().lower()
    except Exception:
        pass

    if (
        resp.status_code == 400
        and (
            erro_tipo == "invalid_grant"
            or erro_msg == "invalid_grant"
            or "invalid refresh token" in erro_desc
        )
    ):
        raise HTTPException(
            status_code=401,
            detail="Token Bling expirado para esta loja. Refaça a conexão em Integrações para continuar.",
        )

    raise HTTPException(
        status_code=502,
        detail=f"Falha ao renovar token do Bling (HTTP {resp.status_code}).",
    )
def _bling_listar_produtos(access_token):
    url = "https://api.bling.com.br/Api/v3/produtos"
    headers = {"Authorization": f"Bearer {access_token}"}
    produtos = []
    limiter = _BlingAdaptiveLimiter(start_interval=0.08)

    # Busca produtos simples (P) e variaÃƒÂ§ÃƒÂµes (V), pois alguns SKUs podem existir somente como variaÃƒÂ§ÃƒÂ£o.
    for tipo in ("P", "V"):
        for pagina in range(1, 1000):
            resp = _bling_get_with_adaptive_limit(
                url,
                headers=headers,
                params={"pagina": pagina, "limite": 100, "tipo": tipo},
                timeout=20,
                limiter=limiter,
                max_attempts=6,
            )
            if resp is None:
                return None, 503
            if resp.status_code == 401:
                return None, 401
            if resp.status_code == 429:
                return None, 429
            if resp.status_code != 200:
                return None, resp.status_code
            try:
                data = resp.json().get("data", [])
            except Exception:
                logger.exception("[Bling] Resposta invalida ao listar produtos (tipo=%s, pagina=%s)", tipo, pagina)
                return None, 502
            if not data:
                break
            for p in data:
                ncm_val = p.get("ncm")
                if isinstance(ncm_val, dict):
                    ncm_val = ncm_val.get("codigo") or ncm_val.get("id") or ncm_val.get("valor")
                produtos.append({
                    "id_bling": p.get("id"),
                    "sku": p.get("codigo"),
                    "nome_bling": p.get("nome"),
                    "situacao_bling": p.get("situacao"),
                    "ncm_bling": str(ncm_val or "").strip()
                })

    vistos = set()
    produtos_unicos = []
    for p in produtos:
        chave = str(p.get("id_bling") or "").strip() or str(p.get("sku") or "").strip().upper()
        if not chave or chave in vistos:
            continue
        vistos.add(chave)
        produtos_unicos.append(p)
    return produtos_unicos, 200


def _bling_obter_ncm_cest_produto(access_token: str, produto_id: str):
    """Retorna NCM e CEST via endpoint de detalhe do produto; usado apenas em sincronizaÃƒÂ§ÃƒÂ£o opcional."""
    pid = str(produto_id or "").strip()
    if not pid:
        return {"ncm": "", "cest": ""}, 200
    headers = {"Authorization": f"Bearer {access_token}"}
    resp = _bling_get_with_adaptive_limit(
        f"https://api.bling.com.br/Api/v3/produtos/{pid}",
        headers=headers,
        timeout=20,
        limiter=_BlingAdaptiveLimiter(start_interval=0.08),
        max_attempts=5,
    )
    if resp is None:
        return {"ncm": "", "cest": ""}, 503
    if resp.status_code == 401:
        return {"ncm": "", "cest": ""}, 401
    if resp.status_code == 429:
        return {"ncm": "", "cest": ""}, 429
    if resp.status_code != 200:
        return {"ncm": "", "cest": ""}, resp.status_code

    try:
        data_det = resp.json().get("data", {}) or {}
        trib = data_det.get("tributacao") or {}

        ncm_det = trib.get("ncm") if isinstance(trib, dict) else data_det.get("ncm")
        if isinstance(ncm_det, dict):
            ncm_det = ncm_det.get("codigo") or ncm_det.get("id") or ncm_det.get("valor")
        ncm_str = str(ncm_det or "").strip()

        cest_str = ""
        if isinstance(trib, dict):
            cest_det = trib.get("cest")
            if cest_det:
                if isinstance(cest_det, dict):
                    cest_det = cest_det.get("codigo") or cest_det.get("id") or cest_det.get("valor")
                cest_str = str(cest_det or "").strip()

        if not cest_str:
            cest_det = data_det.get("cest")
            if cest_det:
                if isinstance(cest_det, dict):
                    cest_det = cest_det.get("codigo") or cest_det.get("id") or cest_det.get("valor")
                cest_str = str(cest_det or "").strip()

        if not cest_str and isinstance(trib, dict):
            for chave in trib.keys():
                if 'cest' in str(chave).lower():
                    valor = trib[chave]
                    if isinstance(valor, dict):
                        valor = valor.get("codigo") or valor.get("id") or valor.get("valor")
                    cest_str = str(valor or "").strip()
                    if cest_str:
                        break

        if not cest_str:
            def _buscar_cest_recursivo(obj):
                if isinstance(obj, dict):
                    for k, v in obj.items():
                        if "cest" in str(k).lower():
                            if isinstance(v, dict):
                                val = v.get("codigo") or v.get("id") or v.get("valor")
                            else:
                                val = v
                            val = str(val or "").strip()
                            if val:
                                return val
                        found = _buscar_cest_recursivo(v)
                        if found:
                            return found
                elif isinstance(obj, list):
                    for item in obj:
                        found = _buscar_cest_recursivo(item)
                        if found:
                            return found
                return ""

            cest_str = _buscar_cest_recursivo(data_det)

        return {"ncm": ncm_str, "cest": cest_str}, 200
    except Exception as e:
        logger.exception(f"Erro ao buscar NCM/CEST para {pid}: {e}")
        return {"ncm": "", "cest": ""}, 500


def _carregar_mapeamento_unidades():
    """Carrega mapeamento de IDs de unidades para nomes amigÃƒÂ¡veis."""
    mapeamento_path = os.path.join(PASTA_INFO, "unidades_nomes.json")
    mapeamento_padrao = {}
    
    try:
        if os.path.exists(mapeamento_path):
            with open(mapeamento_path, 'r', encoding='utf-8') as f:
                dados = json.load(f)
                # Remove aliases genÃƒÂ©ricos antigos (Unidade 2, Unidade Principal, etc.)
                if isinstance(dados, dict):
                    limpo = {}
                    alterado = False
                    for k, v in dados.items():
                        nome = str(v or "").strip()
                        nome_sem_prefixo = re.sub(r"^\s*Unidade\s+", "", nome, flags=re.IGNORECASE).strip()
                        if nome_sem_prefixo != nome:
                            alterado = True
                        nome = nome_sem_prefixo
                        if re.match(r"^Unidade(\s+\d+|\s+Principal)?$", nome, re.IGNORECASE):
                            alterado = True
                            continue
                        limpo[str(k)] = nome
                    if alterado:
                        try:
                            _salvar_mapeamento_unidades(limpo)
                        except Exception:
                            pass
                    return limpo
                return {}
    except Exception:
        pass
    
    # Criar arquivo padrÃƒÂ£o se nÃ£o existir
    try:
        os.makedirs(PASTA_INFO, exist_ok=True)
        with open(mapeamento_path, 'w', encoding='utf-8') as f:
            json.dump(mapeamento_padrao, f, indent=2, ensure_ascii=False)
    except Exception:
        pass
    
    return mapeamento_padrao

def _salvar_mapeamento_unidades(mapeamento: dict):
    """Salva mapeamento de IDs de unidades para nomes amigÃƒÂ¡veis."""
    mapeamento_path = os.path.join(PASTA_INFO, "unidades_nomes.json")
    try:
        os.makedirs(PASTA_INFO, exist_ok=True)
        with open(mapeamento_path, 'w', encoding='utf-8') as f:
            json.dump(mapeamento, f, indent=2, ensure_ascii=False)
        return True
    except Exception:
        return False

def _bling_buscar_unidade_negocio(access_token, unidade_id, cache=None, mapeamento=None):
    """Busca o nome de uma unidade de negÃƒÂ³cio por ID.
    Como a API nÃ£o expÃƒÂµe nomes, usa mapeamento manual."""
    if cache is None:
        cache = {}
    if mapeamento is None:
        mapeamento = {}
    
    unidade_id_str = str(unidade_id)
    
    # Verificar cache
    if unidade_id_str in cache:
        return cache[unidade_id_str]
    
    # Verificar mapeamento manual
    if unidade_id_str in mapeamento:
        nome = mapeamento[unidade_id_str]
        cache[unidade_id_str] = nome
        return nome
    
    # Fallback: usar ID formatado
    # Evita exibir fallback genÃƒÂ©rico que confunde com nome real da loja.
    fallback = ""
    cache[unidade_id_str] = fallback
    return fallback

def _bling_map_canais_venda_basico(access_token: str):
    """Retorna mapa {idCanalVenda: descricao} para usar como nome real da loja virtual."""
    headers = {"Authorization": f"Bearer {access_token}"}
    url = "https://api.bling.com.br/Api/v3/canais-venda"
    mapa = {}
    pagina = 1
    while True:
        try:
            resp = BLING_SESSION.get(url, headers=headers, params={"pagina": pagina, "limite": 100}, timeout=20)
        except requests.RequestException:
            break
        if resp.status_code == 401:
            return None, 401
        if resp.status_code != 200:
            break

        data = resp.json().get("data", [])
        if not data:
            break

        for item in data:
            cid = str(item.get("id") or "").strip()
            nome = str(item.get("descricao") or "").strip()
            if cid and nome:
                mapa[cid] = nome

        pagina += 1
        if pagina > 50:
            break

    return mapa, 200

def _bling_map_unidades_por_canais(access_token: str):
    """Monta mapa {idUnidadeNegocio: nome} a partir de Canais de Venda (filiais)."""
    headers = {"Authorization": f"Bearer {access_token}"}
    url_canais = "https://api.bling.com.br/Api/v3/canais-venda"
    mapa = {}
    pagina = 1

    while True:
        try:
            resp = BLING_SESSION.get(url_canais, headers=headers, params={"pagina": pagina, "limite": 100}, timeout=20)
        except requests.RequestException:
            break

        if resp.status_code == 401:
            return None, 401
        if resp.status_code != 200:
            break

        canais = resp.json().get("data", [])
        if not canais:
            break

        for canal in canais:
            cid = canal.get("id")
            if not cid:
                continue
            try:
                det = BLING_SESSION.get(f"https://api.bling.com.br/Api/v3/canais-venda/{cid}", headers=headers, timeout=20)
            except requests.RequestException:
                continue

            if det.status_code == 401:
                return None, 401
            if det.status_code != 200:
                continue

            data_det = det.json().get("data", {}) or {}
            for filial in data_det.get("filiais", []) or []:
                uid = str(filial.get("idUnidadeNegocio") or "").strip()
                nome = str(filial.get("unidadeNegocio") or "").strip()
                if uid and nome:
                    mapa[uid] = nome

        pagina += 1
        if pagina > 50:
            break

    return mapa, 200

