def _shared_sync_get_invite(invite_id: str) -> dict:
    invite_id = str(invite_id or "").strip()
    for item in _shared_sync_invites_all():
        if str(item.get("id") or "") == invite_id:
            return item
    raise HTTPException(status_code=404, detail="Convite de compartilhamento nao encontrado.")


def _shared_sync_get_link(link_id: str) -> dict:
    link_id = str(link_id or "").strip()
    for item in _shared_sync_links_all():
        if str(item.get("id") or "") == link_id:
            return item
    raise HTTPException(status_code=404, detail="Vinculo de compartilhamento nao encontrado.")


def _shared_sync_session_is_source(sessao: dict, item: dict) -> bool:
    return (
        _shared_sync_normalizar_username(sessao.get("username")) == _shared_sync_normalizar_username(item.get("source_username"))
        and _shared_sync_normalizar_client_id(sessao.get("client_id")) == _shared_sync_normalizar_client_id(item.get("source_client_id"))
    )


def _shared_sync_session_is_target(sessao: dict, item: dict) -> bool:
    return (
        _shared_sync_normalizar_username(sessao.get("username")) == _shared_sync_normalizar_username(item.get("target_username"))
        and _shared_sync_normalizar_client_id(sessao.get("client_id")) == _shared_sync_normalizar_client_id(item.get("target_client_id"))
    )


def _shared_sync_pair_key(source_client_id: str, source_username: str, target_client_id: str, target_username: str) -> tuple[str, str, str, str]:
    return (
        _shared_sync_normalizar_client_id(source_client_id),
        _shared_sync_normalizar_username(source_username),
        _shared_sync_normalizar_client_id(target_client_id),
        _shared_sync_normalizar_username(target_username),
    )


def _shared_sync_item_pair_key(item: dict) -> tuple[str, str, str, str]:
    return _shared_sync_pair_key(
        item.get("source_client_id"),
        item.get("source_username"),
        item.get("target_client_id"),
        item.get("target_username"),
    )


def _shared_sync_link_id_for_pair(item: dict) -> str:
    return _shared_sync_safe_doc_id("shared-sync-link", *_shared_sync_item_pair_key(item))


def _shared_sync_link_direction_parts(link: dict, direction_key: str) -> tuple[str, str, str, str]:
    if direction_key == "target_to_source":
        return (
            _shared_sync_normalizar_client_id(link.get("target_client_id")),
            _shared_sync_normalizar_username(link.get("target_username")),
            _shared_sync_normalizar_client_id(link.get("source_client_id")),
            _shared_sync_normalizar_username(link.get("source_username")),
        )
    return (
        _shared_sync_normalizar_client_id(link.get("source_client_id")),
        _shared_sync_normalizar_username(link.get("source_username")),
        _shared_sync_normalizar_client_id(link.get("target_client_id")),
        _shared_sync_normalizar_username(link.get("target_username")),
    )


def _shared_sync_link_direction_for_session(sessao: dict, link: dict) -> str:
    if _shared_sync_session_is_source(sessao, link):
        return "source_to_target"
    if _shared_sync_session_is_target(sessao, link):
        return "target_to_source"
    raise HTTPException(status_code=403, detail="Voce nao participa deste compartilhamento.")


def _shared_sync_link_reverse_direction(direction_key: str) -> str:
    return "source_to_target" if direction_key == "target_to_source" else "target_to_source"


def _shared_sync_link_bundle_id_for_direction(link: dict, scope: str, direction_key: str) -> str:
    directional = link.get("directional_bundles") if isinstance(link.get("directional_bundles"), dict) else {}
    direction_map = directional.get(direction_key) if isinstance(directional.get(direction_key), dict) else {}
    if direction_map.get(scope):
        return str(direction_map.get(scope))
    if direction_key == "source_to_target":
        bundles = link.get("bundles") if isinstance(link.get("bundles"), dict) else {}
        if bundles.get(scope):
            return str(bundles.get(scope))
    from_client, from_username, to_client, to_username = _shared_sync_link_direction_parts(link, direction_key)
    return _shared_sync_pair_doc_id(from_client, from_username, to_client, to_username, scope)


def _shared_sync_link_set_bundle_for_direction(link: dict, scope: str, direction_key: str, bundle_id: str) -> None:
    directional = link.get("directional_bundles") if isinstance(link.get("directional_bundles"), dict) else {}
    direction_map = directional.get(direction_key) if isinstance(directional.get(direction_key), dict) else {}
    direction_map[scope] = str(bundle_id or "")
    directional[direction_key] = direction_map
    link["directional_bundles"] = directional
    if direction_key == "source_to_target":
        bundles = link.get("bundles") if isinstance(link.get("bundles"), dict) else {}
        bundles[scope] = str(bundle_id or "")
        link["bundles"] = bundles


def _shared_sync_item_timestamp(item: dict) -> int:
    for key in ("updated_ts", "created_ts", "responded_ts"):
        try:
            value = int((item or {}).get(key) or 0)
            if value:
                return value
        except Exception:
            pass
    return 0


def _shared_sync_unir_scopes(*listas) -> list[str]:
    saida = []
    for lista in listas:
        for scope in lista or []:
            scope_norm = str(scope or "").strip()
            if scope_norm in SHARED_SYNC_SCOPES and scope_norm not in saida:
                saida.append(scope_norm)
    return saida


def _shared_sync_mesmo_par(item: dict, source_user: dict, target_user: dict) -> bool:
    return _shared_sync_item_pair_key(item) == _shared_sync_pair_key(
        source_user.get("client_id"),
        source_user.get("username"),
        target_user.get("client_id"),
        target_user.get("username"),
    )


def _shared_sync_find_pending_invite(source_user: dict, target_user: dict) -> Optional[dict]:
    candidatos = [
        item for item in _shared_sync_invites_all()
        if str(item.get("status") or "pending") == "pending"
        and _shared_sync_mesmo_par(item, source_user, target_user)
    ]
    if not candidatos:
        return None
    candidatos.sort(key=_shared_sync_item_timestamp, reverse=True)
    return candidatos[0]


def _shared_sync_find_active_link(source_user: dict, target_user: dict) -> Optional[dict]:
    candidatos = [
        item for item in _shared_sync_links_all()
        if bool(item.get("active", True))
        and _shared_sync_mesmo_par(item, source_user, target_user)
    ]
    if not candidatos:
        return None
    candidatos.sort(key=_shared_sync_item_timestamp, reverse=True)
    return candidatos[0]


def _shared_sync_merge_link_items(existing: dict, incoming: dict) -> dict:
    merged = dict(existing or {})
    incoming = dict(incoming or {})
    merged["id"] = merged.get("id") or incoming.get("id") or _shared_sync_link_id_for_pair(incoming or merged)
    merged["invite_id"] = merged.get("invite_id") or incoming.get("invite_id") or ""
    for key in ("source_username", "source_client_id", "source_name", "target_username", "target_client_id", "target_name", "created_at", "created_ts"):
        if not merged.get(key) and incoming.get(key):
            merged[key] = incoming.get(key)
    merged["active"] = bool(incoming.get("active", merged.get("active", True)))
    merged["source_is_admin"] = bool(merged.get("source_is_admin") or incoming.get("source_is_admin"))
    merged["source_keep_synced"] = bool(merged.get("source_keep_synced") or incoming.get("source_keep_synced"))
    merged["target_keep_synced"] = bool(merged.get("target_keep_synced") or incoming.get("target_keep_synced"))
    merged["scopes"] = _shared_sync_unir_scopes(merged.get("scopes"), incoming.get("scopes"))
    bundles = {}
    if isinstance(merged.get("bundles"), dict):
        bundles.update(merged.get("bundles") or {})
    if isinstance(incoming.get("bundles"), dict):
        bundles.update(incoming.get("bundles") or {})
    merged["bundles"] = bundles
    directional = {}
    if isinstance(merged.get("directional_bundles"), dict):
        directional.update(_shared_sync_json_clone(merged.get("directional_bundles") or {}))
    if isinstance(incoming.get("directional_bundles"), dict):
        for direction_key, value in (incoming.get("directional_bundles") or {}).items():
            current = directional.get(direction_key) if isinstance(directional.get(direction_key), dict) else {}
            if isinstance(value, dict):
                current.update(value)
            directional[direction_key] = current
    merged["directional_bundles"] = directional
    if _shared_sync_item_timestamp(incoming) >= _shared_sync_item_timestamp(merged):
        merged["updated_at"] = incoming.get("updated_at") or merged.get("updated_at") or _shared_sync_now_iso()
        merged["updated_ts"] = int(incoming.get("updated_ts") or merged.get("updated_ts") or time.time())
    return merged


def _shared_sync_session_is_admin(sessao: Optional[dict]) -> bool:
    if not isinstance(sessao, dict):
        return False
    permissoes = sessao.get("permissions") if isinstance(sessao.get("permissions"), dict) else {}
    return bool(sessao.get("is_admin") or permissoes.get("full") is True or permissoes.get("admin_usuarios") is True)


def _shared_sync_source_is_admin(item: dict, sessao: Optional[dict] = None) -> bool:
    if _shared_sync_session_is_admin(sessao):
        return True
    item = item or {}
    if bool(item.get("source_is_admin")):
        return True
    source_username = _shared_sync_normalizar_username(item.get("source_username"))
    source_client = _shared_sync_normalizar_client_id(item.get("source_client_id"))
    if source_username == "admin":
        return True
    if not source_username:
        return False
    try:
        permissoes = _carregar_permissoes_usuario(source_username, source_client)
        return bool(permissoes.get("full") is True or permissoes.get("admin_usuarios") is True)
    except Exception:
        return False


def _shared_sync_scope_permitido_entre_clientes(item: dict, scope: str, sessao: Optional[dict] = None) -> bool:
    if scope != "lojas_integracoes":
        return True
    if _shared_sync_source_is_admin(item, sessao):
        return True
    source_client = _shared_sync_normalizar_client_id((item or {}).get("source_client_id"))
    target_client = _shared_sync_normalizar_client_id((item or {}).get("target_client_id"))
    return bool(source_client and target_client and source_client == target_client)


def _shared_sync_filtrar_scopes_entre_clientes(scopes: list[str], item: dict, sessao: Optional[dict] = None) -> list[str]:
    saida = []
    for scope in scopes or []:
        if scope not in SHARED_SYNC_SCOPES:
            continue
        if not _shared_sync_scope_permitido_entre_clientes(item, scope, sessao):
            continue
        if scope not in saida:
            saida.append(scope)
    return saida


def _shared_sync_invite_public(item: dict, sessao: Optional[dict] = None) -> dict:
    scopes = _shared_sync_filtrar_scopes_entre_clientes(item.get("scopes") or [], item, sessao)
    prepare_errors = item.get("prepare_errors") if isinstance(item.get("prepare_errors"), list) else []
    try:
        prepare_progress = int(float(item.get("prepare_progress") or 0))
    except Exception:
        prepare_progress = 0
    prepare_progress = max(0, min(100, prepare_progress))
    try:
        prepare_done = int(float(item.get("prepare_done") or 0))
    except Exception:
        prepare_done = 0
    try:
        prepare_total = int(float(item.get("prepare_total") or 0))
    except Exception:
        prepare_total = 0
    return {
        "id": item.get("id"),
        "status": item.get("status") or "pending",
        "source_username": item.get("source_username") or "",
        "source_client_id": item.get("source_client_id") or "",
        "source_name": item.get("source_name") or "",
        "target_username": item.get("target_username") or "",
        "target_client_id": item.get("target_client_id") or "",
        "target_name": item.get("target_name") or "",
        "scopes": scopes,
        "scope_labels": [SHARED_SYNC_SCOPES[scope].get("label") or scope for scope in scopes],
        "message": item.get("message") or "",
        "source_keep_synced": bool(item.get("source_keep_synced")),
        "target_keep_synced": bool(item.get("target_keep_synced")),
        "prepare_status": item.get("prepare_status") or "ready",
        "prepare_progress": prepare_progress,
        "prepare_done": max(0, prepare_done),
        "prepare_total": max(0, prepare_total),
        "prepare_current_scope": item.get("prepare_current_scope") or "",
        "prepare_current_label": item.get("prepare_current_label") or "",
        "prepare_message": item.get("prepare_message") or "",
        "prepare_started_at": item.get("prepare_started_at") or "",
        "prepare_finished_at": item.get("prepare_finished_at") or "",
        "prepare_errors": prepare_errors[:10],
        "created_at": item.get("created_at") or "",
        "responded_at": item.get("responded_at") or "",
        "direction": (
            "sent" if sessao and _shared_sync_session_is_source(sessao, item)
            else "received" if sessao and _shared_sync_session_is_target(sessao, item)
            else ""
        ),
    }


def _shared_sync_link_sync_status_public(item: dict, sessao: Optional[dict], scopes: list[str]) -> dict:
    if not sessao:
        return {"scopes": {}, "pending_receive": 0}
    try:
        send_direction = _shared_sync_link_direction_for_session(sessao, item)
    except HTTPException:
        return {"scopes": {}, "pending_receive": 0}
    receive_direction = _shared_sync_link_reverse_direction(send_direction)
    state = _shared_sync_state_read(sessao.get("client_id"), sessao.get("username") or "")
    state_scopes = state.get("scopes") if isinstance(state.get("scopes"), dict) else {}
    por_scope = {}
    pending_receive = 0
    last_sent_at = ""
    last_received_at = ""
    for scope in scopes:
        send_bundle = _shared_sync_link_bundle_id_for_direction(item, scope, send_direction)
        receive_bundle = _shared_sync_link_bundle_id_for_direction(item, scope, receive_direction)
        send_meta = _shared_sync_remote_meta_by_id(send_bundle) or {}
        receive_meta = _shared_sync_remote_meta_by_id(receive_bundle) or {}
        send_state_key = _shared_sync_user_share_state_scope(item.get("id"), send_direction, scope)
        receive_state_key = _shared_sync_user_share_state_scope(item.get("id"), receive_direction, scope)
        send_state = state_scopes.get(send_state_key) if isinstance(state_scopes.get(send_state_key), dict) else {}
        receive_state = state_scopes.get(receive_state_key) if isinstance(state_scopes.get(receive_state_key), dict) else {}
        remote_hash = str(receive_meta.get("snapshot_hash") or "")
        received_hash = str(receive_state.get("snapshot_hash") or "")
        has_pending = bool(receive_meta and remote_hash and remote_hash != received_hash)
        if has_pending:
            pending_receive += 1
        last_sent_at = max(last_sent_at, str(send_meta.get("updated_at") or ""))
        last_received_at = max(last_received_at, str(receive_state.get("synced_at") or ""))
        por_scope[scope] = {
            "label": (SHARED_SYNC_SCOPES.get(scope) or {}).get("label") or scope,
            "send_direction": send_direction,
            "receive_direction": receive_direction,
            "send": {
                "exists": bool(send_meta),
                "updated_at": send_meta.get("updated_at") or "",
                "updated_by": send_meta.get("updated_by") or "",
                "item_count": send_meta.get("item_count") or 0,
                "file_count": send_meta.get("file_count") or 0,
                "skipped": bool(send_state.get("skipped")),
                "state": send_state,
            },
            "receive": {
                "exists": bool(receive_meta),
                "updated_at": receive_meta.get("updated_at") or "",
                "updated_by": receive_meta.get("updated_by") or "",
                "item_count": receive_meta.get("item_count") or 0,
                "file_count": receive_meta.get("file_count") or 0,
                "pending": has_pending,
                "state": receive_state,
            },
            "known_count": _shared_sync_user_share_known_count(state, item.get("id"), scope),
        }
    return {
        "send_direction": send_direction,
        "receive_direction": receive_direction,
        "pending_receive": pending_receive,
        "last_sent_at": last_sent_at,
        "last_received_at": last_received_at,
        "scopes": por_scope,
    }


def _shared_sync_link_public(item: dict, sessao: Optional[dict] = None) -> dict:
    scopes = _shared_sync_filtrar_scopes_entre_clientes(item.get("scopes") or [], item, sessao)
    source = sessao and _shared_sync_session_is_source(sessao, item)
    target = sessao and _shared_sync_session_is_target(sessao, item)
    return {
        "id": item.get("id"),
        "invite_id": item.get("invite_id") or "",
        "active": bool(item.get("active", True)),
        "source_username": item.get("source_username") or "",
        "source_client_id": item.get("source_client_id") or "",
        "source_name": item.get("source_name") or "",
        "target_username": item.get("target_username") or "",
        "target_client_id": item.get("target_client_id") or "",
        "target_name": item.get("target_name") or "",
        "scopes": scopes,
        "scope_labels": [SHARED_SYNC_SCOPES[scope].get("label") or scope for scope in scopes],
        "source_keep_synced": bool(item.get("source_keep_synced")),
        "target_keep_synced": bool(item.get("target_keep_synced")),
        "auto_sync_enabled": bool(item.get("active", True) and item.get("source_keep_synced") and item.get("target_keep_synced")),
        "created_at": item.get("created_at") or "",
        "updated_at": item.get("updated_at") or "",
        "direction": "source" if source else "target" if target else "",
        "can_push": bool((source or target) and item.get("active", True)),
        "can_pull": bool((source or target) and item.get("active", True)),
        "sync_status": _shared_sync_link_sync_status_public(item, sessao, scopes),
    }


def _shared_sync_user_shares_for_session(sessao: dict) -> dict:
    invites_por_par = {}
    for item in _shared_sync_invites_all():
        if _shared_sync_session_is_source(sessao, item) or _shared_sync_session_is_target(sessao, item):
            status = str(item.get("status") or "pending")
            key = (*_shared_sync_item_pair_key(item), status)
            atual = invites_por_par.get(key)
            if not atual or _shared_sync_item_timestamp(item) >= _shared_sync_item_timestamp(atual):
                invites_por_par[key] = item
    links_por_par = {}
    for item in _shared_sync_links_all():
        if _shared_sync_session_is_source(sessao, item) or _shared_sync_session_is_target(sessao, item):
            key = _shared_sync_item_pair_key(item)
            atual = links_por_par.get(key)
            links_por_par[key] = _shared_sync_merge_link_items(atual, item) if atual else item
    invites = [_shared_sync_invite_public(item, sessao) for item in invites_por_par.values()]
    links = [_shared_sync_link_public(item, sessao) for item in links_por_par.values()]
    invites.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    links.sort(key=lambda item: str(item.get("updated_at") or item.get("created_at") or ""), reverse=True)
    return {
        "success": True,
        "backend": "firebase" if _firebase_deve_usar() else "local",
        "scopes": {scope: _shared_sync_scope_public(scope) for scope in SHARED_SYNC_SCOPES},
        "invites": invites,
        "links": links,
    }


def _shared_sync_link_bundle_id(link: dict, scope: str) -> str:
    return _shared_sync_link_bundle_id_for_direction(link, scope, "source_to_target")


def _shared_sync_push_pair_scope(source_sessao: dict, target: dict, scope: str, machine_id: str = "", link_id: str = "", invite_id: str = "") -> dict:
    item_ref = {
        "source_client_id": source_sessao.get("client_id"),
        "source_username": source_sessao.get("username"),
        "source_is_admin": _shared_sync_session_is_admin(source_sessao),
        "target_client_id": target.get("client_id"),
        "target_username": target.get("username"),
    }
    if not _shared_sync_scope_permitido_entre_clientes(item_ref, scope, source_sessao):
        raise HTTPException(status_code=400, detail="Lojas e integracoes nao podem ser compartilhadas entre clientes diferentes.")
    link_ref = {
        "id": str(link_id or _shared_sync_link_id_for_pair({
            "source_client_id": source_sessao.get("client_id"),
            "source_username": source_sessao.get("username"),
            "target_client_id": target.get("client_id"),
            "target_username": target.get("username"),
        })),
        "source_client_id": source_sessao.get("client_id"),
        "source_username": source_sessao.get("username"),
        "target_client_id": target.get("client_id"),
        "target_username": target.get("username"),
    }
    direction_key = "source_to_target"
    bundle_id = _shared_sync_pair_doc_id(
        source_sessao.get("client_id"),
        source_sessao.get("username"),
        target.get("client_id"),
        target.get("username"),
        scope,
    )
    known_keys = _shared_sync_user_share_known_keys(source_sessao.get("client_id"), source_sessao.get("username") or "", link_ref["id"], scope)
    result = _shared_sync_push_scope(
        source_sessao.get("client_id"),
        scope,
        source_sessao,
        machine_id,
        bundle_id=bundle_id,
        extra_meta={
            "visibility": "user-share",
            "source_client_id": _shared_sync_normalizar_client_id(source_sessao.get("client_id")),
            "source_username": _shared_sync_normalizar_username(source_sessao.get("username")),
            "target_client_id": _shared_sync_normalizar_client_id(target.get("client_id")),
            "target_username": _shared_sync_normalizar_username(target.get("username")),
            "invite_id": str(invite_id or ""),
            "link_id": str(link_id or ""),
        },
        user_only=True,
        state_scope=_shared_sync_user_share_state_scope(link_ref["id"], direction_key, scope),
        known_keys=known_keys,
        allow_empty_delta=True,
    )
    _shared_sync_user_share_add_known_keys(source_sessao.get("client_id"), source_sessao.get("username") or "", link_ref["id"], scope, result.get("item_keys") or [])
    return result


def _shared_sync_exception_message(exc: Exception) -> str:
    detail = getattr(exc, "detail", None)
    if isinstance(detail, str) and detail.strip():
        return detail.strip()
    return str(exc or "").strip() or "Erro ao preparar dados."


def _shared_sync_scope_label(scope: str) -> str:
    return (SHARED_SYNC_SCOPES.get(scope) or {}).get("label") or str(scope or "")


def _shared_sync_save_invite_prepare_progress(
    invite_id: str,
    *,
    status: str = "preparing",
    done: int = 0,
    total: int = 0,
    current_scope: str = "",
    message: str = "",
) -> None:
    try:
        invite = _shared_sync_get_invite(invite_id)
    except Exception:
        return
    total_int = max(0, int(total or 0))
    done_int = max(0, min(total_int or done, int(done or 0)))
    final_status = str(status or "preparing").strip().lower()
    if final_status in {"ready", "partial", "failed"}:
        progress = 100
    elif total_int:
        progress = int(round((done_int / total_int) * 100))
    else:
        progress = 0
    progress = max(0, min(100, progress))
    agora = _shared_sync_now_iso()
    invite["prepare_status"] = final_status
    invite["prepare_done"] = done_int
    invite["prepare_total"] = total_int
    invite["prepare_progress"] = progress
    invite["prepare_current_scope"] = str(current_scope or "")
    invite["prepare_current_label"] = _shared_sync_scope_label(current_scope) if current_scope else ""
    invite["prepare_message"] = str(message or "").strip()
    invite["updated_at"] = agora
    invite["updated_ts"] = int(time.time())
    if final_status == "preparing" and not invite.get("prepare_started_at"):
        invite["prepare_started_at"] = agora
    if final_status in {"ready", "partial", "failed"}:
        invite["prepare_finished_at"] = agora
    _shared_sync_save_invite(invite)


def _shared_sync_mark_invite_prepare_failed(invite_id: str, exc: Exception) -> None:
    try:
        invite = _shared_sync_get_invite(invite_id)
    except Exception:
        return
    message = _shared_sync_exception_message(exc)
    agora = _shared_sync_now_iso()
    invite["status"] = "failed"
    invite["prepare_status"] = "failed"
    invite["prepare_progress"] = 100
    invite["prepare_message"] = message
    invite["prepare_finished_at"] = agora
    invite["prepare_errors"] = [{
        "scope": str(invite.get("prepare_current_scope") or ""),
        "label": str(invite.get("prepare_current_label") or "Preparação"),
        "message": message,
    }]
    invite["updated_at"] = agora
    invite["updated_ts"] = int(time.time())
    _shared_sync_save_invite(invite)


def _shared_sync_prepare_invite_packages(invite_id: str, source_sessao: dict, destino: dict, scopes: list[str], machine_id: str = "") -> None:
    try:
        _shared_sync_prepare_invite_packages_impl(invite_id, source_sessao, destino, scopes, machine_id)
    except Exception as exc:
        logger.exception("[SHARED-SYNC] Erro inesperado ao preparar convite %s: %s", invite_id, exc)
        _shared_sync_mark_invite_prepare_failed(invite_id, exc)


def _shared_sync_prepare_invite_packages_impl(invite_id: str, source_sessao: dict, destino: dict, scopes: list[str], machine_id: str = "") -> None:
    bundles: dict[str, str] = {}
    results: list[dict] = []
    errors: list[dict] = []
    scopes = [scope for scope in (scopes or []) if scope in SHARED_SYNC_SCOPES]
    total = len(scopes)
    _shared_sync_save_invite_prepare_progress(
        invite_id,
        status="preparing",
        done=0,
        total=total,
        message="Iniciando preparação dos dados.",
    )
    link_id = _shared_sync_link_id_for_pair({
        "source_client_id": source_sessao.get("client_id"),
        "source_username": source_sessao.get("username"),
        "target_client_id": destino.get("client_id"),
        "target_username": destino.get("username"),
    })
    for index, scope in enumerate(scopes, start=1):
        label = _shared_sync_scope_label(scope)
        _shared_sync_save_invite_prepare_progress(
            invite_id,
            status="preparing",
            done=index - 1,
            total=total,
            current_scope=scope,
            message=f"Preparando {label}.",
        )
        try:
            result = _shared_sync_push_pair_scope(source_sessao, destino, scope, machine_id, link_id=link_id, invite_id=invite_id)
            bundles[scope] = result.get("id") or _shared_sync_pair_doc_id(
                source_sessao.get("client_id"),
                source_sessao.get("username"),
                destino.get("client_id"),
                destino.get("username"),
                scope,
            )
            results.append(result)
            _shared_sync_save_invite_prepare_progress(
                invite_id,
                status="preparing",
                done=index,
                total=total,
                current_scope=scope,
                message=f"{label} preparado.",
            )
        except Exception as exc:
            logger.warning("[SHARED-SYNC] Falha ao preparar escopo %s do convite %s: %s", scope, invite_id, exc)
            errors.append({
                "scope": scope,
                "label": label,
                "message": _shared_sync_exception_message(exc),
            })
            _shared_sync_save_invite_prepare_progress(
                invite_id,
                status="preparing",
                done=index,
                total=total,
                current_scope=scope,
                message=f"{label} falhou; seguindo para o próximo dado.",
            )

    try:
        invite = _shared_sync_get_invite(invite_id)
    except Exception:
        return

    agora = _shared_sync_now_iso()
    invite["bundles"] = bundles
    invite["directional_bundles"] = {"source_to_target": dict(bundles)}
    invite["prepared_results"] = results
    invite["prepare_errors"] = errors
    invite["prepare_done"] = total
    invite["prepare_total"] = total
    invite["prepare_progress"] = 100
    invite["prepare_current_scope"] = ""
    invite["prepare_current_label"] = ""
    invite["prepare_finished_at"] = agora
    invite["updated_at"] = agora
    invite["updated_ts"] = int(time.time())
    if bundles:
        invite["scopes"] = [scope for scope in scopes if scope in bundles]
        invite["prepare_status"] = "partial" if errors else "ready"
        invite["prepare_message"] = "Preparação parcial. Alguns dados falharam." if errors else "Dados preparados. Aguardando aceite."
    else:
        invite["status"] = "failed"
        invite["prepare_status"] = "failed"
        invite["scopes"] = scopes
        invite["prepare_message"] = "Nenhum dado foi preparado. Confira as falhas."
    _shared_sync_save_invite(invite)


def _shared_sync_start_invite_prepare_thread(invite_id: str, source_sessao: dict, destino: dict, scopes: list[str], machine_id: str = "") -> None:
    thread = threading.Thread(
        target=_shared_sync_prepare_invite_packages,
        args=(invite_id, dict(source_sessao or {}), dict(destino or {}), list(scopes or []), str(machine_id or "")),
        name=f"shared-sync-invite-{invite_id[:8]}",
        daemon=True,
    )
    thread.start()


def _shared_sync_pull_pair_scope(target_sessao: dict, link: dict, scope: str) -> dict:
    if not _shared_sync_scope_permitido_entre_clientes(link, scope, target_sessao):
        raise HTTPException(status_code=400, detail="Lojas e integracoes nao podem ser importadas entre clientes diferentes.")
    my_direction = _shared_sync_link_direction_for_session(target_sessao, link)
    receive_direction = _shared_sync_link_reverse_direction(my_direction)
    bundle_id = _shared_sync_link_bundle_id_for_direction(link, scope, receive_direction)
    bundle, meta = _shared_sync_obter_bundle_por_id(bundle_id)
    manifest = _shared_sync_manifest_from_bundle(bundle)
    scope_config = {"user_share": True, "share_between_users": True}
    result = _shared_sync_aplicar_pacote(target_sessao.get("client_id"), scope, bundle, target_sessao.get("username") or "", scope_config)
    state_scope = _shared_sync_user_share_state_scope(link.get("id"), receive_direction, scope)
    _shared_sync_state_update(target_sessao.get("client_id"), target_sessao.get("username") or "", state_scope, meta, "pull")
    _shared_sync_user_share_add_known_keys(
        target_sessao.get("client_id"),
        target_sessao.get("username") or "",
        link.get("id"),
        scope,
        manifest.get("item_keys") or [],
    )
    return {
        "scope": scope,
        "success": True,
        "direction": "pull",
        "sync_direction": receive_direction,
        "link_id": link.get("id"),
        "file_count": result.get("file_count") or 0,
        "item_count": manifest.get("item_count") or meta.get("item_count") or 0,
        "backup_dir": result.get("backup_dir") or "",
        "snapshot_hash": meta.get("snapshot_hash") or "",
        "remote_updated_at": meta.get("updated_at") or "",
        "remote_updated_by": meta.get("updated_by") or "",
    }


def _shared_sync_push_link_scope(source_sessao: dict, link: dict, scope: str, machine_id: str = "") -> dict:
    direction_key = _shared_sync_link_direction_for_session(source_sessao, link)
    if not _shared_sync_scope_permitido_entre_clientes(link, scope, source_sessao):
        raise HTTPException(status_code=400, detail="Lojas e integracoes nao podem ser compartilhadas entre clientes diferentes.")
    from_client, from_username, to_client, to_username = _shared_sync_link_direction_parts(link, direction_key)
    bundle_id = _shared_sync_link_bundle_id_for_direction(link, scope, direction_key)
    known_keys = _shared_sync_user_share_known_keys(source_sessao.get("client_id"), source_sessao.get("username") or "", link.get("id"), scope)
    result = _shared_sync_push_scope(
        source_sessao.get("client_id"),
        scope,
        source_sessao,
        machine_id,
        bundle_id=bundle_id,
        extra_meta={
            "visibility": "user-share",
            "source_client_id": from_client,
            "source_username": from_username,
            "target_client_id": to_client,
            "target_username": to_username,
            "sync_direction": direction_key,
            "invite_id": link.get("invite_id") or "",
            "link_id": link.get("id") or "",
        },
        user_only=True,
        state_scope=_shared_sync_user_share_state_scope(link.get("id"), direction_key, scope),
        known_keys=known_keys,
        allow_empty_delta=False,
    )
    if result.get("skipped"):
        state = _shared_sync_state_read(source_sessao.get("client_id"), source_sessao.get("username") or "")
        scopes_state = state.setdefault("scopes", {})
        scopes_state[_shared_sync_user_share_state_scope(link.get("id"), direction_key, scope)] = {
            "direction": "push",
            "skipped": True,
            "reason": result.get("reason") or "already_shared",
            "synced_at": _shared_sync_now_iso(),
        }
        _shared_sync_state_write(source_sessao.get("client_id"), source_sessao.get("username") or "", state)
        return result
    _shared_sync_link_set_bundle_for_direction(link, scope, direction_key, result.get("id") or bundle_id)
    _shared_sync_user_share_add_known_keys(source_sessao.get("client_id"), source_sessao.get("username") or "", link.get("id"), scope, result.get("item_keys") or [])
    link["updated_at"] = _shared_sync_now_iso()
    link["updated_ts"] = int(time.time())
    _shared_sync_save_link(link)
    return result


@app.get("/api/shared-sync/users")
def shared_sync_listar_usuarios_destino(
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    atual_username = _shared_sync_normalizar_username(sessao.get("username"))
    atual_client = _shared_sync_normalizar_client_id(sessao.get("client_id"))
    usuarios = []
    for item in _listar_usuarios_admin_sql():
        usuario = _shared_sync_usuario_publico(item)
        if not usuario.get("active"):
            continue
        if (
            _shared_sync_normalizar_username(usuario.get("username")) == atual_username
            and _shared_sync_normalizar_client_id(usuario.get("client_id")) == atual_client
        ):
            continue
        usuarios.append(usuario)
    usuarios.sort(key=lambda item: (_shared_sync_normalizar_client_id(item.get("client_id")), _shared_sync_normalizar_username(item.get("username"))))
    return {
        "success": True,
        "users": usuarios,
        "current_user": {
            "username": atual_username,
            "client_id": atual_client,
        },
    }


@app.get("/api/shared-sync/user-shares")
def shared_sync_user_shares_status(
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    return _shared_sync_user_shares_for_session(sessao)


@app.post("/api/shared-sync/user-shares/invite")
def shared_sync_user_shares_invite(
    payload: SharedSyncUserInviteCreateRequest,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    scopes = _shared_sync_resolver_scopes_usuario(payload.scopes)
    destino = _shared_sync_resolver_usuario_destino(payload.target_username, payload.target_client_id)
    source_user = _shared_sync_usuario_publico(sessao.get("usuario") or {})
    source_user["username"] = _shared_sync_normalizar_username(sessao.get("username"))
    source_user["client_id"] = _shared_sync_normalizar_client_id(sessao.get("client_id"))
    if (
        _shared_sync_normalizar_username(destino.get("username")) == _shared_sync_normalizar_username(sessao.get("username"))
        and _shared_sync_normalizar_client_id(destino.get("client_id")) == _shared_sync_normalizar_client_id(sessao.get("client_id"))
    ):
        raise HTTPException(status_code=400, detail="Escolha outro usuario para receber os dados.")
    if _shared_sync_find_active_link(source_user, destino):
        raise HTTPException(status_code=409, detail="Ja existe um compartilhamento ativo com esse usuario. Use o botao Enviar agora no vinculo existente.")
    pending_invite = _shared_sync_find_pending_invite(source_user, destino)
    if pending_invite:
        agora = _shared_sync_now_iso()
        pending_invite["scopes"] = _shared_sync_unir_scopes(pending_invite.get("scopes"), scopes)
        if str(payload.message or "").strip():
            pending_invite["message"] = str(payload.message or "").strip()[:1000]
        pending_invite["source_is_admin"] = bool(pending_invite.get("source_is_admin") or _shared_sync_session_is_admin(sessao))
        pending_invite["source_keep_synced"] = bool(pending_invite.get("source_keep_synced") or payload.keep_synced)
        pending_invite["prepare_status"] = "preparing"
        pending_invite["prepare_progress"] = 0
        pending_invite["prepare_done"] = 0
        pending_invite["prepare_total"] = len(pending_invite.get("scopes") or scopes)
        pending_invite["prepare_current_scope"] = ""
        pending_invite["prepare_current_label"] = ""
        pending_invite["prepare_message"] = "Aguardando início da preparação."
        pending_invite["prepare_started_at"] = agora
        pending_invite["prepare_finished_at"] = ""
        pending_invite["prepare_errors"] = []
        pending_invite["updated_at"] = agora
        pending_invite["updated_ts"] = int(time.time())
        pending_invite["source_machine_id"] = str(payload.machine_id or pending_invite.get("source_machine_id") or "").strip()
        pending_invite = _shared_sync_save_invite(pending_invite)
        _shared_sync_start_invite_prepare_thread(pending_invite.get("id") or "", sessao, destino, pending_invite.get("scopes") or scopes, payload.machine_id or "")
        return {
            "success": True,
            "message": "Convite pendente atualizado. Preparando os dados novamente em segundo plano.",
            "invite": _shared_sync_invite_public(pending_invite, sessao),
            "results": [],
        }

    invite_id = uuid.uuid4().hex

    agora = _shared_sync_now_iso()
    invite = {
        "id": invite_id,
        "status": "pending",
        "source_username": source_user.get("username"),
        "source_client_id": source_user.get("client_id"),
        "source_name": source_user.get("name") or source_user.get("username"),
        "source_is_admin": _shared_sync_session_is_admin(sessao),
        "target_username": destino.get("username"),
        "target_client_id": destino.get("client_id"),
        "target_name": destino.get("name") or destino.get("username"),
        "scopes": scopes,
        "bundles": {},
        "message": str(payload.message or "").strip()[:1000],
        "source_keep_synced": bool(payload.keep_synced),
        "target_keep_synced": False,
        "prepare_status": "preparing",
        "prepare_progress": 0,
        "prepare_done": 0,
        "prepare_total": len(scopes),
        "prepare_current_scope": "",
        "prepare_current_label": "",
        "prepare_message": "Aguardando início da preparação.",
        "prepare_started_at": agora,
        "prepare_finished_at": "",
        "prepare_errors": [],
        "created_at": agora,
        "created_ts": int(time.time()),
        "updated_at": agora,
        "updated_ts": int(time.time()),
        "source_machine_id": str(payload.machine_id or "").strip(),
    }
    invite = _shared_sync_save_invite(invite)
    _shared_sync_start_invite_prepare_thread(invite_id, sessao, destino, scopes, payload.machine_id or "")
    firebase_ok = invite.get("storage") == "firebase"
    return {
        "success": True,
        "message": (
            "Convite enviado. Preparando os dados em segundo plano."
            if firebase_ok
            else "Convite salvo localmente, mas o Firebase nao confirmou o envio para outra maquina."
        ),
        "invite": _shared_sync_invite_public(invite, sessao),
        "results": [],
    }


@app.post("/api/shared-sync/user-shares/invites/{invite_id}/accept")
def shared_sync_user_shares_accept(
    invite_id: str,
    payload: SharedSyncUserInviteActionRequest,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    invite = _shared_sync_get_invite(invite_id)
    if not _shared_sync_session_is_target(sessao, invite):
        raise HTTPException(status_code=403, detail="Apenas o usuario de destino pode aceitar este convite.")
    if str(invite.get("status") or "pending") != "pending":
        raise HTTPException(status_code=400, detail="Este convite ja foi respondido.")
    prepare_status = str(invite.get("prepare_status") or "ready").strip().lower()
    if prepare_status == "preparing":
        raise HTTPException(status_code=409, detail="Convite ainda esta preparando os dados. Tente novamente em alguns instantes.")
    if prepare_status == "failed":
        raise HTTPException(status_code=400, detail="A origem nao conseguiu preparar os dados deste convite.")

    scopes = _shared_sync_resolver_scopes_usuario(invite.get("scopes") or [])
    scopes = _shared_sync_filtrar_scopes_entre_clientes(scopes, invite, sessao)
    bundles = invite.get("bundles") if isinstance(invite.get("bundles"), dict) else {}
    scopes = [scope for scope in scopes if bundles.get(scope)]
    if not scopes:
        raise HTTPException(status_code=400, detail="Convite sem pacote de dados disponivel para importar.")
    link_id = _shared_sync_link_id_for_pair(invite)
    link = {
        "id": link_id,
        "invite_id": invite.get("id"),
        "active": True,
        "source_username": invite.get("source_username"),
        "source_client_id": invite.get("source_client_id"),
        "source_name": invite.get("source_name") or invite.get("source_username"),
        "source_is_admin": bool(invite.get("source_is_admin") or _shared_sync_source_is_admin(invite)),
        "target_username": invite.get("target_username"),
        "target_client_id": invite.get("target_client_id"),
        "target_name": invite.get("target_name") or invite.get("target_username"),
        "scopes": scopes,
        "bundles": invite.get("bundles") if isinstance(invite.get("bundles"), dict) else {},
        "directional_bundles": invite.get("directional_bundles") if isinstance(invite.get("directional_bundles"), dict) else {"source_to_target": invite.get("bundles") if isinstance(invite.get("bundles"), dict) else {}},
        "source_keep_synced": bool(invite.get("source_keep_synced")),
        "target_keep_synced": bool(payload.keep_synced),
        "created_at": _shared_sync_now_iso(),
        "created_ts": int(time.time()),
        "updated_at": _shared_sync_now_iso(),
        "updated_ts": int(time.time()),
    }
    for existing in _shared_sync_links_all():
        if str(existing.get("id") or "") == link_id or _shared_sync_item_pair_key(existing) == _shared_sync_item_pair_key(link):
            link = _shared_sync_merge_link_items(existing, link)
            link["id"] = link_id
            link["active"] = True
            link["updated_at"] = _shared_sync_now_iso()
            link["updated_ts"] = int(time.time())
            break

    results = []
    for scope in scopes:
        results.append(_shared_sync_pull_pair_scope(sessao, link, scope))

    agora = _shared_sync_now_iso()
    invite["status"] = "accepted"
    invite["target_keep_synced"] = bool(payload.keep_synced)
    invite["responded_at"] = agora
    invite["responded_ts"] = int(time.time())
    invite["updated_at"] = agora
    invite["updated_ts"] = int(time.time())
    _shared_sync_save_invite(invite)
    _shared_sync_save_link(link)
    return {
        "success": True,
        "message": "Convite aceito e dados importados.",
        "invite": _shared_sync_invite_public(invite, sessao),
        "link": _shared_sync_link_public(link, sessao),
        "results": results,
    }


@app.post("/api/shared-sync/user-shares/invites/{invite_id}/reject")
def shared_sync_user_shares_reject(
    invite_id: str,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    invite = _shared_sync_get_invite(invite_id)
    if not _shared_sync_session_is_target(sessao, invite):
        raise HTTPException(status_code=403, detail="Apenas o usuario de destino pode recusar este convite.")
    if str(invite.get("status") or "pending") != "pending":
        raise HTTPException(status_code=400, detail="Este convite ja foi respondido.")
    agora = _shared_sync_now_iso()
    invite["status"] = "rejected"
    invite["responded_at"] = agora
    invite["responded_ts"] = int(time.time())
    invite["updated_at"] = agora
    invite["updated_ts"] = int(time.time())
    _shared_sync_save_invite(invite)
    return {"success": True, "message": "Convite recusado.", "invite": _shared_sync_invite_public(invite, sessao)}


@app.put("/api/shared-sync/user-shares/links/{link_id}")
def shared_sync_user_shares_link_update(
    link_id: str,
    payload: SharedSyncUserLinkUpdateRequest,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    link = _shared_sync_get_link(link_id)
    is_source = _shared_sync_session_is_source(sessao, link)
    is_target = _shared_sync_session_is_target(sessao, link)
    if not (is_source or is_target):
        raise HTTPException(status_code=403, detail="Voce nao participa deste compartilhamento.")
    if payload.keep_synced is not None:
        if is_source:
            link["source_keep_synced"] = bool(payload.keep_synced)
        if is_target:
            link["target_keep_synced"] = bool(payload.keep_synced)
    if payload.active is not None and payload.active is False:
        link["active"] = False
        link["stopped_by"] = sessao.get("username")
        link["stopped_at"] = _shared_sync_now_iso()
    elif payload.active is not None and payload.active is True:
        link["active"] = True
    link["updated_at"] = _shared_sync_now_iso()
    link["updated_ts"] = int(time.time())
    _shared_sync_save_link(link)
    return {"success": True, "message": "Preferencias atualizadas.", "link": _shared_sync_link_public(link, sessao)}


@app.post("/api/shared-sync/user-shares/links/{link_id}/push")
def shared_sync_user_shares_link_push(
    link_id: str,
    payload: SharedSyncUserLinkRunRequest,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    link = _shared_sync_get_link(link_id)
    if not bool(link.get("active", True)):
        raise HTTPException(status_code=400, detail="Compartilhamento pausado.")
    _shared_sync_link_direction_for_session(sessao, link)
    scopes = _shared_sync_resolver_scopes_usuario(payload.scopes or link.get("scopes") or [])
    scopes = _shared_sync_filtrar_scopes_entre_clientes(scopes, link, sessao)
    results = [_shared_sync_push_link_scope(sessao, link, scope, payload.machine_id or "") for scope in scopes]
    return {"success": True, "direction": "push", "results": results, "link": _shared_sync_link_public(link, sessao)}


@app.post("/api/shared-sync/user-shares/links/{link_id}/pull")
def shared_sync_user_shares_link_pull(
    link_id: str,
    payload: SharedSyncUserLinkRunRequest,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    link = _shared_sync_get_link(link_id)
    if not bool(link.get("active", True)):
        raise HTTPException(status_code=400, detail="Compartilhamento pausado.")
    _shared_sync_link_direction_for_session(sessao, link)
    scopes = _shared_sync_resolver_scopes_usuario(payload.scopes or link.get("scopes") or [])
    scopes = _shared_sync_filtrar_scopes_entre_clientes(scopes, link, sessao)
    results = [_shared_sync_pull_pair_scope(sessao, link, scope) for scope in scopes]
    return {"success": True, "direction": "pull", "results": results, "link": _shared_sync_link_public(link, sessao)}


@app.post("/api/shared-sync/user-shares/auto-push")
def shared_sync_user_shares_auto_push(
    payload: SharedSyncUserLinkRunRequest,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    requested = set(str(scope or "").strip() for scope in (payload.scopes or []) if str(scope or "").strip())
    results = []
    skipped = []
    for link in _shared_sync_links_all():
        try:
            _shared_sync_link_direction_for_session(sessao, link)
        except HTTPException:
            continue
        if not bool(link.get("active", True)):
            skipped.append({"link_id": link.get("id"), "reason": "inactive"})
            continue
        if not (link.get("source_keep_synced") and link.get("target_keep_synced")):
            skipped.append({"link_id": link.get("id"), "reason": "sync_disabled_by_participant"})
            continue
        for scope in link.get("scopes") or []:
            if scope not in SHARED_SYNC_SCOPES:
                continue
            if not _shared_sync_scope_permitido_entre_clientes(link, scope, sessao):
                skipped.append({"link_id": link.get("id"), "scope": scope, "reason": "cross_client_sensitive_scope"})
                continue
            if requested and scope not in requested:
                continue
            result = _shared_sync_push_link_scope(sessao, link, scope, payload.machine_id or "")
            if result.get("skipped"):
                skipped.append({"link_id": link.get("id"), "scope": scope, "reason": result.get("reason") or "already_shared"})
                continue
            results.append(result)
    return {"success": True, "direction": "auto-push", "results": results, "skipped": skipped}


@app.post("/api/shared-sync/user-shares/auto")
def shared_sync_user_shares_auto(
    payload: SharedSyncUserLinkRunRequest,
    authorization: Optional[str] = Header(default=None),
    client_id: str = Depends(get_tenant_id),
):
    sessao = _shared_sync_session(authorization, client_id)
    requested = set(str(scope or "").strip() for scope in (payload.scopes or []) if str(scope or "").strip())
    state = _shared_sync_state_read(sessao.get("client_id"), sessao.get("username") or "")
    state_scopes = state.get("scopes") if isinstance(state.get("scopes"), dict) else {}
    results = []
    skipped = []
    for link in _shared_sync_links_all():
        try:
            my_direction = _shared_sync_link_direction_for_session(sessao, link)
        except HTTPException:
            continue
        if not bool(link.get("active", True)):
            skipped.append({"link_id": link.get("id"), "reason": "inactive"})
            continue
        if not (link.get("source_keep_synced") and link.get("target_keep_synced")):
            skipped.append({"link_id": link.get("id"), "reason": "sync_disabled_by_participant"})
            continue
        receive_direction = _shared_sync_link_reverse_direction(my_direction)
        for scope in link.get("scopes") or []:
            if scope not in SHARED_SYNC_SCOPES:
                continue
            if requested and scope not in requested:
                continue
            if not _shared_sync_scope_permitido_entre_clientes(link, scope, sessao):
                skipped.append({"link_id": link.get("id"), "scope": scope, "reason": "cross_client_sensitive_scope"})
                continue

            receive_bundle = _shared_sync_link_bundle_id_for_direction(link, scope, receive_direction)
            meta = _shared_sync_remote_meta_by_id(receive_bundle)
            if meta:
                remote_hash = str(meta.get("snapshot_hash") or "")
                state_scope = _shared_sync_user_share_state_scope(link.get("id"), receive_direction, scope)
                local_hash = str(((state_scopes.get(state_scope) or {}).get("snapshot_hash")) or "")
                if remote_hash and remote_hash != local_hash:
                    try:
                        results.append(_shared_sync_pull_pair_scope(sessao, link, scope))
                    except Exception as exc:
                        skipped.append({"link_id": link.get("id"), "scope": scope, "direction": "pull", "reason": _shared_sync_exception_message(exc)})
                else:
                    skipped.append({"link_id": link.get("id"), "scope": scope, "direction": "pull", "reason": "already_current"})
            else:
                skipped.append({"link_id": link.get("id"), "scope": scope, "direction": "pull", "reason": "no_remote"})

            try:
                result = _shared_sync_push_link_scope(sessao, link, scope, payload.machine_id or "")
                if result.get("skipped"):
                    skipped.append({"link_id": link.get("id"), "scope": scope, "direction": "push", "reason": result.get("reason") or "already_shared"})
                else:
                    results.append(result)
            except Exception as exc:
                skipped.append({"link_id": link.get("id"), "scope": scope, "direction": "push", "reason": _shared_sync_exception_message(exc)})
    return {"success": True, "direction": "user-share-auto", "results": results, "skipped": skipped}


