def _carregar_usuarios_local():
    """Fallback offline para login quando SQL/planilha estiverem indisponÃƒÂ­veis.
    Formato esperado em info/usuarios_local.json:
    [
      {
        "username": "admin",
        "password": "senha-ou-bcrypt",
        "name": "Administrador",
        "client_id": "default",
        "permissions": {"full": true},
        "active": true,
        "valid_until": "2030-12-31",
        "machine_id": "acesso-via-navegador"
      }
    ]
    """
    try:
        if not os.path.exists(ARQUIVO_USUARIOS_LOCAL):
            return None, None

        with open(ARQUIVO_USUARIOS_LOCAL, "r", encoding="utf-8") as f:
            data = json.load(f)

        if not isinstance(data, list):
            logger.warning("[LOGIN] usuarios_local.json invalido: esperado array.")
            return None, None

        usuarios = {}
        headers = []
        for i, item in enumerate(data, start=1):
            if not isinstance(item, dict):
                continue
            username = str(item.get("username") or "").strip().lower()
            password = str(item.get("password") or "").strip()
            if not username or not password:
                continue
            usuarios[username] = {
                "password": password,
                "name": str(item.get("name") or username),
                "email": _normalizar_email(item.get("email") or item.get("google_email")),
                "client_id": str(item.get("client_id") or "default"),
                "permissions": _normalizar_permissoes(item.get("permissions") if isinstance(item.get("permissions"), dict) else {}),
                "original_row": [],
                "row_index": i,
                "source": "local",
                "active": bool(item.get("active", True)),
                "valid_until": str(item.get("valid_until") or "").strip() or None,
                "machine_id": str(item.get("machine_id") or "").strip() or None,
            }

        if not usuarios:
            return None, None

        logger.warning(f"[LOGIN] Usando usuÃƒÂ¡rios locais (arquivo offline): {len(usuarios)} usuÃƒÂ¡rio(s).")
        return usuarios, headers
    except Exception as e:
        logger.warning(f"[LOGIN] Falha ao carregar usuarios_local.json: {e}")
        return None, None

def verificar_validade_acesso(username, ws):
    """Verifica se a data de validade do usuÃƒÆ’Ã‚Â¡rio nÃƒÆ’Ã‚Â£o expirou."""
    try:
        todos_dados = ws.get_all_values()
        if not todos_dados: return True, "Planilha vazia", None
        
        headers = [str(h).lower().strip() for h in todos_dados[0]]
        
        # Tenta achar colunas
        idx_usuario = -1
        for k in ["usuario", "usuÃƒÆ’Ã‚Â¡rio", "user", "login", "nome"]:
            if k in headers: idx_usuario = headers.index(k); break
            
        idx_validade = -1
        for k in ["validade", "vencimento", "expira"]:
            if k in headers: idx_validade = headers.index(k); break
            
        # Busca dinÃƒÂ¢mica da coluna de ID da planilha do usuÃƒÂ¡rio
        idx_planilha = -1
        for k in [
            "planilha jk", "planilha", "spreadsheet id", "sheet id", "id planilha",
            "chave de acesso", "chave acesso", "chave de acesso planilha", "id da planilha"
        ]:
            if k in headers: 
                idx_planilha = headers.index(k)
                logger.info(f"[VALIDADE] Coluna de planilha encontrada no ÃƒÂ­ndice {idx_planilha} (coluna {chr(65+idx_planilha)})")
                break
        
        if idx_planilha == -1:
            logger.warning("[VALIDADE] Coluna de planilha do usuÃƒÂ¡rio NÃƒO encontrada nos headers.")
            logger.warning(f"[VALIDADE] Headers disponÃƒÂ­veis: {headers}")
            
        if idx_usuario == -1:
            return True, "Coluna usuÃƒÆ’Ã‚Â¡rio nÃƒÆ’Ã‚Â£o encontrada", None

        for row in todos_dados[1:]:
            if len(row) > idx_usuario and str(row[idx_usuario]).lower().strip() == username.lower():
                # Extrai ID Planilha do UsuÃƒÆ’Ã‚Â¡rio
                sheet_id = None
                if idx_planilha != -1 and len(row) > idx_planilha:
                    sheet_id = str(row[idx_planilha]).strip()
                    logger.info(f"[VALIDADE] UsuÃƒÂ¡rio '{username}': Planilha do usuÃƒÂ¡rio = '{sheet_id}' (coluna {chr(65+idx_planilha)})")
                elif idx_planilha != -1:
                    logger.warning(f"[VALIDADE] UsuÃƒÂ¡rio '{username}': Linha tem {len(row)} colunas, mas ÃƒÂ­ndice planilha ÃƒÂ© {idx_planilha}")

                if idx_validade == -1 or len(row) <= idx_validade: 
                    return True, "Sem data", sheet_id
                
                data_str = str(row[idx_validade]).strip()
                if not data_str: return False, "Data de validade nÃƒÆ’Ã‚Â£o configurada.", sheet_id
                
                try:
                    dt_val = datetime.strptime(data_str, "%d/%m/%Y")
                    if datetime.now() > dt_val:
                        return False, f"Acesso expirado em {data_str}.", sheet_id
                    return True, "Acesso vÃƒÆ’Ã‚Â¡lido", sheet_id
                except:
                    return False, f"Data invÃƒÆ’Ã‚Â¡lida: {data_str}", sheet_id
        return False, "UsuÃƒÆ’Ã‚Â¡rio nÃƒÆ’Ã‚Â£o encontrado para validaÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o", None
    except Exception as e:
        print(f"Erro validade: {e}")
        return True, "Erro na verificaÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o (Liberado)", None

def extrair_permissoes(row, headers):
    """Extrai permissÃƒÂµes dinamicamente a partir da planilha de usuÃƒÂ¡rios."""
    permissoes = {k: False for k in PERMISSION_KEYS}

    def _norm_header(val: str) -> str:
        val = str(val).strip().lower()
        val = unicodedata.normalize('NFKD', val)
        val = ''.join([c for c in val if not unicodedata.combining(c)])
        return val

    headers_norm = [_norm_header(h) for h in (headers or [])]

    map_headers = {
        'analise_promo': ['analise promocional ml', 'analise promocional ml', 'analise promo', 'promocao ml'],
        'renovacao_fixa': ['renovaÃƒÂ§ÃƒÂ£o fixa', 'renovacao fixa'],
        'vendas': ['vendas'],
        'estoque': ['estoque'],
        'integracao': ['integraÃƒÂ§ÃƒÂ£o', 'integracao', 'integraÃƒÂ§ÃƒÂµes', 'integracoes'],
        'etiquetas': ['etiquetas'],
        'full': ['full', 'admin total', 'administrador'],
        'favoritos': ['favoritos'],
        'perguntas_pos_venda': ['perguntas e pos venda', 'perguntas e pÃ³s venda', 'perguntas pos venda', 'pos venda', 'pÃ³s venda'],
        'anuncios_ml': ['anuncios mercado livre', 'anuncios mercado livre', 'anuncios ml'],
        'medias_compras': ['mÃƒÂ©dias e compras', 'medias e compras', 'media e compras', 'medias compras'],
        'mercado_full': ['modulo full', 'mercado full', 'mercado livre full', 'ml full'],
        'cadastro': ['cadastro', 'cadastro de produtos'],
        'impostos': ['impostos', 'imposto'],
        'configuracoes': ['configuraÃƒÂ§ÃƒÂµes', 'configuracoes', 'configuraÃƒÂ§ÃƒÂ£o', 'configuracao'],
        'importacoes': ['importaÃƒÂ§ÃƒÂµes', 'importacoes', 'importaÃƒÂ§ÃƒÂ£o', 'importacao'],
        'simulador': ['simulador', 'simulaÃƒÂ§ÃƒÂ£o', 'simulacao'],
    }

    fallback_map = {
        'analise_promo': 10, 'renovacao_fixa': 11, 'vendas': 12, 'estoque': 13,
        'integracao': 14, 'etiquetas': 15, 'full': 16, 'favoritos': 17,
        'perguntas_pos_venda': -1, 'anuncios_ml': 18, 'medias_compras': 19, 'mercado_full': -1,
        'cadastro': -1, 'impostos': -1, 'configuracoes': -1, 'importacoes': -1,
        'simulador': -1,
    }

    for mod_name, candidates in map_headers.items():
        idx = -1
        for cand in candidates:
            cand_norm = _norm_header(cand)
            if cand_norm in headers_norm:
                idx = headers_norm.index(cand_norm)
                break
        if idx == -1:
            idx = fallback_map.get(mod_name, -1)

        if idx >= 0 and len(row) > idx:
            val = str(row[idx]).upper().strip()
            if val in ['VERDADEIRO', 'TRUE', 'SIM', '1', 'X', 'OK']:
                permissoes[mod_name] = True

    return _normalizar_permissoes(permissoes)

def verificar_trava_seguranca(ws, row_index, headers, username, client_id=None):
    """Verifica trava de seguranÃƒÆ’Ã‚Â§a (MAC Address) igual ao login.py"""
    try:
        if client_id:
            mac_address = client_id.strip().upper()
        else:
            return False, "Acesso negado: ÃƒÆ’Ã¢â‚¬Â° necessÃƒÆ’Ã‚Â¡rio utilizar o Aplicativo Desktop oficial."
            
        data_hora = datetime.now().strftime("%d/%m/%Y %H:%M:%S")
        
        # Procura ÃƒÆ’Ã‚Â­ndices das colunas (case insensitive)
        headers_lower = [str(h).lower().strip() for h in headers]
        
        # Tenta achar coluna Maquina
        idx_maquina = -1
        if "maquina" in headers_lower: idx_maquina = headers_lower.index("maquina")
        
        # Tenta achar coluna Ultimo Acesso
        idx_acesso = -1
        for i, h in enumerate(headers_lower):
            if "ultimo acesso" in h or "ÃƒÆ’Ã‚Âºltimo acesso" in h: idx_acesso = i; break
            
        if idx_maquina == -1:
            return True, "Coluna Maquina nÃƒÆ’Ã‚Â£o encontrada (Ignorado)"

        # LÃƒÆ’Ã‚Âª valor atual da mÃƒÆ’Ã‚Â¡quina na planilha (row_index ÃƒÆ’Ã‚Â© 1-based)
        maquina_registrada = ws.cell(row_index, idx_maquina + 1).value
        maquina_registrada = str(maquina_registrada).strip() if maquina_registrada else ""

        if not maquina_registrada:
            # Vincula
            ws.update_cell(row_index, idx_maquina + 1, mac_address)
            if idx_acesso != -1: ws.update_cell(row_index, idx_acesso + 1, data_hora)
            return True, "MÃƒÆ’Ã‚Â¡quina vinculada com sucesso"
        
        elif maquina_registrada.lower() == mac_address.lower():
            # Autorizado
            if idx_acesso != -1: ws.update_cell(row_index, idx_acesso + 1, data_hora)
            return True, "Acesso autorizado"
        
        else:
            # Bloqueado
            return False, f"Bloqueado. Vinculado a: {maquina_registrada}"
            
    except Exception as e:
        print(f"Erro ao registrar acesso: {e}")
        return False, f"Erro seguranÃƒÆ’Ã‚Â§a: {e}"

def carregar_usuarios_sheets():
    usuarios_firebase = _firebase_listar_usuarios(seed_if_empty=True) if _firebase_deve_usar() else None
    if isinstance(usuarios_firebase, dict):
        return usuarios_firebase, None, []

    usuarios_sql, headers_sql = _carregar_usuarios_sql()
    if usuarios_sql is not None:
        return usuarios_sql, None, headers_sql

    client = autenticar_google_sheets()
    if not client:
        usuarios_cache, headers_cache = _carregar_cache_usuarios()
        if usuarios_cache is not None:
            _salvar_usuarios_sql(usuarios_cache, source="cache")
            return usuarios_cache, None, headers_cache
        usuarios_local, headers_local = _carregar_usuarios_local()
        if usuarios_local is not None:
            _salvar_usuarios_sql(usuarios_local, source="local")
            return usuarios_local, None, headers_local
        return None, None, None

    try:
        last_error = None
        sh = None
        for tentativa in range(1, 4):
            try:
                sh = client.open_by_key(SPREADSHEET_ID_CLIENTES)
                break
            except Exception as e:
                last_error = e
                logger.warning(f"[LOGIN] Tentativa {tentativa}/3 ao abrir planilha falhou: {e}")
                time.sleep(1.2 * tentativa)
        if sh is None:
            raise last_error

        try:
            ws = sh.worksheet("Clientes")
        except:
            ws = sh.sheet1
            
        # Usa get_all_values para evitar erros de cabeÃƒÆ’Ã‚Â§alho duplicado do get_all_records
        rows = ws.get_all_values()
        if not rows: return {}, ws, []
        
        headers_raw = [str(h).strip() for h in rows[0]]
        headers = [h.lower() for h in headers_raw]
        usuarios = {}

        # Mapeamento de ÃƒÆ’Ã‚Â­ndices
        def _norm_header(h: str) -> str:
            h = unicodedata.normalize('NFKD', h)
            h = ''.join([c for c in h if not unicodedata.combining(c)])
            h = re.sub(r'[^a-zA-Z0-9]+', '', h).upper()
            return h

        headers_norm = [_norm_header(h) for h in headers_raw]

        def find_idx(keys):
            for k in keys:
                if k in headers:
                    return headers.index(k)
            return -1

        def find_idx_norm(keys_norm):
            for k in keys_norm:
                if k in headers_norm:
                    return headers_norm.index(k)
            return -1

        idx_user = find_idx(["usuÃƒÆ’Ã‚Â¡rio", "usuario", "user", "login"])
        idx_pass = find_idx(["senha", "password", "pass"])
        idx_name = find_idx(["nome", "name"])
        idx_email = find_idx(["email", "e-mail", "gmail", "google email", "email google", "e-mail google"])
        if idx_email == -1:
            idx_email = find_idx_norm(["EMAIL", "EMAILGOOGLE", "GOOGLEEMAIL", "GMAIL"])
        idx_client_id = find_idx(["nÃƒÆ’Ã‚Âºmero do cliente", "numero do cliente", "id cliente"])
        if idx_client_id == -1:
            idx_client_id = find_idx_norm(["NUMERODOCLIENTE", "IDCLIENTE", "CLIENTEID", "CODIGOCLIENTE", "CODCLIENTE"])

        if idx_user == -1 or idx_pass == -1:
            print("Colunas de UsuÃƒÆ’Ã‚Â¡rio/Senha nÃƒÆ’Ã‚Â£o encontradas.")
            return {}, ws, headers

        for i, row in enumerate(rows[1:], start=2):
            if len(row) <= idx_user or len(row) <= idx_pass: continue
            
            user = str(row[idx_user]).strip()
            raw_pw = str(row[idx_pass]).strip()
            name = str(row[idx_name]).strip() if idx_name != -1 and len(row) > idx_name else user
            email = str(row[idx_email]).strip() if idx_email != -1 and len(row) > idx_email else ""
            client_id = str(row[idx_client_id]).strip() if idx_client_id != -1 and len(row) > idx_client_id else None
            
            if user and raw_pw:
                permissoes_usuario = extrair_permissoes(row, headers_raw)
                usuarios[user.lower()] = {
                    "password": raw_pw,
                    "name": name,
                    "email": _normalizar_email(email),
                    "client_id": client_id,
                    "permissions": permissoes_usuario,
                    "original_row": row,
                    "row_index": i
                }

        _salvar_cache_usuarios(usuarios, headers)
        _salvar_usuarios_sql(usuarios, source="planilha")
        return usuarios, ws, headers
    except Exception as e:
        print(f"Erro ao carregar usuÃƒÆ’Ã‚Â¡rios: {e}")
        usuarios_cache, headers_cache = _carregar_cache_usuarios()
        if usuarios_cache is not None:
            return usuarios_cache, None, headers_cache
        usuarios_local, headers_local = _carregar_usuarios_local()
        if usuarios_local is not None:
            return usuarios_local, None, headers_local
        return None, None, None


def _login_senha_confere(senha_informada: str, senha_salva: str) -> bool:
    senha = str(senha_informada or "")
    salva = str(senha_salva or "")
    if not senha or not salva:
        return False
    if salva.startswith("$2"):
        try:
            return bcrypt.checkpw(senha.encode("utf-8"), salva.encode("utf-8"))
        except Exception:
            return False
    return secrets.compare_digest(senha, salva)


def _login_validade_ok(usuario: dict) -> tuple[bool, str]:
    data_txt = _normalizar_data_sistema((usuario or {}).get("valid_until"))
    if not data_txt:
        return True, ""
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            data_limite = datetime.strptime(data_txt[:10], fmt)
            if datetime.now() > data_limite.replace(hour=23, minute=59, second=59):
                return False, f"Acesso expirado em {data_txt}."
            return True, ""
        except Exception:
            continue
    return True, ""


def _login_usuario_ativo(usuario: dict) -> bool:
    valor = (usuario or {}).get("active", True)
    if isinstance(valor, str):
        return valor.strip().lower() not in {"0", "false", "falso", "nao", "nÃ£o", "inativo", "bloqueado"}
    return bool(valor)


def _firebase_validar_e_registrar_maquina(username: str, usuario: dict, permissoes: dict, machine_final: str) -> tuple[bool, str, str]:
    if _usuario_pode_logar_em_qualquer_dispositivo(username, permissoes):
        return True, "", machine_final

    username_norm = str(username or "").strip().lower()
    coll = _firebase_collection()
    if coll is None:
        if _firebase_access_obrigatorio():
            return False, "Firebase indisponivel para validar maquinas.", machine_final
        return True, "", machine_final

    ref = coll.document(_firebase_doc_id(username_norm))

    try:
        snap = ref.get()
        if not snap.exists:
            return False, "Usuario nao encontrado no Firebase.", machine_final
        usuario_atual = _firebase_user_from_data(username_norm, snap.to_dict() or {})
        maquinas = _normalizar_lista_maquinas(usuario_atual.get("machine_ids"), usuario_atual.get("machine_id"))
        if machine_final in maquinas:
            return True, "", machine_final
        max_machines = _normalizar_max_machines(usuario_atual.get("max_machines", 1))
        if max_machines != 0 and len(maquinas) >= max_machines:
            return False, "Limite de dispositivos atingido para este usuario. Peca ao administrador para resetar os dispositivos.", machine_final
        maquinas.append(machine_final)
        ref.update({
            "machine_id": maquinas[0] if maquinas else machine_final,
            "machine_ids": maquinas,
            "updated_at": _firebase_now_iso(),
        })
        ok, msg = True, ""
        if ok:
            usuario_atualizado = dict(usuario)
            maquinas_locais = _normalizar_lista_maquinas(usuario.get("machine_ids"), usuario.get("machine_id"))
            if machine_final not in maquinas_locais:
                maquinas_locais.append(machine_final)
            usuario_atualizado["machine_id"] = maquinas_locais[0] if maquinas_locais else machine_final
            usuario_atualizado["machine_ids"] = maquinas_locais
            _salvar_usuarios_sql({username_norm: usuario_atualizado}, source="firebase-cache")
        return bool(ok), str(msg or ""), machine_final
    except Exception as exc:
        logger.warning("[FIREBASE-AUTH] Falha ao validar maquina no Firebase para %s: %s", username_norm, exc)
        if _firebase_access_obrigatorio():
            return False, f"Firebase indisponivel para validar maquinas: {exc}", machine_final
        return True, "", machine_final


def _login_validar_e_registrar_maquina(username: str, usuario: dict, permissoes: dict, machine_id: str, request: Request) -> tuple[bool, str, str]:
    machine_final, _meta = _montar_machine_id_login(request, machine_id)
    if _firebase_deve_usar() and (usuario or {}).get("source") == "firebase":
        return _firebase_validar_e_registrar_maquina(username, usuario, permissoes, machine_final)

    if _usuario_pode_logar_em_qualquer_dispositivo(username, permissoes):
        return True, "", machine_final

    maquinas = _normalizar_lista_maquinas(usuario.get("machine_ids"), usuario.get("machine_id"))
    if machine_final in maquinas:
        return True, "", machine_final

    max_machines = _normalizar_max_machines(usuario.get("max_machines", 1))
    if max_machines != 0 and len(maquinas) >= max_machines:
        return False, "Limite de dispositivos atingido para este usuario. PeÃ§a ao administrador para resetar os dispositivos.", machine_final

    maquinas.append(machine_final)
    usuario_atualizado = dict(usuario)
    usuario_atualizado["machine_id"] = maquinas[0] if maquinas else machine_final
    usuario_atualizado["machine_ids"] = maquinas
    _salvar_usuarios_sql({username: usuario_atualizado}, source="sql-login")
    return True, "", machine_final


def _google_login_client_id() -> str:
    return _env_config_value("GOOGLE_LOGIN_CLIENT_ID", "GOOGLE_CLIENT_ID", cache_as="GOOGLE_LOGIN_CLIENT_ID")


def _google_login_client_secret() -> str:
    return _env_config_value("GOOGLE_LOGIN_CLIENT_SECRET", "GOOGLE_CLIENT_SECRET", cache_as="GOOGLE_LOGIN_CLIENT_SECRET")


def _google_login_scopes() -> str:
    scopes = _env_config_value("GOOGLE_LOGIN_SCOPES", "GOOGLE_OAUTH_SCOPES")
    required_scopes = [
        "openid",
        "email",
        "profile",
        "https://www.googleapis.com/auth/drive.file",
    ]
    scope_parts = [item.strip() for item in str(scopes or "").split() if item.strip()]
    for required_scope in required_scopes:
        if required_scope not in scope_parts:
            scope_parts.append(required_scope)
    return " ".join(scope_parts)


def _google_login_verify_id_token(id_token_value: str, client_id_google: str) -> dict:
    return google_id_token.verify_oauth2_token(
        id_token_value,
        GoogleAuthRequest(),
        client_id_google,
        clock_skew_in_seconds=60,
    )


def _google_login_redirect_uri(request: Optional[Request] = None) -> str:
    local_configured = _env_config_value("GOOGLE_LOGIN_REDIRECT_URI_LOCAL", "GOOGLE_LOCAL_REDIRECT_URI")
    public_configured = _env_config_value("GOOGLE_LOGIN_REDIRECT_URI_PUBLIC", "GOOGLE_PUBLIC_REDIRECT_URI")
    configured = _env_config_value("GOOGLE_LOGIN_REDIRECT_URI", "GOOGLE_REDIRECT_URI")
    if _request_eh_local(request) and local_configured:
        return local_configured.rstrip("/")
    if request is not None and not _request_eh_local(request) and public_configured:
        return public_configured.rstrip("/")
    if configured:
        return configured.rstrip("/")

    if request is not None:
        try:
            proto = str(request.headers.get("x-forwarded-proto") or request.url.scheme or "http").split(",")[0].strip() or "http"
            host = str(request.headers.get("x-forwarded-host") or request.headers.get("host") or request.url.netloc or "").split(",")[0].strip()
            if host:
                return f"{proto}://{host}/auth/google/callback"
        except Exception:
            pass

    return "http://127.0.0.1:8001/auth/google/callback"


def _google_login_configurado() -> bool:
    return bool(_google_login_client_id() and _google_login_client_secret())


def _buscar_usuario_por_email_google(usuarios: dict, email: str) -> tuple[Optional[str], Optional[dict]]:
    email_norm = _normalizar_email(email)
    if not email_norm or not isinstance(usuarios, dict):
        return None, None

    fallback_username = None
    fallback_usuario = None
    for username, usuario in usuarios.items():
        if not isinstance(usuario, dict):
            continue
        username_norm = str(username or "").strip().lower()
        if _normalizar_email(usuario.get("email") or usuario.get("google_email")) == email_norm:
            return username_norm, usuario
        if username_norm == email_norm:
            fallback_username = username_norm
            fallback_usuario = usuario

    return fallback_username, fallback_usuario


def _montar_resposta_login_sucesso(username: str, usuario: dict, permissoes: dict, client_id: str, machine_final: str) -> LoginResponse:
    token = criar_access_token(username, client_id)
    user_data = {
        "username": username,
        "name": str(usuario.get("name") or username),
        "email": _normalizar_email(usuario.get("email")),
        "client_id": client_id,
        "machine_id": machine_final,
    }
    return LoginResponse(
        success=True,
        message="Login realizado com sucesso.",
        user_data=user_data,
        permissions=_normalizar_permissoes(permissoes),
        access_token=token,
    )


def _autenticar_usuario_por_google_info(token_info: dict, machine_id: str, request: Request) -> LoginResponse:
    issuer = str((token_info or {}).get("iss") or "")
    if issuer not in {"accounts.google.com", "https://accounts.google.com"}:
        return LoginResponse(success=False, message="Origem da conta Google invalida.")

    email = _normalizar_email((token_info or {}).get("email"))
    email_verified = (token_info or {}).get("email_verified")
    if isinstance(email_verified, str):
        email_verified = email_verified.strip().lower() == "true"
    if not email or not bool(email_verified):
        return LoginResponse(success=False, message="Use uma conta Google com e-mail verificado.")

    usuarios, _ws, _headers = carregar_usuarios_sheets()
    username, usuario = _buscar_usuario_por_email_google(usuarios or {}, email)
    if not username or not isinstance(usuario, dict):
        return LoginResponse(
            success=False,
            message="Conta Google nao vinculada. Peça ao administrador para cadastrar esse e-mail no usuario.",
        )

    if not _login_usuario_ativo(usuario):
        return LoginResponse(success=False, message="Usuario inativo. Contate o administrador.")

    validade_ok, msg_validade = _login_validade_ok(usuario)
    if not validade_ok:
        return LoginResponse(success=False, message=msg_validade or "Acesso expirado ou invalido.")

    permissoes = _normalizar_permissoes(usuario.get("permissions") or {})
    client_id = str(usuario.get("client_id") or "default").strip() or "default"
    usuario["client_id"] = client_id
    if not _normalizar_email(usuario.get("email")):
        usuario["email"] = email

    maquina_ok, msg_maquina, machine_final = _login_validar_e_registrar_maquina(
        username,
        usuario,
        permissoes,
        machine_id,
        request,
    )
    if not maquina_ok:
        return LoginResponse(success=False, message=msg_maquina)

    try:
        _registrar_login_maquina(username, client_id, machine_final, request)
    except Exception as exc:
        logger.warning("[LOGIN] Nao foi possivel registrar auditoria de login Google para %s: %s", username, exc)
    try:
        _machine_presence_save(_machine_presence_record(username, client_id, machine_final, request, "login-google"))
    except Exception as exc:
        logger.warning("[LOGIN] Nao foi possivel registrar presenca inicial Google para %s: %s", username, exc)

    return _montar_resposta_login_sucesso(username, usuario, permissoes, client_id, machine_final)


def _google_login_error_redirect(message: str):
    query = urlencode({"google_error": str(message or "Nao foi possivel entrar com Google.")})
    return RedirectResponse(url=f"/frontend_index.html?{query}", status_code=303)


def _google_login_success_html(resp: LoginResponse):
    user_json = json.dumps(resp.user_data or {}, ensure_ascii=False).replace("</", "<\\/")
    permissions_json = json.dumps(resp.permissions or {}, ensure_ascii=False).replace("</", "<\\/")
    token_json = json.dumps(resp.access_token or "", ensure_ascii=False).replace("</", "<\\/")
    html = f"""
<!doctype html>
<html lang="pt-BR">
<head>
    <meta charset="utf-8">
    <title>Entrando...</title>
</head>
<body>
    <script>
        localStorage.setItem('user_data', JSON.stringify({user_json}));
        localStorage.setItem('permissions', JSON.stringify({permissions_json}));
        const token = {token_json};
        if (token) {{
            localStorage.setItem('access_token', token);
        }} else {{
            localStorage.removeItem('access_token');
        }}
        window.location.replace('/dashboard.html');
    </script>
</body>
</html>
"""
    return HTMLResponse(content=html)


def _google_login_poll_html(success: bool, message: str):
    titulo = html_lib.escape("Login concluido" if success else "Login nao autorizado")
    texto = html_lib.escape(str(message or ("Login concluido. Volte ao sistema." if success else "Nao foi possivel entrar com Google.")))
    html = f"""
<!doctype html>
<html lang="pt-BR">
<head>
    <meta charset="utf-8">
    <title>{titulo}</title>
    <style>
        body {{
            margin: 0;
            min-height: 100vh;
            display: grid;
            place-items: center;
            font-family: Arial, sans-serif;
            background: #071326;
            color: #e8f3ff;
        }}
        main {{
            max-width: 480px;
            padding: 32px;
            text-align: center;
        }}
        h1 {{ margin: 0 0 12px; font-size: 26px; }}
        p {{ margin: 0; line-height: 1.5; color: #b8c7dc; }}
    </style>
</head>
<body>
    <main>
        <h1>{titulo}</h1>
        <p>{texto}</p>
    </main>
</body>
</html>
"""
    return HTMLResponse(content=html)


def _google_login_poll_response_payload(resp: LoginResponse) -> dict:
    return {
        "created_at": time.time(),
        "success": bool(resp.success),
        "message": resp.message,
        "user_data": resp.user_data or {},
        "permissions": resp.permissions or {},
        "access_token": resp.access_token or "",
    }


def _google_login_store_poll_result(state: str, payload: dict):
    state = str(state or "").strip()
    if not state:
        return
    payload = dict(payload or {})
    payload["created_at"] = time.time()
    with GOOGLE_LOGIN_STATE_LOCK:
        GOOGLE_LOGIN_RESULTS[state] = payload


def _google_login_finish_poll(state: str, resp: LoginResponse):
    _google_login_store_poll_result(state, _google_login_poll_response_payload(resp))
    if resp.success:
        return _google_login_poll_html(True, "Login concluido. Volte ao sistema para continuar.")
    return _google_login_poll_html(False, resp.message or "Conta Google nao autorizada.")


@app.get("/api/auth/google/config")
def google_auth_config(request: Request):
    client_id = _google_login_client_id()
    client_secret = _google_login_client_secret()
    return {
        "success": True,
        "enabled": bool(client_id and client_secret),
        "oauth_enabled": bool(client_id and client_secret),
        "client_id": client_id,
        "redirect_uri": _google_login_redirect_uri(request),
        "scopes": _google_login_scopes(),
    }


@app.get("/api/auth/google/start")
def google_auth_start(request: Request, machine_id: str = "", mode: str = ""):
    mode = str(mode or "").strip().lower()
    client_id_google = _google_login_client_id()
    client_secret_google = _google_login_client_secret()
    if not client_id_google or not client_secret_google:
        if mode == "json":
            return {
                "success": False,
                "message": "Login Google nao configurado. Informe GOOGLE_LOGIN_CLIENT_ID e GOOGLE_LOGIN_CLIENT_SECRET no servidor.",
            }
        return _google_login_error_redirect("Login Google nao configurado. Informe GOOGLE_LOGIN_CLIENT_ID e GOOGLE_LOGIN_CLIENT_SECRET no servidor.")

    state = secrets.token_urlsafe(32)
    redirect_uri = _google_login_redirect_uri(request)
    agora = time.time()
    with GOOGLE_LOGIN_STATE_LOCK:
        expirados = [chave for chave, item in GOOGLE_LOGIN_STATES.items() if agora - float((item or {}).get("created_at") or 0) > 900]
        for chave in expirados:
            GOOGLE_LOGIN_STATES.pop(chave, None)
        GOOGLE_LOGIN_STATES[state] = {
            "created_at": agora,
            "machine_id": str(machine_id or ""),
            "redirect_uri": redirect_uri,
            "poll": mode == "json",
        }

    params = {
        "client_id": client_id_google,
        "redirect_uri": redirect_uri,
        "response_type": "code",
        "scope": _google_login_scopes(),
        "state": state,
        "access_type": "offline",
        "include_granted_scopes": "true",
        "prompt": "select_account consent",
    }
    auth_url = "https://accounts.google.com/o/oauth2/v2/auth?" + urlencode(params)
    if mode == "json":
        return {
            "success": True,
            "auth_url": auth_url,
            "state": state,
            "redirect_uri": redirect_uri,
        }
    return RedirectResponse(url=auth_url, status_code=303)


@app.get("/api/auth/google/result/{state}")
def google_auth_result(state: str):
    state = str(state or "").strip()
    agora = time.time()
    with GOOGLE_LOGIN_STATE_LOCK:
        expirados = [chave for chave, item in GOOGLE_LOGIN_RESULTS.items() if agora - float((item or {}).get("created_at") or 0) > 900]
        for chave in expirados:
            GOOGLE_LOGIN_RESULTS.pop(chave, None)
        resultado = GOOGLE_LOGIN_RESULTS.get(state)
        if not isinstance(resultado, dict):
            return {"success": False, "pending": True}
        resultado = dict(resultado)
        GOOGLE_LOGIN_RESULTS.pop(state, None)

    resultado.pop("created_at", None)
    resultado["pending"] = False
    return resultado


@app.get("/auth/google/callback")
def google_auth_callback(request: Request, code: Optional[str] = None, state: Optional[str] = None, error: Optional[str] = None):
    state = str(state or "").strip()
    if error:
        with GOOGLE_LOGIN_STATE_LOCK:
            state_data_error = GOOGLE_LOGIN_STATES.pop(state, None) if state else None
        if isinstance(state_data_error, dict) and state_data_error.get("poll"):
            return _google_login_finish_poll(
                state,
                LoginResponse(success=False, message=f"Google recusou o login: {error}."),
            )
        return _google_login_error_redirect(f"Google recusou o login: {error}.")

    if not code or not state:
        return _google_login_error_redirect("Retorno do Google incompleto.")

    with GOOGLE_LOGIN_STATE_LOCK:
        state_data = GOOGLE_LOGIN_STATES.pop(state, None)
    poll_mode = bool(isinstance(state_data, dict) and state_data.get("poll"))
    if not isinstance(state_data, dict):
        return _google_login_error_redirect("Sessao do login Google expirou. Tente novamente.")
    if time.time() - float(state_data.get("created_at") or 0) > 900:
        if poll_mode:
            return _google_login_finish_poll(
                state,
                LoginResponse(success=False, message="Sessao do login Google expirou. Tente novamente."),
            )
        return _google_login_error_redirect("Sessao do login Google expirou. Tente novamente.")

    client_id_google = _google_login_client_id()
    client_secret_google = _google_login_client_secret()
    redirect_uri = str(state_data.get("redirect_uri") or _google_login_redirect_uri(request)).strip()

    try:
        token_resp = requests.post(
            "https://oauth2.googleapis.com/token",
            data={
                "code": code,
                "client_id": client_id_google,
                "client_secret": client_secret_google,
                "redirect_uri": redirect_uri,
                "grant_type": "authorization_code",
            },
            timeout=20,
        )
        token_payload = token_resp.json() if token_resp.content else {}
    except Exception as exc:
        logger.warning("[LOGIN] Falha ao trocar codigo Google: %s", exc)
        if poll_mode:
            return _google_login_finish_poll(
                state,
                LoginResponse(success=False, message="Nao foi possivel concluir o login Google."),
            )
        return _google_login_error_redirect("Nao foi possivel concluir o login Google.")

    if token_resp.status_code != 200:
        detalhe = ""
        if isinstance(token_payload, dict):
            detalhe = str(token_payload.get("error_description") or token_payload.get("error") or "").strip()
        logger.warning("[LOGIN] Google token exchange falhou: %s", detalhe or token_resp.text[:300])
        if poll_mode:
            return _google_login_finish_poll(
                state,
                LoginResponse(success=False, message=detalhe or "Google nao autorizou o login."),
            )
        return _google_login_error_redirect(detalhe or "Google nao autorizou o login.")

    id_token_value = str((token_payload or {}).get("id_token") or "").strip()
    if not id_token_value:
        if poll_mode:
            return _google_login_finish_poll(
                state,
                LoginResponse(success=False, message="Google nao retornou a identidade da conta."),
            )
        return _google_login_error_redirect("Google nao retornou a identidade da conta.")

    try:
        token_info = _google_login_verify_id_token(id_token_value, client_id_google)
    except (ValueError, GoogleAuthError) as exc:
        logger.warning("[LOGIN] ID token Google invalido no callback: %s", exc)
        if poll_mode:
            return _google_login_finish_poll(
                state,
                LoginResponse(success=False, message="Nao foi possivel validar sua conta Google."),
            )
        return _google_login_error_redirect("Nao foi possivel validar sua conta Google.")

    login_resp = _autenticar_usuario_por_google_info(
        token_info,
        str(state_data.get("machine_id") or ""),
        request,
    )
    if login_resp.success:
        try:
            google_email = _normalizar_email((token_info or {}).get("email"))
            _google_oauth_salvar_tokens_usuario(
                str((login_resp.user_data or {}).get("username") or ""),
                str((login_resp.user_data or {}).get("client_id") or ""),
                google_email,
                token_payload,
            )
        except Exception as exc:
            logger.warning("[DRIVE-SYNC] Nao foi possivel salvar token OAuth Google: %s", exc)
    if poll_mode:
        return _google_login_finish_poll(state, login_resp)
    if not login_resp.success:
        return _google_login_error_redirect(login_resp.message)

    return _google_login_success_html(login_resp)


@app.post("/api/auth/google", response_model=LoginResponse)
async def google_login_endpoint(payload: GoogleLoginRequest, request: Request):
    client_id_google = _google_login_client_id()
    if not client_id_google:
        return LoginResponse(success=False, message="Login com Google ainda nao configurado no servidor.")

    credential = str(payload.credential or "").strip()
    if not credential:
        return LoginResponse(success=False, message="Credencial Google nao recebida.")

    try:
        token_info = _google_login_verify_id_token(credential, client_id_google)
    except (ValueError, GoogleAuthError) as exc:
        logger.warning("[LOGIN] Token Google invalido: %s", exc)
        return LoginResponse(success=False, message="Nao foi possivel validar sua conta Google.")
    except Exception as exc:
        logger.warning("[LOGIN] Falha ao validar token Google: %s", exc)
        return LoginResponse(success=False, message="Erro ao validar login Google.")

    return _autenticar_usuario_por_google_info(token_info, payload.machine_id, request)


DRIVE_SYNC_FOLDER_ROOT = "JK Sistema Backups"
DRIVE_SYNC_FILE_EXT = ".jksync"
DRIVE_SYNC_ALLOWED_EXTENSIONS = {".json", ".csv", ".db", ".sqlite", ".sqlite3"}
DRIVE_SYNC_MAX_FILE_BYTES = 80 * 1024 * 1024


def _google_oauth_init_db():
    _init_auth_db()
    conn = _auth_db_conexao()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS google_oauth_tokens (
                username TEXT NOT NULL,
                client_id TEXT NOT NULL,
                google_email TEXT,
                access_token TEXT,
                refresh_token TEXT,
                expires_at TEXT,
                scopes TEXT,
                updated_at TEXT NOT NULL,
                PRIMARY KEY (username, client_id)
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def _google_oauth_carregar_tokens(username: str, client_id: str) -> Optional[dict]:
    username_norm = str(username or "").strip().lower()
    client_norm = str(client_id or "").strip() or "default"
    if not username_norm:
        return None
    _google_oauth_init_db()
    conn = _auth_db_conexao()
    try:
        row = conn.execute(
            """
            SELECT username, client_id, google_email, access_token, refresh_token,
                   expires_at, scopes, updated_at
            FROM google_oauth_tokens
            WHERE username = ? AND client_id = ?
            """,
            (username_norm, client_norm),
        ).fetchone()
        return dict(row) if row else None
    finally:
        conn.close()


def _google_oauth_salvar_tokens_usuario(username: str, client_id: str, google_email: str, token_payload: dict):
    username_norm = str(username or "").strip().lower()
    client_norm = str(client_id or "").strip() or "default"
    if not username_norm or not client_norm or not isinstance(token_payload, dict):
        return

    access_token = str(token_payload.get("access_token") or "").strip()
    refresh_token = str(token_payload.get("refresh_token") or "").strip()
    if not access_token and not refresh_token:
        return

    existente = _google_oauth_carregar_tokens(username_norm, client_norm) or {}
    if not refresh_token:
        refresh_token = str(existente.get("refresh_token") or "").strip()

    expires_at = str(existente.get("expires_at") or "").strip()
    try:
        expires_in = int(token_payload.get("expires_in") or 0)
    except Exception:
        expires_in = 0
    if expires_in > 0:
        expires_at = (datetime.utcnow() + timedelta(seconds=max(60, expires_in - 60))).strftime("%Y-%m-%dT%H:%M:%SZ")

    scopes = str(token_payload.get("scope") or existente.get("scopes") or _google_login_scopes()).strip()
    email = _normalizar_email(google_email or existente.get("google_email"))
    agora = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

    _google_oauth_init_db()
    conn = _auth_db_conexao()
    try:
        conn.execute(
            """
            INSERT INTO google_oauth_tokens (
                username, client_id, google_email, access_token, refresh_token,
                expires_at, scopes, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(username, client_id) DO UPDATE SET
                google_email=excluded.google_email,
                access_token=excluded.access_token,
                refresh_token=excluded.refresh_token,
                expires_at=excluded.expires_at,
                scopes=excluded.scopes,
                updated_at=excluded.updated_at
            """,
            (
                username_norm,
                client_norm,
                email,
                access_token,
                refresh_token,
                expires_at,
                scopes,
                agora,
            ),
        )
        conn.commit()
    finally:
        conn.close()


def _google_oauth_parse_expiry(expires_at: str) -> Optional[datetime]:
    texto = str(expires_at or "").strip()
    if not texto:
        return None
    for fmt in ("%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(texto[:20].rstrip("Z"), fmt.replace("Z", ""))
        except Exception:
            continue
    try:
        return datetime.fromisoformat(texto.replace("Z", "+00:00")).replace(tzinfo=None)
    except Exception:
        return None


def _drive_sync_contexto_usuario(authorization: Optional[str]) -> dict:
    payload = _payload_sessao_por_authorization(authorization)
    username = str(payload.get("username") or "").strip().lower()
    client_id = str(payload.get("client_id") or "").strip() or "default"

    usuarios, headers, _ = carregar_usuarios_sheets()
    usuario = (usuarios or {}).get(username) if isinstance(usuarios, dict) else None
    if not isinstance(usuario, dict):
        raise HTTPException(status_code=401, detail="Usuario da sessao nao encontrado. Faca login novamente.")
    client_usuario = str(usuario.get("client_id") or client_id or "default").strip() or "default"
    if client_usuario != client_id:
        raise HTTPException(status_code=403, detail="Token invalido para o cliente autenticado.")
    return {
        "username": username,
        "client_id": client_id,
        "email": _normalizar_email(usuario.get("email") or usuario.get("google_email")),
        "user": usuario,
    }


def _google_drive_token_linkado(ctx: dict) -> Optional[dict]:
    return _google_oauth_carregar_tokens(ctx.get("username"), ctx.get("client_id"))


def _google_drive_refresh_access_token(ctx: dict, registro: Optional[dict] = None) -> str:
    registro = registro or _google_drive_token_linkado(ctx)
    refresh_token = str((registro or {}).get("refresh_token") or "").strip()
    if not refresh_token:
        raise HTTPException(
            status_code=403,
            detail="Drive nao vinculado. Entre pelo botao Google uma vez para autorizar o backup automatico.",
        )

    try:
        resp = requests.post(
            "https://oauth2.googleapis.com/token",
            data={
                "client_id": _google_login_client_id(),
                "client_secret": _google_login_client_secret(),
                "refresh_token": refresh_token,
                "grant_type": "refresh_token",
            },
            timeout=25,
        )
        payload = resp.json() if resp.content else {}
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Nao foi possivel renovar o acesso ao Google Drive: {exc}")

    if resp.status_code != 200:
        detalhe = ""
        if isinstance(payload, dict):
            detalhe = str(payload.get("error_description") or payload.get("error") or "").strip()
        raise HTTPException(status_code=502, detail=detalhe or "Google nao renovou o acesso ao Drive.")

    payload["refresh_token"] = refresh_token
    _google_oauth_salvar_tokens_usuario(
        ctx.get("username"),
        ctx.get("client_id"),
        (registro or {}).get("google_email") or ctx.get("email"),
        payload,
    )
    return str(payload.get("access_token") or "").strip()


def _google_drive_access_token(ctx: dict) -> str:
    registro = _google_drive_token_linkado(ctx)
    if not registro:
        raise HTTPException(
            status_code=403,
            detail="Drive nao vinculado. Entre pelo botao Google uma vez para autorizar o backup automatico.",
        )
    access_token = str(registro.get("access_token") or "").strip()
    expires_at = _google_oauth_parse_expiry(registro.get("expires_at"))
    if access_token and (expires_at is None or expires_at > datetime.utcnow() + timedelta(seconds=45)):
        return access_token
    return _google_drive_refresh_access_token(ctx, registro)


def _google_drive_request(ctx: dict, method: str, url: str, **kwargs) -> requests.Response:
    headers = dict(kwargs.pop("headers", {}) or {})
    token = _google_drive_access_token(ctx)
    headers["Authorization"] = f"Bearer {token}"
    kwargs.setdefault("timeout", 40)
    resp = requests.request(method, url, headers=headers, **kwargs)
    if resp.status_code == 401:
        token = _google_drive_refresh_access_token(ctx)
        headers["Authorization"] = f"Bearer {token}"
        resp = requests.request(method, url, headers=headers, **kwargs)
    if resp.status_code >= 400:
        detalhe = ""
        try:
            payload = resp.json()
            detalhe = str(((payload.get("error") or {}).get("message") if isinstance(payload, dict) else "") or "")
        except Exception:
            detalhe = resp.text[:300]
        raise HTTPException(status_code=502, detail=detalhe or f"Google Drive retornou erro HTTP {resp.status_code}.")
    return resp


def _google_drive_query_literal(valor: str) -> str:
    return "'" + str(valor or "").replace("\\", "\\\\").replace("'", "\\'") + "'"


def _google_drive_get_or_create_folder(ctx: dict, name: str, parent_id: Optional[str] = None) -> str:
    parent_clause = f"{_google_drive_query_literal(parent_id)} in parents" if parent_id else "'root' in parents"
    query = " and ".join([
        "mimeType='application/vnd.google-apps.folder'",
        f"name={_google_drive_query_literal(name)}",
        "trashed=false",
        parent_clause,
    ])
    resp = _google_drive_request(
        ctx,
        "GET",
        "https://www.googleapis.com/drive/v3/files",
        params={"q": query, "spaces": "drive", "fields": "files(id,name)", "pageSize": 1},
    )
    data = resp.json() if resp.content else {}
    files = data.get("files") if isinstance(data, dict) else []
    if files:
        return str(files[0].get("id") or "")

    metadata = {
        "name": name,
        "mimeType": "application/vnd.google-apps.folder",
        "parents": [parent_id] if parent_id else ["root"],
    }
    resp = _google_drive_request(
        ctx,
        "POST",
        "https://www.googleapis.com/drive/v3/files",
        json=metadata,
        params={"fields": "id,name"},
    )
    data = resp.json() if resp.content else {}
    folder_id = str(data.get("id") or "").strip()
    if not folder_id:
        raise HTTPException(status_code=502, detail="Google Drive nao retornou a pasta de backup.")
    return folder_id


def _drive_sync_safe_name(valor: str) -> str:
    texto = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(valor or "default").strip())
    return (texto or "default")[:80]


def _drive_sync_folder_id(ctx: dict) -> str:
    root_id = _google_drive_get_or_create_folder(ctx, DRIVE_SYNC_FOLDER_ROOT)
    client_id = _google_drive_get_or_create_folder(ctx, _drive_sync_safe_name(ctx.get("client_id")), root_id)
    return _google_drive_get_or_create_folder(ctx, _drive_sync_safe_name(ctx.get("username")), client_id)


def _drive_sync_state_path(client_id: str, username: str) -> str:
    tenant_path = get_tenant_path(client_id)
    return os.path.join(tenant_path, f"drive_sync_state_{_drive_sync_safe_name(username)}.json")


def _drive_sync_carregar_estado(client_id: str, username: str) -> dict:
    path = _drive_sync_state_path(client_id, username)
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            return data if isinstance(data, dict) else {}
    except Exception:
        pass
    return {}


def _drive_sync_salvar_estado(client_id: str, username: str, data: dict):
    path = _drive_sync_state_path(client_id, username)
    estado = _drive_sync_carregar_estado(client_id, username)
    estado.update(data or {})
    estado["updated_at"] = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(estado, f, ensure_ascii=False, indent=2)


def _drive_sync_relativo_seguro(rel_path: str) -> str:
    rel = str(rel_path or "").replace("\\", "/").strip().lstrip("/")
    norm = os.path.normpath(rel).replace("\\", "/")
    if not norm or norm == "." or norm.startswith("../") or norm == ".." or os.path.isabs(norm):
        raise HTTPException(status_code=400, detail="Backup contem caminho invalido.")
    return norm


def _drive_sync_coletar_arquivos(client_id: str) -> list[dict]:
    tenant_path = get_tenant_path(client_id)
    tenant_abs = os.path.abspath(tenant_path)
    entries = []
    if not os.path.exists(tenant_abs):
        return entries

    for root, dirs, files in os.walk(tenant_abs):
        dirs[:] = [
            d for d in dirs
            if d not in {"__pycache__", "_drive_restore_backup"} and not d.startswith(".")
        ]
        for filename in files:
            name_lower = filename.lower()
            if name_lower.startswith("drive_sync_state_"):
                continue
            if name_lower.endswith((".tmp", ".log", ".bak")) or ".backup_" in name_lower:
                continue
            ext = os.path.splitext(filename)[1].lower()
            if ext not in DRIVE_SYNC_ALLOWED_EXTENSIONS:
                continue
            abs_path = os.path.abspath(os.path.join(root, filename))
            if not abs_path.startswith(tenant_abs + os.sep):
                continue
            try:
                size = os.path.getsize(abs_path)
            except OSError:
                continue
            if size > DRIVE_SYNC_MAX_FILE_BYTES:
                logger.warning("[DRIVE-SYNC] Ignorando arquivo grande demais no backup: %s", abs_path)
                continue
            sha = hashlib.sha256()
            try:
                with open(abs_path, "rb") as f:
                    for chunk in iter(lambda: f.read(1024 * 1024), b""):
                        sha.update(chunk)
                rel = os.path.relpath(abs_path, tenant_abs).replace("\\", "/")
                entries.append({
                    "relative_path": _drive_sync_relativo_seguro(rel),
                    "abs_path": abs_path,
                    "size": size,
                    "mtime": os.path.getmtime(abs_path),
                    "sha256": sha.hexdigest(),
                })
            except Exception as exc:
                logger.warning("[DRIVE-SYNC] Falha ao preparar arquivo para backup %s: %s", abs_path, exc)

    entries.sort(key=lambda item: item["relative_path"])
    return entries


def _drive_sync_snapshot_hash(entries: list[dict]) -> str:
    sha = hashlib.sha256()
    for item in entries:
        sha.update(str(item.get("relative_path") or "").encode("utf-8"))
        sha.update(b"\0")
        sha.update(str(item.get("size") or 0).encode("ascii"))
        sha.update(b"\0")
        sha.update(str(item.get("sha256") or "").encode("ascii"))
        sha.update(b"\n")
    return sha.hexdigest()


def _drive_sync_fernet(ctx: dict) -> Fernet:
    if Fernet is None:
        raise HTTPException(status_code=500, detail="Criptografia indisponivel neste instalador.")
    app_secret = _google_login_client_secret()
    if not app_secret:
        raise HTTPException(status_code=500, detail="Client Secret Google nao configurado para criptografar o backup.")
    username = str(ctx.get("username") or "").strip().lower()
    client_id = str(ctx.get("client_id") or "").strip() or "default"
    salt = f"jk-sistema-drive-sync|{client_id}|{username}".encode("utf-8")
    key = hashlib.pbkdf2_hmac("sha256", app_secret.encode("utf-8"), salt, 180000, dklen=32)
    return Fernet(base64.urlsafe_b64encode(key))


def _drive_sync_montar_pacote(ctx: dict) -> tuple[bytes, dict]:
    client_id = str(ctx.get("client_id") or "default").strip() or "default"
    username = str(ctx.get("username") or "").strip().lower()
    entries = _drive_sync_coletar_arquivos(client_id)
    snapshot_hash = _drive_sync_snapshot_hash(entries)
    manifest_files = [
        {
            "relative_path": item["relative_path"],
            "size": item["size"],
            "mtime": item["mtime"],
            "sha256": item["sha256"],
        }
        for item in entries
    ]
    manifest = {
        "schema": 1,
        "app": "JK Sistema",
        "created_at": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "client_id": client_id,
        "username": username,
        "google_email": ctx.get("email") or "",
        "snapshot_hash": snapshot_hash,
        "file_count": len(entries),
        "files": manifest_files,
    }

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
        for item in entries:
            zf.write(item["abs_path"], "files/" + item["relative_path"])

    encrypted = _drive_sync_fernet(ctx).encrypt(zip_buffer.getvalue())
    return encrypted, manifest


def _drive_sync_listar_backups(ctx: dict, limit: int = 10) -> list[dict]:
    folder_id = _drive_sync_folder_id(ctx)
    query = f"{_google_drive_query_literal(folder_id)} in parents and trashed=false and name contains '{DRIVE_SYNC_FILE_EXT}'"
    resp = _google_drive_request(
        ctx,
        "GET",
        "https://www.googleapis.com/drive/v3/files",
        params={
            "q": query,
            "spaces": "drive",
            "orderBy": "modifiedTime desc",
            "pageSize": max(1, min(100, int(limit or 10))),
            "fields": "files(id,name,modifiedTime,size,md5Checksum)",
        },
    )
    data = resp.json() if resp.content else {}
    files = data.get("files") if isinstance(data, dict) else []
    return files if isinstance(files, list) else []


def _drive_sync_limpar_backups_antigos(ctx: dict, manter: int = 20):
    try:
        backups = _drive_sync_listar_backups(ctx, limit=100)
        for item in backups[int(manter or 20):]:
            file_id = str((item or {}).get("id") or "").strip()
            if file_id:
                _google_drive_request(
                    ctx,
                    "DELETE",
                    f"https://www.googleapis.com/drive/v3/files/{quote(file_id, safe='')}",
                    timeout=25,
                )
    except Exception as exc:
        logger.warning("[DRIVE-SYNC] Nao foi possivel limpar backups antigos: %s", exc)


def _drive_sync_upload_backup(ctx: dict) -> dict:
    encrypted, manifest = _drive_sync_montar_pacote(ctx)
    folder_id = _drive_sync_folder_id(ctx)
    filename = (
        f"jk-sistema-backup-{_drive_sync_safe_name(ctx.get('client_id'))}-"
        f"{_drive_sync_safe_name(ctx.get('username'))}-"
        f"{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}{DRIVE_SYNC_FILE_EXT}"
    )
    metadata = {
        "name": filename,
        "parents": [folder_id],
        "mimeType": "application/octet-stream",
        "description": "Backup criptografado do JK Sistema",
    }
    resp = _google_drive_request(
        ctx,
        "POST",
        "https://www.googleapis.com/upload/drive/v3/files",
        params={"uploadType": "multipart", "fields": "id,name,modifiedTime,size"},
        files={
            "metadata": ("metadata", json.dumps(metadata, ensure_ascii=False), "application/json; charset=UTF-8"),
            "file": (filename, encrypted, "application/octet-stream"),
        },
        timeout=90,
    )
    data = resp.json() if resp.content else {}
    _drive_sync_salvar_estado(
        ctx.get("client_id"),
        ctx.get("username"),
        {
            "last_remote_file_id": data.get("id"),
            "last_remote_file_name": data.get("name"),
            "last_remote_modified_time": data.get("modifiedTime"),
            "last_snapshot_hash": manifest.get("snapshot_hash"),
            "last_backup_at": manifest.get("created_at"),
            "last_file_count": manifest.get("file_count"),
        },
    )
    _drive_sync_limpar_backups_antigos(ctx)
    return {"file": data, "manifest": manifest}


def _drive_sync_download_backup(ctx: dict, file_id: str) -> bytes:
    resp = _google_drive_request(
        ctx,
        "GET",
        f"https://www.googleapis.com/drive/v3/files/{quote(str(file_id), safe='')}",
        params={"alt": "media"},
        timeout=90,
    )
    return resp.content or b""


def _drive_sync_restaurar_bytes(ctx: dict, encrypted: bytes) -> dict:
    try:
        zip_bytes = _drive_sync_fernet(ctx).decrypt(encrypted)
    except InvalidToken:
        raise HTTPException(status_code=403, detail="Nao foi possivel descriptografar o backup desta conta.")

    tenant_path = get_tenant_path(ctx.get("client_id"))
    tenant_abs = os.path.abspath(tenant_path)
    restore_stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
    backup_dir = os.path.join(tenant_abs, "_drive_restore_backup", restore_stamp)

    with zipfile.ZipFile(io.BytesIO(zip_bytes), "r") as zf:
        try:
            manifest = json.loads(zf.read("manifest.json").decode("utf-8"))
        except Exception:
            raise HTTPException(status_code=400, detail="Backup do Drive esta corrompido ou incompleto.")
        if str(manifest.get("client_id") or "").strip() != str(ctx.get("client_id") or "").strip():
            raise HTTPException(status_code=403, detail="Backup pertence a outro cliente do sistema.")
        arquivos = manifest.get("files")
        if not isinstance(arquivos, list):
            raise HTTPException(status_code=400, detail="Manifesto do backup invalido.")

        restaurados = 0
        for item in arquivos:
            if not isinstance(item, dict):
                continue
            rel = _drive_sync_relativo_seguro(item.get("relative_path"))
            zip_name = "files/" + rel
            try:
                content = zf.read(zip_name)
            except KeyError:
                logger.warning("[DRIVE-SYNC] Arquivo ausente no pacote: %s", rel)
                continue
            destino = os.path.abspath(os.path.join(tenant_abs, rel.replace("/", os.sep)))
            if not destino.startswith(tenant_abs + os.sep):
                raise HTTPException(status_code=400, detail="Backup contem destino invalido.")
            os.makedirs(os.path.dirname(destino), exist_ok=True)
            if os.path.exists(destino):
                antigo = os.path.join(backup_dir, rel.replace("/", os.sep))
                os.makedirs(os.path.dirname(antigo), exist_ok=True)
                try:
                    shutil.copy2(destino, antigo)
                except Exception:
                    pass
            with open(destino, "wb") as f:
                f.write(content)
            restaurados += 1

    manifest["restored_file_count"] = restaurados
    return manifest


def _drive_sync_restaurar_ultimo(ctx: dict) -> dict:
    backups = _drive_sync_listar_backups(ctx, limit=1)
    if not backups:
        return {"restored": False, "message": "Nenhum backup encontrado no Google Drive.", "latest": None}
    latest = backups[0]
    encrypted = _drive_sync_download_backup(ctx, latest.get("id"))
    manifest = _drive_sync_restaurar_bytes(ctx, encrypted)
    _drive_sync_salvar_estado(
        ctx.get("client_id"),
        ctx.get("username"),
        {
            "last_remote_file_id": latest.get("id"),
            "last_remote_file_name": latest.get("name"),
            "last_remote_modified_time": latest.get("modifiedTime"),
            "last_snapshot_hash": manifest.get("snapshot_hash"),
            "last_restore_at": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
            "last_file_count": manifest.get("file_count"),
        },
    )
    return {"restored": True, "latest": latest, "manifest": manifest}


def _drive_sync_local_snapshot(client_id: str) -> tuple[str, int]:
    entries = _drive_sync_coletar_arquivos(client_id)
    return _drive_sync_snapshot_hash(entries), len(entries)


@app.get("/api/drive-sync/status")
def drive_sync_status(authorization: Optional[str] = Header(default=None)):
    ctx = _drive_sync_contexto_usuario(authorization)
    token_info = _google_drive_token_linkado(ctx)
    if not token_info:
        return {
            "success": True,
            "linked": False,
            "message": "Drive ainda nao vinculado. Entre pelo Google para ativar o backup automatico.",
        }
    backups = _drive_sync_listar_backups(ctx, limit=1)
    return {
        "success": True,
        "linked": True,
        "latest": backups[0] if backups else None,
        "state": _drive_sync_carregar_estado(ctx.get("client_id"), ctx.get("username")),
    }


@app.post("/api/drive-sync/backup")
def drive_sync_backup(authorization: Optional[str] = Header(default=None)):
    ctx = _drive_sync_contexto_usuario(authorization)
    result = _drive_sync_upload_backup(ctx)
    return {
        "success": True,
        "action": "uploaded",
        "message": "Backup salvo no Google Drive.",
        "file": result.get("file"),
        "file_count": (result.get("manifest") or {}).get("file_count"),
    }


@app.post("/api/drive-sync/restore-latest")
def drive_sync_restore_latest(authorization: Optional[str] = Header(default=None)):
    ctx = _drive_sync_contexto_usuario(authorization)
    result = _drive_sync_restaurar_ultimo(ctx)
    if not result.get("restored"):
        return {"success": True, "action": "none", "message": result.get("message"), "latest": None}
    manifest = result.get("manifest") or {}
    return {
        "success": True,
        "action": "restored",
        "message": "Backup do Google Drive restaurado nesta maquina.",
        "latest": result.get("latest"),
        "file_count": manifest.get("restored_file_count") or manifest.get("file_count"),
    }


@app.post("/api/drive-sync/backup-if-changed")
def drive_sync_backup_if_changed(authorization: Optional[str] = Header(default=None)):
    ctx = _drive_sync_contexto_usuario(authorization)
    token_info = _google_drive_token_linkado(ctx)
    if not token_info:
        return {
            "success": True,
            "linked": False,
            "action": "not_linked",
            "message": "Drive ainda nao vinculado. Entre pelo Google para ativar o backup automatico.",
        }

    client_id = ctx.get("client_id")
    username = ctx.get("username")
    estado = _drive_sync_carregar_estado(client_id, username)
    latest_list = _drive_sync_listar_backups(ctx, limit=1)
    latest = latest_list[0] if latest_list else None
    if latest and latest.get("id") != estado.get("last_remote_file_id"):
        return {
            "success": True,
            "linked": True,
            "action": "remote_changed",
            "message": "Existe backup remoto mais novo. Abra o dashboard para restaurar antes de enviar novos dados.",
            "latest": latest,
        }

    local_hash, local_count = _drive_sync_local_snapshot(client_id)
    if not local_count:
        return {
            "success": True,
            "linked": True,
            "action": "empty",
            "message": "Nenhum dado local encontrado para enviar ao Drive.",
        }
    if local_hash == estado.get("last_snapshot_hash"):
        return {
            "success": True,
            "linked": True,
            "action": "synced",
            "message": "Backup do Drive ja esta atualizado.",
            "file_count": local_count,
        }

    result = _drive_sync_upload_backup(ctx)
    return {
        "success": True,
        "linked": True,
        "action": "uploaded",
        "message": "Backup local enviado ao Google Drive.",
        "file": result.get("file"),
        "file_count": (result.get("manifest") or {}).get("file_count"),
    }


@app.post("/api/drive-sync/auto")
def drive_sync_auto(authorization: Optional[str] = Header(default=None)):
    ctx = _drive_sync_contexto_usuario(authorization)
    token_info = _google_drive_token_linkado(ctx)
    if not token_info:
        return {
            "success": True,
            "linked": False,
            "action": "not_linked",
            "message": "Drive ainda nao vinculado. Entre pelo Google para ativar o backup automatico.",
        }

    client_id = ctx.get("client_id")
    username = ctx.get("username")
    estado = _drive_sync_carregar_estado(client_id, username)
    local_hash, local_count = _drive_sync_local_snapshot(client_id)
    latest_list = _drive_sync_listar_backups(ctx, limit=1)
    latest = latest_list[0] if latest_list else None

    if latest and latest.get("id") != estado.get("last_remote_file_id"):
        local_igual_ao_ultimo = bool(estado.get("last_snapshot_hash")) and local_hash == estado.get("last_snapshot_hash")
        if local_count == 0 or local_igual_ao_ultimo or not estado.get("last_remote_file_id"):
            result = _drive_sync_restaurar_ultimo(ctx)
            manifest = result.get("manifest") or {}
            return {
                "success": True,
                "linked": True,
                "action": "restored",
                "message": "Dados restaurados do Google Drive.",
                "latest": result.get("latest"),
                "file_count": manifest.get("restored_file_count") or manifest.get("file_count"),
            }
        return {
            "success": True,
            "linked": True,
            "action": "conflict",
            "message": "Ha dados locais e um backup remoto diferente. Use Sincronizar Drive para enviar o estado local ou restaurar manualmente.",
            "latest": latest,
        }

    if local_count and local_hash != estado.get("last_snapshot_hash"):
        result = _drive_sync_upload_backup(ctx)
        return {
            "success": True,
            "linked": True,
            "action": "uploaded",
            "message": "Backup local enviado ao Google Drive.",
            "file": result.get("file"),
            "file_count": (result.get("manifest") or {}).get("file_count"),
        }

    return {
        "success": True,
        "linked": True,
        "action": "synced",
        "message": "Dados locais ja estao sincronizados com o Google Drive.",
        "latest": latest,
        "file_count": local_count,
    }


@app.post("/api/login", response_model=LoginResponse)
async def login_endpoint(payload: LoginRequest, request: Request):
    username = str(payload.username or "").strip().lower()
    senha = str(payload.password or "")
    if not username or not senha:
        return LoginResponse(success=False, message="Informe usuario e senha.")

    usuarios, ws, headers = carregar_usuarios_sheets()
    if not isinstance(usuarios, dict) or not usuarios:
        return LoginResponse(success=False, message="Nenhum usuario foi encontrado para autenticar.")

    usuario = usuarios.get(username)
    if not isinstance(usuario, dict):
        return LoginResponse(success=False, message="Usuario ou senha invalidos.")

    if not _login_senha_confere(senha, usuario.get("password") or ""):
        return LoginResponse(success=False, message="Usuario ou senha invalidos.")

    if not _login_usuario_ativo(usuario):
        return LoginResponse(success=False, message="Usuario inativo. Contate o administrador.")

    validade_ok, msg_validade = _login_validade_ok(usuario)
    sheet_id_validade = None
    if validade_ok and ws is not None:
        validade_ok, msg_validade, sheet_id_validade = verificar_validade_acesso(username, ws)
    if not validade_ok:
        return LoginResponse(success=False, message=msg_validade or "Acesso expirado ou invalido.")

    permissoes = (
        usuario.get("permissions")
        if isinstance(usuario.get("permissions"), dict)
        else extrair_permissoes(usuario.get("original_row") or [], headers or [])
    )
    permissoes = _normalizar_permissoes(permissoes)

    client_id = str(payload.client_id or usuario.get("client_id") or sheet_id_validade or "default").strip() or "default"
    usuario["client_id"] = client_id
    maquina_ok, msg_maquina, machine_final = _login_validar_e_registrar_maquina(
        username,
        usuario,
        permissoes,
        payload.machine_id,
        request,
    )
    if not maquina_ok:
        return LoginResponse(success=False, message=msg_maquina)

    try:
        _registrar_login_maquina(username, client_id, machine_final, request)
    except Exception as exc:
        logger.warning("[LOGIN] Nao foi possivel registrar auditoria de login para %s: %s", username, exc)
    try:
        _machine_presence_save(_machine_presence_record(username, client_id, machine_final, request, "login"))
    except Exception as exc:
        logger.warning("[LOGIN] Nao foi possivel registrar presenca inicial para %s: %s", username, exc)

    return _montar_resposta_login_sucesso(username, usuario, permissoes, client_id, machine_final)

