def _ml_price_band_index(price: Any) -> int | None:
    p = _parse_float_flex(price)
    if p is None or p < 0:
        return None
    if p <= 18.99:
        return 0
    if p <= 48.99:
        return 1
    if p <= 78.99:
        return 2
    if p <= 99.99:
        return 3
    if p <= 119.99:
        return 4
    if p <= 149.99:
        return 5
    if p <= 199.99:
        return 6
    return 7


def _recalcular_frete_por_grade_oficial(
    frete_base: Any,
    preco_base: Any,
    preco_alvo: Any,
) -> float | None:
    frete_ref = _parse_float_flex(frete_base)
    base_band = _ml_price_band_index(preco_base)
    alvo_band = _ml_price_band_index(preco_alvo)
    if frete_ref is None or base_band is None or alvo_band is None:
        return None

    row_match = None
    for _peso_label, valores in ML_FRETE_GRADE_OFICIAL:
        if base_band < len(valores) and abs(float(valores[base_band]) - float(frete_ref)) <= 0.02:
            row_match = valores
            break

    if row_match is None:
        return None
    if alvo_band >= len(row_match):
        return None
    return round(float(row_match[alvo_band]), 2)


def _recalcular_frete_por_faixa_ml(
    frete_base: Any,
    preco_base: Any,
    preco_alvo: Any,
    listing_type_id: str = "",
) -> float | None:
    """
    Quando o frete base coincide com a faixa oficial do ML para o preÃ§o-base,
    recalcula o frete do preÃ§o-alvo usando a mesma tabela/faixa.
    Se nÃ£o coincidir, retorna None para permitir fallback proporcional.
    """
    recalculado = _recalcular_frete_por_grade_oficial(frete_base, preco_base, preco_alvo)
    if recalculado is not None:
        return recalculado

    frete_ref = _parse_float_flex(frete_base)
    p_base = _parse_float_flex(preco_base)
    p_alvo = _parse_float_flex(preco_alvo)
    if frete_ref is None or p_base is None or p_alvo is None:
        return None
    if p_base <= 0 or p_alvo <= 0:
        return None

    frete_faixa_base = _ml_estimar_taxa_fixa_por_preco(p_base, listing_type_id=listing_type_id)
    frete_faixa_alvo = _ml_estimar_taxa_fixa_por_preco(p_alvo, listing_type_id=listing_type_id)
    if frete_faixa_base is None or frete_faixa_alvo is None:
        return None
    if abs(float(frete_ref) - float(frete_faixa_base)) > 0.02:
        return None
    return round(float(frete_faixa_alvo), 2)


def _normalizar_sku_saida(v):
    sku_raw = str(v or "").strip()
    if not sku_raw:
        return ""
    partes = [p.strip() for p in sku_raw.split(",") if p.strip()]
    if not partes:
        return ""
    return ", ".join(_normalizar_sku_mes(p) for p in partes)


def _build_df_planilha_analise_promo(dados_analise: list[dict], limpar_status_exibicao: bool = False) -> pd.DataFrame:
    linhas = []
    for item in dados_analise or []:
        preco_final = _to_float_safe(item.get('M 21 Fixa'))
        preco_final_ml = _to_float_safe(item.get('M ML'))
        preco_final_ml_display = _to_float_safe(item.get('preco_final_ml_display') or item.get('recebe_ml'))
        custo = _to_float_safe(item.get('Custo'))
        taxa_pct = _to_rate_safe(item.get('%'))
        imposto_pct_rate = _to_rate_safe(item.get('Imposto %', item.get('Imposto', '')))
        desconto_ml_val = _to_float_safe(item.get('Desconto ML'))

        # Normaliza preÃ§os finais priorizando campos explÃƒÂ­citos quando disponÃƒÂ­veis.
        preco_final_base = _to_float_safe(item.get('PreÃ§o Final'))
        if preco_final_base is not None:
            preco_final = preco_final_base
        preco_final_ml_base = _to_float_safe(
            item.get('deal_price')
            or item.get('preco_promocional_ml')
            or item.get('PreÃ§o Promocional ML')
        )
        if preco_final_ml_base is None:
            preco_final_ml_base = _to_float_safe(item.get('PreÃ§o Final ML'))
        if preco_final_ml_base is not None:
            preco_final_ml = preco_final_ml_base
        if preco_final_ml_display is None:
            preco_final_ml_display = _to_float_safe(item.get('PreÃ§o Final ML'))

        frete_base = item.get('Frete', '')
        frete_ml = item.get('Frete ML', frete_base)
        frete_gratis = item.get('Frete Gratis', item.get('Frete GrÃ¡tis', ''))
        frete_gratis_ml = item.get('Frete Gratis ML', item.get('Frete GrÃ¡tis ML', ''))
        if not frete_gratis:
            frete_gratis = 'SIM' if (preco_final is not None and preco_final >= 79.0) else 'NÃƒO'
        if not frete_gratis_ml:
            frete_gratis_ml = 'SIM' if (preco_final_ml is not None and preco_final_ml >= 79.0) else 'NÃƒO'

        frete_gratis_bool = _flag_frete_gratis(frete_gratis)
        frete_gratis_ml_bool = _flag_frete_gratis(frete_gratis_ml)

        frete_val = _to_float_safe(frete_base)
        frete_ml_val = _to_float_safe(frete_ml)
        tipo_txt = str(item.get("Tipo") or "").strip().lower()
        listing_type_hint = "free" if "grat" in tipo_txt else ""
        taxa_fixa_item = _to_float_safe(item.get("Taxa Fixa"))
        taxa_fixa_ml_item = _to_float_safe(item.get("Taxa Fixa ML"))
        taxa_fixa_a = taxa_fixa_item
        taxa_fixa_b = taxa_fixa_ml_item
        if taxa_fixa_a is None and preco_final is not None:
            taxa_fixa_a = _ml_estimar_taxa_fixa_por_preco(preco_final, listing_type_id=listing_type_hint)
        if taxa_fixa_b is None and preco_final_ml is not None:
            taxa_fixa_b = _ml_estimar_taxa_fixa_por_preco(preco_final_ml, listing_type_id=listing_type_hint)

        # Para frete grÃ¡tis, prioriza o recÃƒÂ¡lculo por faixa oficial do ML
        # com base no preÃ§o final da planilha. Se nÃ£o der para reconhecer a
        # faixa do frete-base, mantÃƒÂ©m o ajuste proporcional como fallback.
        if frete_gratis_ml_bool and frete_val is not None and preco_final is not None and preco_final_ml is not None:
            frete_ml_ajustado = _recalcular_frete_por_faixa_ml(
                frete_val,
                preco_final,
                preco_final_ml,
                listing_type_id=listing_type_hint,
            )
            if frete_ml_ajustado is None:
                frete_ml_ajustado = _ajustar_frete_por_preco_base(frete_val, preco_final, preco_final_ml)
            if frete_ml_ajustado is not None:
                frete_ml_val = frete_ml_ajustado
                frete_ml = formatar_moeda_br(frete_ml_val)

        # Regra solicitada: sem frete grÃ¡tis, usar valor fixo na coluna de frete.
        # Frete fica com o valor da API/arquivo de frete.
        # Taxa fixa do ML pertence ao detalhamento da tarifa, nao substitui frete.

        tarifa = _to_float_safe(item.get('Tarifa'))
        tarifa_ml = _to_float_safe(item.get('Tarifa ML'))
        if tarifa is None:
            tarifa = (preco_final * taxa_pct) if (preco_final is not None and taxa_pct is not None) else None
        if tarifa_ml is None:
            tarifa_ml = (preco_final_ml * taxa_pct) if (preco_final_ml is not None and taxa_pct is not None) else None
        desconto_ml_val = _calcular_desconto_ml_valor(
            desconto_atual=desconto_ml_val,
            ml_pct=item.get('ML % Campanha'),
            preco_base=item.get('PreÃƒÂ§o Base') or item.get('PreÃƒÂ§o Original') or item.get('ORIGINAL_PRICE'),
            preco_final_ml=preco_final_ml,
            tarifa_base=tarifa,
            tarifa_ml=tarifa_ml,
        )
        imposto_valor = (preco_final * imposto_pct_rate) if (preco_final is not None and imposto_pct_rate is not None) else None
        imposto_ml_valor = (preco_final_ml * imposto_pct_rate) if (preco_final_ml is not None and imposto_pct_rate is not None) else None
        if imposto_valor is None:
            imposto_valor = _to_float_safe(item.get('Imposto'))
        if imposto_ml_valor is None:
            imposto_ml_valor = _to_float_safe(item.get('Imposto ML'))

        valor_liquido = None
        valor_liquido_ml = None
        if preco_final is not None and custo is not None:
            valor_liquido = preco_final - custo - (frete_val or 0.0) - (imposto_valor or 0.0) - (tarifa or 0.0)
        if preco_final_ml is not None and custo is not None:
            valor_liquido_ml = preco_final_ml - custo - (frete_ml_val or 0.0) - (imposto_ml_valor or 0.0) - (tarifa_ml or 0.0)
            if desconto_ml_val is not None:
                valor_liquido_ml += desconto_ml_val

        margem_pct = None
        margem_ml_pct = None
        if valor_liquido is not None and preco_final not in (None, 0):
            margem_pct = (valor_liquido * 100.0) / preco_final
        if valor_liquido_ml is not None and preco_final_ml not in (None, 0):
            margem_ml_pct = (valor_liquido_ml * 100.0) / preco_final_ml

        status_raw = item.get('SituaÃƒÂ§ÃƒÂ£o', item.get('Status', ''))
        if limpar_status_exibicao and status_raw == 'Sem promocao fixa':
            status_raw = ''

        linhas.append({
            'Tipo': item.get('Tipo', ''),
            '%': item.get('%', ''),
            'SKU': _normalizar_sku_saida(item.get('SKU', '')),
            'TÃ­tulo': item.get('TÃ­tulo', ''),
            'Frete': frete_base,
            'Frete ML': frete_ml,
            'Frete GrÃ¡tis': frete_gratis,
            'Frete GrÃ¡tis ML': frete_gratis_ml,
            'Custo': item.get('Custo', ''),
            'Tarifa': formatar_moeda_br(tarifa) if tarifa is not None else item.get('Tarifa', ''),
            'Tarifa ML': formatar_moeda_br(tarifa_ml) if tarifa_ml is not None else item.get('Tarifa ML', ''),
            'MLB': item.get('MLB', ''),
            'Campanha ML': item.get('Campanha ML', ''),
            '% Fixa': item.get('% Fixa', item.get('Desconto', '')),
            'ML % Campanha': item.get('ML % Campanha', ''),
            'PreÃ§o Final': formatar_moeda_br(preco_final) if preco_final is not None else item.get('PreÃ§o Final', item.get('M 21 Fixa', '')),
            'Imposto %': _format_pct_br(imposto_pct_rate * 100.0) if imposto_pct_rate is not None else item.get('Imposto %', item.get('Imposto', '')),
            'Imposto': formatar_moeda_br(imposto_valor) if imposto_valor is not None else item.get('Imposto', ''),
            'Imposto Fixa': item.get('Imposto Fixa', formatar_moeda_br(imposto_valor) if imposto_valor is not None else item.get('Imposto', '')),
            'PreÃ§o Final ML': formatar_moeda_br(preco_final_ml_display) if preco_final_ml_display is not None else (formatar_moeda_br(preco_final_ml) if preco_final_ml is not None else item.get('PreÃ§o Final ML', item.get('M ML', ''))),
            'Imposto ML': formatar_moeda_br(imposto_ml_valor) if imposto_ml_valor is not None else item.get('Imposto ML', ''),
            'Desconto ML': formatar_moeda_br(desconto_ml_val) if desconto_ml_val is not None else item.get('Desconto ML', item.get('Desconto', '')),
            'Valor LÃ­quido': formatar_moeda_br(valor_liquido) if valor_liquido is not None else item.get('Valor LÃ­quido', ''),
            'Valor lÃ­quido ML': formatar_moeda_br(valor_liquido_ml) if valor_liquido_ml is not None else item.get('Valor lÃ­quido ML', ''),
            'Status': status_raw,
            'Margem': _format_pct_br(margem_pct) if margem_pct is not None else item.get('Margem', item.get('Margem %', '')),
            'Margem ML': _format_pct_br(margem_ml_pct) if margem_ml_pct is not None else item.get('Margem ML', item.get('Margem %', '')),
            'AÃ§Ã£o': item.get('Participar ou nÃ£o', item.get('AÃ§Ã£o', '')),
        })

    df = pd.DataFrame(linhas)
    for c in COLUNAS_PLANILHA_ANALISE_PROMO:
        if c not in df.columns:
            df[c] = ''
    return df[COLUNAS_PLANILHA_ANALISE_PROMO]


def _salvar_planilha_analise_promo(client_id: str, dados_analise: list[dict], prefixo: str = 'analise_promo') -> str:
    tenant_path = get_tenant_path(client_id)
    pasta_tmp = os.path.join(tenant_path, 'tmp', 'promo')
    os.makedirs(pasta_tmp, exist_ok=True)
    ts = datetime.now().strftime('%Y%m%d_%H%M%S')
    nome = f"{prefixo}_{ts}.xlsx"
    caminho = os.path.join(pasta_tmp, nome)
    df = _build_df_planilha_analise_promo(dados_analise, limpar_status_exibicao=True)
    with pd.ExcelWriter(caminho, engine='openpyxl') as writer:
        df.to_excel(writer, index=False, sheet_name='Analise Promocao')
    return nome


def _promo_linha_status_ativo_ou_programado(row: dict) -> bool:
    status = str((row or {}).get("Status") or "").strip().lower()
    return status in {"ativo", "programado", "active", "scheduled", "programmed"}


def _promo_linha_pct_fixa_maior_que_zero(row: dict) -> bool:
    valor = (row or {}).get("% Fixa", (row or {}).get("Desconto", ""))
    percentual = _parse_float_flex(valor)
    if percentual is None:
        return True
    return abs(float(percentual)) > 0.000001


def _promo_meta_contagem(meta: dict, *keys: str) -> Optional[int]:
    if not isinstance(meta, dict):
        return None
    for key in keys:
        valor = meta.get(key)
        parsed = _parse_float_flex(valor)
        if parsed is not None:
            return max(0, int(parsed))
    return None


def _promo_total_esperado_por_contagens(active_count: Optional[int], eligible_count: Optional[int]) -> Optional[int]:
    valores = [v for v in (active_count, eligible_count) if v is not None]
    if not valores:
        return None
    if active_count is not None and eligible_count is not None and active_count != eligible_count:
        return max(0, int(active_count)) + max(0, int(eligible_count))
    return max(0, int(max(valores)))


def _ml_classificar_status_promocao_valor(valor) -> str:
    status = normalizar_texto(valor)
    if not status:
        return ""
    if status in {"scheduled", "programmed", "programado", "programada", "agendado", "agendada", "pending"}:
        return "Programado"
    if "schedul" in status or "program" in status or "agend" in status:
        return "Programado"
    if status in {"active", "ativo", "participating", "participando", "started", "running"}:
        return "Ativo"
    if "start" in status or "particip" in status:
        return "Ativo"
    return ""


def _ml_classificar_status_promocao_entry(entry: dict) -> str:
    if not isinstance(entry, dict):
        return ""
    candidatos = [
        entry.get("_jk_status_item_consultado"),
        entry.get("status"),
        entry.get("promotion_status"),
        entry.get("status_item"),
        entry.get("item_status"),
        entry.get("state"),
    ]
    for chave in ("promotion", "campaign", "deal", "offer"):
        obj = entry.get(chave)
        if isinstance(obj, dict):
            candidatos.extend([
                obj.get("status"),
                obj.get("promotion_status"),
                obj.get("status_item"),
                obj.get("state"),
            ])

    encontrou_ativo = False
    for candidato in candidatos:
        classificacao = _ml_classificar_status_promocao_valor(candidato)
        if classificacao == "Programado":
            return "Programado"
        if classificacao == "Ativo":
            encontrou_ativo = True
    return "Ativo" if encontrou_ativo else ""


def _ml_classificar_status_promocao_por_id(promocoes_item, campaign_id: str) -> str:
    campaign_norm = str(campaign_id or "").strip().lower()
    if not campaign_norm:
        return ""

    chaves_id = {
        "id",
        "promotion_id",
        "promotionid",
        "campaign_id",
        "campaignid",
        "deal_id",
        "dealid",
        "offer_id",
        "offerid",
    }
    classificacoes = []

    def _ids_do_objeto(obj: dict) -> set[str]:
        ids = set()
        for chave, valor in obj.items():
            chave_norm = str(chave or "").strip().lower()
            if chave_norm in chaves_id and valor is not None:
                ids.add(str(valor).strip().lower())
        return ids

    vistos = set()
    nodes = 0

    def visitar(obj, depth: int = 0):
        nonlocal nodes
        nodes += 1
        if nodes > 4000 or depth > 8:
            return
        if isinstance(obj, (dict, list)):
            obj_id = id(obj)
            if obj_id in vistos:
                return
            vistos.add(obj_id)
        if isinstance(obj, list):
            for item in obj[:250]:
                visitar(item, depth + 1)
            return
        if not isinstance(obj, dict):
            return

        if campaign_norm in _ids_do_objeto(obj):
            classificacoes.append(_ml_classificar_status_promocao_entry(obj))

        for chave, valor in obj.items():
            if str(chave or "").strip().lower() == "item":
                continue
            if isinstance(valor, (dict, list)):
                visitar(valor, depth + 1)

    visitar(promocoes_item)
    if "Programado" in classificacoes:
        return "Programado"
    if "Ativo" in classificacoes:
        return "Ativo"
    return ""


def _ml_iterar_campos_payload_limitado(obj, *, max_depth: int = 8, max_nodes: int = 4000):
    """Percorre payloads grandes do ML sem risco de recursao infinita/profundidade excessiva."""
    stack = [("", obj, 0)]
    vistos = set()
    nodes = 0
    while stack:
        caminho, valor, depth = stack.pop()
        nodes += 1
        if nodes > max_nodes:
            break

        if isinstance(valor, dict):
            obj_id = id(valor)
            if obj_id in vistos:
                continue
            vistos.add(obj_id)
            if depth >= max_depth:
                continue
            for chave, conteudo in valor.items():
                chave_norm = str(chave or "").strip().lower()
                novo_caminho = f"{caminho}.{chave_norm}" if caminho else chave_norm
                if isinstance(conteudo, (dict, list)):
                    stack.append((novo_caminho, conteudo, depth + 1))
                else:
                    yield novo_caminho, conteudo
            continue

        if isinstance(valor, list):
            obj_id = id(valor)
            if obj_id in vistos:
                continue
            vistos.add(obj_id)
            if depth >= max_depth:
                continue
            for item in valor[:250]:
                if isinstance(item, (dict, list)):
                    stack.append((caminho, item, depth + 1))
                else:
                    yield caminho, item
            continue

        yield caminho, valor


def _ml_extrair_preco_promocao_raw(entry: dict, priorizar_percentual_total_api: bool = False):
    """Extrai somente preco final/desconto da promocao no payload do Mercado Livre."""
    if not isinstance(entry, dict):
        return None, None

    chaves_preco_ordem = (
        "price",
        "deal_price",
        "promotion_price",
        "final_price",
        "campaign_price",
        "new_price",
        "loyalty_price",
        "max_discounted_price",
        "discounted_price",
        "suggested_price",
    )
    chaves_preco = set(chaves_preco_ordem)
    termos_preco = (
        "price",
        "preco",
        "precio",
        "deal_price",
        "promotion_price",
        "final_price",
        "loyalty_price",
        "campaign_price",
        "new_price",
        "suggested_price",
        "max_discounted_price",
        "discounted_price",
    )
    termos_excluir_preco = (
        "receive",
        "receives",
        "seller_receives",
        "seller_receive",
        "net",
        "liquid",
        "liquido",
        "margin",
        "margem",
        "contribution",
        "contribuicao",
        "fee",
        "tariff",
        "tarifa",
        "commission",
        "comissao",
        "tax",
        "imposto",
    )

    def _path_tem(caminho: str, termos: tuple[str, ...]) -> bool:
        caminho_norm = str(caminho or "").lower()
        return any(termo in caminho_norm for termo in termos)

    candidatos_preco = []
    for chave in chaves_preco_ordem:
        obj = entry.get(chave)
        if isinstance(obj, dict):
            candidatos_preco.extend([obj.get("amount"), obj.get("value")])
        else:
            candidatos_preco.append(obj)

    for caminho, valor in _ml_iterar_campos_payload_limitado(entry):
        caminho_norm = str(caminho or "").lower()
        chave_norm = caminho_norm.rsplit(".", 1)[-1]
        if _path_tem(caminho_norm, termos_excluir_preco):
            continue
        if chave_norm in chaves_preco:
            candidatos_preco.append(valor)
            continue
        if chave_norm in {"amount", "value"} and _path_tem(caminho_norm, termos_preco):
            candidatos_preco.append(valor)

    preco = next((v for v in (_parse_float_flex(x) for x in candidatos_preco) if v is not None and v > 0), None)

    chaves_desconto_total = {
        "discount_percentage",
        "discount_percent",
    }
    chaves_desconto_componentes = {
        "seller_discount_percentage",
        "meli_discount_percentage",
        "seller_percentage",
        "meli_percentage",
    }
    termos_desconto = (
        "discount",
        "desconto",
        "seller_percentage",
        "meli_percentage",
        "seller_discount",
        "meli_discount",
    )
    termos_excluir_desconto = (
        "margin",
        "margem",
        "contribution",
        "contribuicao",
        "profit",
        "lucro",
        "receive",
        "receives",
        "seller_receives",
        "net",
        "liquid",
        "liquido",
        "fee",
        "tariff",
        "tarifa",
        "tax",
        "imposto",
    )

    candidatos_total_direto = [
        entry.get("discount_percentage"),
        entry.get("discount_percent"),
    ]
    candidatos_componentes_diretos = [
        entry.get("seller_discount_percentage"),
        entry.get("meli_discount_percentage"),
    ]
    meli_pct = _parse_float_flex(entry.get("meli_percentage") or entry.get("meli_discount_percentage"))
    seller_pct = _parse_float_flex(entry.get("seller_percentage") or entry.get("seller_discount_percentage"))
    soma_componentes = None
    if meli_pct is not None or seller_pct is not None:
        soma_componentes = float(meli_pct or 0.0) + float(seller_pct or 0.0)

    candidatos_total_payload = []
    candidatos_componentes_payload = []
    candidatos_contexto_payload = []
    candidatos_payload_ordem_original = []

    for caminho, valor in _ml_iterar_campos_payload_limitado(entry):
        caminho_norm = str(caminho or "").lower()
        chave_norm = caminho_norm.rsplit(".", 1)[-1]
        if _path_tem(caminho_norm, termos_excluir_desconto):
            continue
        if chave_norm in chaves_desconto_total:
            candidatos_total_payload.append(valor)
            candidatos_payload_ordem_original.append(valor)
            continue
        if chave_norm in chaves_desconto_componentes:
            candidatos_componentes_payload.append(valor)
            candidatos_payload_ordem_original.append(valor)
            continue
        if chave_norm in {"percent", "percentage", "pct"} and _path_tem(caminho_norm, termos_desconto):
            candidatos_contexto_payload.append(valor)
            candidatos_payload_ordem_original.append(valor)

    candidatos_desconto = []
    if priorizar_percentual_total_api:
        candidatos_desconto.extend(candidatos_total_direto)
        candidatos_desconto.extend(candidatos_total_payload)
        if soma_componentes is not None:
            candidatos_desconto.append(soma_componentes)
        candidatos_desconto.extend(candidatos_componentes_diretos)
        candidatos_desconto.extend(candidatos_componentes_payload)
        candidatos_desconto.extend(candidatos_contexto_payload)
    else:
        candidatos_desconto.extend(candidatos_total_direto)
        candidatos_desconto.extend(candidatos_componentes_diretos)
        if soma_componentes is not None:
            candidatos_desconto.insert(0, soma_componentes)
        candidatos_desconto.extend(candidatos_payload_ordem_original)

    desconto = next((v for v in (_parse_float_flex(x) for x in candidatos_desconto) if v is not None), None)
    if desconto is None:
        preco_original = _parse_float_flex(entry.get("original_price"))
        if preco_original is not None and preco_original > 0 and preco is not None and preco > 0:
            desconto = max(0.0, min(100.0, ((float(preco_original) - float(preco)) / float(preco_original)) * 100.0))
    return preco, desconto


def _ml_parse_percentual_promocao_texto(valor):
    if valor is None:
        return None
    texto = str(valor).strip()
    if not texto:
        return None
    match_pct = re.search(r"(-?\d+(?:[.,]\d+)?)\s*%", texto)
    if match_pct:
        return _parse_float_flex(match_pct.group(1))
    return _parse_float_flex(valor)


def _ml_extrair_percentual_sugerido_campanha_raw(entry: dict, preco_base=None):
    """Extrai o percentual total sugerido/ofertado pela campanha ML."""
    if not isinstance(entry, dict):
        return None

    def _normalizar_chave(chave: str) -> str:
        chave_txt = str(chave or "").strip().lower().replace("-", "_")
        return re.sub(r"[^a-z0-9_]", "", chave_txt)

    def _numero_campo(valor, chaves: tuple[str, ...] = ("percentage", "percent", "pct", "amount", "value", "price")):
        if isinstance(valor, dict):
            for chave in chaves:
                numero = _parse_float_flex(valor.get(chave))
                if numero is not None:
                    return numero
            return None
        return _parse_float_flex(valor)

    def _percentual_valido(valor):
        pct = _ml_parse_percentual_promocao_texto(valor)
        if pct is None:
            pct = _numero_campo(valor, ("percentage", "percent", "pct", "value", "amount"))
        if pct is None:
            return None
        pct = float(pct)
        if 0 < pct <= 100:
            return pct
        return None

    def _primeiro_percentual(candidatos):
        for valor in candidatos:
            pct = _percentual_valido(valor)
            if pct is not None:
                return pct
        return None

    def _percentual_por_valor(valor, base):
        numero = _numero_campo(valor, ("amount", "value", "discount", "price"))
        base_num = _parse_float_flex(base)
        if numero is None or base_num is None or base_num <= 0:
            return None
        pct = (float(numero) / float(base_num)) * 100.0
        if 0 < pct <= 100:
            return pct
        return None

    def _percentual_por_preco(preco_sugerido, base):
        preco_num = _numero_campo(preco_sugerido, ("amount", "value", "price"))
        base_num = _parse_float_flex(base)
        if preco_num is None or base_num is None or base_num <= 0 or preco_num <= 0:
            return None
        pct = ((float(base_num) - float(preco_num)) / float(base_num)) * 100.0
        if 0 < pct <= 100:
            inteiro = round(pct)
            if abs(pct - inteiro) <= 0.25:
                return float(inteiro)
            return pct
        return None

    def _preco_base_campanha():
        for valor in (
            entry.get("original_price"),
            entry.get("regular_price"),
            entry.get("base_price"),
            entry.get("standard_price"),
            preco_base,
        ):
            numero = _parse_float_flex(valor)
            if numero is not None and numero > 0:
                return numero
        return None

    def _soma_percentuais_componentes():
        seller_pct = _percentual_valido(
            entry.get("seller_percentage")
            if entry.get("seller_percentage") is not None
            else entry.get("seller_discount_percentage")
        )
        meli_pct = _percentual_valido(
            entry.get("meli_percentage")
            if entry.get("meli_percentage") is not None
            else entry.get("meli_discount_percentage")
        )
        if seller_pct is None and meli_pct is None:
            return None
        soma = float(seller_pct or 0.0) + float(meli_pct or 0.0)
        if 0 < soma <= 100:
            return soma
        return None

    chaves_seller_pct = {
        "seller_percentage",
        "seller_discount_percentage",
        "seller_discount_percent",
        "sellerpercentage",
        "sellerdiscountpercentage",
    }
    chaves_meli_pct = {
        "meli_percentage",
        "meli_discount_percentage",
        "meli_discount_percent",
        "melipercentage",
        "melidiscountpercentage",
    }
    chaves_sugeridas_pct = {
        "suggested_discount_percentage",
        "suggested_discount_percent",
        "recommended_discount_percentage",
        "recommended_discount_percent",
        "campaign_discount_percentage",
        "campaign_discount_percent",
        "deal_discount_percentage",
        "offer_discount_percentage",
        "min_discount_percentage",
        "minimum_discount_percentage",
        "max_discount_percentage",
        "maximum_discount_percentage",
    }
    chaves_diretas_pct = {
        "discount_percentage",
        "discount_percent",
    }
    chaves_valor_desconto = {
        "seller_discount_amount",
        "seller_discount_value",
        "suggested_discount_amount",
        "suggested_discount_value",
        "recommended_discount_amount",
        "recommended_discount_value",
        "campaign_discount_amount",
        "campaign_discount_value",
        "discount_amount",
        "discount_value",
    }
    chaves_preco_sugerido = {
        "price",
        "deal_price",
        "promotion_price",
        "final_price",
        "discounted_price",
        "suggested_discounted_price",
        "suggested_price",
        "suggested_deal_price",
        "recommended_discounted_price",
        "recommended_price",
        "campaign_price",
    }

    seller_direto = []
    meli_direto = []
    sugerido_direto = []
    direto_pct = []
    valor_desconto = []
    preco_sugerido = []
    preco_base_item = _preco_base_campanha()

    for chave, valor in entry.items():
        chave_norm = _normalizar_chave(chave)
        if chave_norm in chaves_seller_pct:
            seller_direto.append(valor)
        elif chave_norm in chaves_meli_pct:
            meli_direto.append(valor)
        elif chave_norm in chaves_sugeridas_pct:
            sugerido_direto.append(valor)
        elif chave_norm in chaves_diretas_pct:
            direto_pct.append(valor)
        elif chave_norm in chaves_valor_desconto:
            valor_desconto.append(valor)
        elif chave_norm in chaves_preco_sugerido:
            preco_sugerido.append(valor)

    seller_payload = []
    meli_payload = []
    sugerido_payload = []
    direto_payload = []
    valor_payload = []
    preco_payload = []
    termos_excluir = ("fee", "tariff", "tarifa", "tax", "imposto", "margin", "margem", "contribution", "receive")

    for caminho, valor in _ml_iterar_campos_payload_limitado(entry):
        caminho_norm = str(caminho or "").lower()
        if any(termo in caminho_norm for termo in termos_excluir):
            continue
        chave_norm = _normalizar_chave(caminho_norm.rsplit(".", 1)[-1])
        tem_percentual = "percent" in caminho_norm or "percentage" in caminho_norm or chave_norm.endswith("_pct")
        if chave_norm in chaves_seller_pct or ("seller" in caminho_norm and tem_percentual):
            seller_payload.append(valor)
            continue
        if chave_norm in chaves_meli_pct or ("meli" in caminho_norm and tem_percentual):
            meli_payload.append(valor)
            continue
        if chave_norm in chaves_sugeridas_pct or (tem_percentual and any(t in caminho_norm for t in ("suggest", "recommend", "campaign", "deal", "offer"))):
            sugerido_payload.append(valor)
            continue
        if chave_norm in chaves_diretas_pct:
            direto_payload.append(valor)
            continue
        if tem_percentual and "discount" in caminho_norm:
            direto_payload.append(valor)
            continue
        if chave_norm in chaves_valor_desconto or ("discount" in caminho_norm and any(t in caminho_norm for t in ("seller", "suggest", "recommend", "campaign", "deal", "offer")) and not tem_percentual):
            valor_payload.append(valor)
            continue
        if chave_norm in chaves_preco_sugerido:
            preco_payload.append(valor)

    for grupo in (sugerido_direto, sugerido_payload, direto_pct, direto_payload):
        pct = _primeiro_percentual(grupo)
        if pct is not None:
            return pct

    for grupo in (preco_sugerido, preco_payload):
        for valor in grupo:
            pct = _percentual_por_preco(valor, preco_base_item)
            if pct is not None:
                return pct

    componentes = _soma_percentuais_componentes()
    if componentes is not None:
        return componentes

    meli_pct = _primeiro_percentual(meli_direto) or _primeiro_percentual(meli_payload)
    seller_pct = _primeiro_percentual(seller_direto) or _primeiro_percentual(seller_payload)
    if meli_pct is not None and seller_pct is not None:
        soma = float(meli_pct) + float(seller_pct)
        if 0 < soma <= 100:
            return soma

    if seller_pct is not None:
        return seller_pct
    if meli_pct is not None:
        return meli_pct

    for grupo in (valor_desconto, valor_payload):
        for valor in grupo:
            pct = _percentual_por_valor(valor, preco_base_item)
            if pct is not None:
                return pct

    return None


def _ml_extrair_desconto_tarifa_promocao_raw(entry: dict):
    """Extrai o valor em R$ de reduÃ§Ã£o de tarifa da campanha, quando a API retorna esse detalhe."""
    if not isinstance(entry, dict):
        return None

    candidatos_explicitos = []

    for novo_caminho, valor in _ml_iterar_campos_payload_limitado(entry):
        parece_valor_tarifa = (
            "sale_fee" in novo_caminho
            or "fee" in novo_caminho
            or "tariff" in novo_caminho
            or "tarifa" in novo_caminho
        )
        parece_desconto_tarifa = (
            "fee_discount" in novo_caminho
            or "discount_fee" in novo_caminho
            or "tariff_discount" in novo_caminho
            or "sale_fee_discount" in novo_caminho
            or "sale_fee_reduction" in novo_caminho
            or "reduction" in novo_caminho
            or "reducao" in novo_caminho
            or "reduÃ§Ã£o" in novo_caminho
            or "discount" in novo_caminho
            or "desconto" in novo_caminho
            or "rebate" in novo_caminho
        )
        parece_percentual = "percent" in novo_caminho or "percentage" in novo_caminho or novo_caminho.endswith("_pct")
        if parece_valor_tarifa and parece_desconto_tarifa and not parece_percentual:
            v = _parse_float_flex(valor)
            if v is not None and v > 0:
                candidatos_explicitos.append(float(v))
    if candidatos_explicitos:
        return candidatos_explicitos[0]

    meli_pct = _parse_float_flex(entry.get("meli_percentage"))
    preco_base = (
        _parse_float_flex(entry.get("original_price"))
        or _parse_float_flex(entry.get("base_price"))
        or _parse_float_flex(entry.get("standard_price"))
    )
    if meli_pct is not None and preco_base is not None:
        return round(float(preco_base) * float(meli_pct) / 100.0, 2)
    return None


def _ml_extrair_tarifa_cobrada_promocao_raw(entry: dict):
    """Extrai o valor cobrado de tarifa dentro do payload da promocao, quando disponivel."""
    if not isinstance(entry, dict):
        return None

    candidatos = []

    for novo_caminho, valor in _ml_iterar_campos_payload_limitado(entry):
        parece_tarifa = (
            "sale_fee" in novo_caminho
            or "fee_amount" in novo_caminho
            or "tariff_amount" in novo_caminho
            or "tarifa_valor" in novo_caminho
            or novo_caminho.endswith(".fee")
        )
        parece_desconto = (
            "discount" in novo_caminho
            or "reduction" in novo_caminho
            or "rebate" in novo_caminho
            or "desconto" in novo_caminho
            or "reducao" in novo_caminho
            or "reduÃƒÂ§ÃƒÂ£o" in novo_caminho
        )
        parece_percentual = (
            "percent" in novo_caminho
            or "percentage" in novo_caminho
            or novo_caminho.endswith("_pct")
            or novo_caminho.endswith(".pct")
        )
        if parece_tarifa and not parece_desconto and not parece_percentual:
            v = _parse_float_flex(valor)
            if v is not None and v >= 0:
                candidatos.append(float(v))
    return candidatos[0] if candidatos else None


def _ml_obter_item_promocao_raw(client_id: str, loja: str, cfg: dict, campaign_id: str, promotion_type: str, item_id: str, request_fn=None):
    request_fn = request_fn or _ml_api_request
    campaign_id = str(campaign_id or "").strip()
    promotion_type = str(promotion_type or "").strip()
    if promotion_type in {"-", "None", "null"}:
        promotion_type = ""
    item_id = str(item_id or "").strip()
    if not campaign_id or not promotion_type or not item_id:
        return {}, cfg

    urls = [
        f"https://api.mercadolibre.com/seller-promotions/promotions/{campaign_id}/items",
    ]
    consultas_status = [
        ("status_item", "pending"),
        ("status", "pending"),
        ("status_item", "started"),
        ("status", "started"),
        ("status_item", "active"),
        ("status", "active"),
        ("status_item", "candidate"),
        ("status", "candidate"),
        ("status_item", "eligible"),
        ("status", "eligible"),
        ("", ""),
    ]
    for status_param, status_item in consultas_status:
        params = {
            "app_version": "v2",
            "promotion_type": promotion_type,
            "item_id": item_id,
        }
        if status_param and status_item:
            params[status_param] = status_item
        for url in urls:
            offset = 0
            limit = 50
            paginas = 0
            while True:
                paginas += 1
                params_chamada = dict(params)
                params_chamada.update({"offset": offset, "limit": limit})
                if request_fn is _ml_api_request:
                    resp, cfg = _ml_api_request_com_retry(
                        client_id,
                        loja,
                        cfg,
                        "GET",
                        url,
                        params=params_chamada,
                        timeout=30,
                        max_attempts=3,
                    )
                else:
                    resp, cfg = request_fn(client_id, loja, cfg, "GET", url, params=params_chamada, timeout=30)
                if resp.status_code != 200:
                    break
                try:
                    data = resp.json() or {}
                except Exception:
                    data = {}
                entries = data.get("results") or data.get("items") or []
                for entry in entries:
                    if not isinstance(entry, dict):
                        continue
                    raw_item = entry.get("item")
                    item_obj_id = raw_item.get("id") if isinstance(raw_item, dict) else raw_item
                    entry_id = str(entry.get("item_id") or entry.get("itemId") or item_obj_id or entry.get("id") or "").strip()
                    if entry_id == item_id:
                        entry = dict(entry)
                        if status_item:
                            entry["_jk_status_item_consultado"] = status_item
                            entry["_jk_status_param_consultado"] = status_param
                        return entry, cfg
                paging = data.get("paging") or {}
                total = int(paging.get("total") or 0)
                offset += limit
                if not entries or len(entries) < limit or (total and offset >= total) or paginas >= 100:
                    break
    return {}, cfg


def _ml_promocao_raw_texto(entry: dict, chaves: tuple[str, ...]) -> str:
    if not isinstance(entry, dict):
        return ""
    containers = [
        entry,
        entry.get("promotion") if isinstance(entry.get("promotion"), dict) else {},
        entry.get("campaign") if isinstance(entry.get("campaign"), dict) else {},
        entry.get("deal") if isinstance(entry.get("deal"), dict) else {},
        entry.get("offer") if isinstance(entry.get("offer"), dict) else {},
    ]
    for container in containers:
        if not isinstance(container, dict):
            continue
        for chave in chaves:
            valor = container.get(chave)
            texto = str(valor or "").strip()
            if texto and texto.lower() not in {"-", "none", "null"}:
                return texto
    return ""


def _ml_promocao_raw_id(entry: dict) -> str:
    return _ml_promocao_raw_texto(
        entry,
        (
            "promotion_id",
            "promotionId",
            "campaign_id",
            "campaignId",
            "deal_id",
            "dealId",
            "offer_id",
            "offerId",
            "id",
        ),
    )


def _ml_promocao_raw_tipo(entry: dict) -> str:
    return _ml_promocao_raw_texto(
        entry,
        ("promotion_type", "promotionType", "type", "campaign_type", "campaignType"),
    )


def _ml_promocao_raw_nome(entry: dict) -> str:
    return _ml_promocao_raw_texto(entry, ("name", "title", "label"))


def _ml_promocao_raw_offer_id(entry: dict) -> str:
    texto = _ml_promocao_raw_texto(
        entry,
        ("offer_id", "offerId", "ref_id", "refId", "candidate_offer_id", "candidateOfferId"),
    )
    if texto:
        return texto
    if not isinstance(entry, dict):
        return ""
    chaves_offer = {"offer_id", "offerid", "ref_id", "refid", "candidate_offer_id", "candidateofferid"}
    for caminho, valor in _ml_iterar_campos_payload_limitado(entry, max_depth=5, max_nodes=900):
        ultimo = str(caminho or "").rsplit(".", 1)[-1].strip().lower().replace("-", "_")
        ultimo = re.sub(r"[^a-z0-9_]", "", ultimo)
        if ultimo in chaves_offer or ultimo.replace("_", "") in chaves_offer:
            valor_txt = str(valor or "").strip()
            if valor_txt and valor_txt.lower() not in {"-", "none", "null"}:
                return valor_txt
    return ""


def _ml_grupo_promocao_por_meta(promotion_type: str = "", nome: str = "") -> str:
    tipo = str(promotion_type or "").strip().upper()
    nome_norm = normalizar_texto(str(nome or ""))
    if tipo in {"SELLER_CAMPAIGN", "SELLER_COUPON_CAMPAIGN"}:
        return "usuario"
    if tipo in {"SMART", "PRICE_MATCHING", "PRICE_MATCHING_MELI_ALL", "MARKETPLACE_CAMPAIGN", "PRE_NEGOTIATED"}:
        return "mercado_livre"
    if any(chave in nome_norm for chave in ["aceler", "tarifa", "menos tarifa", "reduzimos", "aumente suas vendas"]):
        return "mercado_livre"
    return "outras"


def _ml_grupo_promocao_raw(entry: dict) -> str:
    return _ml_grupo_promocao_por_meta(_ml_promocao_raw_tipo(entry), _ml_promocao_raw_nome(entry))


def _ml_resolver_raw_promocao_equivalente_para_analise(
    client_id: str,
    loja: str,
    cfg: dict,
    item_id: str,
    raw_atual: dict,
    campaign_id: str,
    promotion_type: str,
    preco_base=None,
    request_fn=None,
):
    """Para SMART candidate, usa a campanha equivalente de mesmo nome com melhor oferta."""
    if not item_id or not isinstance(raw_atual, dict):
        return raw_atual, cfg
    tipo_alvo = str(promotion_type or _ml_promocao_raw_tipo(raw_atual) or "").strip().upper()
    if tipo_alvo != "SMART":
        return raw_atual, cfg
    if _promo_status_item_promocao(raw_atual) not in {"candidate", "eligible"}:
        return raw_atual, cfg

    request_fn = request_fn or _ml_api_request
    try:
        promocoes_item, cfg = _ml_obter_promocoes_item(client_id, loja, cfg, item_id, request_fn=request_fn)
    except Exception:
        return raw_atual, cfg
    if not promocoes_item:
        return raw_atual, cfg

    raw_ref = _ml_encontrar_promocao_raw_item(promocoes_item, campaign_id) or {}
    nome_ref = _ml_promocao_raw_nome(raw_atual) or _ml_promocao_raw_nome(raw_ref)
    nome_ref_norm = normalizar_texto(nome_ref)
    if not nome_ref_norm:
        return raw_atual, cfg

    def _metricas(raw: dict) -> tuple[float | None, float | None]:
        preco, desc = _ml_extrair_preco_promocao_raw(raw, priorizar_percentual_total_api=True)
        if preco is None:
            preco = _parse_float_flex((raw or {}).get("price"))
        pct = _ml_extrair_percentual_sugerido_campanha_raw(raw, preco_base)
        if pct is None:
            pct = desc
        if pct is None:
            seller_pct = _parse_float_flex((raw or {}).get("seller_percentage"))
            meli_pct = _parse_float_flex((raw or {}).get("meli_percentage"))
            if seller_pct is not None or meli_pct is not None:
                pct = float(seller_pct or 0.0) + float(meli_pct or 0.0)
        return (_to_float_safe(preco), _to_float_safe(pct))

    melhor = raw_atual
    melhor_preco, melhor_pct = _metricas(melhor)
    for raw in promocoes_item:
        if not isinstance(raw, dict):
            continue
        raw_tipo = str(_ml_promocao_raw_tipo(raw) or tipo_alvo or "").strip().upper()
        if raw_tipo and raw_tipo != tipo_alvo:
            continue
        if normalizar_texto(_ml_promocao_raw_nome(raw)) != nome_ref_norm:
            continue
        candidato_preco, candidato_pct = _metricas(raw)
        if candidato_preco is None and candidato_pct is None:
            continue
        melhorou_preco = (
            candidato_preco is not None
            and (melhor_preco is None or float(candidato_preco) < float(melhor_preco) - 0.01)
        )
        melhorou_pct = (
            candidato_pct is not None
            and (melhor_pct is None or float(candidato_pct) > float(melhor_pct) + 0.01)
        )
        if not (melhorou_preco or melhorou_pct):
            continue

        detalhe = {}
        promo_id = _ml_promocao_raw_id(raw)
        promo_type = _ml_promocao_raw_tipo(raw) or tipo_alvo
        if promo_id and promo_type:
            try:
                detalhe, cfg = _ml_obter_item_promocao_raw(
                    client_id,
                    loja,
                    cfg,
                    promo_id,
                    promo_type,
                    item_id,
                    request_fn=request_fn,
                )
            except Exception:
                detalhe = {}
        melhor = detalhe if detalhe else raw
        melhor_preco, melhor_pct = _metricas(melhor)

    return melhor, cfg


def _ml_promocao_raw_esta_ativa_ou_indefinida(entry: dict) -> bool:
    status = _ml_classificar_status_promocao_entry(entry)
    if status in {"Ativo", ""}:
        return True
    return False


