def _ml_extrair_valor_desconto_taxa_promocao_raw(entry: dict):
    """Extrai apenas reducao de taxa/tarifa explicitamente indicada no payload."""
    if not isinstance(entry, dict):
        return None
    for caminho, valor in _ml_iterar_campos_payload_limitado(entry):
        caminho_norm = str(caminho or "").lower()
        caminho_ascii = normalizar_texto(caminho_norm)
        parece_taxa = (
            "sale_fee" in caminho_norm
            or "selling_fee" in caminho_norm
            or "fee_per_sale" in caminho_norm
            or "fee" in caminho_norm
            or "tariff" in caminho_norm
            or "tarifa" in caminho_ascii
            or "taxa" in caminho_ascii
        )
        parece_desconto = (
            "fee_discount" in caminho_norm
            or "discount_fee" in caminho_norm
            or "tariff_discount" in caminho_norm
            or "sale_fee_discount" in caminho_norm
            or "sale_fee_reduction" in caminho_norm
            or "discount" in caminho_norm
            or "reduction" in caminho_norm
            or "rebate" in caminho_norm
            or "desconto" in caminho_ascii
            or "reducao" in caminho_ascii
        )
        parece_percentual = (
            "percent" in caminho_norm
            or "percentage" in caminho_norm
            or caminho_norm.endswith("_pct")
            or caminho_norm.endswith(".pct")
        )
        parece_desconto_preco = (
            "price" in caminho_norm
            or "preco" in caminho_ascii
            or "loyalty" in caminho_norm
            or "seller_percentage" in caminho_norm
            or "meli_percentage" in caminho_norm
            or "discount_percentage" in caminho_norm
        )
        if parece_taxa and parece_desconto and not parece_percentual and not parece_desconto_preco:
            v = _parse_float_flex(valor)
            if v is not None and v > 0:
                return float(v)
    return None


def _ml_obter_desconto_taxa_promocao_item(
    client_id: str,
    loja: str,
    cfg: dict,
    item_id: str,
    item: Optional[dict] = None,
    price_info: Optional[dict] = None,
    fee_data: Optional[dict] = None,
    deal_ids: Optional[list] = None,
    request_fn=None,
):
    """Busca a promocao ativa do item e calcula reducao de tarifa para a margem."""
    request_fn = request_fn or _ml_api_request
    price_info = price_info or {}
    fee_data = fee_data or {}
    item = item or {}
    item_id = str(item_id or "").strip()
    info = {
        "promotion_fee_discount": None,
        "promotion_fee_discount_text": "",
        "promotion_fee_charged": None,
        "promotion_fee_charged_text": "",
        "promotion_fee_discount_source": "",
        "promotion_fee_discount_applied": False,
        "promotion_fee_discount_note": "",
        "promotion_id": price_info.get("promotion_id"),
        "promotion_type": price_info.get("promotion_type"),
        "promotion_name": "",
    }
    if not item_id:
        return info, cfg

    ids_alvo: list[str] = []

    def _add_id(valor):
        texto = str(valor or "").strip()
        if texto and texto.lower() not in {"-", "none", "null"} and texto not in ids_alvo:
            ids_alvo.append(texto)

    _add_id(price_info.get("promotion_id"))
    for deal_id in deal_ids or []:
        _add_id(deal_id)

    promocoes_item = []
    try:
        promocoes_item, cfg = _ml_obter_promocoes_item(
            client_id,
            loja,
            cfg,
            item_id,
            request_fn=request_fn,
        )
    except Exception as exc:
        logger.warning("[ML API] Falha ao consultar promocoes do item %s para desconto de tarifa: %s", item_id, exc)
        promocoes_item = []

    candidatos_ml: list[dict] = []
    candidatos_usuario: list[dict] = []
    vistos = set()

    def _add_candidato(raw, preferido: bool = False):
        if not isinstance(raw, dict):
            return
        chave = (
            _ml_promocao_raw_id(raw).lower(),
            _ml_promocao_raw_tipo(raw).lower(),
            str(raw.get("_jk_status_item_consultado") or ""),
        )
        if chave in vistos:
            return
        vistos.add(chave)
        grupo = _ml_grupo_promocao_raw(raw)
        ativo = _ml_promocao_raw_esta_ativa_ou_indefinida(raw)
        if grupo == "mercado_livre" and ativo:
            if preferido:
                candidatos_ml.insert(0, raw)
            else:
                candidatos_ml.append(raw)
        elif grupo == "usuario" and ativo:
            candidatos_usuario.append(raw)

    if ids_alvo:
        for promo_id in ids_alvo:
            raw = _ml_encontrar_promocao_raw_item(promocoes_item, promo_id)
            _add_candidato(raw, preferido=True)

    if isinstance(promocoes_item, list):
        for raw in promocoes_item:
            if not isinstance(raw, dict):
                continue
            raw_id = _ml_promocao_raw_id(raw)
            if ids_alvo and raw_id and raw_id not in ids_alvo:
                _add_candidato(raw)
                continue
            _add_candidato(raw, preferido=bool(raw_id and raw_id in ids_alvo))

    promo_id_fallback = str(price_info.get("promotion_id") or "").strip()
    promo_type_fallback = str(price_info.get("promotion_type") or "").strip()
    if promo_id_fallback and promo_type_fallback and _ml_grupo_promocao_por_meta(promo_type_fallback) == "mercado_livre":
        _add_candidato({"id": promo_id_fallback, "promotion_type": promo_type_fallback}, preferido=True)

    preco_final = _to_float_safe(price_info.get("price"))
    preco_base = (
        _to_float_safe(price_info.get("original_price"))
        or _to_float_safe(price_info.get("standard_price"))
        or _to_float_safe(item.get("original_price"))
        or _to_float_safe(item.get("base_price"))
        or preco_final
    )
    tarifa_base = _to_float_safe(fee_data.get("ad_cost"))
    melhor = dict(info)

    def _detalhar_raw_promocao(raw: dict) -> dict:
        nonlocal cfg
        promo_id = _ml_promocao_raw_id(raw)
        promo_type = _ml_promocao_raw_tipo(raw)
        if promo_id and promo_type and item_id:
            try:
                detalhe, cfg = _ml_obter_item_promocao_raw(
                    client_id,
                    loja,
                    cfg,
                    promo_id,
                    promo_type,
                    item_id,
                    request_fn=request_fn,
                )
                if isinstance(detalhe, dict) and detalhe:
                    return detalhe
            except Exception as exc:
                logger.warning(
                    "[ML API] Falha ao detalhar promocao %s/%s do item %s: %s",
                    promo_id,
                    promo_type,
                    item_id,
                    exc,
                )
        return raw if isinstance(raw, dict) else {}

    raw_a_base = _detalhar_raw_promocao(candidatos_usuario[0]) if candidatos_usuario else {}

    for raw_b in candidatos_ml:
        raw_b_item = _detalhar_raw_promocao(raw_b)
        promo_id = _ml_promocao_raw_id(raw_b_item) or _ml_promocao_raw_id(raw_b) or promo_id_fallback
        promo_type = _ml_promocao_raw_tipo(raw_b_item) or _ml_promocao_raw_tipo(raw_b) or promo_type_fallback
        promo_name = _ml_promocao_raw_nome(raw_b_item) or _ml_promocao_raw_nome(raw_b)

        raw_a_item = raw_a_base
        preco_a_raw, desc_a_raw = _ml_extrair_preco_promocao_raw(raw_a_item)
        preco_b_raw, _desc_b_raw = _ml_extrair_preco_promocao_raw(raw_b_item)
        preco_a = preco_a_raw or preco_base or preco_final
        preco_b = preco_b_raw or preco_final or preco_base
        if preco_a_raw is None and desc_a_raw is not None and preco_base and preco_base > 0:
            preco_a = round(float(preco_base) * max(0.0, 1.0 - (float(desc_a_raw) / 100.0)), 2)

        fee_a = {}
        tarifa_a_val = _ml_extrair_tarifa_cobrada_promocao_raw(raw_a_item)
        if tarifa_a_val is None and preco_a is not None:
            item_taxa_a = dict(item or {})
            item_taxa_a["price"] = preco_a
            try:
                fee_a, cfg = _ml_obter_taxas_anuncio(
                    client_id,
                    loja,
                    cfg,
                    item_taxa_a,
                    request_fn=request_fn,
                )
            except Exception:
                fee_a = {}
            tarifa_a_val = _to_float_safe(fee_a.get("ad_cost"))
        if tarifa_a_val is None:
            tarifa_a_val = tarifa_base

        tarifa_b_val = _ml_extrair_tarifa_cobrada_promocao_raw(raw_b_item)
        if tarifa_b_val is None and preco_b is not None:
            item_taxa_b = dict(item or {})
            item_taxa_b["price"] = preco_b
            try:
                fee_b, cfg = _ml_obter_taxas_anuncio(
                    client_id,
                    loja,
                    cfg,
                    item_taxa_b,
                    request_fn=request_fn,
                )
            except Exception:
                fee_b = {}
            tarifa_b_val = _to_float_safe(fee_b.get("ad_cost"))
        if tarifa_b_val is None:
            tarifa_b_val = _to_float_safe(fee_data.get("ad_cost"))

        if tarifa_a_val is None or tarifa_b_val is None:
            continue

        desconto = round(float(tarifa_a_val) - float(tarifa_b_val), 2)

        if desconto is None or desconto <= 0:
            continue

        desconto = round(float(desconto), 2)
        tarifa_promocao = max(float(tarifa_b_val), 0.0)

        melhor.update({
            "promotion_fee_discount": desconto,
            "promotion_fee_discount_text": formatar_moeda_br(desconto),
            "promotion_fee_charged": round(float(tarifa_promocao), 2),
            "promotion_fee_charged_text": formatar_moeda_br(tarifa_promocao),
            "promotion_fee_discount_source": "seller_promotions_listing_prices_comparison",
            "promotion_fee_discount_applied": False,
            "promotion_fee_discount_note": "Comparativo via API entre sale_fee_amount do preco base/usuario e sale_fee_amount do preco promocional. Nao aplicado automaticamente na margem.",
            "promotion_id": promo_id or melhor.get("promotion_id"),
            "promotion_type": promo_type or melhor.get("promotion_type"),
            "promotion_name": promo_name,
            "promotion_fee_base": round(float(tarifa_a_val), 2) if tarifa_a_val is not None else None,
            "promotion_fee_base_text": formatar_moeda_br(tarifa_a_val) if tarifa_a_val is not None else "",
            "promotion_fee_ml": round(float(tarifa_b_val), 2) if tarifa_b_val is not None else None,
            "promotion_fee_ml_text": formatar_moeda_br(tarifa_b_val) if tarifa_b_val is not None else "",
        })
        return melhor, cfg

    return melhor, cfg


def _ml_aplicar_desconto_taxa_promocao_fee_data(fee_data: dict, promo_fee_info: dict) -> dict:
    fee_data = dict(fee_data or {})
    promo_fee_info = promo_fee_info or {}
    source = str(promo_fee_info.get("promotion_fee_discount_source") or "").strip()
    if source == "seller_promotions_listing_prices_comparison":
        for campo in (
            "promotion_id",
            "promotion_type",
            "promotion_name",
            "promotion_fee_base",
            "promotion_fee_base_text",
            "promotion_fee_ml",
            "promotion_fee_ml_text",
            "promotion_fee_discount_source",
            "promotion_fee_discount_note",
        ):
            if promo_fee_info.get(campo) not in (None, ""):
                fee_data[campo] = promo_fee_info.get(campo)
        fee_data["promotion_fee_discount_applied"] = False
        partes = [fee_data.get("fee_breakdown") or ""]
        if promo_fee_info.get("promotion_fee_base_text") or promo_fee_info.get("promotion_fee_ml_text"):
            partes.append(
                "Comparativo tarifa promocao: "
                f"base {promo_fee_info.get('promotion_fee_base_text') or '-'}"
                f" -> vigente {promo_fee_info.get('promotion_fee_ml_text') or '-'}"
            )
        fee_data["fee_breakdown"] = " | ".join([parte for parte in partes if parte])
        return fee_data

    desconto = _to_float_safe(promo_fee_info.get("promotion_fee_discount"))
    tarifa_base = _to_float_safe(promo_fee_info.get("promotion_fee_base"))
    tarifa_promocao = (
        _to_float_safe(promo_fee_info.get("promotion_fee_charged"))
        if promo_fee_info.get("promotion_fee_charged") not in (None, "")
        else _to_float_safe(promo_fee_info.get("promotion_fee_ml"))
    )
    tarifa_atual = _to_float_safe(fee_data.get("ad_cost"))
    if desconto is None or desconto <= 0 or tarifa_promocao is None:
        return fee_data

    tarifa_original = tarifa_base if tarifa_base is not None else tarifa_atual
    if tarifa_original is not None:
        desconto = min(float(desconto), max(float(tarifa_original), 0.0))
        fee_data["ad_cost_original"] = round(float(tarifa_original), 2)
        fee_data["ad_cost_original_text"] = formatar_moeda_br(tarifa_original)

    tarifa_com_desconto = max(float(tarifa_promocao), 0.0)
    fee_data["ad_cost"] = round(tarifa_com_desconto, 2)
    fee_data["ad_cost_text"] = formatar_moeda_br(tarifa_com_desconto)
    fee_data["promotion_fee_discount"] = round(desconto, 2)
    fee_data["promotion_fee_discount_text"] = formatar_moeda_br(desconto)
    fee_data["promotion_fee_discount_applied"] = True
    fee_data["promotion_fee_charged"] = round(tarifa_com_desconto, 2)
    fee_data["promotion_fee_charged_text"] = formatar_moeda_br(tarifa_com_desconto)
    fee_data["promotion_fee_discount_source"] = promo_fee_info.get("promotion_fee_discount_source") or "seller_promotions"
    if promo_fee_info.get("promotion_id"):
        fee_data["promotion_id"] = promo_fee_info.get("promotion_id")
    if promo_fee_info.get("promotion_type"):
        fee_data["promotion_type"] = promo_fee_info.get("promotion_type")
    if promo_fee_info.get("promotion_name"):
        fee_data["promotion_name"] = promo_fee_info.get("promotion_name")
    for campo in (
        "promotion_fee_base",
        "promotion_fee_base_text",
        "promotion_fee_ml",
        "promotion_fee_ml_text",
    ):
        if promo_fee_info.get(campo) not in (None, ""):
            fee_data[campo] = promo_fee_info.get(campo)
    partes = [fee_data.get("fee_breakdown") or ""]
    partes.append(f"Desconto tarifa promocao: {formatar_moeda_br(desconto)}")
    partes.append(f"Tarifa com desconto: {formatar_moeda_br(tarifa_com_desconto)}")
    fee_data["fee_breakdown"] = " | ".join([parte for parte in partes if parte])
    return fee_data


def _ml_listar_ids_anuncios_ativos(
    client_id: str,
    loja: str,
    cfg: dict,
    user_id: str,
    limite: int = 5000,
    progress_callback: Optional[Callable[[str], None]] = None,
) -> tuple[list[str], dict]:
    cfg_local = dict(cfg or {})
    user = str(user_id or "").strip()
    if not user:
        raise HTTPException(status_code=400, detail="ID do usuario Mercado Livre nao encontrado")

    limite = max(100, min(int(limite or 5000), 20000))
    cache_key = f"promo:ml_ids_ativos:{client_id}:{loja}:{user}:{limite}"
    cached = _ml_cache_get(cache_key)
    if cached is not None:
        return cached, cfg_local

    url = f"https://api.mercadolibre.com/users/{user}/items/search"
    ids: list[str] = []
    vistos: set[str] = set()

    def registrar(batch) -> int:
        adicionados = 0
        for item_raw in batch or []:
            item_id = str((item_raw or {}).get("id") if isinstance(item_raw, dict) else item_raw or "").strip()
            if item_id and item_id not in vistos:
                vistos.add(item_id)
                ids.append(item_id)
                adicionados += 1
                if len(ids) >= limite:
                    break
        return adicionados

    scan_ok = False
    scroll_id = ""
    try:
        params = {"search_type": "scan", "limit": 100, "status": "active"}
        for _pagina in range(max(1, math.ceil(limite / 100))):
            if scroll_id:
                params = {"search_type": "scan", "scroll_id": scroll_id, "limit": 100}
            resp, cfg_local = _ml_api_request_com_retry(
                client_id,
                loja,
                cfg_local,
                "GET",
                url,
                params=params,
                timeout=35,
                max_attempts=3,
                progress_callback=progress_callback,
            )
            if resp.status_code != 200:
                break
            data = resp.json() or {}
            batch = data.get("results") or []
            if not batch:
                scan_ok = True
                break
            registrar(batch)
            scan_ok = True
            scroll_id = str(data.get("scroll_id") or "").strip()
            if not scroll_id or len(ids) >= limite:
                break
    except Exception as exc:
        logger.warning("[PROMO API] Falha no scan de anuncios ativos da loja %s: %s", loja, exc)

    if not scan_ok or not ids:
        ids = []
        vistos = set()
        offset = 0
        page_limit = 100
        max_offset = min(limite, 1000)
        while len(ids) < max_offset and offset < 1000:
            limite_chamada = min(page_limit, max_offset - len(ids), 1000 - offset)
            if limite_chamada <= 0:
                break
            resp, cfg_local = _ml_api_request_com_retry(
                client_id,
                loja,
                cfg_local,
                "GET",
                url,
                params={"offset": offset, "limit": limite_chamada, "status": "active"},
                timeout=30,
                max_attempts=3,
                progress_callback=progress_callback,
            )
            if resp.status_code != 200:
                raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao listar anuncios ativos do Mercado Livre"))
            data = resp.json() or {}
            batch = data.get("results") or []
            if not batch:
                break
            registrar(batch)
            paging = data.get("paging") or {}
            total = int(paging.get("total", len(ids)) or len(ids))
            offset += limite_chamada
            if offset >= total:
                break

    _ml_cache_set(cache_key, ids)
    return ids, cfg_local


def _ml_listar_itens_promocao_com_raw(
    client_id: str,
    loja: str,
    cfg: dict,
    campaign_id: str,
    *,
    promotion_type: str = "",
    usar_fallback_pesado: bool = False,
    max_items: int = 300,
    buscar_detalhes: bool = True,
    status_promocao: str = "",
    status_item_preferencial: str = "active",
    forcar_fallback_pesado: bool = False,
    progress_callback: Optional[Callable[[str], None]] = None,
):
    campaign_id = str(campaign_id or "").strip()
    if not campaign_id:
        return [], {}, cfg

    item_ids = []
    raw_por_item = {}
    promotion_type = str(promotion_type or "").strip()
    status_promocao = str(status_promocao or "").strip()
    status_item_preferencial = str(status_item_preferencial or "").strip()
    promo_url_tpls = []
    if promotion_type:
        if status_promocao:
            promo_url_tpls.append(
                f"https://api.mercadolibre.com/seller-promotions/promotions/{campaign_id}/items?app_version=v2&promotion_type={quote_plus(promotion_type)}&status={quote_plus(status_promocao)}"
            )
        if status_item_preferencial:
            promo_url_tpls.append(
                f"https://api.mercadolibre.com/seller-promotions/promotions/{campaign_id}/items?app_version=v2&promotion_type={quote_plus(promotion_type)}&status_item={quote_plus(status_item_preferencial)}"
            )
        promo_url_tpls.append(
            f"https://api.mercadolibre.com/seller-promotions/promotions/{campaign_id}/items?app_version=v2&promotion_type={quote_plus(promotion_type)}"
        )
    elif status_promocao:
        promo_url_tpls.append(
            f"https://api.mercadolibre.com/seller-promotions/{campaign_id}/items?app_version=v2&status={quote_plus(status_promocao)}"
        )
    promo_url_tpls.extend([
        f"https://api.mercadolibre.com/seller-promotions/{campaign_id}/items?app_version=v2",
        f"https://api.mercadolibre.com/seller-promotions/{campaign_id}/items",
    ])

    for promo_url_tpl in promo_url_tpls:
        params_url_tpl = parse_qs(urlparse(promo_url_tpl).query)
        status_consultado = ""
        status_param_consultado = ""
        if params_url_tpl.get("status_item"):
            status_consultado = str((params_url_tpl.get("status_item") or [""])[0] or "").strip()
            status_param_consultado = "status_item"
        elif params_url_tpl.get("status"):
            status_consultado = str((params_url_tpl.get("status") or [""])[0] or "").strip()
            status_param_consultado = "status"
        offset = 0
        limit = 50
        encontrou_endpoint = False
        paginas_lidas = 0
        max_paginas = max(1, math.ceil(max_items / limit) + 1)
        assinaturas_paginas = set()
        while True:
            paginas_lidas += 1
            if paginas_lidas > max_paginas:
                logger.warning(f"[PROMO API] Interrompendo paginacao da promocao {campaign_id}: limite de paginas atingido")
                break
            sep = "&" if "?" in promo_url_tpl else "?"
            url = f"{promo_url_tpl}{sep}offset={offset}&limit={limit}"
            try:
                resp, cfg = _ml_api_request_com_retry(
                    client_id,
                    loja,
                    cfg,
                    "GET",
                    url,
                    timeout=35,
                    max_attempts=4,
                    progress_callback=progress_callback,
                )
            except Exception as exc:
                logger.warning(f"[ML API] Timeout/falha ao buscar itens da promocao {campaign_id}: {exc}")
                if progress_callback:
                    try:
                        progress_callback(f"Mercado Livre nao respondeu para a promocao {campaign_id}; tentando outro caminho de consulta.")
                    except Exception:
                        pass
                break
            if resp.status_code == 404:
                break
            if resp.status_code != 200:
                logger.warning(f"[ML API] Falha ao buscar itens da promocao {campaign_id}: {resp.status_code}")
                break
            encontrou_endpoint = True
            try:
                data = resp.json() or {}
            except Exception:
                data = {}
            entries = data.get("results") or data.get("items") or []
            def _entry_assinatura(entry):
                if isinstance(entry, dict):
                    raw_item = entry.get("item")
                    item_obj_id = raw_item.get("id") if isinstance(raw_item, dict) else raw_item
                    return str(entry.get("item_id") or entry.get("itemId") or item_obj_id or entry.get("id") or "")
                return str(entry or "")

            assinatura = tuple(_entry_assinatura(entry) for entry in entries[:20])
            if assinatura and assinatura in assinaturas_paginas:
                logger.warning(f"[PROMO API] Interrompendo paginacao repetida da promocao {campaign_id}")
                break
            if assinatura:
                assinaturas_paginas.add(assinatura)
            for entry in entries:
                item_id = ""
                if isinstance(entry, dict):
                    raw_id = str(entry.get("id") or "").strip()
                    raw_item = entry.get("item")
                    item_obj_id = raw_item.get("id") if isinstance(raw_item, dict) else raw_item
                    item_id = str(
                        entry.get("item_id")
                        or entry.get("itemId")
                        or entry.get("item_id_to")
                        or item_obj_id
                        or (raw_id if raw_id.upper().startswith("MLB") else "")
                        or ""
                    ).strip()
                    if item_id:
                        if status_consultado:
                            entry = dict(entry)
                            entry["_jk_status_item_consultado"] = status_consultado
                            entry["_jk_status_param_consultado"] = status_param_consultado
                        raw_por_item[item_id] = entry
                else:
                    item_id = str(entry or "").strip()
                if item_id:
                    item_ids.append(item_id)
                if len(item_ids) >= max_items:
                    logger.warning(f"[PROMO API] Promocao {campaign_id} limitada a {max_items} anuncios para evitar travamento")
                    break
            if len(item_ids) >= max_items:
                break
            paging = data.get("paging") or {}
            total = int(paging.get("total") or 0)
            offset += limit
            if not entries or len(entries) < limit or (total and offset >= total):
                break
        if encontrou_endpoint and item_ids:
            break

    if item_ids and not forcar_fallback_pesado:
        item_ids = list(dict.fromkeys(item_ids))
        if not buscar_detalhes:
            itens = [{"id": item_id} for item_id in item_ids]
            return itens, raw_por_item, cfg
        itens, cfg = _ml_buscar_itens_batch(client_id, loja, cfg, item_ids, progress_callback=progress_callback)
        return itens, raw_por_item, cfg

    if not usar_fallback_pesado:
        logger.warning(f"[PROMO API] Promocao {campaign_id} sem itens no endpoint direto; fallback pesado desativado")
        if item_ids:
            ids_unicos = list(dict.fromkeys(item_ids))[:max_items]
            if not buscar_detalhes:
                itens = [{"id": item_id} for item_id in ids_unicos]
            else:
                itens, cfg = _ml_buscar_itens_batch(client_id, loja, cfg, ids_unicos, progress_callback=progress_callback)
            return itens, raw_por_item, cfg
        return [], raw_por_item, cfg

    user_id = cfg.get("user_id")
    if not user_id:
        raise HTTPException(status_code=400, detail="ID do usuario Mercado Livre nao encontrado")

    campaign_norm = campaign_id.lower()
    try:
        all_ids, cfg = _ml_listar_ids_anuncios_ativos(
            client_id,
            loja,
            cfg,
            user_id,
            progress_callback=progress_callback,
        )
    except Exception as exc:
        logger.warning("[PROMO API] Falha na varredura complementar da promocao %s: %s", campaign_id, exc)
        if progress_callback:
            try:
                progress_callback(
                    f"Mercado Livre demorou para responder na varredura complementar da promocao {campaign_id}; seguindo com os dados ja encontrados."
                )
            except Exception:
                pass
        all_ids = []
    logger.info(
        "[PROMO API] Promocao %s: iniciando varredura complementar de %s anuncios ativos%s",
        campaign_id,
        len(all_ids),
        f" (endpoint direto trouxe {len(set(item_ids))})" if item_ids else "",
    )
    participantes = []
    max_workers = min(6, max(2, len(all_ids))) if all_ids else 0
    if max_workers:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_map = {
                executor.submit(_ml_obter_promocoes_item, client_id, loja, dict(cfg), str(item_id)): str(item_id)
                for item_id in all_ids if item_id
            }
            for future in as_completed(future_map):
                item_id = future_map[future]
                try:
                    promocoes_item, _cfg_tmp = future.result()
                except Exception:
                    promocoes_item = []
                if campaign_norm in _ml_extrair_ids_promocoes_item(promocoes_item):
                    participantes.append({"id": item_id})
                    raw_encontrado = _ml_encontrar_promocao_raw_item(promocoes_item, campaign_id)
                    if raw_encontrado:
                        raw_por_item.setdefault(item_id, raw_encontrado)
                    if len(participantes) >= max_items:
                        logger.warning(f"[PROMO API] Varredura da promocao {campaign_id} limitada a {max_items} anuncios")
                        break
    ids_finais = list(dict.fromkeys(
        [str(item_id or "").strip() for item_id in item_ids if str(item_id or "").strip()]
        + [str(item.get("id") or "").strip() for item in participantes if str(item.get("id") or "").strip()]
    ))[:max_items]
    logger.info(
        "[PROMO API] Promocao %s: varredura complementar encontrou %s participante(s); total final=%s",
        campaign_id,
        len(participantes),
        len(ids_finais),
    )
    if buscar_detalhes and ids_finais:
        itens_finais, cfg = _ml_buscar_itens_batch(client_id, loja, cfg, ids_finais, progress_callback=progress_callback)
        return itens_finais, raw_por_item, cfg
    return [{"id": item_id} for item_id in ids_finais], raw_por_item, cfg


def _ml_listar_itens_promocao_multistatus_com_raw(
    client_id: str,
    loja: str,
    cfg: dict,
    campaign_id: str,
    *,
    promotion_type: str = "",
    max_items: int = 5000,
    buscar_detalhes: bool = False,
    expected_min_items: Optional[int] = None,
    progress_callback: Optional[Callable[[str], None]] = None,
):
    consultas = [
        {"status_promocao": "pending", "status_item_preferencial": ""},
        {"status_promocao": "started", "status_item_preferencial": ""},
        {"status_promocao": "", "status_item_preferencial": "active"},
        {"status_promocao": "", "status_item_preferencial": ""},
        {"status_promocao": "candidate", "status_item_preferencial": ""},
        {"status_promocao": "eligible", "status_item_preferencial": ""},
    ]
    ids = []
    raw_total = {}
    for consulta in consultas:
        itens, raw_por_item, cfg = _ml_listar_itens_promocao_com_raw(
            client_id,
            loja,
            cfg,
            campaign_id,
            promotion_type=promotion_type,
            usar_fallback_pesado=False,
            max_items=max_items,
            buscar_detalhes=False,
            status_promocao=consulta["status_promocao"],
            status_item_preferencial=consulta["status_item_preferencial"],
            progress_callback=progress_callback,
        )
        for item in itens or []:
            item_id = str((item or {}).get("id") or "").strip()
            if item_id and item_id not in ids:
                ids.append(item_id)
        for item_id, raw in (raw_por_item or {}).items():
            item_key = str(item_id or "").strip()
            if item_key:
                raw_atual = raw_total.get(item_key)
                if not raw_atual or _promo_prioridade_status_item(raw) > _promo_prioridade_status_item(raw_atual):
                    raw_total[item_key] = raw
        if len(ids) >= max_items:
            break

    expected_min = None
    try:
        if expected_min_items is not None:
            expected_min = max(0, min(int(expected_min_items), int(max_items)))
    except Exception:
        expected_min = None

    if ids and expected_min and len(ids) < expected_min:
        logger.warning(
            "[PROMO API] Promocao %s parece truncada: %s/%s itens. Acionando varredura complementar.",
            campaign_id,
            len(ids),
            expected_min,
        )
        itens_extra, raw_extra, cfg = _ml_listar_itens_promocao_com_raw(
            client_id,
            loja,
            cfg,
            campaign_id,
            promotion_type=promotion_type,
            usar_fallback_pesado=True,
            forcar_fallback_pesado=True,
            max_items=max_items,
            buscar_detalhes=False,
            status_promocao="",
            status_item_preferencial="",
            progress_callback=progress_callback,
        )
        for item in itens_extra or []:
            item_id = str((item or {}).get("id") or "").strip()
            if item_id and item_id not in ids:
                ids.append(item_id)
        for item_id, raw in (raw_extra or {}).items():
            item_key = str(item_id or "").strip()
            if item_key:
                raw_atual = raw_total.get(item_key)
                if not raw_atual or _promo_prioridade_status_item(raw) > _promo_prioridade_status_item(raw_atual):
                    raw_total[item_key] = raw

    if not ids:
        return _ml_listar_itens_promocao_com_raw(
            client_id,
            loja,
            cfg,
            campaign_id,
            promotion_type=promotion_type,
            usar_fallback_pesado=True,
            max_items=max_items,
            buscar_detalhes=buscar_detalhes,
            status_promocao="",
            status_item_preferencial="",
            progress_callback=progress_callback,
        )

    ids = list(dict.fromkeys(ids))[:max_items]
    if buscar_detalhes:
        itens_detalhados, cfg = _ml_buscar_itens_batch(client_id, loja, cfg, ids, progress_callback=progress_callback)
        return itens_detalhados, raw_total, cfg
    return [{"id": item_id} for item_id in ids], raw_total, cfg


@app.post("/api/promo/analise-via-api")
def analisar_promo_via_api(req: PromoAnaliseApiRequest, client_id: str = Depends(get_tenant_id)):
    """
    Compara duas promocoes/campanhas existentes do Mercado Livre
    usando dados da API e custo do produto no cadastro local.
    """
    promo_a = str(req.promocao_a_id or "").strip()
    promo_a_type = str(req.promocao_a_type or "").strip()
    if promo_a_type in {"-", "None", "null"}:
        promo_a_type = ""

    promo_b_ids = []
    if isinstance(req.promocao_b_ids, list):
        promo_b_ids.extend([str(v or "").strip() for v in req.promocao_b_ids])
    if req.promocao_b_id:
        promo_b_ids.append(str(req.promocao_b_id or "").strip())
    promo_b_ids = [p for p in promo_b_ids if p and p not in {"-", "None", "null"}]
    promo_b_ids = list(dict.fromkeys(promo_b_ids))

    promo_b_types = []
    if isinstance(req.promocao_b_types, list):
        promo_b_types = [("" if str(v or "").strip() in {"-", "None", "null"} else str(v or "").strip()) for v in req.promocao_b_types]
    elif req.promocao_b_type:
        v = str(req.promocao_b_type or "").strip()
        promo_b_types = ["" if v in {"-", "None", "null"} else v]

    promo_b_files = list(req.promocao_b_files or [])

    if not req.loja or not promo_a or not promo_b_ids:
        raise HTTPException(status_code=400, detail="Informe loja, Promocao 1 e ao menos uma Promocao 2 para comparar.")
    if any(promo_a == promo_b for promo_b in promo_b_ids):
        raise HTTPException(status_code=400, detail="Selecione Promocoes 2 diferentes da Promocao 1.")
    if len(promo_b_files) != len(promo_b_ids):
        raise HTTPException(status_code=400, detail="Envie um arquivo para cada Promocao 2 selecionada.")

    inicio = time.time()
    cfg = _obter_cfg_ml(client_id, req.loja)
    itens_a_refs, raw_a, cfg = _ml_listar_itens_promocao_com_raw(
        client_id,
        req.loja,
        cfg,
        promo_a,
        promotion_type=promo_a_type,
        usar_fallback_pesado=True,
        forcar_fallback_pesado=True,
        max_items=5000,
        buscar_detalhes=False,
    )
    ids_a = {str(x.get("id") or "").strip() for x in (itens_a_refs or []) if str(x.get("id") or "").strip()}

    promocoes_b_info = []
    ids_intersecao_global = set()
    for idx_b, promo_b in enumerate(promo_b_ids):
        promo_b_type = promo_b_types[idx_b] if idx_b < len(promo_b_types) else ""
        itens_b_refs, raw_b, cfg = _ml_listar_itens_promocao_multistatus_com_raw(
            client_id,
            req.loja,
            cfg,
            promo_b,
            promotion_type=promo_b_type,
            buscar_detalhes=False,
        )
        ids_b = {str(x.get("id") or "").strip() for x in (itens_b_refs or []) if str(x.get("id") or "").strip()}
        ids_intersecao = sorted(ids_a & ids_b)
        ids_intersecao_global.update(ids_intersecao)
        logger.info(
            f"[PROMO API] Filtro Promocao 2 + Promocao 1 ativa: "
            f"promo1={len(ids_a)} promo2={len(ids_b)} intersecao={len(ids_intersecao)} promo2_id={promo_b}"
        )
        promocoes_b_info.append({
            "promo_b": promo_b,
            "promo_b_type": promo_b_type,
            "ids_b": ids_b,
            "ids_intersecao": ids_intersecao,
            "raw_b": raw_b,
            "arquivo_nome": (promo_b_files[idx_b] if idx_b < len(promo_b_files) else ""),
        })

    itens_filtrados, cfg = _ml_buscar_itens_batch(client_id, req.loja, cfg, sorted(ids_intersecao_global))
    itens_por_id = {
        str(item.get("id") or "").strip(): item
        for item in (itens_filtrados or [])
        if str(item.get("id") or "").strip()
    }

    custos_por_sku, impostos_por_sku = _carregar_custos_impostos_cadastro_por_sku_loja(client_id, req.loja)

    def _montar_linha_item(item_id: str, item: dict, promo_b: str, promo_b_type: str, ids_b: set[str], raw_b: dict, arquivo_nome_b: str):
        item = itens_por_id[item_id]
        sku = _ml_extrair_sku(item) or str(item.get("seller_custom_field") or "").strip()
        sku_display = sku
        skus_variacoes = []
        variacoes = _ml_extrair_variacoes_resumo(item, client_id=client_id, loja=req.loja)
        if variacoes:
            skus_variacoes = [str(v.get("sku") or "").strip() for v in variacoes if str(v.get("sku") or "").strip() and str(v.get("sku") or "").strip() != "-"]
            if skus_variacoes:
                sku_display = " / ".join(list(dict.fromkeys(skus_variacoes))[:4])

        cfg_local = dict(cfg)
        price_info, cfg_local = _ml_obter_preco_detalhado(client_id, req.loja, cfg_local, item_id, fallback_price=item.get("price"))
        preco_atual = _parse_float_flex(price_info.get("price")) or _parse_float_flex(item.get("price")) or 0.0
        preco_base_anuncio = (
            _parse_float_flex(price_info.get("standard_price"))
            or _parse_float_flex(price_info.get("original_price"))
            or _parse_float_flex(item.get("original_price"))
            or _parse_float_flex(item.get("base_price"))
            or preco_atual
        )
        raw_a_item = raw_a.get(item_id, {})
        raw_b_item = raw_b.get(item_id, {})
        if promo_a_type and not raw_a_item:
            raw_a_item, cfg_local = _ml_obter_item_promocao_raw(client_id, req.loja, cfg_local, promo_a, promo_a_type, item_id)
        if promo_b_type and (not raw_b_item or _promo_status_item_promocao(raw_b_item) in {"candidate", "eligible"}):
            detalhe_b, cfg_local = _ml_obter_item_promocao_raw(client_id, req.loja, cfg_local, promo_b, promo_b_type, item_id)
            if detalhe_b:
                raw_b_item = detalhe_b
        raw_b_item, cfg_local = _ml_resolver_raw_promocao_equivalente_para_analise(
            client_id,
            req.loja,
            cfg_local,
            item_id,
            raw_b_item,
            promo_b,
            promo_b_type,
            preco_base_anuncio,
        )
        promocoes_item_a = None
        preco_a_raw, desc_a_raw = _ml_extrair_preco_promocao_raw(raw_a_item, priorizar_percentual_total_api=True)
        if preco_a_raw is None and desc_a_raw is None:
            try:
                promocoes_item_a, cfg_local = _ml_obter_promocoes_item(client_id, req.loja, cfg_local, item_id)
                raw_a_fallback = _ml_encontrar_promocao_raw_item(promocoes_item_a, promo_a)
                if raw_a_fallback:
                    raw_a_item = raw_a_fallback
                    preco_a_raw, desc_a_raw = _ml_extrair_preco_promocao_raw(raw_a_item, priorizar_percentual_total_api=True)
            except Exception:
                promocoes_item_a = None
        preco_b_raw, desc_b_raw = _ml_extrair_preco_promocao_raw(raw_b_item, priorizar_percentual_total_api=True)
        status_promo_a = _ml_classificar_status_promocao_entry(raw_a_item)
        if str(price_info.get("promotion_id") or "").strip().lower() == promo_a.lower():
            status_promo_a = "Ativo"
        if not status_promo_a:
            try:
                if promocoes_item_a is None:
                    promocoes_item_a, cfg_local = _ml_obter_promocoes_item(client_id, req.loja, cfg_local, item_id)
                status_promo_a = _ml_classificar_status_promocao_por_id(promocoes_item_a, promo_a)
            except Exception:
                status_promo_a = ""
        presente_a = status_promo_a == "Ativo"
        presente_a_programado = status_promo_a == "Programado"
        if not presente_a and not presente_a_programado:
            return None
        desconto_tarifa_ml = _ml_extrair_desconto_tarifa_promocao_raw(raw_b_item)
        preco_a = preco_a_raw or preco_base_anuncio or preco_atual
        preco_b = preco_b_raw or preco_atual or preco_base_anuncio

        desconto_a = desc_a_raw
        desconto_b = _ml_extrair_percentual_sugerido_campanha_raw(raw_b_item, preco_base_anuncio)
        if desconto_b is None:
            desconto_b = desc_b_raw
        if preco_a_raw is None and desconto_a is not None and preco_base_anuncio and preco_base_anuncio > 0:
            preco_a = round(float(preco_base_anuncio) * max(0.0, 1.0 - (float(desconto_a) / 100.0)), 2)
        if desconto_a is None and preco_base_anuncio and preco_a and preco_base_anuncio > 0:
            desconto_a = max(0.0, ((preco_base_anuncio - preco_a) / preco_base_anuncio) * 100.0)
        if desconto_b is None and preco_base_anuncio and preco_b and preco_base_anuncio > 0:
            desconto_b = max(0.0, ((preco_base_anuncio - preco_b) / preco_base_anuncio) * 100.0)

        shipping_data, cfg_local = _ml_obter_frete_detalhado(
            client_id,
            req.loja,
            cfg_local,
            item_id,
            item.get("shipping") or {},
            reconsultar_zero=True,
            contexto_frete=_ml_contexto_frete_item(item, preco_b or preco_a or preco_atual or preco_base_anuncio),
        )
        frete_api = shipping_data.get("shipping_cost")
        frete_api_val = _parse_float_flex(frete_api)
        frete_fallback_val = 0.0
        frete_a_val = frete_api_val if frete_api_val is not None else frete_fallback_val
        frete_b_val = frete_api_val if frete_api_val is not None else frete_fallback_val
        buyer_cost = _parse_float_flex(shipping_data.get("shipping_buyer_cost"))
        frete_gratis_api = bool(shipping_data.get("free_shipping")) or (buyer_cost is not None and buyer_cost <= 0)

        custo = _resolver_custo_medio_por_skus(custos_por_sku, skus_variacoes or [sku, sku_display])
        imposto_rate = _resolver_imposto_rate_por_sku(impostos_por_sku, sku)
        if imposto_rate is None:
            imposto_rate = _resolver_imposto_rate_por_sku(impostos_por_sku, sku_display)
        item_taxa_a = dict(item)
        item_taxa_a["price"] = preco_a
        fee_a, cfg_local = _ml_obter_taxas_anuncio(client_id, req.loja, cfg_local, item_taxa_a)
        item_taxa_b = dict(item)
        item_taxa_b["price"] = preco_b
        fee_b, cfg_local = _ml_obter_taxas_anuncio(client_id, req.loja, cfg_local, item_taxa_b)
        frete_gratis_a = bool(frete_gratis_api or (frete_api_val is None and preco_a is not None and preco_a >= 79.0))
        frete_gratis_b = bool(frete_gratis_api or (frete_api_val is None and preco_b is not None and preco_b >= 79.0))
        taxa_fixa_a = _parse_float_flex(fee_a.get("fixed_fee_amount"))
        taxa_fixa_b = _parse_float_flex(fee_b.get("fixed_fee_amount"))
        if taxa_fixa_a is None:
            taxa_fixa_a = _ml_estimar_taxa_fixa_por_preco(
                preco_a,
                domain_id=item.get("domain_id") or "",
                category_id=item.get("category_id") or "",
                listing_type_id=item.get("listing_type_id") or "",
            )
        if taxa_fixa_b is None:
            taxa_fixa_b = _ml_estimar_taxa_fixa_por_preco(
                preco_b,
                domain_id=item.get("domain_id") or "",
                category_id=item.get("category_id") or "",
                listing_type_id=item.get("listing_type_id") or "",
            )
        # Frete fica com o valor da API de shipping_options.
        # A taxa fixa do ML pertence ao detalhamento da tarifa, nao substitui frete.
        tarifa_a_val = _ml_extrair_tarifa_cobrada_promocao_raw(raw_a_item)
        if tarifa_a_val is None:
            tarifa_a_val = _parse_float_flex(fee_a.get("ad_cost"))
        tarifa_b_tmp = _parse_float_flex(fee_b.get("ad_cost"))
        if desconto_tarifa_ml is not None and tarifa_b_tmp is not None and desconto_tarifa_ml >= (tarifa_b_tmp * 0.8):
            # Alguns formatos chamam a prÃ³pria tarifa de sale_fee; nesse caso nÃ£o ÃƒÂ© o desconto.
            desconto_tarifa_ml = None
        desconto_tarifa_ml = _calcular_desconto_ml_valor(
            desconto_atual=desconto_tarifa_ml,
            ml_pct=desconto_b,
            preco_base=preco_base_anuncio,
            preco_final_ml=preco_b,
            tarifa_base=tarifa_a_val,
            tarifa_ml=tarifa_b_tmp,
        )
        desconto_tarifa_ml = _ml_ajustar_desconto_tarifa_recebivel_promocao(
            raw_b_item,
            desconto_tarifa_ml,
            preco_b,
            desconto_b,
        )
        recebe_ml = _ml_calcular_recebivel_promocao(
            raw_b_item,
            preco_b,
            tarifa_b_tmp,
            frete_b_val,
            desconto_tarifa_ml,
        )

        valor_liquido_a = None
        valor_liquido_b = None
        margem_a = None
        margem_b = None
        imposto_a = (preco_a * imposto_rate) if imposto_rate is not None else None
        imposto_b = (preco_b * imposto_rate) if imposto_rate is not None else None
        if custo is not None:
            valor_liquido_a = preco_a - float(custo) - frete_a_val - (imposto_a or 0.0) - (tarifa_a_val or 0.0)
            valor_liquido_b = preco_b - float(custo) - frete_b_val - (imposto_b or 0.0) - (_parse_float_flex(fee_b.get("ad_cost")) or 0.0)
            if desconto_tarifa_ml is not None:
                valor_liquido_b += float(desconto_tarifa_ml)
            if preco_a:
                margem_a = (valor_liquido_a * 100.0) / preco_a
            if preco_b:
                margem_b = (valor_liquido_b * 100.0) / preco_b

        presente_b = item_id in ids_b
        margem_minima_pct = float(req.margem_minima or 0)
        if margem_a is None or margem_a < margem_minima_pct:
            decisao = "NÃ£o participar"
        elif margem_b is None:
            decisao = "NÃ£o participar"
        elif margem_b < margem_minima_pct:
            decisao = "NÃ£o participar"
        elif margem_a is not None and margem_b < margem_a:
            decisao = "NÃ£o participar"
        else:
            decisao = "Participar"

        status = status_promo_a
        return {
            "Tipo": fee_b.get("listing_type_name") or fee_a.get("listing_type_name") or _ml_nome_tipo_anuncio(item.get("listing_type_id")),
            "%": _format_pct_br(
                fee_b.get("sale_fee_pct")
                if fee_b.get("sale_fee_pct") is not None
                else (fee_a.get("sale_fee_pct") if fee_a.get("sale_fee_pct") is not None else fee_b.get("meli_fee_pct"))
            ),
            "SKU": sku_display or sku,
            "TÃ­tulo": str(item.get("title") or ""),
            "Frete": formatar_moeda_br(frete_a_val),
            "Frete ML": formatar_moeda_br(frete_b_val),
            "Frete Gratis": "SIM" if frete_gratis_a else "NÃƒO",
            "Frete Gratis ML": "SIM" if frete_gratis_b else "NÃƒO",
            "Custo": formatar_moeda_br(custo) if custo is not None else "",
            "Tarifa": formatar_moeda_br(tarifa_a_val) if tarifa_a_val is not None else "",
            "Tarifa ML": formatar_moeda_br(fee_b.get("ad_cost")) if fee_b.get("ad_cost") is not None else "",
            "MLB": item_id,
            "Campanha ML": f"{promo_a} x {promo_b}",
            "Arquivo Promocao 2": arquivo_nome_b or "",
            "% Fixa": _format_pct_br(desconto_a),
            "ML % Campanha": _format_pct_br(desconto_b),
            "PreÃ§o Final": formatar_moeda_br(preco_a),
            "deal_price": round(float(preco_b), 2) if preco_b is not None else None,
            "preco_promocional_ml": round(float(preco_b), 2) if preco_b is not None else None,
            "preco_final_ml_display": recebe_ml,
            "Imposto %": _format_pct_br(imposto_rate * 100.0) if imposto_rate is not None else "",
            "Imposto": formatar_moeda_br(imposto_a) if imposto_a is not None else "",
            "PreÃ§o Final ML": formatar_moeda_br(recebe_ml) if recebe_ml is not None else formatar_moeda_br(preco_b),
            "Imposto ML": formatar_moeda_br(imposto_b) if imposto_b is not None else "",
            "Desconto ML": formatar_moeda_br(desconto_tarifa_ml) if desconto_tarifa_ml is not None else "",
            "Valor LÃ­quido": formatar_moeda_br(valor_liquido_a) if valor_liquido_a is not None else "",
            "Valor lÃ­quido ML": formatar_moeda_br(valor_liquido_b) if valor_liquido_b is not None else "",
            "Status": status,
            "Margem": _format_pct_br(margem_a),
            "Margem ML": _format_pct_br(margem_b),
            "AÃ§Ã£o": decisao,
            "Participar ou nÃ£o": decisao,
            "offer_id": _ml_promocao_raw_offer_id(raw_b_item),
            "promotion_type": promo_b_type,
        }

    dados_analise = []
    for promo_b_info in promocoes_b_info:
        promo_b = promo_b_info["promo_b"]
        promo_b_type = promo_b_info["promo_b_type"]
        ids_b = promo_b_info["ids_b"]
        ids_intersecao = promo_b_info["ids_intersecao"]
        raw_b = promo_b_info["raw_b"]
        arquivo_nome_b = promo_b_info["arquivo_nome"]
        item_pairs = [(item_id, itens_por_id[item_id]) for item_id in ids_intersecao if item_id in itens_por_id]
        logger.info(f"[PROMO API] Comparando promocoes {promo_a} x {promo_b}: {len(item_pairs)} anuncios encontrados")
        if item_pairs:
            max_workers = min(10, max(2, len(item_pairs)))
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                future_map = {
                    executor.submit(_montar_linha_item, item_id, item, promo_b, promo_b_type, ids_b, raw_b, arquivo_nome_b): item_id
                    for item_id, item in item_pairs
                }
                linhas_por_id = {}
                for future in as_completed(future_map):
                    item_id = future_map[future]
                    try:
                        linha = future.result()
                        if linha:
                            linhas_por_id[item_id] = linha
                    except Exception as e:
                        logger.warning(f"[PROMO API] Falha ao montar item {item_id}: {e}")
                dados_analise.extend([linhas_por_id[item_id] for item_id, _item in item_pairs if item_id in linhas_por_id])
    dados_analise = [
        row for row in dados_analise
        if row
        and _promo_linha_status_ativo_ou_programado(row)
        and _promo_linha_pct_fixa_maior_que_zero(row)
    ]

    planilha_nome = _salvar_planilha_analise_promo(client_id, dados_analise, prefixo='analise_promo_api')
    df_payload = _build_df_planilha_analise_promo(dados_analise).fillna("")
    dados_payload = df_payload.to_dict(orient="records")
    meta_por_linha = {}
    for item in dados_analise:
        chave = (str(item.get("MLB") or "").strip(), str(item.get("Campanha ML") or "").strip())
        if not chave[0]:
            continue
        meta_por_linha[chave] = {
            "offer_id": str(item.get("offer_id") or "").strip(),
            "promotion_type": str(item.get("promotion_type") or "").strip(),
            "deal_price": _parse_float_flex(item.get("deal_price") or item.get("preco_promocional_ml")),
        }
    for row in dados_payload:
        row['Frete Gratis'] = row.get('Frete GrÃ¡tis', '')
        row['Frete Gratis ML'] = row.get('Frete GrÃ¡tis ML', '')
        meta = meta_por_linha.get((str(row.get("MLB") or "").strip(), str(row.get("Campanha ML") or "").strip())) or {}
        if meta.get("offer_id"):
            row["offer_id"] = meta["offer_id"]
        if meta.get("promotion_type"):
            row["promotion_type"] = meta["promotion_type"]
        if meta.get("deal_price") is not None:
            row["deal_price"] = meta["deal_price"]
    return {
        "success": True,
        "mode": "api_comparacao_promocoes",
        "loja": req.loja,
        "promocao_a_id": promo_a,
        "promocao_b_id": promo_b_ids[0] if promo_b_ids else "",
        "promocao_b_ids": promo_b_ids,
        "total": len(dados_analise),
        "tempo_segundos": round(time.time() - inicio, 1),
        "data": dados_payload,
        "planilha_gerada": planilha_nome,
    }


async def analisar_promo_via_api_sem_arquivos(
    loja: str,
    promocao_a_id: str,
    promocao_a_type: str = "",
    margem_minima: float = 15.0,
    promocoes_b_meta: str = "[]",
    client_id: str = "default",
    progress_hook: Optional[Callable[[dict], None]] = None,
):
    inicio = time.time()

    def _emit_progress(progress: int, message: str, phase: str = "running", details: Optional[dict] = None):
        if not progress_hook:
            return
        payload = {
            "progress": max(0, min(99, int(progress))),
            "message": str(message or "").strip() or "Processando analise de promocoes via API...",
            "phase": phase,
        }
        if isinstance(details, dict) and details:
            payload["details"] = details
        try:
            progress_hook(payload)
        except Exception:
            pass

    promo_a = str(promocao_a_id or "").strip()
    promo_a_type = str(promocao_a_type or "").strip()
    if promo_a_type in {"-", "None", "null"}:
        promo_a_type = ""

    try:
        promocoes_meta = json.loads(promocoes_b_meta or "[]")
    except Exception:
        raise HTTPException(status_code=400, detail="Metadados das Promocoes 2 invalidos.")

    if not loja or not promo_a:
        raise HTTPException(status_code=400, detail="Informe a loja e a Promocao 1.")
    if not isinstance(promocoes_meta, list) or not promocoes_meta:
        raise HTTPException(status_code=400, detail="Selecione ao menos uma Promocao 2.")

    promocoes_processar = []
    for meta in promocoes_meta:
        if not isinstance(meta, dict):
            continue
        promo_b = str(meta.get("promo_b_id") or meta.get("value") or "").strip()
        if not promo_b:
            continue
        promo_b_type = str(meta.get("promo_b_type") or meta.get("promoType") or "").strip()
        if promo_b_type in {"-", "None", "null"}:
            promo_b_type = ""
        promo_texto = str(meta.get("promo_texto") or meta.get("text") or promo_b).strip()
        active_count = _promo_meta_contagem(meta, "active_count", "activeCount", "active", "ativos")
        eligible_count = _promo_meta_contagem(meta, "eligible_count", "eligibleCount", "eligible", "elegiveis")
        promocoes_processar.append({
            "promo_b": promo_b,
            "promo_b_type": promo_b_type,
            "promo_texto": promo_texto or promo_b,
            "active_count": active_count,
            "eligible_count": eligible_count,
        })

    if not promocoes_processar:
        raise HTTPException(status_code=400, detail="Nenhuma Promocao 2 valida foi selecionada.")

    total_solicitacoes = len(promocoes_processar)
    _emit_progress(12, "Validando promocoes selecionadas na API do Mercado Livre...")

    cfg = _obter_cfg_ml(client_id, loja)
    _emit_progress(22, "Consultando anuncios da Promocao 1...")
    itens_a_refs, raw_a, cfg = _ml_listar_itens_promocao_com_raw(
        client_id,
        loja,
        cfg,
        promo_a,
        promotion_type=promo_a_type,
        usar_fallback_pesado=True,
        forcar_fallback_pesado=True,
        max_items=5000,
        buscar_detalhes=False,
        progress_callback=lambda msg: _emit_progress(24, msg, details={"promo": promo_a}),
    )
    ids_a = {str(x.get("id") or "").strip() for x in (itens_a_refs or []) if str(x.get("id") or "").strip()}
    _emit_progress(32, f"Promocao 1 carregada com {len(ids_a)} anuncio(s).")

    custos_por_sku, impostos_por_sku = _carregar_custos_impostos_cadastro_por_sku_loja(client_id, loja)

    def _erro_legivel(exc: Exception) -> str:
        if isinstance(exc, HTTPException):
            return str(exc.detail or "Erro na API do Mercado Livre")
        texto = str(exc or "").strip()
        return texto or exc.__class__.__name__

    def _montar_linha_api(item_id: str, item: dict | None, promo_meta: dict, raw_b: dict):
        item = dict(item or {})
        item.setdefault("id", item_id)

        raw_b_item = raw_b.get(item_id, {}) if isinstance(raw_b, dict) else {}
        cfg_local = dict(cfg)
        if promo_meta.get("promo_b_type") and (not raw_b_item or _promo_status_item_promocao(raw_b_item) in {"candidate", "eligible"}):
            try:
                detalhe_b, cfg_local = _ml_obter_item_promocao_raw(
                    client_id,
                    loja,
                    cfg_local,
                    promo_meta["promo_b"],
                    promo_meta.get("promo_b_type") or "",
                    item_id,
                )
                if detalhe_b:
                    raw_b_item = detalhe_b
            except Exception:
                if not raw_b_item:
                    raw_b_item = {}
        raw_b_item, cfg_local = _ml_resolver_raw_promocao_equivalente_para_analise(
            client_id,
            loja,
            cfg_local,
            item_id,
            raw_b_item,
            promo_meta["promo_b"],
            promo_meta.get("promo_b_type") or "",
            None,
        )

        raw_a_item = raw_a.get(item_id, {}) if isinstance(raw_a, dict) else {}
        if promo_a_type and not raw_a_item:
            try:
                raw_a_item, cfg_local = _ml_obter_item_promocao_raw(client_id, loja, cfg_local, promo_a, promo_a_type, item_id)
            except Exception:
                raw_a_item = {}

        if not item.get("title"):
            item["title"] = str(raw_b_item.get("title") or raw_b_item.get("name") or item_id)

        sku = _ml_extrair_sku(item) or str(item.get("seller_custom_field") or raw_b_item.get("seller_sku") or raw_b_item.get("sku") or "").strip()
        sku_display = sku
        skus_variacoes = []
        try:
            variacoes = _ml_extrair_variacoes_resumo(item, client_id=client_id, loja=loja)
        except Exception:
            variacoes = []
        if variacoes:
            skus_variacoes = [str(v.get("sku") or "").strip() for v in variacoes if str(v.get("sku") or "").strip() and str(v.get("sku") or "").strip() != "-"]
            if skus_variacoes:
                sku_display = " / ".join(list(dict.fromkeys(skus_variacoes))[:4])

        try:
            price_info, cfg_local = _ml_obter_preco_detalhado(client_id, loja, cfg_local, item_id, fallback_price=item.get("price"))
        except Exception:
            price_info = {}
        preco_atual = _parse_float_flex(price_info.get("price")) or _parse_float_flex(item.get("price")) or 0.0
        preco_base_anuncio = (
            _parse_float_flex(raw_b_item.get("original_price"))
            or _parse_float_flex(price_info.get("standard_price"))
            or _parse_float_flex(price_info.get("original_price"))
            or _parse_float_flex(item.get("original_price"))
            or _parse_float_flex(item.get("base_price"))
            or preco_atual
        )

        promocoes_item_a = None
        preco_a_raw, desc_a_raw = _ml_extrair_preco_promocao_raw(raw_a_item, priorizar_percentual_total_api=True)
        if preco_a_raw is None and desc_a_raw is None:
            try:
                promocoes_item_a, cfg_local = _ml_obter_promocoes_item(client_id, loja, cfg_local, item_id)
                raw_a_fallback = _ml_encontrar_promocao_raw_item(promocoes_item_a, promo_a)
                if raw_a_fallback:
                    raw_a_item = raw_a_fallback
                    preco_a_raw, desc_a_raw = _ml_extrair_preco_promocao_raw(raw_a_item, priorizar_percentual_total_api=True)
            except Exception:
                promocoes_item_a = None
        preco_b_raw, desc_b_raw = _ml_extrair_preco_promocao_raw(raw_b_item, priorizar_percentual_total_api=True)
        status_promo_a = _ml_classificar_status_promocao_entry(raw_a_item)
        if str(price_info.get("promotion_id") or "").strip().lower() == promo_a.lower():
            status_promo_a = "Ativo"
        if not status_promo_a:
            try:
                if promocoes_item_a is None:
                    promocoes_item_a, cfg_local = _ml_obter_promocoes_item(client_id, loja, cfg_local, item_id)
                status_promo_a = _ml_classificar_status_promocao_por_id(promocoes_item_a, promo_a)
            except Exception:
                status_promo_a = ""
        presente_a = status_promo_a == "Ativo"
        presente_a_programado = status_promo_a == "Programado"
        if not presente_a and not presente_a_programado:
            return None
        preco_a = preco_a_raw or preco_base_anuncio or preco_atual
        preco_b = preco_b_raw or _parse_float_flex(raw_b_item.get("price")) or preco_atual or preco_base_anuncio

        desconto_a = desc_a_raw
        if not presente_a and not presente_a_programado and desconto_a is None and preco_a is not None:
            desconto_a = 0.0
        if preco_a_raw is None and desconto_a is not None and preco_base_anuncio and preco_base_anuncio > 0:
            preco_a = round(float(preco_base_anuncio) * max(0.0, 1.0 - (float(desconto_a) / 100.0)), 2)
        if desconto_a is None and preco_a is not None and preco_base_anuncio and preco_base_anuncio > 0:
            desconto_a = max(0.0, ((preco_base_anuncio - preco_a) / preco_base_anuncio) * 100.0)

        desconto_b = _ml_extrair_percentual_sugerido_campanha_raw(raw_b_item, preco_base_anuncio)
        if desconto_b is None:
            desconto_b = desc_b_raw
        meli_pct = _parse_float_flex(raw_b_item.get("meli_percentage"))
        seller_pct = _parse_float_flex(raw_b_item.get("seller_percentage"))
        if desconto_b is None:
            desconto_b = seller_pct if seller_pct is not None else meli_pct
        if desconto_b is None and preco_base_anuncio and preco_b and preco_base_anuncio > 0:
            desconto_b = max(0.0, ((preco_base_anuncio - preco_b) / preco_base_anuncio) * 100.0)

        try:
            shipping_data, cfg_local = _ml_obter_frete_detalhado(
                client_id,
                loja,
                cfg_local,
                item_id,
                item.get("shipping") or {},
                reconsultar_zero=True,
                contexto_frete=_ml_contexto_frete_item(item, preco_b or preco_a or preco_atual or preco_base_anuncio),
            )
        except Exception:
            shipping_data = {}
        frete_api_val = _parse_float_flex(shipping_data.get("shipping_cost"))
        buyer_cost = _parse_float_flex(shipping_data.get("shipping_buyer_cost"))
        frete_gratis_api = bool(shipping_data.get("free_shipping")) or (buyer_cost is not None and buyer_cost <= 0)

        custo = _resolver_custo_medio_por_skus(custos_por_sku, skus_variacoes or [sku, sku_display])
        imposto_rate = _resolver_imposto_rate_por_sku(impostos_por_sku, sku)
        if imposto_rate is None:
            imposto_rate = _resolver_imposto_rate_por_sku(impostos_por_sku, sku_display)

        fee_a = {}
        tarifa_a_val = None
        taxa_fixa_a = None
        tipo_anuncio = _ml_nome_tipo_anuncio(item.get("listing_type_id"))
        if preco_a is not None:
            item_taxa_a = dict(item)
            item_taxa_a["price"] = preco_a
            try:
                fee_a, cfg_local = _ml_obter_taxas_anuncio(client_id, loja, cfg_local, item_taxa_a)
            except Exception:
                fee_a = {}
            tarifa_a_val = _parse_float_flex(fee_a.get("ad_cost"))
            tarifa_promocao_a = _ml_extrair_tarifa_cobrada_promocao_raw(raw_a_item)
            if tarifa_promocao_a is not None:
                tarifa_a_val = tarifa_promocao_a
            taxa_fixa_a = _parse_float_flex(fee_a.get("fixed_fee_amount"))
            tipo_anuncio = fee_a.get("listing_type_name") or tipo_anuncio

        item_taxa_b = dict(item)
        item_taxa_b["price"] = preco_b
        try:
            fee_b, cfg_local = _ml_obter_taxas_anuncio(client_id, loja, cfg_local, item_taxa_b)
        except Exception:
            fee_b = {}
        tarifa_b_val = _parse_float_flex(fee_b.get("ad_cost"))
        taxa_fixa_b = _parse_float_flex(fee_b.get("fixed_fee_amount"))
        tipo_anuncio = fee_b.get("listing_type_name") or tipo_anuncio

        if taxa_fixa_a is None and preco_a is not None:
            taxa_fixa_a = _ml_estimar_taxa_fixa_por_preco(preco_a, domain_id=item.get("domain_id") or "", category_id=item.get("category_id") or "", listing_type_id=item.get("listing_type_id") or "")
        if taxa_fixa_b is None:
            taxa_fixa_b = _ml_estimar_taxa_fixa_por_preco(preco_b, domain_id=item.get("domain_id") or "", category_id=item.get("category_id") or "", listing_type_id=item.get("listing_type_id") or "")

        frete_a_val = None
        frete_b_val = frete_api_val if frete_api_val is not None else 0.0
        frete_gratis_a = False
        frete_gratis_b = bool(frete_gratis_api or (frete_api_val is None and preco_b is not None and preco_b >= 79.0))
        if preco_a is not None:
            frete_a_val = frete_api_val if frete_api_val is not None else 0.0
            frete_gratis_a = bool(frete_gratis_api or (frete_api_val is None and preco_a is not None and preco_a >= 79.0))
        # Frete fica com o valor da API de shipping_options.
        # A taxa fixa do ML pertence ao detalhamento da tarifa, nao substitui frete.

        desconto_tarifa_ml = _ml_extrair_desconto_tarifa_promocao_raw(raw_b_item)
        desconto_tarifa_ml = _calcular_desconto_ml_valor(
            desconto_atual=desconto_tarifa_ml,
            ml_pct=desconto_b,
            preco_base=preco_base_anuncio,
            preco_final_ml=preco_b,
            tarifa_base=tarifa_a_val,
            tarifa_ml=tarifa_b_val,
        )
        desconto_tarifa_ml = _ml_ajustar_desconto_tarifa_recebivel_promocao(
            raw_b_item,
            desconto_tarifa_ml,
            preco_b,
            desconto_b,
        )
        recebe_ml = _ml_calcular_recebivel_promocao(
            raw_b_item,
            preco_b,
            tarifa_b_val,
            frete_b_val,
            desconto_tarifa_ml,
        )
        imposto_a = (preco_a * imposto_rate) if (imposto_rate is not None and preco_a is not None) else None
        imposto_b = (preco_b * imposto_rate) if imposto_rate is not None else None
        valor_liquido_a = None
        valor_liquido_b = None
        margem_a = None
        margem_b = None
        if custo is not None and preco_a is not None:
            valor_liquido_a = preco_a - float(custo) - (frete_a_val or 0.0) - (imposto_a or 0.0) - (tarifa_a_val or 0.0)
            if preco_a:
                margem_a = (valor_liquido_a * 100.0) / preco_a
        if custo is not None:
            valor_liquido_b = preco_b - float(custo) - (frete_b_val or 0.0) - (imposto_b or 0.0) - (tarifa_b_val or 0.0)
            if desconto_tarifa_ml is not None:
                valor_liquido_b += float(desconto_tarifa_ml)
            if preco_b:
                margem_b = (valor_liquido_b * 100.0) / preco_b

        margem_minima_pct = float(margem_minima or 0)
        if margem_a is None or margem_a < margem_minima_pct:
            decisao = "Nao participar"
        elif margem_b is None or margem_b < margem_minima_pct:
            decisao = "Nao participar"
        elif margem_a is not None and margem_b < margem_a:
            decisao = "Nao participar"
        else:
            decisao = "Participar"

        if presente_a:
            status = "Ativo"
        elif presente_a_programado:
            status = "Programado"
        else:
            status = "Base atual"
        return {
            "Tipo": tipo_anuncio,
            "%": _format_pct_br(
                fee_b.get("sale_fee_pct")
                if fee_b.get("sale_fee_pct") is not None
                else (fee_a.get("sale_fee_pct") if fee_a.get("sale_fee_pct") is not None else None)
            ),
            "SKU": sku_display or sku,
            "TÃ­tulo": str(item.get("title") or raw_b_item.get("title") or ""),
            "Frete": formatar_moeda_br(frete_a_val) if preco_a is not None else "",
            "Frete ML": formatar_moeda_br(frete_b_val),
            "Frete Gratis": ("SIM" if frete_gratis_a else "NAO") if preco_a is not None else "",
            "Frete Gratis ML": "SIM" if frete_gratis_b else "NAO",
            "Custo": formatar_moeda_br(custo) if custo is not None else "",
            "Tarifa": formatar_moeda_br(tarifa_a_val) if tarifa_a_val is not None and preco_a is not None else "",
            "Tarifa ML": formatar_moeda_br(tarifa_b_val) if tarifa_b_val is not None else "",
            "MLB": item_id,
            "Campanha ML": promo_meta["promo_texto"] or promo_meta["promo_b"],
            "Arquivo Promocao 2": "",
            "% Fixa": _format_pct_br(desconto_a) if preco_a is not None else "",
            "ML % Campanha": _format_pct_br(desconto_b),
            "PreÃ§o Final": formatar_moeda_br(preco_a) if preco_a is not None else "",
            "deal_price": round(float(preco_b), 2) if preco_b is not None else None,
            "preco_promocional_ml": round(float(preco_b), 2) if preco_b is not None else None,
            "preco_final_ml_display": recebe_ml,
            "Imposto %": _format_pct_br(imposto_rate * 100.0) if imposto_rate is not None else "",
            "Imposto": formatar_moeda_br(imposto_a) if imposto_a is not None else "",
            "PreÃ§o Final ML": formatar_moeda_br(recebe_ml) if recebe_ml is not None else formatar_moeda_br(preco_b),
            "Imposto ML": formatar_moeda_br(imposto_b) if imposto_b is not None else "",
            "Desconto ML": formatar_moeda_br(desconto_tarifa_ml) if desconto_tarifa_ml is not None else "",
            "Valor LÃ­quido": formatar_moeda_br(valor_liquido_a) if valor_liquido_a is not None else "",
            "Valor lÃ­quido ML": formatar_moeda_br(valor_liquido_b) if valor_liquido_b is not None else "",
            "Status": status,
            "Margem": _format_pct_br(margem_a),
            "Margem ML": _format_pct_br(margem_b),
            "AÃ§Ã£o": decisao,
            "Participar ou nÃ£o": decisao,
            "offer_id": _ml_promocao_raw_offer_id(raw_b_item),
            "promotion_type": promo_meta.get("promo_b_type") or "",
        }

    analises = []
    for idx, promo_meta in enumerate(promocoes_processar, start=1):
        _emit_progress(
            36 + int((idx / max(1, total_solicitacoes)) * 18),
            f"Consultando Promocao 2 {idx}/{total_solicitacoes}: {promo_meta['promo_texto']}",
            details={"solicitacao_atual": idx, "solicitacoes_total": total_solicitacoes, "promo_b": promo_meta["promo_b"]},
        )
        try:
            itens_b_refs, raw_b, cfg = _ml_listar_itens_promocao_multistatus_com_raw(
                client_id,
                loja,
                cfg,
                promo_meta["promo_b"],
                promotion_type=promo_meta.get("promo_b_type") or "",
                max_items=5000,
                buscar_detalhes=False,
                expected_min_items=_promo_total_esperado_por_contagens(
                    promo_meta.get("active_count"),
                    promo_meta.get("eligible_count"),
                ),
                progress_callback=lambda msg, i=idx, meta=promo_meta: _emit_progress(
                    40 + int((i / max(1, total_solicitacoes)) * 12),
                    msg,
                    details={"solicitacao_atual": i, "solicitacoes_total": total_solicitacoes, "promo_b": meta["promo_b"]},
                ),
            )
        except Exception as exc:
            erro_txt = _erro_legivel(exc)
            logger.warning("[PROMO API SEM ARQUIVOS] Promocao %s falhou ao consultar itens: %s", promo_meta["promo_b"], erro_txt)
            _emit_progress(
                48 + int((idx / max(1, total_solicitacoes)) * 10),
                f"Promocao {promo_meta['promo_texto']} falhou. Continuando as demais...",
                details={"solicitacao_atual": idx, "solicitacoes_total": total_solicitacoes, "erro": erro_txt},
            )
            analises.append({
                "promo_b_id": promo_meta["promo_b"],
                "promo_b_type": promo_meta.get("promo_b_type") or "",
                "promo_b_nome": promo_meta["promo_texto"],
                "active_count": promo_meta.get("active_count"),
                "eligible_count": promo_meta.get("eligible_count"),
                "arquivo_nome": f"analise_api_{re.sub(r'[^A-Za-z0-9]+', '_', promo_meta['promo_b'])}.xlsx",
                "tab_label": promo_meta["promo_texto"] or promo_meta["promo_b"],
                "total": 0,
                "planilha_gerada": None,
                "data": [],
                "origem": "api",
                "error": erro_txt,
            })
            continue
        ids_b = [
            str(x.get("id") or "").strip()
            for x in (itens_b_refs or [])
            if str(x.get("id") or "").strip()
        ]
        ids_b = list(dict.fromkeys(ids_b))
        _emit_progress(
            56 + int((idx / max(1, total_solicitacoes)) * 12),
            f"Consultando dados de {len(ids_b)} anuncio(s) da Promocao 2...",
            details={"solicitacao_atual": idx, "solicitacoes_total": total_solicitacoes, "itens_solicitacao": len(ids_b)},
        )

        try:
            itens_filtrados, cfg = _ml_buscar_itens_batch(
                client_id,
                loja,
                cfg,
                ids_b,
                progress_callback=lambda msg: _emit_progress(
                    60 + int((idx / max(1, total_solicitacoes)) * 8),
                    msg,
                    details={"solicitacao_atual": idx, "solicitacoes_total": total_solicitacoes, "promo_b": promo_meta["promo_b"]},
                ),
            )
        except Exception as exc:
            erro_txt = _erro_legivel(exc)
            logger.warning("[PROMO API SEM ARQUIVOS] Promocao %s falhou ao buscar detalhes: %s", promo_meta["promo_b"], erro_txt)
            _emit_progress(
                62 + int((idx / max(1, total_solicitacoes)) * 10),
                f"Promocao {promo_meta['promo_texto']} falhou ao consultar detalhes. Continuando as demais...",
                details={"solicitacao_atual": idx, "solicitacoes_total": total_solicitacoes, "erro": erro_txt},
            )
            analises.append({
                "promo_b_id": promo_meta["promo_b"],
                "promo_b_type": promo_meta.get("promo_b_type") or "",
                "promo_b_nome": promo_meta["promo_texto"],
                "active_count": promo_meta.get("active_count"),
                "eligible_count": promo_meta.get("eligible_count"),
                "arquivo_nome": f"analise_api_{re.sub(r'[^A-Za-z0-9]+', '_', promo_meta['promo_b'])}.xlsx",
                "tab_label": promo_meta["promo_texto"] or promo_meta["promo_b"],
                "total": 0,
                "planilha_gerada": None,
                "data": [],
                "origem": "api",
                "error": erro_txt,
            })
            continue
        itens_por_id = {
            str(item.get("id") or "").strip(): item
            for item in (itens_filtrados or [])
            if str(item.get("id") or "").strip()
        }
        item_pairs = [(item_id, itens_por_id.get(item_id)) for item_id in ids_b]
        _emit_progress(
            70 + int((idx / max(1, total_solicitacoes)) * 20),
            f"Montando analise {idx}/{total_solicitacoes} com dados da API...",
            details={"solicitacao_atual": idx, "solicitacoes_total": total_solicitacoes, "itens_solicitacao": len(item_pairs)},
        )

        linhas = []
        if item_pairs:
            max_workers = min(10, max(2, len(item_pairs)))
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                future_map = {
                    executor.submit(_montar_linha_api, item_id, item, promo_meta, raw_b): item_id
                    for item_id, item in item_pairs
                }
                linhas_por_id = {}
                for future in as_completed(future_map):
                    item_id = future_map[future]
                    try:
                        linha = future.result()
                        if linha:
                            linhas_por_id[item_id] = linha
                    except Exception:
                        logger.exception("[PROMO API SEM ARQUIVOS] Falha ao montar item %s", item_id)
                linhas = [linhas_por_id[item_id] for item_id, _ in item_pairs if item_id in linhas_por_id]
        total_montadas = len(linhas)
        total_status_ok = sum(1 for row in linhas if _promo_linha_status_ativo_ou_programado(row))
        total_pct_ok = sum(1 for row in linhas if _promo_linha_pct_fixa_maior_que_zero(row))
        linhas = [
            row for row in linhas
            if _promo_linha_status_ativo_ou_programado(row)
            and _promo_linha_pct_fixa_maior_que_zero(row)
        ]
        logger.info(
            "[PROMO API SEM ARQUIVOS] %s: candidatos=%s, linhas_montadas=%s, status_ok=%s, pct_fixa_ok=%s, final=%s",
            promo_meta["promo_b"],
            len(item_pairs),
            total_montadas,
            total_status_ok,
            total_pct_ok,
            len(linhas),
        )

        planilha_nome = _salvar_planilha_analise_promo(
            client_id,
            linhas,
            prefixo=f"analise_promo_api_{re.sub(r'[^A-Za-z0-9]+', '_', promo_meta['promo_b'])[:40]}",
        )
        df_payload = _build_df_planilha_analise_promo(linhas).fillna("")
        dados_payload = df_payload.to_dict(orient="records")
        meta_por_linha = {
            str(item.get("MLB") or "").strip(): {
                "offer_id": str(item.get("offer_id") or "").strip(),
                "promotion_type": str(item.get("promotion_type") or "").strip(),
                "deal_price": _parse_float_flex(item.get("deal_price") or item.get("preco_promocional_ml")),
            }
            for item in linhas
            if str(item.get("MLB") or "").strip()
        }
        for row in dados_payload:
            row["Frete Gratis"] = row.get("Frete GrÃ¡tis", row.get("Frete Gratis", ""))
            row["Frete Gratis ML"] = row.get("Frete GrÃ¡tis ML", row.get("Frete Gratis ML", ""))
            meta = meta_por_linha.get(str(row.get("MLB") or "").strip()) or {}
            if meta.get("offer_id"):
                row["offer_id"] = meta["offer_id"]
            if meta.get("promotion_type"):
                row["promotion_type"] = meta["promotion_type"]
            if meta.get("deal_price") is not None:
                row["deal_price"] = meta["deal_price"]

        arquivo_nome = f"analise_api_{re.sub(r'[^A-Za-z0-9]+', '_', promo_meta['promo_b'])}.xlsx"
        analises.append({
            "promo_b_id": promo_meta["promo_b"],
            "promo_b_type": promo_meta.get("promo_b_type") or "",
            "promo_b_nome": promo_meta["promo_texto"],
            "active_count": promo_meta.get("active_count"),
            "eligible_count": promo_meta.get("eligible_count"),
            "arquivo_nome": arquivo_nome,
            "tab_label": promo_meta["promo_texto"] or promo_meta["promo_b"],
            "total": len(dados_payload),
            "planilha_gerada": planilha_nome,
            "data": dados_payload,
            "origem": "api",
        })

    _emit_progress(98, "Finalizando resultado da analise via API...")
    return {
        "success": True,
        "mode": "api_comparacao_promocoes_sem_arquivos",
        "loja": loja,
        "promocao_a_id": promo_a,
        "total_abas": len(analises),
        "tempo_segundos": round(time.time() - inicio, 1),
        "analises": analises,
        "data": analises[0]["data"] if analises else [],
        "planilha_gerada": analises[0]["planilha_gerada"] if analises else None,
    }


@app.post("/api/promo/analise-via-api-arquivos")
async def analisar_promo_via_api_com_arquivos(
    loja: str = Form(...),
    promocao_a_id: str = Form(...),
    promocao_a_type: str = Form(""),
    margem_minima: float = Form(15.0),
    promocoes_b_meta: str = Form(...),
    files: list[UploadFile] = File(...),
    client_id: str = Depends(get_tenant_id),
    progress_hook: Optional[Callable[[dict], None]] = None,
):
    inicio = time.time()

    def _emit_progress(progress: int, message: str, phase: str = "running", details: Optional[dict] = None):
        if not progress_hook:
            return
        payload = {
            "progress": max(0, min(99, int(progress))),
            "message": str(message or "").strip() or "Processando analise de promocoes...",
            "phase": phase,
        }
        if isinstance(details, dict) and details:
            payload["details"] = details
        try:
            progress_hook(payload)
        except Exception:
            pass

    promo_a = str(promocao_a_id or "").strip()
    promo_a_type = str(promocao_a_type or "").strip()
    if promo_a_type in {"-", "None", "null"}:
        promo_a_type = ""

    try:
        promocoes_meta = json.loads(promocoes_b_meta or "[]")
    except Exception:
        raise HTTPException(status_code=400, detail="Metadados das Promocoes 2 invalidos.")

    if not loja or not promo_a:
        raise HTTPException(status_code=400, detail="Informe a loja e a Promocao 1.")
    if not isinstance(promocoes_meta, list) or not promocoes_meta:
        raise HTTPException(status_code=400, detail="Anexe ao menos um arquivo vinculado a uma Promocao 2.")
    if not files:
        raise HTTPException(status_code=400, detail="Envie os arquivos das Promocoes 2.")

    _emit_progress(12, "Validando vinculos entre Promocoes 2 e arquivos enviados...")

    arquivos_por_nome = {}
    for upload in files:
        nome = str(getattr(upload, "filename", "") or "").strip()
        if nome:
            arquivos_por_nome[nome.lower()] = upload

    promocoes_processar = []
    for meta in promocoes_meta:
        if not isinstance(meta, dict):
            continue
        arquivo_nome = str(meta.get("arquivo_nome") or "").strip()
        promo_b = str(meta.get("promo_b_id") or "").strip()
        if not arquivo_nome or not promo_b:
            continue
        upload = arquivos_por_nome.get(arquivo_nome.lower())
        if upload is None:
            raise HTTPException(status_code=400, detail=f"Arquivo nao encontrado no envio: {arquivo_nome}")
        promocoes_processar.append({
            "promo_b": promo_b,
            "promo_b_type": str(meta.get("promo_b_type") or "").strip(),
            "promo_texto": str(meta.get("promo_texto") or promo_b).strip(),
            "active_count": _promo_meta_contagem(meta, "active_count", "activeCount", "active", "ativos"),
            "eligible_count": _promo_meta_contagem(meta, "eligible_count", "eligibleCount", "eligible", "elegiveis"),
            "arquivo_nome": arquivo_nome,
            "upload": upload,
        })

    if not promocoes_processar:
        raise HTTPException(status_code=400, detail="Nenhum arquivo valido de Promocao 2 foi vinculado.")

    total_solicitacoes = len(promocoes_processar)
    _emit_progress(
        18,
        f"{total_solicitacoes} solicitacao(oes) de Promocao 2 recebida(s).",
        details={"solicitacoes_total": total_solicitacoes},
    )

    cfg = _obter_cfg_ml(client_id, loja)
    _emit_progress(24, "Consultando anuncios da Promocao 1...")
    itens_a_refs, raw_a, cfg = _ml_listar_itens_promocao_com_raw(
        client_id,
        loja,
        cfg,
        promo_a,
        promotion_type=promo_a_type,
        usar_fallback_pesado=True,
        forcar_fallback_pesado=True,
        max_items=5000,
        buscar_detalhes=False,
        progress_callback=lambda msg: _emit_progress(28, msg, details={"promo": promo_a}),
    )
    ids_a = {str(x.get("id") or "").strip() for x in (itens_a_refs or []) if str(x.get("id") or "").strip()}
    _emit_progress(32, f"Promocao 1 carregada com {len(ids_a)} anuncio(s).")

    custos_por_sku, impostos_por_sku = _carregar_custos_impostos_cadastro_por_sku_loja(client_id, loja)

    analises = []
    ids_globais = set()
    for idx, promo in enumerate(promocoes_processar, start=1):
        progress_leitura = 34 + int((idx / max(1, total_solicitacoes)) * 16)
        _emit_progress(
            progress_leitura,
            f"Lendo arquivo {idx}/{total_solicitacoes}: {promo['arquivo_nome']}",
            details={
                "solicitacao_atual": idx,
                "solicitacoes_total": total_solicitacoes,
                "arquivo": promo["arquivo_nome"],
            },
        )
        content = await promo["upload"].read()
        df = await asyncio.to_thread(ler_e_tratar_arquivo, content, promo["arquivo_nome"], "Promocoes")
        mapa_promo2, ordem_ids = _extrair_mapa_promocao2_arquivo(df)
        if not mapa_promo2:
            raise HTTPException(status_code=400, detail=f"Nao foi possivel localizar os MLBs no arquivo {promo['arquivo_nome']}.")
        promo["mapa_promo2"] = mapa_promo2
        promo["ordem_ids"] = ordem_ids
        ids_globais.update(ordem_ids)

    _emit_progress(55, f"Consultando dados de {len(ids_globais)} anuncio(s) na API do ML...")

    itens_filtrados, cfg = _ml_buscar_itens_batch(
        client_id,
        loja,
        cfg,
        sorted(ids_globais),
        progress_callback=lambda msg: _emit_progress(60, msg, details={"itens": len(ids_globais)}),
    )
    itens_por_id = {
        str(item.get("id") or "").strip(): item
        for item in (itens_filtrados or [])
        if str(item.get("id") or "").strip()
    }
    _emit_progress(66, f"Dados recebidos de {len(itens_por_id)} anuncio(s). Iniciando comparacao...")

    def _montar_linha_arquivo(item_id: str, item: dict | None, entrada_b: dict, promo_meta: dict):
        item = dict(item or {})
        item.setdefault("id", item_id)
        if not item.get("title"):
            item["title"] = entrada_b.get("TÃ­tulo") or item_id

        sku_base = _promo_txt_clean(entrada_b.get("SKU"))
        sku = _ml_extrair_sku(item) or str(item.get("seller_custom_field") or "").strip() or sku_base
        sku_display = sku or sku_base
        skus_variacoes = []
        try:
            variacoes = _ml_extrair_variacoes_resumo(item, client_id=client_id, loja=loja)
        except Exception:
            variacoes = []
        if variacoes:
            skus_variacoes = [str(v.get("sku") or "").strip() for v in variacoes if str(v.get("sku") or "").strip() and str(v.get("sku") or "").strip() != "-"]
            if skus_variacoes:
                sku_display = " / ".join(list(dict.fromkeys(skus_variacoes))[:4])

        cfg_local = dict(cfg)
        try:
            price_info, cfg_local = _ml_obter_preco_detalhado(client_id, loja, cfg_local, item_id, fallback_price=item.get("price"))
        except Exception:
            price_info = {}
        preco_atual = _parse_float_flex(price_info.get("price")) or _parse_float_flex(item.get("price")) or 0.0
        preco_base_anuncio = (
            _parse_float_flex(price_info.get("standard_price"))
            or _parse_float_flex(price_info.get("original_price"))
            or _parse_float_flex(item.get("original_price"))
            or _parse_float_flex(item.get("base_price"))
            or preco_atual
        )

        raw_a_item = raw_a.get(item_id, {})
        if promo_a_type and not raw_a_item:
            try:
                raw_a_item, cfg_local = _ml_obter_item_promocao_raw(client_id, loja, cfg_local, promo_a, promo_a_type, item_id)
            except Exception:
                raw_a_item = {}
        raw_b_item = {}
        promo_b_type = str(promo_meta.get("promo_b_type") or "").strip()
        promo_b_id = str(promo_meta.get("promo_b") or "").strip()
        if promo_b_type and promo_b_id:
            try:
                raw_b_item, cfg_local = _ml_obter_item_promocao_raw(client_id, loja, cfg_local, promo_b_id, promo_b_type, item_id)
            except Exception:
                raw_b_item = {}
        raw_b_item, cfg_local = _ml_resolver_raw_promocao_equivalente_para_analise(
            client_id,
            loja,
            cfg_local,
            item_id,
            raw_b_item,
            promo_b_id,
            promo_b_type,
            None,
        )

        promocoes_item_a = None
        preco_a_raw, desc_a_raw = _ml_extrair_preco_promocao_raw(raw_a_item, priorizar_percentual_total_api=True)
        if preco_a_raw is None and desc_a_raw is None:
            try:
                promocoes_item_a, cfg_local = _ml_obter_promocoes_item(client_id, loja, cfg_local, item_id)
                raw_a_fallback = _ml_encontrar_promocao_raw_item(promocoes_item_a, promo_a)
                if raw_a_fallback:
                    raw_a_item = raw_a_fallback
                    preco_a_raw, desc_a_raw = _ml_extrair_preco_promocao_raw(raw_a_item, priorizar_percentual_total_api=True)
            except Exception:
                promocoes_item_a = None
        preco_b = _parse_float_flex(entrada_b.get("PreÃ§o Final ML")) or preco_atual or preco_base_anuncio
        status_promo_a = _ml_classificar_status_promocao_entry(raw_a_item)
        if str(price_info.get("promotion_id") or "").strip().lower() == promo_a.lower():
            status_promo_a = "Ativo"
        if not status_promo_a:
            try:
                if promocoes_item_a is None:
                    promocoes_item_a, cfg_local = _ml_obter_promocoes_item(client_id, loja, cfg_local, item_id)
                status_promo_a = _ml_classificar_status_promocao_por_id(promocoes_item_a, promo_a)
            except Exception:
                status_promo_a = ""
        presente_a_ativo = status_promo_a == "Ativo"
        presente_a_programado = status_promo_a == "Programado"
        if not presente_a_ativo and not presente_a_programado:
            return None
        preco_a = preco_a_raw or preco_base_anuncio or preco_atual

        desconto_a = desc_a_raw
        desconto_b = _ml_extrair_percentual_sugerido_campanha_raw(raw_b_item, preco_base_anuncio)
        if desconto_b is None:
            desconto_b = _ml_parse_percentual_promocao_texto(entrada_b.get("ML % Campanha"))
        if not presente_a_ativo and not presente_a_programado and desconto_a is None and preco_a is not None:
            desconto_a = 0.0
        if preco_a_raw is None and desconto_a is not None and preco_base_anuncio and preco_base_anuncio > 0:
            preco_a = round(float(preco_base_anuncio) * max(0.0, 1.0 - (float(desconto_a) / 100.0)), 2)
        if desconto_a is None and preco_base_anuncio and preco_a and preco_base_anuncio > 0:
            desconto_a = max(0.0, ((preco_base_anuncio - preco_a) / preco_base_anuncio) * 100.0)
        if desconto_b is None and preco_base_anuncio and preco_b and preco_base_anuncio > 0:
            desconto_b = max(0.0, ((preco_base_anuncio - preco_b) / preco_base_anuncio) * 100.0)

        try:
            shipping_data, cfg_local = _ml_obter_frete_detalhado(
                client_id,
                loja,
                cfg_local,
                item_id,
                item.get("shipping") or {},
                reconsultar_zero=True,
                contexto_frete=_ml_contexto_frete_item(item, preco_b or preco_a or preco_atual or preco_base_anuncio),
            )
        except Exception:
            shipping_data = {}
        frete_api_val = _parse_float_flex(shipping_data.get("shipping_cost"))
        buyer_cost = _parse_float_flex(shipping_data.get("shipping_buyer_cost"))
        frete_gratis_api = bool(shipping_data.get("free_shipping")) or (buyer_cost is not None and buyer_cost <= 0)

        custo = _resolver_custo_medio_por_skus(custos_por_sku, skus_variacoes or [sku, sku_display, sku_base])
        imposto_rate = _resolver_imposto_rate_por_sku(impostos_por_sku, sku)
        if imposto_rate is None:
            imposto_rate = _resolver_imposto_rate_por_sku(impostos_por_sku, sku_display)

        tarifa_a_val = None
        tarifa_b_val = None
        taxa_fixa_a = None
        taxa_fixa_b = None
        tipo_anuncio = _ml_nome_tipo_anuncio(item.get("listing_type_id"))
        pct_taxa = None

        if preco_a is not None:
            item_taxa_a = dict(item)
            item_taxa_a["price"] = preco_a
            try:
                fee_a, cfg_local = _ml_obter_taxas_anuncio(client_id, loja, cfg_local, item_taxa_a)
            except Exception:
                fee_a = {}
            tarifa_a_val = _parse_float_flex(fee_a.get("ad_cost"))
            tarifa_promocao_a = _ml_extrair_tarifa_cobrada_promocao_raw(raw_a_item)
            if tarifa_promocao_a is not None:
                tarifa_a_val = tarifa_promocao_a
            taxa_fixa_a = _parse_float_flex(fee_a.get("fixed_fee_amount"))
            tipo_anuncio = fee_a.get("listing_type_name") or tipo_anuncio
            pct_taxa = fee_a.get("sale_fee_pct")
        else:
            fee_a = {}

        item_taxa_b = dict(item)
        item_taxa_b["price"] = preco_b
        try:
            fee_b, cfg_local = _ml_obter_taxas_anuncio(client_id, loja, cfg_local, item_taxa_b)
        except Exception:
            fee_b = {}
        tarifa_b_val = _parse_float_flex(fee_b.get("ad_cost"))
        taxa_fixa_b = _parse_float_flex(fee_b.get("fixed_fee_amount"))
        tipo_anuncio = fee_b.get("listing_type_name") or tipo_anuncio
        pct_taxa = fee_b.get("sale_fee_pct") if fee_b.get("sale_fee_pct") is not None else pct_taxa

        if taxa_fixa_a is None and preco_a is not None:
            taxa_fixa_a = _ml_estimar_taxa_fixa_por_preco(preco_a, domain_id=item.get("domain_id") or "", category_id=item.get("category_id") or "", listing_type_id=item.get("listing_type_id") or "")
        if taxa_fixa_b is None:
            taxa_fixa_b = _ml_estimar_taxa_fixa_por_preco(preco_b, domain_id=item.get("domain_id") or "", category_id=item.get("category_id") or "", listing_type_id=item.get("listing_type_id") or "")

        frete_a_val = None
        frete_b_val = frete_api_val if frete_api_val is not None else 0.0
        frete_gratis_a = False
        frete_gratis_b = bool(frete_gratis_api or (frete_api_val is None and preco_b is not None and preco_b >= 79.0))
        if preco_a is not None:
            frete_a_val = frete_api_val if frete_api_val is not None else 0.0
            frete_gratis_a = bool(frete_gratis_api or (frete_api_val is None and preco_a is not None and preco_a >= 79.0))

        # Frete fica com o valor da API de shipping_options.
        # A taxa fixa do ML pertence ao detalhamento da tarifa, nao substitui frete.

        desconto_tarifa_ml = _calcular_desconto_ml_valor(
            desconto_atual=entrada_b.get("Desconto ML"),
            ml_pct=desconto_b,
            preco_base=preco_base_anuncio,
            preco_final_ml=preco_b,
            tarifa_base=tarifa_a_val,
            tarifa_ml=tarifa_b_val,
        )
        desconto_tarifa_ml = _ml_ajustar_desconto_tarifa_recebivel_promocao(
            raw_b_item,
            desconto_tarifa_ml,
            preco_b,
            desconto_b,
        )
        recebe_ml = _ml_calcular_recebivel_promocao(
            raw_b_item,
            preco_b,
            tarifa_b_val,
            frete_b_val,
            desconto_tarifa_ml,
        )
        imposto_a = (preco_a * imposto_rate) if (imposto_rate is not None and preco_a is not None) else None
        imposto_b = (preco_b * imposto_rate) if imposto_rate is not None else None
        valor_liquido_a = None
        valor_liquido_b = None
        margem_a = None
        margem_b = None
        if custo is not None and preco_a is not None:
            valor_liquido_a = preco_a - float(custo) - (frete_a_val or 0.0) - (imposto_a or 0.0) - (tarifa_a_val or 0.0)
            if preco_a:
                margem_a = (valor_liquido_a * 100.0) / preco_a
        if custo is not None:
            valor_liquido_b = preco_b - float(custo) - (frete_b_val or 0.0) - (imposto_b or 0.0) - (tarifa_b_val or 0.0)
            if desconto_tarifa_ml is not None:
                valor_liquido_b += float(desconto_tarifa_ml)
            if preco_b:
                margem_b = (valor_liquido_b * 100.0) / preco_b

        if presente_a_ativo:
            status = "Ativo"
        elif presente_a_programado:
            status = "Programado"
        else:
            status = "Base atual"

        margem_minima_pct = float(margem_minima or 0)
        tem_valores_comparacao = (
            custo is not None
            and preco_a not in (None, 0)
            and preco_b not in (None, 0)
            and margem_a is not None
            and tarifa_b_val is not None
            and valor_liquido_b is not None
            and margem_b is not None
        )
        if not tem_valores_comparacao:
            decisao = "NÃ£o participar"
        elif margem_a is None or margem_a < margem_minima_pct:
            decisao = "NÃ£o participar"
        elif margem_b is None:
            decisao = "NÃ£o participar"
        elif margem_b < margem_minima_pct:
            decisao = "NÃ£o participar"
        elif margem_b is not None and margem_a is not None and margem_b < margem_a:
            decisao = "NÃ£o participar"
        else:
            decisao = "Participar"

        return {
            "Tipo": tipo_anuncio,
            "%": _format_pct_br(
                fee_b.get("sale_fee_pct")
                if fee_b.get("sale_fee_pct") is not None
                else (fee_a.get("sale_fee_pct") if fee_a.get("sale_fee_pct") is not None else pct_taxa)
            ),
            "SKU": sku_display or sku_base,
            "TÃ­tulo": str(item.get("title") or entrada_b.get("TÃ­tulo") or ""),
            "Frete": formatar_moeda_br(frete_a_val) if preco_a is not None else "",
            "Frete ML": formatar_moeda_br(frete_b_val),
            "Frete Gratis": ("SIM" if frete_gratis_a else "NÃƒO") if preco_a is not None else "",
            "Frete Gratis ML": "SIM" if frete_gratis_b else "NÃƒO",
            "Custo": formatar_moeda_br(custo) if custo is not None else "",
            "Tarifa": formatar_moeda_br(tarifa_a_val) if tarifa_a_val is not None and preco_a is not None else "",
            "Tarifa ML": formatar_moeda_br(tarifa_b_val) if tarifa_b_val is not None else "",
            "MLB": item_id,
            "Campanha ML": promo_meta["promo_texto"] or promo_meta["promo_b"],
            "Arquivo Promocao 2": promo_meta["arquivo_nome"],
            "% Fixa": _format_pct_br(desconto_a) if preco_a is not None else "",
            "ML % Campanha": _format_pct_br(desconto_b),
            "PreÃ§o Final": formatar_moeda_br(preco_a) if preco_a is not None else "",
            "deal_price": round(float(preco_b), 2) if preco_b is not None else None,
            "preco_promocional_ml": round(float(preco_b), 2) if preco_b is not None else None,
            "preco_final_ml_display": recebe_ml,
            "Imposto %": _format_pct_br(imposto_rate * 100.0) if imposto_rate is not None else "",
            "Imposto": formatar_moeda_br(imposto_a) if imposto_a is not None else "",
            "PreÃ§o Final ML": formatar_moeda_br(recebe_ml) if recebe_ml is not None else formatar_moeda_br(preco_b),
            "Imposto ML": formatar_moeda_br(imposto_b) if imposto_b is not None else "",
            "Desconto ML": formatar_moeda_br(desconto_tarifa_ml) if desconto_tarifa_ml is not None else "",
            "Valor LÃ­quido": formatar_moeda_br(valor_liquido_a) if valor_liquido_a is not None else "",
            "Valor lÃ­quido ML": formatar_moeda_br(valor_liquido_b) if valor_liquido_b is not None else "",
            "Status": status,
            "Margem": _format_pct_br(margem_a),
            "Margem ML": _format_pct_br(margem_b),
            "AÃ§Ã£o": decisao,
            "Participar ou nÃ£o": decisao,
        }

    for idx, promo_meta in enumerate(promocoes_processar, start=1):
        mapa_promo2 = promo_meta["mapa_promo2"]
        ordem_ids = promo_meta["ordem_ids"]
        item_pairs = [(item_id, itens_por_id.get(item_id)) for item_id in ordem_ids]
        progress_comp = 68 + int((idx / max(1, total_solicitacoes)) * 25)
        _emit_progress(
            progress_comp,
            f"Processando solicitacao {idx}/{total_solicitacoes}: {promo_meta['promo_texto'] or promo_meta['promo_b']}",
            details={
                "solicitacao_atual": idx,
                "solicitacoes_total": total_solicitacoes,
                "itens_solicitacao": len(item_pairs),
                "arquivo": promo_meta["arquivo_nome"],
            },
        )
        logger.info(f"[PROMO API ARQUIVOS] Promocao 1={promo_a} Arquivo={promo_meta['arquivo_nome']} itens={len(item_pairs)}")
        linhas = []
        if item_pairs:
            max_workers = min(10, max(2, len(item_pairs)))
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                future_map = {
                    executor.submit(_montar_linha_arquivo, item_id, item, mapa_promo2.get(item_id, {}), promo_meta): item_id
                    for item_id, item in item_pairs
                }
                linhas_por_id = {}
                for future in as_completed(future_map):
                    item_id = future_map[future]
                    try:
                        linha = future.result()
                        if linha:
                            linhas_por_id[item_id] = linha
                    except Exception as e:
                        logger.warning(f"[PROMO API ARQUIVOS] Falha ao montar item {item_id}: {e}")
                linhas = [linhas_por_id[item_id] for item_id, _ in item_pairs if item_id in linhas_por_id]
        linhas = [
            row for row in linhas
            if _promo_linha_status_ativo_ou_programado(row)
            and _promo_linha_pct_fixa_maior_que_zero(row)
        ]

        planilha_nome = _salvar_planilha_analise_promo(
            client_id,
            linhas,
            prefixo=f"analise_promo_api_{re.sub(r'[^A-Za-z0-9]+', '_', promo_meta['promo_b'])[:40]}",
        )
        df_payload = _build_df_planilha_analise_promo(linhas).fillna("")
        dados_payload = df_payload.to_dict(orient="records")
        meta_por_linha = {
            str(item.get("MLB") or "").strip(): {
                "deal_price": _parse_float_flex(item.get("deal_price") or item.get("preco_promocional_ml")),
            }
            for item in linhas
            if str(item.get("MLB") or "").strip()
        }
        for row in dados_payload:
            row["Frete Gratis"] = row.get("Frete GrÃ¡tis", row.get("Frete Gratis", ""))
            row["Frete Gratis ML"] = row.get("Frete GrÃ¡tis ML", row.get("Frete Gratis ML", ""))
            meta = meta_por_linha.get(str(row.get("MLB") or "").strip()) or {}
            if meta.get("deal_price") is not None:
                row["deal_price"] = meta["deal_price"]

        analises.append({
            "promo_b_id": promo_meta["promo_b"],
            "promo_b_type": promo_meta["promo_b_type"],
            "promo_b_nome": promo_meta["promo_texto"],
            "active_count": promo_meta.get("active_count"),
            "eligible_count": promo_meta.get("eligible_count"),
            "arquivo_nome": promo_meta["arquivo_nome"],
            "tab_label": promo_meta["promo_texto"] or promo_meta["arquivo_nome"],
            "total": len(dados_payload),
            "planilha_gerada": planilha_nome,
            "data": dados_payload,
        })

    _emit_progress(98, "Finalizando resultado da analise...")

    return {
        "success": True,
        "mode": "api_comparacao_promocoes_arquivos",
        "loja": loja,
        "promocao_a_id": promo_a,
        "total_abas": len(analises),
        "tempo_segundos": round(time.time() - inicio, 1),
        "analises": analises,
        "data": analises[0]["data"] if analises else [],
        "planilha_gerada": analises[0]["planilha_gerada"] if analises else None,
    }


def _promo_analise_background_worker(
    *,
    job_id: str,
    loja: str,
    promocao_a_id: str,
    promocao_a_type: str,
    margem_minima: float,
    promocoes_b_meta: str,
    files_payload: list[dict],
    client_id: str,
):
    try:
        _promo_job_set(
            job_id,
            status="running",
            progress=15,
            message="Processando Promocao 1 e arquivos da Promocao 2 em segundo plano...",
        )
        uploads = [
            UploadFile(file=io.BytesIO(item["content"]), filename=item["filename"])
            for item in files_payload
        ]
        resultado = asyncio.run(
            analisar_promo_via_api_com_arquivos(
                loja=loja,
                promocao_a_id=promocao_a_id,
                promocao_a_type=promocao_a_type,
                margem_minima=margem_minima,
                promocoes_b_meta=promocoes_b_meta,
                files=uploads,
                client_id=client_id,
            )
        )
        _promo_job_set(
            job_id,
            status="completed",
            progress=100,
            message="Analise concluida.",
            result=resultado,
        )
    except Exception as e:
        logger.exception("[PROMO API BG] Falha no job %s", job_id)
        _promo_job_set(
            job_id,
            status="error",
            progress=100,
            message="Falha ao processar a analise.",
            error=str(e),
        )


PROMO_AUTOMACAO_INTERVAL_UNITS = {
    "minutes": 1,
    "hours": 60,
    "days": 1440,
    "weeks": 10080,
}


def _promo_automacao_path(client_id: str) -> str:
    return os.path.join(get_tenant_path(str(client_id or "default")), "promo_automacao_api.json")


def _promo_automacao_carregar(client_id: str) -> dict:
    caminho = _promo_automacao_path(client_id)
    if not os.path.exists(caminho):
        return {}
    try:
        with open(caminho, "r", encoding="utf-8") as fh:
            payload = json.load(fh)
        return payload if isinstance(payload, dict) else {}
    except Exception:
        logger.exception("[PROMO AUTO] Falha ao carregar configuracao tenant=%s", client_id)
        return {}


def _promo_automacao_salvar(client_id: str, cfg: dict) -> dict:
    payload = dict(cfg or {})
    payload["updated_at"] = time.time()
    caminho = _promo_automacao_path(client_id)
    os.makedirs(os.path.dirname(caminho), exist_ok=True)
    tmp = caminho + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=2)
    os.replace(tmp, caminho)
    return payload


def _promo_automacao_intervalo(payload: dict) -> tuple[str, int, int]:
    unit = str(payload.get("interval_unit") or payload.get("intervalUnit") or "minutes").strip().lower()
    if unit not in PROMO_AUTOMACAO_INTERVAL_UNITS:
        unit = "minutes"
    fator = PROMO_AUTOMACAO_INTERVAL_UNITS[unit]
    try:
        valor = int(round(float(str(payload.get("interval_value") or payload.get("intervalValue") or 1).replace(",", "."))))
    except Exception:
        valor = 1
    valor = max(1, valor)
    minutos = int(payload.get("interval_minutes") or payload.get("intervalMinutes") or 0)
    if minutos <= 0:
        minutos = max(1, valor * fator)
    minutos = max(1, min(minutos, 12 * 10080))
    return unit, valor, minutos


def _promo_automacao_sanitizar(payload: dict) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    unit, valor, minutos = _promo_automacao_intervalo(payload)
    promos = payload.get("promocoes_b_meta") or payload.get("promocoesBMeta") or []
    promos_out = []
    if isinstance(promos, list):
        for meta in promos:
            if not isinstance(meta, dict):
                continue
            promo_id = str(meta.get("promo_b_id") or meta.get("value") or meta.get("id") or "").strip()
            if not promo_id:
                continue
            promo_type = str(meta.get("promo_b_type") or meta.get("promoType") or meta.get("promotion_type") or "").strip()
            if promo_type in {"-", "None", "null"}:
                promo_type = ""
            promos_out.append({
                "promo_b_id": promo_id,
                "promo_b_type": promo_type,
                "promo_texto": str(meta.get("promo_texto") or meta.get("text") or meta.get("displayText") or promo_id).strip(),
                "active_count": _promo_meta_contagem(meta, "active_count", "activeCount", "active", "ativos"),
                "eligible_count": _promo_meta_contagem(meta, "eligible_count", "eligibleCount", "eligible", "elegiveis"),
            })
    next_raw = _parse_float_flex(payload.get("next_run_at") or payload.get("nextRunAt"))
    return {
        "enabled": bool(payload.get("enabled")),
        "approval_required": payload.get("approval_required", payload.get("approvalRequired", True)) is not False,
        "interval_unit": unit,
        "interval_value": valor,
        "interval_minutes": minutos,
        "next_run_at": float(next_raw or 0),
        "loja": str(payload.get("loja") or "").strip(),
        "promocao_a_id": str(payload.get("promocao_a_id") or payload.get("promocaoAId") or "").strip(),
        "promocao_a_type": str(payload.get("promocao_a_type") or payload.get("promocaoAType") or "").strip(),
        "margem_minima": _parse_float_flex(payload.get("margem_minima") or payload.get("margemMinima")) or 15.0,
        "promocoes_b_meta": promos_out,
    }


def _promo_automacao_public_payload(client_id: str, cfg: dict) -> dict:
    due_flag = bool((cfg or {}).get("due"))
    cfg = _promo_automacao_sanitizar({**(cfg or {}), "enabled": bool((cfg or {}).get("enabled"))})
    bruto = _promo_automacao_carregar(client_id)
    merged = {**bruto, **cfg}
    return {
        "success": True,
        "config": {
            **cfg,
            "next_run_at": float(merged.get("next_run_at") or 0),
            "last_job_id": str(merged.get("last_job_id") or ""),
            "last_job_status": str(merged.get("last_job_status") or ""),
            "last_job_message": str(merged.get("last_job_message") or ""),
            "last_run_at": float(merged.get("last_run_at") or 0),
            "last_completed_at": float(merged.get("last_completed_at") or 0),
            "last_error": str(merged.get("last_error") or ""),
            "last_apply_result": merged.get("last_apply_result") if isinstance(merged.get("last_apply_result"), dict) else None,
            "due": due_flag or bool(merged.get("due")),
            "updated_at": float(merged.get("updated_at") or 0),
        },
        "server_time": time.time(),
    }


def _promo_start_api_worker_job(
    *,
    client_id: str,
    loja: str,
    promocao_a_id: str,
    promocao_a_type: str = "",
    margem_minima: float = 15.0,
    promocoes_b_meta: str = "[]",
) -> dict:
    if not _ensure_promo_worker_running():
        raise HTTPException(status_code=503, detail="Worker dedicado de promocoes indisponivel.")

    data = {
        "loja": loja,
        "promocao_a_id": promocao_a_id,
        "promocao_a_type": promocao_a_type or "",
        "margem_minima": str(margem_minima),
        "promocoes_b_meta": promocoes_b_meta,
        "client_id": client_id,
    }
    try:
        resp = requests.post(
            f"{PROMO_WORKER_URL}/api/promo/jobs/start-api",
            data=data,
            timeout=60,
        )
        payload = _safe_json_response(resp)
    except Exception as e:
        logger.exception("[PROMO WORKER] Falha ao encaminhar job API")
        raise HTTPException(status_code=503, detail=f"Falha ao acionar worker dedicado: {e}")

    if not resp.ok:
        detalhe = payload.get("detail") or payload.get("error") or resp.reason or "Falha no worker dedicado de promocoes."
        raise HTTPException(status_code=resp.status_code, detail=f"Worker promocoes respondeu HTTP {resp.status_code}: {detalhe}")
    return payload


def _promo_consultar_worker_job(job_id: str, client_id: str) -> dict:
    if not job_id:
        return {}
    if not _ensure_promo_worker_running():
        return {}
    try:
        resp = requests.get(
            f"{PROMO_WORKER_URL}/api/promo/jobs/{job_id}",
            params={"client_id": client_id},
            timeout=20,
        )
        payload = _safe_json_response(resp)
        return payload if resp.ok and isinstance(payload, dict) else {}
    except Exception:
        logger.exception("[PROMO AUTO] Falha ao consultar job %s", job_id)
        return {}


def _promo_automacao_linha_valor(row: dict, aliases: list[str]) -> Any:
    aliases_norm = {_normalizar_coluna_exportacao(alias) for alias in aliases}
    for chave, valor in (row or {}).items():
        if _normalizar_coluna_exportacao(chave) in aliases_norm:
            return valor
    return ""


def _promo_automacao_montar_participacoes(resultado: dict, loja: str) -> dict:
    analises = resultado.get("analises") if isinstance(resultado, dict) else []
    if not isinstance(analises, list) or not analises:
        analises = [{
            "promo_b_id": resultado.get("promocao_b_id") or "",
            "promo_b_type": "",
            "promo_b_nome": "Promocao analisada",
            "data": resultado.get("data") if isinstance(resultado, dict) else [],
        }]
    promocoes = []
    for idx, analise in enumerate(analises):
        if not isinstance(analise, dict):
            continue
        promotion_id = str(analise.get("promo_b_id") or analise.get("promotion_id") or "").strip()
        promotion_type = str(analise.get("promo_b_type") or analise.get("promotion_type") or "").strip()
        nome = str(analise.get("promo_b_nome") or analise.get("tab_label") or f"Promocao {idx + 1}").strip()
        rows = analise.get("data") if isinstance(analise.get("data"), list) else []
        items = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            decisao = _normalizar_decisao_planilha(
                _promo_automacao_linha_valor(row, ["AÃ§Ã£o", "Acao", "Participar ou nÃ£o", "Participar ou nao"])
            )
            if decisao != "Participar":
                continue
            item_id = _promo_normalizar_mlb(_promo_automacao_linha_valor(row, ["MLB", "mlb", "Item ID", "item_id", "AnÃºncio", "Anuncio"]))
            if not item_id:
                continue
            items.append({
                "item_id": item_id,
                "deal_price": _parse_float_flex(_promo_automacao_linha_valor(row, ["deal_price", "preco_promocional_ml", "PreÃ§o Promocional ML", "Preco Promocional ML", "PreÃ§o Final ML", "Preco Final ML", "PreÃ§o Final PromoÃ§Ã£o 2", "Preco Final Promocao 2"])),
                "discount_percentage": _parse_float_flex(_promo_automacao_linha_valor(row, ["ML % Campanha", "% Fixa", "Desconto ML %", "discount_percentage", "percentual"])),
                "sku": str(_promo_automacao_linha_valor(row, ["SKU", "sku"]) or "").strip(),
                "titulo": str(_promo_automacao_linha_valor(row, ["TÃ­tulo", "Titulo", "title"]) or "").strip(),
            })
        if promotion_id and items:
            promocoes.append({
                "promotion_id": promotion_id,
                "promotion_type": promotion_type,
                "nome": nome,
                "items": items,
            })
    return {"loja": loja, "promocoes": promocoes}


def _promo_automacao_refresh_job_state(client_id: str, cfg: dict, *, aplicar: bool = False) -> tuple[dict, bool]:
    job_id = str((cfg or {}).get("last_job_id") or "").strip()
    if not job_id:
        return cfg, False
    payload = _promo_consultar_worker_job(job_id, client_id)
    if not payload:
        return cfg, False
    status = str(payload.get("status") or "").lower()
    mudou = False
    if status:
        cfg["last_job_status"] = status
        cfg["last_job_message"] = str(payload.get("message") or "")
        cfg["last_job_progress"] = int(payload.get("progress") or 0)
        mudou = True
    if status == "completed":
        cfg["last_completed_at"] = float(payload.get("updated_at") or time.time())
        cfg["last_error"] = ""
        if aplicar and not bool(cfg.get("approval_required")) and cfg.get("last_applied_job_id") != job_id:
            try:
                result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
                participacoes = _promo_automacao_montar_participacoes(result, str(cfg.get("loja") or ""))
                total = sum(len(p.get("items") or []) for p in participacoes.get("promocoes", []))
                if total > 0:
                    apply_result = aplicar_participacoes_promocoes(
                        PromoAplicarParticipacaoRequest(**participacoes),
                        client_id=client_id,
                    )
                    cfg["last_apply_result"] = apply_result
                else:
                    cfg["last_apply_result"] = {"success": True, "message": "Nenhum item com acao Participar."}
                cfg["last_applied_job_id"] = job_id
                mudou = True
            except Exception as exc:
                logger.exception("[PROMO AUTO] Falha ao aplicar participacoes tenant=%s job=%s", client_id, job_id)
                cfg["last_error"] = str(getattr(exc, "detail", None) or exc)
                mudou = True
    elif status in {"error", "canceled", "cancelled"}:
        cfg["last_error"] = str(payload.get("error") or payload.get("message") or "")
        mudou = True
    return cfg, mudou


def _promo_automacao_config_pronta(cfg: dict) -> bool:
    return bool(
        cfg.get("enabled")
        and str(cfg.get("loja") or "").strip()
        and str(cfg.get("promocao_a_id") or "").strip()
        and isinstance(cfg.get("promocoes_b_meta"), list)
        and len(cfg.get("promocoes_b_meta") or []) > 0
    )


def _promo_automacao_processar_tenant(client_id: str) -> None:
    with PROMO_AUTOMACAO_LOCK:
        cfg = _promo_automacao_carregar(client_id)
        if not cfg:
            return
        cfg = {**cfg, **_promo_automacao_sanitizar(cfg)}
        cfg, mudou = _promo_automacao_refresh_job_state(client_id, cfg, aplicar=True)
        status_atual = str(cfg.get("last_job_status") or "").lower()
        if status_atual in {"queued", "running"}:
            if mudou:
                _promo_automacao_salvar(client_id, cfg)
            return
        if not _promo_automacao_config_pronta(cfg):
            if mudou:
                _promo_automacao_salvar(client_id, cfg)
            return
        agora = time.time()
        next_run_at = float(cfg.get("next_run_at") or 0)
        if next_run_at <= 0:
            cfg["next_run_at"] = agora + int(cfg.get("interval_minutes") or 60) * 60
            _promo_automacao_salvar(client_id, cfg)
            return
        if next_run_at > agora:
            if mudou:
                _promo_automacao_salvar(client_id, cfg)
            return
        chave_execucao = str(client_id)
        if chave_execucao in PROMO_AUTOMACAO_RUNNING:
            return
        PROMO_AUTOMACAO_RUNNING.add(chave_execucao)
    try:
        logger.info("[PROMO AUTO] Iniciando analise automatica tenant=%s loja=%s", client_id, cfg.get("loja"))
        payload = _promo_start_api_worker_job(
            client_id=client_id,
            loja=str(cfg.get("loja") or ""),
            promocao_a_id=str(cfg.get("promocao_a_id") or ""),
            promocao_a_type=str(cfg.get("promocao_a_type") or ""),
            margem_minima=float(cfg.get("margem_minima") or 15.0),
            promocoes_b_meta=json.dumps(cfg.get("promocoes_b_meta") or [], ensure_ascii=False),
        )
        cfg["last_job_id"] = str(payload.get("job_id") or "")
        cfg["last_job_status"] = str(payload.get("status") or "queued")
        cfg["last_job_message"] = str(payload.get("message") or "Analise automatica iniciada pelo servidor.")
        cfg["last_run_at"] = time.time()
        cfg["last_error"] = ""
        cfg["next_run_at"] = time.time() + int(cfg.get("interval_minutes") or 60) * 60
    except Exception as exc:
        logger.exception("[PROMO AUTO] Falha ao iniciar analise automatica tenant=%s", client_id)
        cfg["last_error"] = str(getattr(exc, "detail", None) or exc)
        cfg["last_job_status"] = "error"
        cfg["next_run_at"] = time.time() + min(int(cfg.get("interval_minutes") or 60) * 60, 15 * 60)
    finally:
        with PROMO_AUTOMACAO_LOCK:
            PROMO_AUTOMACAO_RUNNING.discard(str(client_id))
            _promo_automacao_salvar(client_id, cfg)


def _promo_automacao_tenants() -> list[str]:
    tenants = []
    try:
        for nome in os.listdir(PASTA_INFO):
            pasta = os.path.join(PASTA_INFO, nome)
            if os.path.isdir(pasta) and os.path.exists(os.path.join(pasta, "promo_automacao_api.json")):
                tenants.append(nome)
    except Exception as exc:
        logger.warning("[PROMO AUTO] Falha ao listar tenants: %s", exc)
    return tenants


def _promo_automacao_worker() -> None:
    time.sleep(6)
    while True:
        for client_id in _promo_automacao_tenants():
            try:
                _promo_automacao_processar_tenant(client_id)
            except Exception:
                logger.exception("[PROMO AUTO] Falha inesperada tenant=%s", client_id)
        time.sleep(30)


@app.on_event("startup")
def _promo_automacao_iniciar_background():
    global PROMO_AUTOMACAO_THREAD_STARTED
    with PROMO_AUTOMACAO_LOCK:
        if PROMO_AUTOMACAO_THREAD_STARTED:
            return
        PROMO_AUTOMACAO_THREAD_STARTED = True
    threading.Thread(
        target=_promo_automacao_worker,
        name="promo-automacao-servidor",
        daemon=True,
    ).start()


