@app.post("/api/promo/analise-via-api-arquivos/start")
async def iniciar_analise_promo_via_api_com_arquivos(
    loja: str = Form(...),
    promocao_a_id: str = Form(...),
    promocao_a_type: str = Form(""),
    margem_minima: float = Form(15.0),
    promocoes_b_meta: str = Form(...),
    files: list[UploadFile] = File(...),
    client_id: str = Depends(get_tenant_id),
):
    if not files:
        raise HTTPException(status_code=400, detail="Envie os arquivos das Promocoes 2.")
    if not _ensure_promo_worker_running():
        raise HTTPException(status_code=503, detail="Worker dedicado de promocoes indisponivel.")

    data = {
        "loja": loja,
        "promocao_a_id": promocao_a_id,
        "promocao_a_type": promocao_a_type,
        "margem_minima": str(margem_minima),
        "promocoes_b_meta": promocoes_b_meta,
        "client_id": client_id,
    }
    files_payload = []
    try:
        for upload in files:
            filename = str(getattr(upload, "filename", "") or "").strip()
            if not filename:
                continue
            content = await upload.read()
            files_payload.append(("files", (filename, content, upload.content_type or "application/octet-stream")))
        if not files_payload:
            raise HTTPException(status_code=400, detail="Nenhum arquivo valido foi enviado.")

        resp = await asyncio.to_thread(
            requests.post,
            f"{PROMO_WORKER_URL}/api/promo/jobs/start",
            data=data,
            files=files_payload,
            timeout=90,
        )
        payload = _safe_json_response(resp)
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("[PROMO WORKER] Falha ao encaminhar job")
        raise HTTPException(status_code=503, detail=f"Falha ao acionar worker dedicado: {e}")

    if not resp.ok:
        detalhe = payload.get("detail") or payload.get("error") or resp.reason or "Falha no worker dedicado de promocoes."
        raise HTTPException(status_code=resp.status_code, detail=f"Worker promocoes respondeu HTTP {resp.status_code}: {detalhe}")
    try:
        _salvar_arquivos_originais_promo_job(client_id, str(payload.get("job_id") or ""), files_payload)
    except Exception:
        logger.exception("[PROMO EXPORT] Falha ao persistir arquivos originais para exportaÃƒÂ§ÃƒÂ£o")
    return payload


@app.get("/api/promo/analise-via-api-arquivos/progresso/{job_id}")
async def progresso_analise_promo_via_api_com_arquivos(job_id: str, client_id: str = Depends(get_tenant_id)):
    if not _ensure_promo_worker_running():
        raise HTTPException(status_code=503, detail="Worker dedicado de promocoes indisponivel.")
    payload = {}
    ultimo_erro = None
    resp = None
    for tentativa in range(1, 4):
        try:
            resp = await asyncio.to_thread(
                requests.get,
                f"{PROMO_WORKER_URL}/api/promo/jobs/{job_id}",
                params={"client_id": client_id},
                timeout=45,
            )
            payload = _safe_json_response(resp)
            if resp.status_code >= 500 and tentativa < 3:
                await asyncio.sleep(0.7 * tentativa)
                continue
            break
        except Exception as e:
            ultimo_erro = e
            if tentativa < 3:
                await asyncio.sleep(0.7 * tentativa)
                continue
            logger.exception("[PROMO WORKER] Falha ao consultar job %s", job_id)
            raise HTTPException(status_code=503, detail=f"Falha ao consultar worker dedicado: {e}")
    if resp is None:
        raise HTTPException(status_code=503, detail=f"Falha ao consultar worker dedicado: {ultimo_erro or 'sem resposta'}")
    if not resp.ok:
        detalhe = payload.get("detail") or payload.get("error") or resp.reason or "Falha ao consultar job no worker dedicado."
        raise HTTPException(status_code=resp.status_code, detail=f"Worker promocoes respondeu HTTP {resp.status_code}: {detalhe}")
    return payload


@app.post("/api/promo/analise-via-api-arquivos/cancelar/{job_id}")
async def cancelar_analise_promo_via_api_com_arquivos(job_id: str, client_id: str = Depends(get_tenant_id)):
    if not _ensure_promo_worker_running():
        raise HTTPException(status_code=503, detail="Worker dedicado de promocoes indisponivel.")
    try:
        resp = await asyncio.to_thread(
            requests.post,
            f"{PROMO_WORKER_URL}/api/promo/jobs/{job_id}/cancel",
            params={"client_id": client_id},
            timeout=20,
        )
        payload = _safe_json_response(resp)
    except Exception as e:
        logger.exception("[PROMO WORKER] Falha ao cancelar job %s", job_id)
        raise HTTPException(status_code=503, detail=f"Falha ao cancelar worker dedicado: {e}")
    if not resp.ok:
        detalhe = payload.get("detail") or payload.get("error") or resp.reason or "Falha ao cancelar job no worker dedicado."
        raise HTTPException(status_code=resp.status_code, detail=f"Worker promocoes respondeu HTTP {resp.status_code}: {detalhe}")
    return payload


@app.get("/api/promo/automacao")
def promo_automacao_obter(client_id: str = Depends(get_tenant_id)):
    deve_processar = False
    with PROMO_AUTOMACAO_LOCK:
        cfg = _promo_automacao_carregar(client_id)
        if cfg:
            cfg = {**cfg, **_promo_automacao_sanitizar(cfg)}
            cfg, mudou = _promo_automacao_refresh_job_state(client_id, cfg, aplicar=False)
            if cfg.get("enabled") and _promo_automacao_config_pronta(cfg) and float(cfg.get("next_run_at") or 0) <= time.time():
                # A tela nao reinicia o tempo; se venceu, quem dispara e o verificador do servidor.
                cfg["due"] = True
                deve_processar = True
            if mudou:
                _promo_automacao_salvar(client_id, cfg)
    if deve_processar:
        threading.Thread(
            target=_promo_automacao_processar_tenant,
            args=(client_id,),
            name=f"promo-automacao-on-demand-{client_id}",
            daemon=True,
        ).start()
    return _promo_automacao_public_payload(client_id, cfg or {})


@app.put("/api/promo/automacao")
def promo_automacao_salvar(req: PromoAutomacaoConfigRequest, client_id: str = Depends(get_tenant_id)):
    entrada = req.dict()
    with PROMO_AUTOMACAO_LOCK:
        anterior = _promo_automacao_carregar(client_id)
        cfg = _promo_automacao_sanitizar(entrada)
        agora = time.time()
        old_next = float(anterior.get("next_run_at") or 0)
        old_interval = int(anterior.get("interval_minutes") or 0)
        requested_next = float(cfg.get("next_run_at") or 0)
        if cfg.get("enabled"):
            if bool(anterior.get("enabled")) and old_next > 0 and old_interval == int(cfg.get("interval_minutes") or 0):
                cfg["next_run_at"] = old_next
            elif requested_next > agora:
                cfg["next_run_at"] = requested_next
            else:
                cfg["next_run_at"] = agora + int(cfg.get("interval_minutes") or 60) * 60
        else:
            cfg["next_run_at"] = 0

        for key in (
            "last_job_id",
            "last_job_status",
            "last_job_message",
            "last_job_progress",
            "last_run_at",
            "last_completed_at",
            "last_error",
            "last_applied_job_id",
            "last_apply_result",
        ):
            if key in anterior:
                cfg[key] = anterior.get(key)

        cfg = _promo_automacao_salvar(client_id, cfg)

    return _promo_automacao_public_payload(client_id, cfg)


def _promo_aplicar_item_participacao_ml(
    client_id: str,
    loja: str,
    cfg: dict,
    *,
    item_id: str,
    promotion_id: str,
    promotion_type: str,
    offer_id: Optional[str] = None,
    deal_price: Optional[float] = None,
    discount_percentage: Optional[float] = None,
) -> tuple[bool, str, dict]:
    item_id = _promo_normalizar_mlb(item_id)
    promotion_id = str(promotion_id or "").strip()
    promotion_type = str(promotion_type or "").strip()
    if not promotion_type:
        promotion_type = "SMART" if promotion_id.upper().startswith("P-") else "SELLER_CAMPAIGN"
    if not item_id or not promotion_id:
        return False, "MLB ou promocao ausente", cfg

    def _extrair_numero_campo_promocao(valor) -> Optional[float]:
        if isinstance(valor, dict):
            for chave in (
                "amount",
                "value",
                "price",
                "deal_price",
                "suggested_discounted_price",
                "suggested_price",
                "min_discounted_price",
                "minimum_discounted_price",
                "min_deal_price",
            ):
                numero = _parse_float_flex(valor.get(chave))
                if numero is not None:
                    return numero
            return None
        return _parse_float_flex(valor)

    def _coletar_precos_fallback_credibilidade(raw_entry: dict, preco_referencia: Optional[float] = None) -> list[float]:
        if not isinstance(raw_entry, dict):
            return []
        prioridades = {
            "suggested_discounted_price": 0,
            "suggested_price": 1,
            "suggested_deal_price": 1,
            "recommended_discounted_price": 2,
            "recommended_price": 2,
            "min_discounted_price": 3,
            "minimum_discounted_price": 3,
            "min_deal_price": 3,
            "minimum_deal_price": 3,
            "deal_price": 4,
            "final_price": 4,
            "campaign_price": 4,
            "price": 5,
        }
        encontrados = []

        def _registrar(chave: str, valor):
            chave_norm = str(chave or "").strip().lower()
            if chave_norm not in prioridades:
                return
            numero = _extrair_numero_campo_promocao(valor)
            if numero is None or numero <= 0:
                return
            encontrados.append((prioridades[chave_norm], round(float(numero), 2), chave_norm))

        for chave, valor in raw_entry.items():
            _registrar(chave, valor)
        for caminho, valor in _ml_iterar_campos_payload_limitado(raw_entry, max_depth=7, max_nodes=3500):
            ultimo_campo = str(caminho or "").rsplit(".", 1)[-1].strip().lower()
            _registrar(ultimo_campo, valor)

        if not encontrados:
            return []
        referencia = _parse_float_flex(preco_referencia)
        vistos = set()
        ordenados = sorted(
            encontrados,
            key=lambda item: (
                item[0],
                abs(item[1] - float(referencia)) if referencia is not None else 0.0,
            ),
        )
        retorno = []
        for _prioridade, preco, _chave in ordenados:
            if preco <= 0:
                continue
            if preco in vistos:
                continue
            vistos.add(preco)
            retorno.append(preco)
        return retorno

    def _erro_credibilidade(texto_erro: str) -> bool:
        erro_norm = normalizar_texto(texto_erro or "")
        if not erro_norm:
            return False
        return (
            "error_credibility_discounted_price" in erro_norm
            or "error_credibility_price" in erro_norm
            or ("discounted price" in erro_norm and "credible" in erro_norm)
            or ("credibility" in erro_norm and "price" in erro_norm)
        )

    def _extrair_offer_id_promocao(raw_entry: dict) -> str:
        return _ml_promocao_raw_offer_id(raw_entry)

    def _erro_payload_ml(resp) -> str:
        try:
            data = resp.json() or {}
        except Exception:
            return ""
        if not isinstance(data, dict):
            return ""

        mensagens = []
        erros = data.get("errors")
        if isinstance(erros, list):
            for erro in erros[:5]:
                if isinstance(erro, dict):
                    mensagens.append(str(erro.get("error") or erro.get("message") or erro.get("cause") or erro))
                else:
                    mensagens.append(str(erro))

        for lista in (data.get("successful_ids"), data.get("results")):
            if not isinstance(lista, list):
                continue
            for item in lista[:8]:
                if isinstance(item, dict) and item.get("error"):
                    mensagens.append(str(item.get("error")))

        if mensagens:
            return " | ".join([m for m in mensagens if m][:5])
        return ""

    base_payload = {
        "promotion_id": promotion_id,
        "promotion_type": promotion_type,
    }
    promotion_type_upper = promotion_type.upper().strip()
    deal_price_num = _parse_float_flex(deal_price)
    discount_num = _parse_float_flex(discount_percentage)
    offer_id_texto = str(offer_id or "").strip()
    tipos_exigem_offer_id = {"SMART", "PRICE_MATCHING", "PRICE_MATCHING_MELI_ALL"}
    payloads = []
    payloads_vistos = set()

    def _adicionar_payload(payload: dict):
        if not isinstance(payload, dict):
            return
        assinatura = json.dumps(payload, ensure_ascii=True, sort_keys=True)
        if assinatura in payloads_vistos:
            return
        payloads_vistos.add(assinatura)
        payloads.append(payload)

    if promotion_type_upper in tipos_exigem_offer_id:
        raw_item_promocao = {}
        if not offer_id_texto:
            try:
                raw_item_promocao, cfg = _ml_obter_item_promocao_raw(
                    client_id,
                    loja,
                    cfg,
                    promotion_id,
                    promotion_type,
                    item_id,
                )
            except Exception:
                raw_item_promocao = {}
            offer_id_texto = _extrair_offer_id_promocao(raw_item_promocao)
        if not offer_id_texto:
            return (
                False,
                (
                    f"Campanha {promotion_type_upper} exige offer_id do convite/candidato, "
                    "mas o Mercado Livre nao retornou esse identificador para o item."
                ),
                cfg,
            )
        _adicionar_payload({**base_payload, "offer_id": offer_id_texto})
    # Em campanhas do vendedor com percentual fixo, o percentual ja foi usado para
    # calcular o preco cheio. Na adesao do item, a API espera o preco final
    # promocional (deal_price). Enviar fallbacks sem preco depois disso pode fazer
    # o ML recalcular a oferta de forma incorreta e rejeitar com FINAL_PRICE_*.
    elif deal_price_num is not None and deal_price_num > 0:
        _adicionar_payload({**base_payload, "deal_price": round(float(deal_price_num), 2)})
    elif discount_num is not None and discount_num > 0:
        _adicionar_payload({**base_payload, "discount_percentage": round(float(discount_num), 4)})
    elif promotion_type_upper not in {"SELLER_CAMPAIGN", "SELLER_COUPON_CAMPAIGN"}:
        _adicionar_payload(base_payload)

    if not payloads:
        return False, "Preco promocional ausente para aplicar a campanha.", cfg

    ultimo_erro = ""
    raw_credibilidade = None
    idx_payload = 0
    while idx_payload < len(payloads):
        payload = payloads[idx_payload]
        idx_payload += 1
        url_item_promocao = f"https://api.mercadolibre.com/seller-promotions/items/{item_id}"
        params_promocao = {"app_version": "v2"}
        resp, cfg = _ml_api_request(
            client_id,
            loja,
            cfg,
            "POST",
            url_item_promocao,
            params=params_promocao,
            json=payload,
            timeout=20,
        )
        if resp.status_code in (200, 201):
            erro_payload = _erro_payload_ml(resp)
            if erro_payload:
                ultimo_erro = f"Mercado Livre respondeu {resp.status_code}, mas recusou a promocao: {erro_payload}"
                continue
            return True, "", cfg
        erro = _ml_parse_error_detail(resp, f"Erro {resp.status_code} ao incluir item")
        erro_payload = _erro_payload_ml(resp)
        erro_completo = f"{erro} | {erro_payload}" if erro_payload else erro
        erro_norm = normalizar_texto(erro_completo)
        if _promo_erro_candidate_not_found(erro_completo):
            return (
                False,
                (
                    "CANDIDATE_NOT_FOUND: o Mercado Livre informou que este MLB nao esta como "
                    "candidate/elegivel para essa campanha."
                ),
                cfg,
            )
        if "already" in erro_norm or ("ja" in erro_norm and "promoc" in erro_norm):
            edit_resp, cfg = _ml_api_request(
                client_id,
                loja,
                cfg,
                "PUT",
                url_item_promocao,
                params=params_promocao,
                json=payload,
                timeout=20,
            )
            if edit_resp.status_code in (200, 201):
                erro_payload = _erro_payload_ml(edit_resp)
                if erro_payload:
                    ultimo_erro = f"Mercado Livre respondeu {edit_resp.status_code}, mas nao atualizou a promocao: {erro_payload}"
                    continue
                return True, "Participacao existente atualizada", cfg
            ultimo_erro = _ml_parse_error_detail(edit_resp, f"Erro {edit_resp.status_code} ao atualizar item na promocao")
            continue
        if _erro_credibilidade(erro_completo):
            if raw_credibilidade is None:
                try:
                    raw_credibilidade, cfg = _ml_obter_item_promocao_raw(
                        client_id,
                        loja,
                        cfg,
                        promotion_id,
                        promotion_type,
                        item_id,
                    )
                except Exception:
                    raw_credibilidade = {}
            precos_fallback = _coletar_precos_fallback_credibilidade(
                raw_credibilidade or {},
                preco_referencia=deal_price_num,
            )
            for preco_alt in precos_fallback:
                _adicionar_payload({**base_payload, "deal_price": round(float(preco_alt), 2)})
            if discount_num is not None and discount_num > 0:
                _adicionar_payload({**base_payload, "discount_percentage": round(float(discount_num), 4)})
            if idx_payload < len(payloads):
                ultimo_erro = (
                    "Mercado Livre rejeitou o preco promocional por credibilidade e o sistema tentou valor sugerido/fallback automaticamente."
                )
                continue
        ultimo_erro = erro_completo
    return False, ultimo_erro or "Mercado Livre nao aceitou a inclusao do item", cfg


def _aplicar_participacoes_promocoes_payload(
    req: PromoAplicarParticipacaoRequest,
    client_id: str,
    progress_callback: Optional[Callable[[dict], None]] = None,
) -> dict:
    loja = str(req.loja or "").strip()
    if not loja:
        raise HTTPException(status_code=400, detail="Informe a loja.")
    promocoes = req.promocoes if isinstance(req.promocoes, list) else []
    if not promocoes:
        raise HTTPException(status_code=400, detail="Nenhuma promocao enviada para aplicar.")

    cfg = _obter_cfg_ml(client_id, loja)
    resumo = []
    detalhes = []
    total_sucesso = 0
    total_falha = 0
    total_ignorados = 0
    total_itens = sum(
        len(grupo.get("items") or [])
        for grupo in promocoes
        if isinstance(grupo, dict) and isinstance(grupo.get("items"), list)
    )
    processados = 0

    def _notificar(mensagem: str):
        if not progress_callback:
            return
        progresso = 5
        if total_itens > 0:
            progresso = min(98, max(5, int((processados / total_itens) * 93) + 5))
        try:
            progress_callback({
                "progress": progresso,
                "message": mensagem,
                "processed": processados,
                "total": total_itens,
                "total_sucesso": total_sucesso,
                "total_falha": total_falha,
                "total_ignorados": total_ignorados,
            })
        except Exception:
            logger.exception("[PROMO APPLY] Falha ao atualizar progresso")

    _notificar(f"Iniciando entrada em {total_itens} anuncio(s) nas promocoes...")

    for grupo in promocoes:
        if not isinstance(grupo, dict):
            continue
        promotion_id = str(grupo.get("promotion_id") or grupo.get("promo_b_id") or grupo.get("id") or "").strip()
        promotion_type = str(grupo.get("promotion_type") or grupo.get("promo_b_type") or "").strip()
        nome = str(grupo.get("nome") or grupo.get("name") or grupo.get("promo_b_nome") or promotion_id).strip()
        items = grupo.get("items") if isinstance(grupo.get("items"), list) else []
        promo_resumo = {
            "promotion_id": promotion_id,
            "promotion_type": promotion_type,
            "nome": nome,
            "sucesso": 0,
            "falhas": 0,
            "ignorados": 0,
            "erros": [],
        }
        if not promotion_id:
            promo_resumo["falhas"] = len(items)
            promo_resumo["erros"].append("Promocao sem ID.")
            total_falha += len(items)
            processados += len(items)
            _notificar(f"Promocao sem ID ignorada ({processados}/{total_itens}).")
            resumo.append(promo_resumo)
            continue
        for item in items:
            if not isinstance(item, dict):
                total_ignorados += 1
                promo_resumo["ignorados"] += 1
                processados += 1
                _notificar(f"Item invalido ignorado ({processados}/{total_itens}).")
                continue
            item_id = _promo_normalizar_mlb(item.get("item_id") or item.get("mlb") or item.get("MLB"))
            offer_id = str(
                item.get("offer_id")
                or item.get("offerId")
                or item.get("ref_id")
                or item.get("refId")
                or ""
            ).strip()
            deal_price = _parse_float_flex(item.get("deal_price") or item.get("preco_final_ml") or item.get("price"))
            discount_percentage = _parse_float_flex(item.get("discount_percentage") or item.get("percentual") or item.get("ml_pct"))
            if not item_id:
                total_ignorados += 1
                promo_resumo["ignorados"] += 1
                processados += 1
                _notificar(f"Item sem MLB ignorado ({processados}/{total_itens}).")
                continue
            elegibilidade, cfg = _promo_consultar_item_na_campanha(
                client_id,
                loja,
                cfg,
                promotion_id,
                promotion_type,
                item_id,
            )
            if elegibilidade.get("success") and elegibilidade.get("found"):
                if elegibilidade.get("already_participating"):
                    total_ignorados += 1
                    promo_resumo["ignorados"] += 1
                    processados += 1
                    status_atual = elegibilidade.get("status") or "started"
                    if len(promo_resumo["erros"]) < 8:
                        promo_resumo["erros"].append(f"{item_id}: ja esta na campanha ({status_atual}).")
                    if len(detalhes) < 300:
                        detalhes.append({
                            "item_id": item_id,
                            "promotion_id": promotion_id,
                            "promotion_type": promotion_type,
                            "success": True,
                            "ignored": True,
                            "status": status_atual,
                            "message": "Item ja esta participando ou pendente na campanha.",
                        })
                    _notificar(f"{item_id} ja esta na campanha; ignorado ({processados}/{total_itens}).")
                    continue
                if not elegibilidade.get("can_participate"):
                    total_ignorados += 1
                    promo_resumo["ignorados"] += 1
                    processados += 1
                    status_atual = elegibilidade.get("status") or "-"
                    if len(promo_resumo["erros"]) < 8:
                        promo_resumo["erros"].append(f"{item_id}: status {status_atual}; nao esta candidate.")
                    if len(detalhes) < 300:
                        detalhes.append({
                            "item_id": item_id,
                            "promotion_id": promotion_id,
                            "promotion_type": promotion_type,
                            "success": True,
                            "ignored": True,
                            "status": status_atual,
                            "message": "Item nao esta com status candidate para essa campanha.",
                        })
                    _notificar(f"{item_id} nao esta candidate; ignorado ({processados}/{total_itens}).")
                    continue
            elif elegibilidade.get("success") and not elegibilidade.get("found"):
                total_ignorados += 1
                promo_resumo["ignorados"] += 1
                processados += 1
                detalhe = str(elegibilidade.get("detail") or "Nao elegivel para essa campanha.")
                if len(promo_resumo["erros"]) < 8:
                    promo_resumo["erros"].append(f"{item_id}: nao elegivel/candidate nesta campanha.")
                if len(detalhes) < 300:
                    detalhes.append({
                        "item_id": item_id,
                        "promotion_id": promotion_id,
                        "promotion_type": promotion_type,
                        "success": True,
                        "ignored": True,
                        "status": "not_candidate",
                        "message": detalhe,
                    })
                _notificar(f"{item_id} nao e candidato da campanha; ignorado ({processados}/{total_itens}).")
                continue
            ok, erro, cfg = _promo_aplicar_item_participacao_ml(
                client_id,
                loja,
                cfg,
                item_id=item_id,
                promotion_id=promotion_id,
                promotion_type=promotion_type,
                offer_id=offer_id,
                deal_price=deal_price,
                discount_percentage=discount_percentage,
            )
            if ok:
                total_sucesso += 1
                promo_resumo["sucesso"] += 1
            else:
                if _promo_erro_candidate_not_found(erro):
                    total_ignorados += 1
                    promo_resumo["ignorados"] += 1
                    if len(promo_resumo["erros"]) < 8:
                        promo_resumo["erros"].append(f"{item_id}: nao elegivel/candidate nesta campanha.")
                    if len(detalhes) < 300:
                        detalhes.append({
                            "item_id": item_id,
                            "promotion_id": promotion_id,
                            "promotion_type": promotion_type,
                            "success": True,
                            "ignored": True,
                            "status": "candidate_not_found",
                            "message": erro,
                        })
                    processados += 1
                    _notificar(f"{item_id} nao e candidato da campanha; ignorado ({processados}/{total_itens}).")
                    continue
                total_falha += 1
                promo_resumo["falhas"] += 1
                if len(promo_resumo["erros"]) < 8:
                    promo_resumo["erros"].append(f"{item_id}: {erro}")
                if len(detalhes) < 300:
                    detalhes.append({
                        "item_id": item_id,
                        "promotion_id": promotion_id,
                        "promotion_type": promotion_type,
                        "success": False,
                        "error": erro,
                    })
            processados += 1
            _notificar(f"Entrando nas promocoes: {processados}/{total_itens} anuncio(s).")
        resumo.append(promo_resumo)

    return {
        "success": total_falha == 0,
        "loja": loja,
        "total_itens": total_itens,
        "total_sucesso": total_sucesso,
        "total_falha": total_falha,
        "total_ignorados": total_ignorados,
        "detalhes": detalhes,
        "promocoes": resumo,
    }


@app.post("/api/promo/aplicar-participacoes")
def aplicar_participacoes_promocoes(req: PromoAplicarParticipacaoRequest, client_id: str = Depends(get_tenant_id)):
    return _aplicar_participacoes_promocoes_payload(req, client_id)


def _promo_aplicar_participacoes_job_worker(job_id: str, payload_req: dict, client_id: str) -> None:
    def _progress(payload: dict):
        _promo_job_set(
            job_id,
            client_id=client_id,
            status="running",
            progress=int(payload.get("progress") or 0),
            message=str(payload.get("message") or "Entrando nas promocoes..."),
            result=None,
            error="",
            stats=payload,
        )

    try:
        req = PromoAplicarParticipacaoRequest(**(payload_req or {}))
        _promo_job_set(
            job_id,
            client_id=client_id,
            status="running",
            progress=1,
            message="Preparando entrada nas promocoes...",
            result=None,
            error="",
        )
        result = _aplicar_participacoes_promocoes_payload(req, client_id, progress_callback=_progress)
        _promo_job_set(
            job_id,
            client_id=client_id,
            status="completed",
            progress=100,
            message=(
                f"Entrada concluida: {int(result.get('total_sucesso') or 0)} sucesso(s), "
                f"{int(result.get('total_falha') or 0)} falha(s), "
                f"{int(result.get('total_ignorados') or 0)} ignorado(s)."
            ),
            result=result,
            error="",
        )
    except Exception as exc:
        detalhe = str(getattr(exc, "detail", None) or exc or "Erro ao entrar nas promocoes.")
        logger.exception("[PROMO APPLY] Falha no job %s", job_id)
        _promo_job_set(
            job_id,
            client_id=client_id,
            status="error",
            progress=100,
            message=detalhe,
            result=None,
            error=detalhe,
        )


@app.post("/api/promo/aplicar-participacoes/start")
def aplicar_participacoes_promocoes_start(req: PromoAplicarParticipacaoRequest, client_id: str = Depends(get_tenant_id)):
    payload_req = req.model_dump() if hasattr(req, "model_dump") else req.dict()
    loja = str(payload_req.get("loja") or "").strip()
    promocoes = payload_req.get("promocoes") if isinstance(payload_req.get("promocoes"), list) else []
    total_itens = sum(
        len(grupo.get("items") or [])
        for grupo in promocoes
        if isinstance(grupo, dict) and isinstance(grupo.get("items"), list)
    )
    if not loja:
        raise HTTPException(status_code=400, detail="Informe a loja.")
    if total_itens <= 0:
        raise HTTPException(status_code=400, detail="Nenhuma promocao enviada para aplicar.")
    job_id = uuid.uuid4().hex
    _promo_job_set(
        job_id,
        client_id=client_id,
        status="queued",
        progress=0,
        message=f"Entrada em {total_itens} anuncio(s) enviada para segundo plano.",
        result=None,
        error="",
    )
    threading.Thread(
        target=_promo_aplicar_participacoes_job_worker,
        args=(job_id, payload_req, client_id),
        name=f"promo-apply-{job_id[:8]}",
        daemon=True,
    ).start()
    return {
        "success": True,
        "job_id": job_id,
        "status": "queued",
        "progress": 0,
        "message": f"Entrada em {total_itens} anuncio(s) enviada para segundo plano.",
    }


@app.get("/api/promo/aplicar-participacoes/jobs/{job_id}")
def aplicar_participacoes_promocoes_job(job_id: str, client_id: str = Depends(get_tenant_id)):
    job = _promo_job_get(job_id)
    if not job or job.get("client_id") != client_id:
        raise HTTPException(status_code=404, detail="Job de participacao em promocoes nao encontrado.")
    payload = dict(job)
    payload.pop("client_id", None)
    payload["success"] = True
    payload["job_id"] = job_id
    return payload


@app.get("/api/promo/analise")
async def analisar_promo_automatico(
    loja: str,
    margem_minima: float = 15.0,
    offset: int = 0,
    limit: int = 100,
    client_id: str = Depends(get_tenant_id),
):
    """
    Gera analise de promocao sem upload de planilhas,
    usando anuncios ativos do Mercado Livre + custos do cadastro local.
    """
    payload = await ml_listar_anuncios(loja=loja, offset=offset, limit=limit, client_id=client_id)
    anuncios = payload.get("results", []) if isinstance(payload, dict) else []

    custos_por_sku, _ = _carregar_custos_impostos_cadastro_por_sku_loja(client_id, loja)
    dados_analise = []

    for item in anuncios:
        sku = str(item.get("sku") or "").strip()
        preco_atual = _parse_float_flex(item.get("price")) or 0.0
        preco_original = _parse_float_flex(item.get("original_price"))
        if preco_original is None or preco_original <= 0:
            preco_original = preco_atual

        has_promotion = bool(item.get("has_promotion"))
        desconto_pct = _parse_float_flex(item.get("discount_pct"))
        if desconto_pct is None and preco_original > 0 and preco_atual > 0 and preco_original > preco_atual:
            desconto_pct = ((preco_original - preco_atual) / preco_original) * 100.0
        desconto_pct = desconto_pct or 0.0

        custo = _resolver_custo_medio_por_skus(custos_por_sku, sku)
        margem_pct = None
        if custo is not None and preco_atual > 0:
            margem_pct = ((preco_atual - float(custo)) / preco_atual) * 100.0

        if margem_pct is None:
            decisao = "Revisar custo"
        elif margem_pct < margem_minima:
            decisao = "NÃ£o participar"
        else:
            decisao = "Participar"

        situacao = "Promocao ativa" if has_promotion else "Sem promocao"
        dados_analise.append({
            "MLB": str(item.get("id") or ""),
            "SKU": sku,
            "TÃ­tulo": str(item.get("title") or ""),
            "SituaÃƒÂ§ÃƒÂ£o": situacao,
            "Desconto": _format_pct_br(desconto_pct),
            "Custo": formatar_moeda_br(custo) if custo is not None else "",
            "M 21 Fixa": formatar_moeda_br(preco_original),
            "M ML": formatar_moeda_br(preco_atual),
            "Margem %": _format_pct_br(margem_pct) if margem_pct is not None else "",
            "Participar ou nÃ£o": decisao,
        })

    planilha_nome = _salvar_planilha_analise_promo(client_id, dados_analise, prefixo='analise_promo_auto')

    return {
        "success": True,
        "mode": "auto_ml",
        "loja": loja,
        "margem_minima": margem_minima,
        "total": payload.get("total", len(dados_analise)) if isinstance(payload, dict) else len(dados_analise),
        "data": dados_analise,
        "planilha_gerada": planilha_nome,
    }

def limpar_dados_para_exportacao(df_original):
    df_limpo = df_original.copy()
    def limpar_valor(val):
        val_str = str(val)
        if "Participar" in val_str and "nÃ£o" not in val_str.lower() and "nao" not in val_str.lower(): return "Participar"
        if "NÃƒO PARTICIPAR" in val_str.upper() or "NAO PARTICIPAR" in val_str.upper(): return "NÃ£o participar"
        return val
    if "Participar ou nÃ£o" not in df_limpo.columns:
        if "AÃ§Ã£o" in df_limpo.columns:
            df_limpo["Participar ou nÃ£o"] = df_limpo["AÃ§Ã£o"]
        else:
            df_limpo["Participar ou nÃ£o"] = "Participar"
    df_limpo["Participar ou nÃ£o"] = df_limpo["Participar ou nÃ£o"].apply(limpar_valor)
    return df_limpo

def _normalizar_coluna_exportacao(valor: Any) -> str:
    texto = normalizar_texto(_limpar_nome_coluna(valor))
    return re.sub(r"[^a-z0-9]+", " ", texto).strip()

def _valor_df_por_alias(row, aliases: list[str]):
    aliases_norm = {_normalizar_coluna_exportacao(alias) for alias in aliases}
    for col in getattr(row, "index", []):
        if _normalizar_coluna_exportacao(col) in aliases_norm:
            valor = row.get(col)
            if valor is None:
                return ""
            try:
                if pd.isna(valor):
                    return ""
            except Exception:
                pass
            return valor
    return ""

def _normalizar_decisao_planilha(valor: Any) -> str:
    texto = str(valor if valor is not None else "").strip()
    if not texto or texto.lower() in {"nan", "none", "null", "nat", "<na>", "-"}:
        return ""
    norm = normalizar_texto(texto)
    if "participar" not in norm:
        return ""
    if "nao" in norm or "n o" in norm:
        return "NÃ£o participar"
    return "Participar"

def _decisao_linha_exportacao(row) -> str:
    for aliases in (
        ["AÃ§Ã£o", "Acao", "ACTION"],
        ["Participar ou nÃ£o", "Participar ou nao", "Participar"],
    ):
        decisao = _normalizar_decisao_planilha(_valor_df_por_alias(row, aliases))
        if decisao:
            return decisao
    return ""

def _localizar_coluna_em_linha(valores, aliases: list[str]) -> Optional[int]:
    aliases_norm = [_normalizar_coluna_exportacao(alias) for alias in aliases]
    valores_norm = [_normalizar_coluna_exportacao(valor) for valor in valores]
    for alias in aliases_norm:
        for idx, valor_norm in enumerate(valores_norm, start=1):
            if valor_norm == alias:
                return idx
    return None

def _localizar_cabecalho_exportacao(ws):
    key_aliases = [
        "ITEM_ID", "MLB", "ID anuncio", "ID anuncio", "ID do anuncio", "ID do anuncio",
        "NÃƒÂºmero do anuncio", "Numero do anuncio", "CÃƒÂ³digo do anuncio", "Codigo do anuncio",
        "AnÃƒÂºncio", "Anuncio", "ID",
    ]
    action_aliases = ["ACTION", "AÃ§Ã£o", "Acao"]

    max_rows = min(int(ws.max_row or 1), 40)
    for row_idx in range(1, max_rows + 1):
        valores = [cell.value for cell in ws[row_idx]]
        col_key = _localizar_coluna_em_linha(valores, key_aliases)
        if not col_key:
            continue
        col_action = _localizar_coluna_em_linha(valores, action_aliases)
        if col_action:
            return row_idx, col_key, col_action

    return None

def gerar_excel_atualizado(file_bytes, df_decisoes):
    try:
        with io.BytesIO(file_bytes) as b:
            wb = openpyxl.load_workbook(b)
            if not wb.sheetnames:
                return None
            sheet_name = find_sheet_name(wb)
            ws = wb[sheet_name]

            cabecalho = _localizar_cabecalho_exportacao(ws)
            if not cabecalho:
                raise ValueError("NÃƒÂ£o encontrei as colunas de MLB/item e ACTION/AÃ§Ã£o na planilha original.")
            header_row, col_key, col_action = cabecalho

            df_clean = limpar_dados_para_exportacao(df_decisoes)
            decisoes_por_mlb = {}
            for _, row in df_clean.iterrows():
                decisao = _decisao_linha_exportacao(row)
                if not decisao:
                    continue
                mlb = _promo_normalizar_mlb(_valor_df_por_alias(row, [
                    "MLB", "ITEM_ID", "ID anuncio", "ID anuncio", "ID do anuncio", "ID do anuncio",
                    "NÃƒÂºmero do anuncio", "Numero do anuncio", "CÃƒÂ³digo do anuncio", "Codigo do anuncio",
                    "AnÃƒÂºncio", "Anuncio", "ID",
                ]))
                if mlb:
                    decisoes_por_mlb[mlb] = decisao

            if not decisoes_por_mlb:
                raise ValueError("Nenhuma decisÃƒÂ£o valida foi enviada para exportaÃƒÂ§ÃƒÂ£o.")

            aplicadas = 0
            for row_idx in range(header_row + 1, int(ws.max_row or header_row) + 1):
                mlb = _promo_normalizar_mlb(ws.cell(row=row_idx, column=col_key).value)
                if not mlb:
                    continue
                decisao = decisoes_por_mlb.get(mlb)
                if not decisao:
                    continue
                ws.cell(row=row_idx, column=col_action).value = decisao
                aplicadas += 1

            if aplicadas == 0:
                raise ValueError("Nenhum MLB da analise foi encontrado na planilha original.")

            output = io.BytesIO()
            wb.save(output)
            output.seek(0)
            return output
    except Exception as e:
        print(f"Erro gerar excel: {e}")
        return None

# --- FUNÃƒÆ’Ã¢â‚¬Â¡ÃƒÆ’Ã¢â‚¬Â¢ES AUXILIARES RENOVACAO (Adaptadas de renovacao.py) ---
def find_sheet_name(workbook):
    """Encontra o nome da aba de promocoes ou retorna a primeira."""
    for name in workbook.sheetnames:
        if "promocoes" in name.lower() or "promo" in name.lower():
            return name
    return workbook.sheetnames[0]

def find_common_key(df_antiga, df_nova):
    """Encontra uma coluna chave comum para unir os dataframes."""
    POSSIBLE_KEYS = ['ITEM_ID', 'SELLER_SKU', 'SKU', 'ID', 'CÃƒÆ’Ã¢â‚¬Å“DIGO', 'MLB']
    for key in POSSIBLE_KEYS:
        if key in df_antiga.columns and key in df_nova.columns:
            return key
    return None

def find_col(df_columns, names):
    """Encontra o primeiro nome de coluna correspondente em uma lista de possibilidades."""
    upper_cols = [str(c).upper().strip() for c in df_columns]
    for name in names:
        target = str(name).upper().strip()
        if target in upper_cols:
            return df_columns[upper_cols.index(target)]
    return None

def processar_renovacao_logic(file_antiga_bytes, file_nova_bytes):
    try:
        # 1. Carregar Planilha Antiga para MemÃƒÆ’Ã‚Â³ria (DataFrame) para busca rÃƒÆ’Ã‚Â¡pida
        with io.BytesIO(file_antiga_bytes) as b:
            # Tenta ler com openpyxl engine para garantir compatibilidade
            try:
                wb = openpyxl.load_workbook(b, data_only=True, read_only=True)
                sheet_name = find_sheet_name(wb)
                wb.close()
                b.seek(0)
                df_antiga = pd.read_excel(b, sheet_name=sheet_name, header=0)
            except:
                b.seek(0)
                df_antiga = pd.read_excel(b, header=0)

        # LÃƒÆ’Ã‚Â³gica de limpeza de cabeÃƒÆ’Ã‚Â§alho do renovacao.py (se > 4 linhas, assume header na linha 5)
        cols_upper = [str(c).upper() for c in df_antiga.columns]
        if len(df_antiga) > 4 and not any(k in cols_upper for k in ['ITEM_ID', 'SKU', 'MLB', 'STATUS']):
             with io.BytesIO(file_antiga_bytes) as b:
                 df_antiga = pd.read_excel(b, header=4)

        df_antiga.columns = df_antiga.columns.str.strip().str.upper()
        
        # Identificar colunas chave na Antiga
        key_col = find_common_key(df_antiga, df_antiga)
        status_col = find_col(df_antiga.columns, ['STATUS', 'ESTADO'])
        
        if not key_col or not status_col:
            return None, f"Colunas chave ou STATUS nÃƒÆ’Ã‚Â£o encontradas na planilha antiga."
            
        # Mapa: Chave -> Status (Remove duplicatas mantendo o ÃƒÆ’Ã‚Âºltimo)
        df_antiga[key_col] = df_antiga[key_col].astype(str).str.strip()
        status_map = df_antiga.set_index(key_col)[status_col].to_dict()
        
        # 2. Carregar Planilha Nova para EdiÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o (OpenPyXL)
        wb_nova = openpyxl.load_workbook(io.BytesIO(file_nova_bytes))
        ws_name = find_sheet_name(wb_nova)
        ws_nova = wb_nova[ws_name]
                
        # Localizar cabeÃƒÆ’Ã‚Â§alho na Nova
        header_row_idx = 1
        header_map = {} 
        
        # Varre as primeiras 10 linhas para achar o cabeÃƒÆ’Ã‚Â§alho
        found_header = False
        for r in range(1, 11):
            row_vals = [str(c.value).strip().upper() if c.value else "" for c in ws_nova[r]]
            # CritÃƒÆ’Ã‚Â©rio: Tem chave E tem ACTION
            if (key_col in row_vals or any(k in row_vals for k in ['ITEM_ID', 'SKU', 'MLB'])) and \
               any(x in row_vals for x in ['ACTION', 'AÃƒÆ’Ã¢â‚¬Â¡ÃƒÆ’Ã†â€™O', 'ACAO']):
                header_row_idx = r
                for idx, val in enumerate(row_vals):
                    if val: header_map[val] = idx + 1
                found_header = True
                break
        
        if not found_header:
            return None, f"CabeÃƒÆ’Ã‚Â§alho nÃƒÆ’Ã‚Â£o encontrado na planilha nova."
            
        idx_key_nova = header_map.get(key_col)
        if not idx_key_nova:
             # Tenta achar qualquer chave vÃƒÆ’Ã‚Â¡lida no header map
             for k in ['ITEM_ID', 'SELLER_SKU', 'SKU', 'ID', 'CÃƒÆ’Ã¢â‚¬Å“DIGO', 'MLB']:
                 if k in header_map:
                     idx_key_nova = header_map[k]
                     break

        idx_action_nova = header_map.get("ACTION") or header_map.get("AÃƒÆ’Ã¢â‚¬Â¡ÃƒÆ’Ã†â€™O") or header_map.get("ACAO")
        
        if not idx_key_nova or not idx_action_nova:
             return None, "Colunas Chave ou ACTION nÃƒÆ’Ã‚Â£o mapeadas na planilha nova."

        # 3. Processar Linhas
        for row in ws_nova.iter_rows(min_row=header_row_idx + 1):
            cell_key = row[idx_key_nova - 1].value
            if not cell_key: continue
            
            key_val = str(cell_key).strip()
            
            # LÃƒÆ’Ã‚Â³gica de DecisÃƒÆ’Ã‚Â£o (Igual ao renovacao.py)
            status_antigo = status_map.get(key_val)
            acao = "Participar" # Default para itens novos (nÃƒÆ’Ã‚Â£o encontrados na antiga)
            
            if status_antigo:
                st_str = str(status_antigo).strip().lower()
                # Se estava ativo ou programado, mantÃƒÆ’Ã‚Â©m (Participar). Se estava inativo/pausado, NÃƒÆ’Ã‚Â£o participar.
                if st_str not in ['ativo', 'programado', 'active']:
                    acao = "NÃƒÆ’Ã‚Â£o participar"
            
            # Atualiza a cÃƒÆ’Ã‚Â©lula de aÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o
            row[idx_action_nova - 1].value = acao
        
        output = io.BytesIO()
        wb_nova.save(output)
        output.seek(0)
        return output, "Sucesso"
    except Exception as e:
        return None, str(e)

def analisar_renovacao_logic(file_antiga_bytes, file_nova_bytes):
    try:
        # --- 1. Carregar Planilha Antiga (Igual ao renovacao.py) ---
        with io.BytesIO(file_antiga_bytes) as b:
            try:
                wb = openpyxl.load_workbook(b, data_only=True, read_only=True)
                sheet_name_antiga = find_sheet_name(wb)
                wb.close()
                b.seek(0)
                df_antiga = pd.read_excel(b, sheet_name=sheet_name_antiga, header=0)
            except:
                b.seek(0)
                df_antiga = pd.read_excel(b, header=0)

        # LÃƒÆ’Ã‚Â³gica de corte de linhas (PadrÃƒÆ’Ã‚Â£o ML: Header na linha 5)
        cols_antiga_upper = [str(c).upper() for c in df_antiga.columns]
        if len(df_antiga) > 4 and not any(k in cols_antiga_upper for k in ['ITEM_ID', 'SKU', 'MLB', 'STATUS']):
             with io.BytesIO(file_antiga_bytes) as b:
                 df_antiga = pd.read_excel(b, sheet_name=sheet_name_antiga if 'sheet_name_antiga' in locals() else 0, header=4)

        df_antiga.columns = df_antiga.columns.str.strip().str.upper()
        
        # --- 2. Carregar Planilha Nova ---
        with io.BytesIO(file_nova_bytes) as b:
            try:
                wb = openpyxl.load_workbook(b, data_only=True, read_only=True)
                sheet_name_nova = find_sheet_name(wb)
                wb.close()
                b.seek(0)
                df_nova = pd.read_excel(b, sheet_name=sheet_name_nova, header=0)
            except:
                b.seek(0)
                df_nova = pd.read_excel(b, header=0)

        cols_nova_upper = [str(c).upper() for c in df_nova.columns]
        if len(df_nova) > 4 and not any(k in cols_nova_upper for k in ['ITEM_ID', 'SKU', 'MLB', 'ACTION', 'AÃƒÆ’Ã¢â‚¬Â¡ÃƒÆ’Ã†â€™O']):
             with io.BytesIO(file_nova_bytes) as b:
                 df_nova = pd.read_excel(b, sheet_name=sheet_name_nova if 'sheet_name_nova' in locals() else 0, header=4)
        
        df_nova.columns = df_nova.columns.str.strip().str.upper()

        # --- 3. Identificar Chaves e Status ---
        key_col = find_common_key(df_antiga, df_antiga)
        status_col = find_col(df_antiga.columns, ['STATUS', 'ESTADO'])
        
        if not key_col:
            return None, "NÃƒÆ’Ã‚Â£o foi possÃƒÆ’Ã‚Â­vel encontrar uma coluna chave comum (ITEM_ID, SKU, etc.)."
        
        # Listas de nomes possÃƒÆ’Ã‚Â­veis para colunas
        DISCOUNT_NAMES = ['DISCOUNT_PERCENTAGE', 'DISCOUNT %', 'DESCONTO', 'DESC %', 'DISCOUNT']
        PRICE_NAMES = ['FINAL_PRICE', 'PREÃƒÆ’Ã¢â‚¬Â¡O FINAL', 'PRECO FINAL', 'PRICE', 'PREÃƒÆ’Ã¢â‚¬Â¡O']

        # --- 4. Processar Status Antigo ---
        df_antiga[key_col] = df_antiga[key_col].astype(str).str.strip()
        
        # Identificar colunas na Antiga
        disc_col_ant = find_col(df_antiga.columns, DISCOUNT_NAMES)
        price_col_ant = find_col(df_antiga.columns, PRICE_NAMES)
        
        antiga_map = {}
        
        def get_clean_val(row, col):
            if not col: return ""
            val = row[col]
            if pd.isna(val): return ""
            return str(val).strip()

        def parse_pct(val):
            if not val: return 0.0
            try:
                s = str(val).replace('%', '').strip()
                if ',' in s and '.' in s: s = s.replace('.', '').replace(',', '.')
                elif ',' in s: s = s.replace(',', '.')
                return float(s)
            except:
                return 0.0

        for _, row in df_antiga.iterrows():
            k = str(row[key_col]).strip()
            antiga_map[k] = {
                'STATUS': get_clean_val(row, status_col),
                'DESC': get_clean_val(row, disc_col_ant),
                'PRICE': get_clean_val(row, price_col_ant)
            }
        
        # --- 5. Processar Nova e Gerar Dados ---
        df_nova[key_col] = df_nova[key_col].astype(str).str.strip()
        
        # Colunas de exibiÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o
        title_col = find_col(df_nova.columns, ['TITLE', 'TITULO', 'TÃƒÆ’Ã‚ÂTULO'])
        disc_col_nova = find_col(df_nova.columns, DISCOUNT_NAMES)
        price_col_nova = find_col(df_nova.columns, PRICE_NAMES)

        dados_analise = []
        # Itera sobre a NOVA (Equivalente a Left Join / How Right do renovacao.py)
        for _, row in df_nova.iterrows():
            key_val = str(row[key_col])
            
            if not key_val.strip().upper().startswith("MLB"):
                continue
            
            antiga_data = antiga_map.get(key_val, {})
            status_antigo = antiga_data.get('STATUS', "")
            
            if not status_antigo:
                acao = "Participar"
            else:
                st_str = str(status_antigo).strip().lower()
                if 'elegÃƒÆ’Ã‚Â­vel' in st_str or 'elegivel' in st_str:
                    acao = "NÃƒÆ’Ã‚Â£o participar"
                elif st_str in ['ativo', 'programado']:
                    acao = "Participar"
                else:
                    acao = "NÃƒÆ’Ã‚Â£o participar"
                
                # Regra: Se desconto novo > desconto antigo, NÃƒÆ’Ã‚Â£o participar
                desc_antiga_val = parse_pct(antiga_data.get('DESC', ""))
                desc_nova_val = parse_pct(str(row[disc_col_nova]) if disc_col_nova else "")
                if desc_nova_val > desc_antiga_val + 1e-9: # +1e-9 para evitar erros de ponto flutuante
                    acao = "NÃƒÆ’Ã‚Â£o participar"
            
            dados_analise.append({
                "KEY": key_val,
                "TITLE": str(row[title_col]) if title_col else "",
                "STATUS_ANTIGO": status_antigo,
                "DESC_ANTIGA": antiga_data.get('DESC', ""),
                "DESC_NOVA": str(row[disc_col_nova]) if disc_col_nova else "",
                "PRICE_ANTIGA": antiga_data.get('PRICE', ""),
                "PRICE_NOVA": str(row[price_col_nova]) if price_col_nova else "",
                "ACTION": acao
            })
            
        return dados_analise, "Sucesso"
    except Exception as e:
        return None, f"Erro interno: {str(e)}"

def gerar_excel_renovacao(file_nova_bytes, decisoes_list):
    try:
        wb = openpyxl.load_workbook(io.BytesIO(file_nova_bytes))
        ws_name = find_sheet_name(wb)
        ws = wb[ws_name]
        
        # Mapeamento: Chave -> Objeto completo de decisÃƒÆ’Ã‚Â£o
        decision_map = {str(d['KEY']).strip(): d for d in decisoes_list}
        
        # Re-localiza colunas (simplificado, assume mesma estrutura da anÃƒÆ’Ã‚Â¡lise)
        # Para robustez total, repetimos a busca de header
        header_row_idx = 1
        col_key_idx = None
        col_action_idx = None
        col_desc_idx = None
        col_price_idx = None
        
        DISCOUNT_NAMES = ['DISCOUNT_PERCENTAGE', 'DISCOUNT %', 'DESCONTO', 'DESC %', 'DISCOUNT']
        PRICE_NAMES = ['FINAL_PRICE', 'PREÃƒÆ’Ã¢â‚¬Â¡O FINAL', 'PRECO FINAL', 'PRICE', 'PREÃƒÆ’Ã¢â‚¬Â¡O']
        
        for r in range(1, 21):
            row_vals = [str(c.value).strip().upper() if c.value else "" for c in ws[r]]
            if any(x in row_vals for x in ['ACTION', 'AÃƒÆ’Ã¢â‚¬Â¡ÃƒÆ’Ã†â€™O', 'ACAO']):
                header_row_idx = r
                
                # Busca ÃƒÆ’Ã‚Â­ndices das colunas de valores e aÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o
                for idx, val in enumerate(row_vals):
                    if val in ['ACTION', 'AÃƒÆ’Ã¢â‚¬Â¡ÃƒÆ’Ã†â€™O', 'ACAO']: col_action_idx = idx + 1
                    if val in DISCOUNT_NAMES: col_desc_idx = idx + 1
                    if val in PRICE_NAMES: col_price_idx = idx + 1
                
                # Busca ÃƒÆ’Ã‚Â­ndice da coluna chave com prioridade para ITEM_ID/MLB
                if 'ITEM_ID' in row_vals:
                    col_key_idx = row_vals.index('ITEM_ID') + 1
                elif 'MLB' in row_vals:
                    col_key_idx = row_vals.index('MLB') + 1
                else:
                    # Fallback para outras chaves
                    for idx, val in enumerate(row_vals):
                        if val in ['SKU', 'SELLER_SKU', 'ID', 'CÃƒÆ’Ã¢â‚¬Å“DIGO']:
                            col_key_idx = idx + 1
                            break
                            
                if col_key_idx and col_action_idx: break
        
        if not col_key_idx or not col_action_idx: return None, "Colunas nÃƒÆ’Ã‚Â£o encontradas para exportaÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o."
        
        for row in ws.iter_rows(min_row=header_row_idx + 1):
            cell_key = row[col_key_idx - 1].value
            if cell_key:
                k = str(cell_key).strip()
                if k in decision_map:
                    data = decision_map[k]
                    # Atualiza AÃƒÆ’Ã‚Â§ÃƒÆ’Ã‚Â£o
                    row[col_action_idx - 1].value = data.get('ACTION', '')
                    
                    # Atualiza Desconto (se existir coluna)
                    if col_desc_idx and 'DESC_NOVA' in data:
                        try:
                            val = data['DESC_NOVA']
                            if val and val != 'nan' and val != 'None':
                                row[col_desc_idx - 1].value = float(val) if str(val).replace('.','',1).isdigit() else val
                        except:
                            row[col_desc_idx - 1].value = data['DESC_NOVA']
                            
                    # Atualiza PreÃƒÆ’Ã‚Â§o (se existir coluna)
                    if col_price_idx and 'PRICE_NOVA' in data:
                        try:
                            val = data['PRICE_NOVA']
                            if val and val != 'nan' and val != 'None':
                                row[col_price_idx - 1].value = float(val) if str(val).replace('.','',1).isdigit() else val
                        except:
                            row[col_price_idx - 1].value = data['PRICE_NOVA']
        
        output = io.BytesIO()
        wb.save(output)
        output.seek(0)
        return output, "Sucesso"
    except Exception as e:
        return None, str(e)

def _renovacao_json_response(resp):
    try:
        return resp.json() or {}
    except Exception:
        return {}


def _renovacao_extrair_campanhas_payload(payload):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        return payload.get("results") or payload.get("campaigns") or payload.get("promotions") or []
    return []


def _renovacao_ml_listar_campanhas_usuario(client_id: str, loja: str) -> tuple[list[dict], dict]:
    nome_loja = str(loja or "").strip()
    if not nome_loja:
        raise HTTPException(status_code=400, detail="Informe a loja do Mercado Livre.")

    cfg = _obter_cfg_ml(client_id, nome_loja)
    user_id = str(cfg.get("user_id") or "").strip()
    if not user_id:
        raise HTTPException(status_code=400, detail="ID do usuario do Mercado Livre nao encontrado para esta loja.")

    resp, cfg = _ml_api_request(
        client_id,
        nome_loja,
        cfg,
        "GET",
        f"https://api.mercadolibre.com/seller-promotions/users/{user_id}",
        params={"app_version": "v2"},
        timeout=25,
    )
    if resp.status_code != 200:
        raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao listar campanhas do Mercado Livre"))

    campanhas_raw = _renovacao_extrair_campanhas_payload(_renovacao_json_response(resp))
    campanhas = []
    for item in campanhas_raw:
        if not isinstance(item, dict):
            continue
        campanha_id = str(item.get("id") or item.get("promotion_id") or "").strip()
        tipo = str(item.get("type") or item.get("promotion_type") or "").strip()
        tipo_upper = tipo.upper()
        if not campanha_id:
            continue
        if tipo_upper != "SELLER_CAMPAIGN" and not campanha_id.upper().startswith("C-MLB"):
            continue
        status = str(item.get("status") or item.get("state") or "").strip()
        status_lower = status.lower()
        status_programado = status_lower in {"pending", "programmed", "scheduled", "ready_to_start"}
        active_count_api = _ml_extrair_contagem_campanha(item, [
            "active_count", "active_items_count", "active_item_count", "started_items_count",
            "participating_items_count", "items_active_count",
        ])
        eligible_count = _ml_extrair_contagem_campanha(item, [
            "eligible_count", "eligible_items_count", "eligible_item_count",
            "candidate_items_count", "candidate_count", "items_count", "item_count",
            "total_items", "products_count", "offers_count",
        ])
        total_count = _ml_extrair_contagem_campanha(item, [
            "items_count", "item_count", "total_items", "products_count", "offers_count",
            "total_count", "total_items_count",
        ])
        programmed_count = _ml_extrair_contagem_campanha(item, [
            "programmed_count", "programmed_items_count", "programmed_item_count",
            "scheduled_count", "scheduled_items_count", "scheduled_item_count",
            "pending_count", "pending_items_count", "pending_item_count",
        ])

        if not status_programado:
            active_count_api, cfg = _ml_contar_itens_promocao_status(
                client_id, nome_loja, cfg, campanha_id, tipo or "SELLER_CAMPAIGN", "started"
            )

        active_count = 0 if status_programado else active_count_api
        if programmed_count is None:
            if status_programado:
                programmed_count, cfg = _ml_contar_itens_promocao_status(
                    client_id, nome_loja, cfg, campanha_id, tipo or "SELLER_CAMPAIGN", "pending"
                )
                if programmed_count is None:
                    for candidato in (total_count, active_count_api, eligible_count):
                        if candidato is not None:
                            programmed_count = candidato
                            break
            else:
                programmed_count = 0
        campanhas.append({
            "id": campanha_id,
            "name": str(item.get("name") or item.get("title") or campanha_id).strip(),
            "title": str(item.get("title") or item.get("name") or campanha_id).strip(),
            "status": status,
            "type": tipo or "SELLER_CAMPAIGN",
            "promotion_type": tipo or "SELLER_CAMPAIGN",
            "sub_type": str(item.get("sub_type") or item.get("subtype") or "").strip(),
            "start_date": item.get("start_date") or item.get("date_start") or item.get("begin_date"),
            "finish_date": item.get("finish_date") or item.get("end_date") or item.get("date_end"),
            "active_count": active_count,
            "eligible_count": eligible_count,
            "programmed_count": programmed_count,
            "scheduled_count": programmed_count,
            "total_count": total_count,
            "raw": item,
        })

    prioridade_status = {"started": 0, "pending": 1, "programmed": 1, "active": 2, "finished": 9, "ended": 9}
    campanhas.sort(key=lambda c: (
        prioridade_status.get(str(c.get("status") or "").lower(), 5),
        str(c.get("start_date") or ""),
        str(c.get("name") or "").lower(),
    ))
    return campanhas, cfg


def _renovacao_parse_data_ml(valor):
    texto = str(valor or "").strip()
    if not texto:
        return None
    tentativas = [
        texto,
        texto.replace("Z", "+00:00"),
        texto.replace(".000+0000", "+00:00"),
    ]
    for item in tentativas:
        try:
            data = dt.datetime.fromisoformat(item)
            if data.tzinfo is not None:
                data = data.astimezone(dt.timezone.utc).replace(tzinfo=None)
            return data
        except Exception:
            pass
    for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"):
        try:
            return dt.datetime.strptime(texto[:19] if "T" in texto else texto[:10], fmt)
        except Exception:
            pass
    return None


def _renovacao_dias_mes(ano: int, mes: int) -> int:
    if mes == 2:
        bissexto = (ano % 4 == 0 and ano % 100 != 0) or (ano % 400 == 0)
        return 29 if bissexto else 28
    return 30 if mes in {4, 6, 9, 11} else 31


def _renovacao_adicionar_meses(data: dt.datetime, meses: int = 1) -> dt.datetime:
    mes_base = data.month - 1 + meses
    ano = data.year + mes_base // 12
    mes = mes_base % 12 + 1
    dia = min(data.day, _renovacao_dias_mes(ano, mes))
    return data.replace(year=ano, month=mes, day=dia)


def _renovacao_datas_proximo_mes(campanha: dict) -> tuple[str, str]:
    inicio = _renovacao_parse_data_ml(campanha.get("start_date")) or (dt.datetime.now() + dt.timedelta(days=1))
    fim = _renovacao_parse_data_ml(campanha.get("finish_date"))
    duracao_dias = 14
    if fim and fim > inicio:
        duracao_dias = max(1, min(14, (fim.date() - inicio.date()).days or 1))

    novo_inicio = _renovacao_adicionar_meses(inicio, 1)
    agora = dt.datetime.now()
    while novo_inicio.date() < agora.date():
        novo_inicio = _renovacao_adicionar_meses(novo_inicio, 1)
    if novo_inicio.date() == agora.date():
        novo_inicio = agora + dt.timedelta(days=1)
    novo_inicio = novo_inicio.replace(hour=0, minute=0, second=0, microsecond=0)
    novo_fim = (novo_inicio + dt.timedelta(days=duracao_dias)).replace(hour=23, minute=59, second=59, microsecond=0)
    return novo_inicio.strftime("%Y-%m-%dT%H:%M:%S"), novo_fim.strftime("%Y-%m-%dT%H:%M:%S")


RENOVACAO_MESES_PT = {
    1: "Janeiro",
    2: "Fevereiro",
    3: "MarÃ§o",
    4: "Abril",
    5: "Maio",
    6: "Junho",
    7: "Julho",
    8: "Agosto",
    9: "Setembro",
    10: "Outubro",
    11: "Novembro",
    12: "Dezembro",
}


def _renovacao_nome_proximo_mes(campanha: dict) -> str:
    inicio_txt, _fim_txt = _renovacao_datas_proximo_mes(campanha or {})
    inicio = _renovacao_parse_data_ml(inicio_txt) or dt.datetime.now()
    mes_nome = RENOVACAO_MESES_PT.get(int(inicio.month), "")
    base = str((campanha or {}).get("name") or (campanha or {}).get("title") or "Promo").strip()
    base = re.sub(r"\s*-\s*(started|pending|programmed|active|finished|ended).*$", "", base, flags=re.I).strip()
    base = re.sub(r"\s*\([^)]*\)\s*$", "", base).strip()
    meses_regex = r"(janeiro|fevereiro|mar[Ã§c]o|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro)"
    if re.search(meses_regex, base, flags=re.I):
        return re.sub(meses_regex, mes_nome, base, count=1, flags=re.I).strip()
    if re.search(r"\b(0?[1-9]|1[0-2])/\d{2,4}\b", base):
        return re.sub(r"\b(0?[1-9]|1[0-2])/\d{2,4}\b", mes_nome, base, count=1).strip()
    if not base or base.lower() == "promo":
        return f"Promo {mes_nome}".strip()
    return f"{base} {mes_nome}".strip()


def _renovacao_normalizar_nome(valor: str) -> str:
    texto = unicodedata.normalize("NFKD", str(valor or "").strip().lower())
    texto = "".join(ch for ch in texto if not unicodedata.combining(ch))
    return re.sub(r"[^a-z0-9]+", "", texto)


def _renovacao_encontrar_campanha_destino(campanhas: list[dict], nome: str, inicio_alvo: str) -> Optional[dict]:
    nome_norm = _renovacao_normalizar_nome(nome)
    inicio_dt = _renovacao_parse_data_ml(inicio_alvo)
    fallback_por_nome = None
    for campanha in campanhas or []:
        if not isinstance(campanha, dict):
            continue
        campanha_id = str(campanha.get("id") or "").strip()
        if not campanha_id:
            continue
        tipo = str(campanha.get("promotion_type") or campanha.get("type") or "").upper()
        if tipo and tipo != "SELLER_CAMPAIGN" and not campanha_id.upper().startswith("C-MLB"):
            continue
        nome_campanha = str(campanha.get("name") or campanha.get("title") or "").strip()
        if _renovacao_normalizar_nome(nome_campanha) != nome_norm:
            continue
        data_campanha = _renovacao_parse_data_ml(campanha.get("start_date"))
        if data_campanha and inicio_dt:
            if data_campanha.year == inicio_dt.year and data_campanha.month == inicio_dt.month:
                return campanha
            continue
        fallback_por_nome = fallback_por_nome or campanha
    return fallback_por_nome


def _renovacao_buscar_numero_em_obj(obj, chaves: set[str]):
    encontrados = []

    def visitar(valor):
        if isinstance(valor, dict):
            for chave, conteudo in valor.items():
                chave_norm = str(chave or "").strip().lower()
                if chave_norm in chaves:
                    numero = _parse_float_flex(conteudo)
                    if numero is not None and numero > 0:
                        encontrados.append(float(numero))
                if isinstance(conteudo, (dict, list)):
                    visitar(conteudo)
        elif isinstance(valor, list):
            for item in valor:
                visitar(item)

    visitar(obj)
    return encontrados[0] if encontrados else None


def _renovacao_desconto_item(item_id: str, raw: dict, detalhe: dict) -> tuple[Optional[float], Optional[float], Optional[float]]:
    raw = raw if isinstance(raw, dict) else {}
    detalhe = detalhe if isinstance(detalhe, dict) else {}
    preco_promo, desconto = _ml_extrair_preco_promocao_raw(raw)
    preco_base = _renovacao_buscar_numero_em_obj(raw, {
        "original_price", "regular_price", "base_price", "standard_price", "price_before_discount",
    })
    if preco_base is None:
        preco_base = _parse_float_flex(detalhe.get("original_price"))
    preco_item = _parse_float_flex(detalhe.get("price"))
    if preco_base is None and preco_item is not None:
        preco_base = float(preco_item)
    if preco_promo is None and raw:
        preco_promo = _renovacao_buscar_numero_em_obj(raw, {
            "deal_price", "promotion_price", "campaign_price", "final_price",
        })

    if desconto is None and preco_base and preco_promo and preco_base > preco_promo:
        desconto = round((1 - (float(preco_promo) / float(preco_base))) * 100, 4)
    if preco_base is None and preco_promo and desconto is not None and 0 < desconto < 100:
        preco_base = round(float(preco_promo) / (1 - (float(desconto) / 100)), 2)
    if preco_promo is None and preco_base and desconto is not None and 0 < desconto < 100:
        preco_promo = round(float(preco_base) * (1 - (float(desconto) / 100)), 2)

    if desconto is None or desconto <= 0:
        logger.warning(f"[RENOVACAO ML] Sem desconto identificavel para {item_id}")
        return None, preco_base, preco_promo
    return round(float(desconto), 4), preco_base, preco_promo


def _renovacao_emitir_progresso(
    progress_callback: Optional[Callable[[dict], None]],
    etapa: str,
    percentual: int | float,
    mensagem: str,
    **extras,
) -> None:
    if not progress_callback:
        return
    try:
        pct = max(0, min(100, int(round(float(percentual or 0)))))
    except Exception:
        pct = 0
    payload = {
        "etapa": str(etapa or "Sincronizacao"),
        "percentual": pct,
        "progress": pct,
        "mensagem": str(mensagem or ""),
    }
    if extras:
        payload.update(extras)
    try:
        progress_callback(payload)
    except Exception:
        logger.debug("[RENOVACAO ML] Falha ao emitir progresso", exc_info=True)


def _renovacao_sync_job_update(job_id: str, **kwargs) -> None:
    if not job_id:
        return
    with RENOVACAO_SYNC_JOBS_LOCK:
        atual = dict(RENOVACAO_SYNC_JOBS.get(job_id) or {})
        atual.update(kwargs)
        atual["updated_at"] = time.time()
        RENOVACAO_SYNC_JOBS[job_id] = atual


def _renovacao_sync_job_get(job_id: str) -> dict:
    with RENOVACAO_SYNC_JOBS_LOCK:
        return dict(RENOVACAO_SYNC_JOBS.get(job_id) or {})


def _renovacao_sync_jobs_limpar_antigos(max_age_seconds: int = 24 * 60 * 60) -> None:
    agora = time.time()
    with RENOVACAO_SYNC_JOBS_LOCK:
        antigos = [
            job_id for job_id, job in RENOVACAO_SYNC_JOBS.items()
            if agora - float((job or {}).get("updated_at") or agora) > max_age_seconds
        ]
        for job_id in antigos:
            RENOVACAO_SYNC_JOBS.pop(job_id, None)


def _renovacao_complementar_itens_campanha_por_varredura(
    client_id: str,
    loja: str,
    cfg: dict,
    campanha_id: str,
    ids_existentes: list[str],
    raw_por_item: dict[str, dict],
    max_items: int = 5000,
    progress_callback: Optional[Callable[[dict], None]] = None,
    progress_start: int = 30,
    progress_end: int = 55,
) -> tuple[list[str], dict[str, dict], dict]:
    user_id = str((cfg or {}).get("user_id") or "").strip()
    if not user_id:
        return ids_existentes, raw_por_item, cfg

    ids = list(dict.fromkeys([str(item_id or "").strip() for item_id in ids_existentes if str(item_id or "").strip()]))
    vistos = set(ids)
    raw_total = dict(raw_por_item or {})
    limite = max(1, min(int(max_items or 5000), 20000))
    _renovacao_emitir_progresso(
        progress_callback,
        "Varredura",
        progress_start,
        "Listando anuncios ativos da loja para completar a campanha de origem...",
        campanha_id=campanha_id,
        ja_encontrados=len(ids),
    )
    todos_ids, cfg = _ml_listar_ids_anuncios_ativos(client_id, loja, cfg, user_id, limite=limite)
    campanha_norm = str(campanha_id or "").strip().lower()
    _renovacao_emitir_progresso(
        progress_callback,
        "Varredura",
        progress_start,
        f"Endpoint direto incompleto. Verificando {len(todos_ids)} anuncio(s) ativos da loja...",
        campanha_id=campanha_id,
        encontrados=len(ids),
        total=len(todos_ids),
    )
    logger.info(
        "[RENOVACAO ML] Varredura da campanha %s em %s anuncio(s) ativos para completar sincronizacao.",
        campanha_id,
        len(todos_ids),
    )

    candidatos = [str(item_id or "").strip() for item_id in todos_ids if str(item_id or "").strip() and str(item_id or "").strip() not in vistos]
    max_workers = min(6, max(2, len(candidatos))) if candidatos else 0
    if not max_workers:
        return ids, raw_total, cfg

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_map = {
            executor.submit(_ml_obter_promocoes_item, client_id, loja, dict(cfg), item_id): item_id
            for item_id in candidatos
        }
        processados = 0
        ultimo_emitido = 0
        intervalo_emit = max(1, min(50, max(1, len(candidatos) // 20)))
        for future in as_completed(future_map):
            processados += 1
            item_id = future_map[future]
            try:
                promocoes_item, _cfg_tmp = future.result()
            except Exception:
                promocoes_item = []
            if (
                processados == 1
                or processados == len(candidatos)
                or processados - ultimo_emitido >= intervalo_emit
            ):
                ultimo_emitido = processados
                pct = progress_start
                if candidatos:
                    pct = progress_start + ((progress_end - progress_start) * processados / len(candidatos))
                _renovacao_emitir_progresso(
                    progress_callback,
                    "Varredura",
                    pct,
                    f"Verificando anuncios ativos: {processados}/{len(candidatos)}. Encontrados na campanha: {len(ids)}.",
                    campanha_id=campanha_id,
                    processados=processados,
                    total=len(candidatos),
                    encontrados=len(ids),
                )
            if campanha_norm not in _ml_extrair_ids_promocoes_item(promocoes_item):
                continue
            vistos.add(item_id)
            ids.append(item_id)
            raw_encontrado = _ml_encontrar_promocao_raw_item(promocoes_item, campanha_id)
            if isinstance(raw_encontrado, dict) and raw_encontrado:
                raw_total.setdefault(item_id, raw_encontrado)
            if len(ids) >= limite:
                logger.warning("[RENOVACAO ML] Varredura da campanha %s limitada a %s anuncios", campanha_id, limite)
                break

    logger.info("[RENOVACAO ML] Campanha %s: %s item(ns) apos complemento por varredura.", campanha_id, len(ids))
    _renovacao_emitir_progresso(
        progress_callback,
        "Varredura",
        progress_end,
        f"Varredura concluida. {len(ids)} MLB(s) encontrados na campanha de origem.",
        campanha_id=campanha_id,
        encontrados=len(ids),
    )
    return ids, raw_total, cfg


def _renovacao_listar_itens_campanha(
    client_id: str,
    loja: str,
    cfg: dict,
    campanha_id: str,
    promotion_type: str,
    expected_count: int | None = None,
    progress_callback: Optional[Callable[[dict], None]] = None,
    progress_start: int = 15,
    progress_end: int = 55,
) -> tuple[list[dict], dict[str, dict], dict]:
    _renovacao_emitir_progresso(
        progress_callback,
        "Listagem",
        progress_start,
        f"Carregando MLBs da campanha {campanha_id}...",
        campanha_id=campanha_id,
    )
    tentativas = [
        {"status_item_preferencial": "active", "status_promocao": ""},
        {"status_item_preferencial": "", "status_promocao": "started"},
        {"status_item_preferencial": "", "status_promocao": "pending"},
        {"status_item_preferencial": "", "status_promocao": ""},
    ]
    ids = []
    raw_total = {}
    for idx_tentativa, tentativa in enumerate(tentativas):
        pct_tentativa = progress_start + (
            max(1, progress_end - progress_start) * (idx_tentativa + 1) / (len(tentativas) + 1)
        )
        _renovacao_emitir_progresso(
            progress_callback,
            "Listagem",
            pct_tentativa,
            f"Consultando itens da campanha no Mercado Livre ({idx_tentativa + 1}/{len(tentativas)})...",
            campanha_id=campanha_id,
            tentativa=idx_tentativa + 1,
        )
        itens, raw_por_item, cfg = _ml_listar_itens_promocao_com_raw(
            client_id,
            loja,
            cfg,
            campanha_id,
            promotion_type=promotion_type or "SELLER_CAMPAIGN",
            usar_fallback_pesado=(idx_tentativa == len(tentativas) - 1),
            max_items=5000,
            buscar_detalhes=False,
            status_item_preferencial=tentativa["status_item_preferencial"],
            status_promocao=tentativa["status_promocao"],
        )
        for item in itens or []:
            item_id = str((item or {}).get("id") or "").strip()
            if item_id and item_id not in ids:
                ids.append(item_id)
        for item_id, raw in (raw_por_item or {}).items():
            raw_total.setdefault(str(item_id).strip(), raw)
    alvo = int(expected_count or 0)
    if alvo and len(ids) < min(alvo, 5000):
        logger.warning(
            "[RENOVACAO ML] Campanha %s retornou %s/%s itens pelo endpoint direto; complementando por varredura.",
            campanha_id,
            len(ids),
            alvo,
        )
        _renovacao_emitir_progresso(
            progress_callback,
            "Listagem",
            min(progress_end - 5, progress_start + 20),
            f"Endpoint direto retornou {len(ids)}/{alvo}. Complementando por varredura nos anuncios ativos...",
            campanha_id=campanha_id,
            encontrados=len(ids),
            esperado=alvo,
        )
        ids, raw_total, cfg = _renovacao_complementar_itens_campanha_por_varredura(
            client_id,
            loja,
            cfg,
            campanha_id,
            ids,
            raw_total,
            max_items=max(5000, alvo),
            progress_callback=progress_callback,
            progress_start=min(progress_end - 20, progress_start + 22),
            progress_end=progress_end,
        )
    else:
        _renovacao_emitir_progresso(
            progress_callback,
            "Listagem",
            progress_end,
            f"Campanha carregada com {len(ids)} MLB(s).",
            campanha_id=campanha_id,
            encontrados=len(ids),
            esperado=alvo,
        )
    return [{"id": item_id} for item_id in ids], raw_total, cfg


def _renovacao_criar_campanha_ml(
    client_id: str,
    loja: str,
    cfg: dict,
    nome: str,
    campanha_fonte: dict,
    datas_alvo: tuple[str, str] | None = None,
) -> tuple[str, dict, dict]:
    inicio, fim = datas_alvo or _renovacao_datas_proximo_mes(campanha_fonte or {})
    payload = {
        "promotion_type": "SELLER_CAMPAIGN",
        "sub_type": "FLEXIBLE_PERCENTAGE",
        "name": nome,
        "start_date": inicio,
        "finish_date": fim,
    }
    resp, cfg = _ml_api_request(
        client_id,
        loja,
        cfg,
        "POST",
        "https://api.mercadolibre.com/seller-promotions/promotions",
        params={"app_version": "v2"},
        json=payload,
        timeout=30,
    )
    if resp.status_code not in (200, 201):
        raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao criar campanha no Mercado Livre"))
    data = _renovacao_json_response(resp)
    nova_id = str(data.get("id") or data.get("promotion_id") or data.get("campaign_id") or "").strip()
    if not nova_id:
        raise HTTPException(status_code=500, detail="Mercado Livre criou a campanha, mas nao retornou o ID.")
    return nova_id, payload, cfg


def _renovacao_normalizar_data_periodo(valor: str | None, *, fim: bool = False) -> str:
    texto = str(valor or "").strip()
    if not texto:
        return ""
    data = _renovacao_parse_data_ml(texto)
    if data:
        hora = "23:59:59" if fim else "00:00:00"
        return f"{data:%Y-%m-%d}T{hora}"
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", texto):
        return f"{texto}T{'23:59:59' if fim else '00:00:00'}"
    return texto


def _renovacao_data_periodo_igual(enviada: str, retornada: str | None) -> bool:
    if not enviada:
        return True
    enviada_dt = _renovacao_parse_data_ml(enviada)
    retornada_dt = _renovacao_parse_data_ml(retornada)
    if enviada_dt and retornada_dt:
        return enviada_dt.date() == retornada_dt.date()
    return str(enviada or "")[:10] == str(retornada or "")[:10]


def _renovacao_buscar_campanha_ml(
    client_id: str,
    loja: str,
    cfg: dict,
    campanha_id: str,
    promotion_type: str,
) -> tuple[dict, dict]:
    resp, cfg = _ml_api_request(
        client_id,
        loja,
        cfg,
        "GET",
        f"https://api.mercadolibre.com/seller-promotions/promotions/{campanha_id}",
        params={"app_version": "v2", "promotion_type": promotion_type},
        timeout=25,
    )
    if resp.status_code != 200:
        return {}, cfg
    data = _renovacao_json_response(resp)
    if isinstance(data, dict):
        return data, cfg
    return {}, cfg


def _renovacao_descrever_periodo_campanha(campanha: dict | None) -> str:
    campanha = campanha if isinstance(campanha, dict) else {}
    inicio = campanha.get("start_date") or campanha.get("date_start") or campanha.get("begin_date") or ""
    fim = campanha.get("finish_date") or campanha.get("end_date") or campanha.get("date_end") or ""
    return f"{str(inicio)[:10] or '-'} ate {str(fim)[:10] or '-'}"


def _renovacao_atualizar_periodo_campanha_ml(
    client_id: str,
    loja: str,
    campanha_id: str,
    start_date: str | None,
    finish_date: str | None,
    promotion_type: str = "SELLER_CAMPAIGN",
    nome: str | None = None,
) -> dict:
    nome_loja = str(loja or "").strip()
    campanha_id = str(campanha_id or "").strip()
    promotion_type = str(promotion_type or "SELLER_CAMPAIGN").strip() or "SELLER_CAMPAIGN"
    if not nome_loja or not campanha_id:
        raise HTTPException(status_code=400, detail="Selecione a loja e a campanha.")

    inicio = _renovacao_normalizar_data_periodo(start_date, fim=False)
    fim = _renovacao_normalizar_data_periodo(finish_date, fim=True)
    if not inicio and not fim:
        raise HTTPException(status_code=400, detail="Informe pelo menos uma data para alterar o periodo.")

    payload = {}
    if str(nome or "").strip():
        payload["name"] = str(nome or "").strip()
    if inicio:
        payload["start_date"] = inicio
    if fim:
        payload["finish_date"] = fim

    inicio_dt = _renovacao_parse_data_ml(inicio) if inicio else None
    fim_dt = _renovacao_parse_data_ml(fim) if fim else None
    if inicio_dt and fim_dt and fim_dt <= inicio_dt:
        raise HTTPException(status_code=400, detail="A data final precisa ser maior que a data inicial.")

    cfg = _obter_cfg_ml(client_id, nome_loja)
    resp, cfg = _ml_api_request(
        client_id,
        nome_loja,
        cfg,
        "PUT",
        f"https://api.mercadolibre.com/seller-promotions/promotions/{campanha_id}",
        params={"app_version": "v2", "promotion_type": promotion_type},
        json=payload,
        timeout=30,
    )
    if resp.status_code not in (200, 201):
        raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao alterar periodo da campanha no Mercado Livre"))
    resposta_put = _renovacao_json_response(resp)
    campanha_verificada, cfg = _renovacao_buscar_campanha_ml(client_id, nome_loja, cfg, campanha_id, promotion_type)
    if not campanha_verificada or not (
        campanha_verificada.get("start_date")
        or campanha_verificada.get("date_start")
        or campanha_verificada.get("begin_date")
        or campanha_verificada.get("finish_date")
        or campanha_verificada.get("end_date")
        or campanha_verificada.get("date_end")
    ):
        try:
            campanhas, cfg = _renovacao_ml_listar_campanhas_usuario(client_id, nome_loja)
            campanha_verificada = next(
                (item for item in campanhas if str(item.get("id") or "") == campanha_id),
                {},
            )
        except Exception as exc:
            logger.warning(
                "[RENOVACAO PERIODO] Nao foi possivel confirmar periodo atualizado loja=%s campanha=%s: %s",
                nome_loja,
                campanha_id,
                exc,
            )

    inicio_ok = _renovacao_data_periodo_igual(inicio, campanha_verificada.get("start_date")) if inicio and campanha_verificada else True
    fim_ok = _renovacao_data_periodo_igual(fim, campanha_verificada.get("finish_date")) if fim and campanha_verificada else True
    if campanha_verificada and (not inicio_ok or not fim_ok):
        periodo_atual = _renovacao_descrever_periodo_campanha(campanha_verificada)
        logger.warning(
            "[RENOVACAO PERIODO] Mercado Livre manteve periodo antigo loja=%s campanha=%s payload=%s retorno=%s",
            nome_loja,
            campanha_id,
            payload,
            campanha_verificada,
        )
        raise HTTPException(
            status_code=409,
            detail=(
                "Mercado Livre recebeu a solicitacao, mas manteve o periodo atual "
                f"({periodo_atual}). Verifique se o novo intervalo excede o limite permitido "
                "ou se o status da campanha permite alterar essa data."
            ),
        )
    return {
        "success": True,
        "loja": nome_loja,
        "campanha_id": campanha_id,
        "payload": payload,
        "campaign": campanha_verificada or resposta_put,
    }


def _renovacao_remover_agendamento_campanha(client_id: str, loja: str, campanha_id: str) -> None:
    with RENOVACAO_AGENDAMENTO_LOCK:
        payload = _renovacao_agendamentos_carregar(client_id)
        chave = _renovacao_agendamento_key(loja, campanha_id)
        payload["agendamentos"] = [
            _renovacao_agendamento_sanitizar(entry)
            for entry in (payload.get("agendamentos") or [])
            if _renovacao_agendamento_key(entry.get("loja"), entry.get("campanha_id")) != chave
        ]
        _renovacao_agendamentos_salvar(client_id, payload)


def _renovacao_deletar_campanha_ml(
    client_id: str,
    loja: str,
    campanha_id: str,
    promotion_type: str = "SELLER_CAMPAIGN",
) -> dict:
    nome_loja = str(loja or "").strip()
    campanha_id = str(campanha_id or "").strip()
    promotion_type = str(promotion_type or "SELLER_CAMPAIGN").strip() or "SELLER_CAMPAIGN"
    if not nome_loja or not campanha_id:
        raise HTTPException(status_code=400, detail="Selecione a loja e a campanha.")

    cfg = _obter_cfg_ml(client_id, nome_loja)
    resp, cfg = _ml_api_request(
        client_id,
        nome_loja,
        cfg,
        "DELETE",
        f"https://api.mercadolibre.com/seller-promotions/promotions/{campanha_id}",
        params={"app_version": "v2", "promotion_type": promotion_type},
        timeout=30,
    )
    if resp.status_code not in (200, 202, 204):
        raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao deletar campanha no Mercado Livre"))
    _renovacao_remover_agendamento_campanha(client_id, nome_loja, campanha_id)
    return {
        "success": True,
        "loja": nome_loja,
        "campanha_id": campanha_id,
        "deleted": True,
    }


def _renovacao_adicionar_item_campanha(
    client_id: str,
    loja: str,
    cfg: dict,
    item_id: str,
    nova_campanha_id: str,
    desconto: float,
    preco_base: float,
    preco_promocional: Optional[float],
    preferir_percentual: bool = False,
) -> tuple[bool, str, dict]:
    deal_price = preco_promocional
    if deal_price is None and preco_base:
        deal_price = round(float(preco_base) * (1 - (float(desconto) / 100)), 2)
    if deal_price is None or deal_price <= 0:
        return False, "preco promocional invalido", cfg

    payload_preco = {
        "promotion_id": nova_campanha_id,
        "promotion_type": "SELLER_CAMPAIGN",
        "deal_price": round(float(deal_price), 2),
    }
    payload_percentual = {
        "promotion_id": nova_campanha_id,
        "promotion_type": "SELLER_CAMPAIGN",
        "discount_percentage": round(float(desconto), 4),
    }
    payloads = [payload_percentual, payload_preco] if preferir_percentual else [payload_preco, payload_percentual]
    ultimo_erro = ""
    for payload in payloads:
        resp, cfg = _ml_api_request(
            client_id,
            loja,
            cfg,
            "POST",
            f"https://api.mercadolibre.com/seller-promotions/items/{item_id}",
            params={"app_version": "v2"},
            json=payload,
            timeout=20,
        )
        if resp.status_code in (200, 201):
            return True, "", cfg
        ultimo_erro = _ml_parse_error_detail(resp, f"Erro {resp.status_code} ao incluir item")
    return False, ultimo_erro, cfg


def _renovacao_copiar_mlbs_campanha(
    client_id: str,
    loja: str,
    cfg: dict,
    campanha_origem_id: str,
    campanha_destino_id: str,
    promotion_type_origem: str = "SELLER_CAMPAIGN",
    promotion_type_destino: str = "SELLER_CAMPAIGN",
    preferir_percentual: bool = False,
    expected_origem_count: int | None = None,
    progress_callback: Optional[Callable[[dict], None]] = None,
) -> tuple[dict, dict]:
    _renovacao_emitir_progresso(
        progress_callback,
        "Origem",
        15,
        "Carregando MLBs ativos ou programados da campanha de origem...",
        campanha_id=campanha_origem_id,
        esperado=expected_origem_count or 0,
    )
    itens_ref, raw_por_item, cfg = _renovacao_listar_itens_campanha(
        client_id,
        loja,
        cfg,
        campanha_origem_id,
        promotion_type_origem or "SELLER_CAMPAIGN",
        expected_count=expected_origem_count,
        progress_callback=progress_callback,
        progress_start=18,
        progress_end=48,
    )
    item_ids = [str(item.get("id") or "").strip() for item in itens_ref if str(item.get("id") or "").strip()]
    item_ids = list(dict.fromkeys(item_ids))
    if not item_ids:
        raise HTTPException(status_code=400, detail="Nao encontrei MLBs ativos ou programados nessa campanha para copiar.")
    _renovacao_emitir_progresso(
        progress_callback,
        "Origem",
        50,
        f"Campanha de origem carregada com {len(item_ids)} MLB(s).",
        total=len(item_ids),
    )

    ids_destino: set[str] = set()
    try:
        _renovacao_emitir_progresso(
            progress_callback,
            "Destino",
            52,
            "Conferindo MLBs que ja estao na campanha nova...",
            campanha_id=campanha_destino_id,
        )
        itens_destino, _raw_destino, cfg = _renovacao_listar_itens_campanha(
            client_id,
            loja,
            cfg,
            campanha_destino_id,
            promotion_type_destino or "SELLER_CAMPAIGN",
            progress_callback=progress_callback,
            progress_start=53,
            progress_end=58,
        )
        ids_destino = {
            str(item.get("id") or "").strip()
            for item in itens_destino
            if str(item.get("id") or "").strip()
        }
    except Exception as exc:
        logger.warning("[RENOVACAO ML] Falha ao verificar itens da campanha destino %s: %s", campanha_destino_id, exc)
        ids_destino = set()

    item_ids_para_incluir = [item_id for item_id in item_ids if item_id not in ids_destino]
    _renovacao_emitir_progresso(
        progress_callback,
        "Comparacao",
        60,
        f"{len(item_ids_para_incluir)} MLB(s) faltam na campanha nova. {len(ids_destino.intersection(set(item_ids)))} ja estavam presentes.",
        faltantes=len(item_ids_para_incluir),
        ja_presentes=len(ids_destino.intersection(set(item_ids))),
    )
    detalhes_por_id = {}
    if item_ids_para_incluir:
        _renovacao_emitir_progresso(
            progress_callback,
            "Detalhes",
            62,
            f"Buscando detalhes de {len(item_ids_para_incluir)} MLB(s) para calcular preco e desconto...",
            total=len(item_ids_para_incluir),
        )
        detalhes, cfg = _ml_buscar_itens_batch(client_id, loja, cfg, item_ids_para_incluir)
        detalhes_por_id = {str(item.get("id") or "").strip(): item for item in detalhes if isinstance(item, dict)}

    sucessos = []
    falhas = []
    total_para_incluir = len(item_ids_para_incluir)
    intervalo_emit = max(1, min(25, max(1, total_para_incluir // 50))) if total_para_incluir else 1
    for idx_item, item_id in enumerate(item_ids_para_incluir, start=1):
        if idx_item == 1 or idx_item == total_para_incluir or idx_item % intervalo_emit == 0:
            pct = 65 + (28 * idx_item / max(1, total_para_incluir))
            _renovacao_emitir_progresso(
                progress_callback,
                "Inclusao",
                pct,
                f"Incluindo MLB {idx_item}/{total_para_incluir}: {item_id}",
                item_id=item_id,
                processados=idx_item,
                total=total_para_incluir,
                incluidos=len(sucessos),
                falhas=len(falhas),
            )
        desconto, preco_base, preco_promocional = _renovacao_desconto_item(
            item_id,
            raw_por_item.get(item_id) or {},
            detalhes_por_id.get(item_id) or {},
        )
        if desconto is None or preco_base is None:
            raw_exato, cfg = _ml_obter_item_promocao_raw(
                client_id,
                loja,
                cfg,
                campanha_origem_id,
                promotion_type_origem or "SELLER_CAMPAIGN",
                item_id,
            )
            if raw_exato:
                desconto, preco_base, preco_promocional = _renovacao_desconto_item(
                    item_id,
                    raw_exato,
                    detalhes_por_id.get(item_id) or {},
                )
        if desconto is None or preco_base is None:
            falhas.append({"item_id": item_id, "erro": "Nao foi possivel identificar desconto/preco base"})
            continue
        ok, erro, cfg = _renovacao_adicionar_item_campanha(
            client_id,
            loja,
            cfg,
            item_id,
            campanha_destino_id,
            desconto,
            preco_base,
            preco_promocional,
            preferir_percentual=preferir_percentual,
        )
        if ok:
            sucessos.append({"item_id": item_id, "desconto": desconto})
        else:
            falhas.append({"item_id": item_id, "erro": erro})

    _renovacao_emitir_progresso(
        progress_callback,
        "Finalizando",
        96,
        f"Finalizando sincronizacao. Incluidos: {len(sucessos)}. Ja presentes: {len(ids_destino.intersection(set(item_ids)))}. Falhas: {len(falhas)}.",
        incluidos=len(sucessos),
        falhas=len(falhas),
    )
    return {
        "total_origem": len(item_ids),
        "mlbs_ja_presentes": len(ids_destino.intersection(set(item_ids))),
        "faltantes": len(item_ids_para_incluir),
        "incluidos": len(sucessos),
        "falhas": falhas[:50],
        "falhas_total": len(falhas),
    }, cfg


def _renovacao_criar_ou_completar_proximo_mes(
    client_id: str,
    loja: str,
    campanha_id: str,
    nome: str = "",
    promotion_type: str = "SELLER_CAMPAIGN",
) -> dict:
    loja = str(loja or "").strip()
    campanha_id = str(campanha_id or "").strip()
    nome = str(nome or "").strip()
    promotion_type = str(promotion_type or "SELLER_CAMPAIGN").strip() or "SELLER_CAMPAIGN"
    if not loja or not campanha_id:
        raise HTTPException(status_code=400, detail="Informe loja e campanha de origem.")

    campanhas, cfg = _renovacao_ml_listar_campanhas_usuario(client_id, loja)
    campanha_fonte = next((c for c in campanhas if str(c.get("id") or "").strip() == campanha_id), None)
    if not campanha_fonte:
        campanha_fonte = {"id": campanha_id, "promotion_type": promotion_type}
    if not nome:
        nome = _renovacao_nome_proximo_mes(campanha_fonte)
    if not nome:
        raise HTTPException(status_code=400, detail="Informe o nome da nova campanha.")

    inicio_alvo, fim_alvo = _renovacao_datas_proximo_mes(campanha_fonte)
    campanha_destino = _renovacao_encontrar_campanha_destino(campanhas, nome, inicio_alvo)
    campanha_existente = bool(campanha_destino)
    if campanha_destino:
        nova_campanha_id = str(campanha_destino.get("id") or "").strip()
        payload_campanha = {
            "name": str(campanha_destino.get("name") or nome).strip(),
            "start_date": campanha_destino.get("start_date") or inicio_alvo,
            "finish_date": campanha_destino.get("finish_date") or fim_alvo,
        }
        promotion_type_destino = str(campanha_destino.get("promotion_type") or campanha_destino.get("type") or "SELLER_CAMPAIGN").strip() or "SELLER_CAMPAIGN"
    else:
        nova_campanha_id, payload_campanha, cfg = _renovacao_criar_campanha_ml(
            client_id,
            loja,
            cfg,
            nome,
            campanha_fonte,
            datas_alvo=(inicio_alvo, fim_alvo),
        )
        promotion_type_destino = "SELLER_CAMPAIGN"

    itens_ref, raw_por_item, cfg = _renovacao_listar_itens_campanha(client_id, loja, cfg, campanha_id, promotion_type)
    item_ids = [str(item.get("id") or "").strip() for item in itens_ref if str(item.get("id") or "").strip()]
    item_ids = list(dict.fromkeys(item_ids))
    if not item_ids:
        raise HTTPException(status_code=400, detail="Nao encontrei MLBs ativos ou programados nessa campanha para copiar.")

    ids_destino: set[str] = set()
    if campanha_existente:
        try:
            itens_destino, _raw_destino, cfg = _renovacao_listar_itens_campanha(
                client_id,
                loja,
                cfg,
                nova_campanha_id,
                promotion_type_destino,
            )
            ids_destino = {
                str(item.get("id") or "").strip()
                for item in itens_destino
                if str(item.get("id") or "").strip()
            }
        except Exception as exc:
            logger.warning("[RENOVACAO ML] Falha ao verificar itens da campanha existente %s: %s", nova_campanha_id, exc)
            ids_destino = set()

    item_ids_para_incluir = [item_id for item_id in item_ids if item_id not in ids_destino]
    detalhes_por_id = {}
    if item_ids_para_incluir:
        detalhes, cfg = _ml_buscar_itens_batch(client_id, loja, cfg, item_ids_para_incluir)
        detalhes_por_id = {str(item.get("id") or "").strip(): item for item in detalhes if isinstance(item, dict)}

    sucessos = []
    falhas = []
    for item_id in item_ids_para_incluir:
        desconto, preco_base, preco_promocional = _renovacao_desconto_item(item_id, raw_por_item.get(item_id) or {}, detalhes_por_id.get(item_id) or {})
        if desconto is None or preco_base is None:
            falhas.append({"item_id": item_id, "erro": "Nao foi possivel identificar desconto/preco base"})
            continue
        ok, erro, cfg = _renovacao_adicionar_item_campanha(
            client_id,
            loja,
            cfg,
            item_id,
            nova_campanha_id,
            desconto,
            preco_base,
            preco_promocional,
        )
        if ok:
            sucessos.append({"item_id": item_id, "desconto": desconto})
        else:
            falhas.append({"item_id": item_id, "erro": erro})

    _cache_invalidar_loja(client_id, loja)
    return {
        "success": True,
        "loja": loja,
        "origem": {"id": campanha_id, "nome": campanha_fonte.get("name") or campanha_id},
        "nova_campanha": {
            "id": nova_campanha_id,
            "nome": payload_campanha.get("name") or nome,
            "start_date": payload_campanha.get("start_date"),
            "finish_date": payload_campanha.get("finish_date"),
            "existente": campanha_existente,
        },
        "campanha_existente": campanha_existente,
        "total_origem": len(item_ids),
        "mlbs_ja_presentes": len(ids_destino.intersection(set(item_ids))),
        "faltantes": len(item_ids_para_incluir),
        "incluidos": len(sucessos),
        "falhas": falhas[:50],
        "falhas_total": len(falhas),
    }


def _renovacao_sincronizar_promocao_existente(
    client_id: str,
    loja: str,
    campanha_origem_id: str,
    campanha_destino_id: str,
    promotion_type_origem: str = "SELLER_CAMPAIGN",
    promotion_type_destino: str = "SELLER_CAMPAIGN",
    progress_callback: Optional[Callable[[dict], None]] = None,
) -> dict:
    _renovacao_emitir_progresso(
        progress_callback,
        "Preparando",
        5,
        "Validando loja e campanhas selecionadas...",
    )
    loja = str(loja or "").strip()
    campanha_origem_id = str(campanha_origem_id or "").strip()
    campanha_destino_id = str(campanha_destino_id or "").strip()
    promotion_type_origem = str(promotion_type_origem or "SELLER_CAMPAIGN").strip() or "SELLER_CAMPAIGN"
    promotion_type_destino = str(promotion_type_destino or "SELLER_CAMPAIGN").strip() or "SELLER_CAMPAIGN"
    if not loja or not campanha_origem_id or not campanha_destino_id:
        raise HTTPException(status_code=400, detail="Informe loja, campanha de origem e campanha nova.")
    if campanha_origem_id == campanha_destino_id:
        raise HTTPException(status_code=400, detail="A campanha de origem e a campanha nova devem ser diferentes.")

    _renovacao_emitir_progresso(
        progress_callback,
        "Campanhas",
        10,
        "Listando campanhas criadas pelo usuario no Mercado Livre...",
        loja=loja,
    )
    campanhas, cfg = _renovacao_ml_listar_campanhas_usuario(client_id, loja)
    campanha_origem = next((c for c in campanhas if str(c.get("id") or "").strip() == campanha_origem_id), None) or {
        "id": campanha_origem_id,
        "promotion_type": promotion_type_origem,
    }
    campanha_destino = next((c for c in campanhas if str(c.get("id") or "").strip() == campanha_destino_id), None) or {
        "id": campanha_destino_id,
        "promotion_type": promotion_type_destino,
    }
    promotion_type_origem = str(campanha_origem.get("promotion_type") or campanha_origem.get("type") or promotion_type_origem).strip() or "SELLER_CAMPAIGN"
    promotion_type_destino = str(campanha_destino.get("promotion_type") or campanha_destino.get("type") or promotion_type_destino).strip() or "SELLER_CAMPAIGN"
    active_origem = _parse_float_flex(campanha_origem.get("active_count"))
    programados_origem = _parse_float_flex(campanha_origem.get("programmed_count"))
    if programados_origem is None:
        programados_origem = _parse_float_flex(campanha_origem.get("scheduled_count"))
    expected_origem_count = int(active_origem or 0) + int(programados_origem or 0)
    if expected_origem_count <= 0:
        total_origem = _parse_float_flex(campanha_origem.get("total_count"))
        expected_origem_count = int(total_origem or 0)
    _renovacao_emitir_progresso(
        progress_callback,
        "Campanhas",
        12,
        f"Origem localizada. Ativos/programados esperados: {expected_origem_count or '-'}."
    )

    copia, cfg = _renovacao_copiar_mlbs_campanha(
        client_id,
        loja,
        cfg,
        campanha_origem_id,
        campanha_destino_id,
        promotion_type_origem,
        promotion_type_destino,
        preferir_percentual=True,
        expected_origem_count=expected_origem_count or None,
        progress_callback=progress_callback,
    )

    _renovacao_emitir_progresso(
        progress_callback,
        "Finalizando",
        98,
        "Atualizando cache local das campanhas...",
    )
    _cache_invalidar_loja(client_id, loja)
    return {
        "success": True,
        "loja": loja,
        "origem": {
            "id": campanha_origem_id,
            "nome": campanha_origem.get("name") or campanha_origem.get("title") or campanha_origem_id,
        },
        "campanha_destino": {
            "id": campanha_destino_id,
            "nome": campanha_destino.get("name") or campanha_destino.get("title") or campanha_destino_id,
            "start_date": campanha_destino.get("start_date"),
            "finish_date": campanha_destino.get("finish_date"),
        },
        **copia,
    }


@app.get("/api/renovacao/campanhas-usuario")
def renovacao_listar_campanhas_usuario(loja: str, client_id: str = Depends(get_tenant_id)):
    campanhas, _cfg = _renovacao_ml_listar_campanhas_usuario(client_id, loja)
    ag_payload = _renovacao_agendamentos_carregar(client_id)
    ag_por_chave = {}
    for entry in ag_payload.get("agendamentos") or []:
        ag = _renovacao_agendamento_sanitizar(entry)
        if _renovacao_normalizar_nome(ag.get("loja")) == _renovacao_normalizar_nome(loja):
            ag_por_chave[_renovacao_agendamento_key(ag.get("loja"), ag.get("campanha_id"))] = ag
    for campanha in campanhas:
        ag = ag_por_chave.get(_renovacao_agendamento_key(loja, campanha.get("id")))
        campanha["auto_renew_enabled"] = bool((ag or {}).get("enabled"))
        campanha["agendamento"] = ag or {
            "enabled": False,
            "loja": str(loja or "").strip(),
            "campanha_id": str(campanha.get("id") or "").strip(),
            "last_error": "",
        }
        campanha.pop("raw", None)
    return {"success": True, "loja": loja, "campaigns": campanhas, "total": len(campanhas)}


