@app.get("/api/favoritos/ml/skus-anuncios")
def favoritos_ml_listar_skus_anuncios(
    request: Request,
    loja: Optional[str] = None,
    sku: Optional[str] = None,
    apenas_lojas: bool = False,
    todas_lojas: bool = False,
    client_id: str = Depends(get_tenant_id),
):
    lojas_validas = _lojas_favoritos_com_bling_ml(client_id)
    lojas_payload = [
        {"nome": str(item.get("nome") or "").strip()}
        for item in lojas_validas
        if str(item.get("nome") or "").strip()
    ]
    if not lojas_payload:
        return {
            "success": True,
            "lojas": [],
            "loja": "",
            "skus": [],
            "total": 0,
            "total_anuncios": 0,
            "warning": "Nenhuma loja com Bling e Mercado Livre conectados foi encontrada em IntegraÃ§Ãµes.",
        }

    if apenas_lojas:
        return {
            "success": True,
            "lojas": lojas_payload,
            "loja": "",
            "skus": [],
            "total": 0,
            "total_anuncios": 0,
        }

    username = _extrair_username_do_request(request)
    sku_busca = str(sku or "").strip()

    if todas_lojas and not sku_busca:
        todos_skus: list[dict] = []
        total_anuncios = 0
        avisos: list[str] = []

        def _carregar_loja_favoritos(loja_info_item: dict) -> dict:
            nome_loja_item = str(loja_info_item.get("nome") or "").strip()
            if not nome_loja_item:
                return {"loja": "", "skus": [], "total_anuncios": 0, "warning": ""}
            cfg = _obter_cfg_ml(client_id, nome_loja_item)
            itens, _cfg = _ml_favoritos_listar_todos_itens_ativos_loja(client_id, nome_loja_item, cfg)
            skus_loja = _favoritos_ml_skus_unicos_itens(itens)
            for item_sku in skus_loja:
                if isinstance(item_sku, dict):
                    item_sku["loja"] = nome_loja_item
                    item_sku["loja_sync"] = nome_loja_item
            skus_loja = _favoritos_ml_enriquecer_estoque_cadastro(client_id, nome_loja_item, skus_loja)
            skus_loja = _favoritos_enriquecer_pesquisas_usuario(
                client_id,
                username,
                nome_loja_item,
                skus_loja,
            )
            return {"loja": nome_loja_item, "skus": skus_loja, "total_anuncios": len(itens), "warning": ""}

        lojas_para_carregar = [item for item in lojas_validas if str(item.get("nome") or "").strip()]
        max_workers = min(4, max(1, len(lojas_para_carregar)))
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futuros = {executor.submit(_carregar_loja_favoritos, loja_info_item): loja_info_item for loja_info_item in lojas_para_carregar}
            for futuro in as_completed(futuros):
                nome_loja_item = str((futuros[futuro] or {}).get("nome") or "").strip()
                try:
                    resultado = futuro.result() or {}
                    todos_skus.extend(resultado.get("skus") or [])
                    total_anuncios += int(resultado.get("total_anuncios") or 0)
                except HTTPException as exc:
                    detalhe = str(getattr(exc, "detail", "") or exc)
                    avisos.append(f"{nome_loja_item}: {detalhe}")
                    logger.warning("[Favoritos ML] Loja ignorada ao listar todos os SKUs (%s): %s", nome_loja_item, detalhe)
                except Exception as exc:
                    avisos.append(f"{nome_loja_item}: {exc}")
                    logger.exception("[Favoritos ML] Falha ao listar SKUs da loja %s no carregamento geral: %s", nome_loja_item, exc)

        todos_skus.sort(key=lambda item: (
            str(item.get("loja") or item.get("loja_sync") or "").lower(),
            str(item.get("sku") or "").lower(),
        ))
        return {
            "success": True,
            "lojas": lojas_payload,
            "loja": "__todas",
            "todas_lojas": True,
            "skus": todos_skus,
            "total": len(todos_skus),
            "total_anuncios": total_anuncios,
            "warnings": avisos,
            "warning": " | ".join(avisos[:3]) if avisos else "",
        }

    loja_chave = _chave_loja_favoritos(loja)
    loja_info = None
    if loja_chave:
        for candidata in lojas_validas:
            if _chave_loja_favoritos(candidata.get("nome")) == loja_chave:
                loja_info = candidata
                break
    if loja_info is None:
        loja_info = lojas_validas[0]

    nome_loja = str(loja_info.get("nome") or "").strip()
    try:
        cfg = _obter_cfg_ml(client_id, nome_loja)
        if sku_busca:
            itens, _cfg = _ml_favoritos_buscar_itens_por_sku(client_id, nome_loja, cfg, sku_busca)
        else:
            itens, _cfg = _ml_favoritos_listar_todos_itens_ativos_loja(client_id, nome_loja, cfg)
        skus = _favoritos_ml_skus_unicos_itens(itens)
        for item_sku in skus:
            if isinstance(item_sku, dict):
                item_sku["loja"] = nome_loja
                item_sku["loja_sync"] = nome_loja
        if sku_busca:
            skus = _favoritos_ml_garantir_sku_busca(skus, sku_busca, itens)
            for item_sku in skus:
                if isinstance(item_sku, dict):
                    item_sku["loja"] = nome_loja
                    item_sku["loja_sync"] = nome_loja
        skus = _favoritos_ml_enriquecer_estoque_cadastro(client_id, nome_loja, skus)
        skus = _favoritos_enriquecer_pesquisas_usuario(
            client_id,
            username,
            nome_loja,
            skus,
        )
        return {
            "success": True,
            "lojas": lojas_payload,
            "loja": nome_loja,
            "skus": skus,
            "total": len(skus),
            "total_anuncios": len(itens),
            "busca_sku": sku_busca,
        }
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("[Favoritos ML] Falha ao listar SKUs de anuncios da loja %s: %s", nome_loja, exc)
        raise HTTPException(status_code=500, detail=f"Erro ao listar SKUs do Mercado Livre: {exc}")


def _ml_listar_promocoes_ativas_payload(client_id: str, loja: str) -> dict:
    nome_loja = str(loja or "").strip()
    if not nome_loja:
        raise HTTPException(status_code=400, detail="Informe a loja do Mercado Livre.")

    cache_key = f"promocoes:{client_id}:{nome_loja}"
    cached = _ml_cache_get(cache_key, _ML_CACHE_TTL_CAMPANHA)
    if isinstance(cached, dict):
        return cached
    stale_cache = _ml_cache_get_stale(cache_key, _ML_CACHE_TTL_CAMPANHA_STALE)

    cfg = _obter_cfg_ml(client_id, nome_loja)
    user_id = str(cfg.get("user_id") or "").strip()
    if not user_id:
        raise HTTPException(status_code=400, detail="ID do usuario do Mercado Livre nao encontrado para esta loja.")

    try:
        timeout_promocoes = int(float(str(os.getenv("ML_PROMO_TIMEOUT", "18") or "18").replace(",", ".")))
    except Exception:
        timeout_promocoes = 18
    timeout_promocoes = max(8, min(timeout_promocoes, 45))
    try:
        tentativas_promocoes = int(float(str(os.getenv("ML_PROMO_MAX_ATTEMPTS", "3") or "3").replace(",", ".")))
    except Exception:
        tentativas_promocoes = 3
    tentativas_promocoes = max(1, min(tentativas_promocoes, 6))

    try:
        resp, cfg = _ml_api_request_com_retry(
            client_id,
            nome_loja,
            cfg,
            "GET",
            f"https://api.mercadolibre.com/seller-promotions/users/{user_id}",
            params={"app_version": "v2"},
            timeout=timeout_promocoes,
            max_attempts=tentativas_promocoes,
        )
    except Exception as exc:
        if isinstance(stale_cache, dict):
            logger.warning(
                "[FAVORITOS PROMO] Usando cache stale de promocoes para %s/%s apos erro na API: %s",
                client_id,
                nome_loja,
                exc,
            )
            return stale_cache
        raise HTTPException(
            status_code=504,
            detail="Mercado Livre demorou para responder ao carregar promocoes desta loja. Tente novamente em instantes.",
        )

    if resp.status_code != 200:
        if isinstance(stale_cache, dict) and resp.status_code in (429, 500, 502, 503, 504):
            logger.warning(
                "[FAVORITOS PROMO] Usando cache stale de promocoes para %s/%s apos HTTP %s",
                client_id,
                nome_loja,
                resp.status_code,
            )
            return stale_cache
        raise HTTPException(status_code=resp.status_code, detail=_ml_parse_error_detail(resp, "Erro ao listar promocoes do Mercado Livre"))

    try:
        payload = resp.json() or {}
    except Exception:
        payload = {}

    if isinstance(payload, list):
        campanhas_raw = payload
    elif isinstance(payload, dict):
        campanhas_raw = payload.get("results") or payload.get("campaigns") or payload.get("promotions") or []
    else:
        campanhas_raw = []

    def _grupo_promocao(campanha: dict) -> str:
        tipo = str(campanha.get("type") or campanha.get("promotion_type") or "").strip().upper()
        nome = normalizar_texto(str(campanha.get("name") or campanha.get("title") or ""))
        if tipo in {"SELLER_CAMPAIGN", "SELLER_COUPON_CAMPAIGN"}:
            return "usuario"
        if tipo in {"SMART", "PRICE_MATCHING", "PRICE_MATCHING_MELI_ALL", "MARKETPLACE_CAMPAIGN", "PRE_NEGOTIATED"}:
            return "mercado_livre"
        if any(chave in nome for chave in ["aceler", "tarifa", "menos tarifa", "reduzimos", "aumente suas vendas"]):
            return "mercado_livre"
        return "outras"

    campanhas = []
    status_inativos = {"finished", "ended", "closed", "paused", "cancelled", "canceled", "inactive", "expired"}
    for item in campanhas_raw:
        if not isinstance(item, dict):
            continue
        campanha_id = str(item.get("id") or item.get("promotion_id") or "").strip()
        if not campanha_id:
            continue
        status = str(item.get("status") or item.get("state") or "").strip()
        if status.lower() in status_inativos:
            continue
        tipo = str(item.get("type") or item.get("promotion_type") or "").strip()
        active_count = _ml_extrair_contagem_campanha(item, [
            "active_count", "active_items_count", "active_item_count", "started_items_count",
            "participating_items_count", "items_active_count",
        ])
        eligible_count = _ml_extrair_contagem_campanha(item, [
            "eligible_count", "eligible_items_count", "eligible_item_count",
            "candidate_items_count", "candidate_count", "items_count", "item_count",
            "total_items", "products_count", "offers_count",
        ])
        campanhas.append({
            "id": campanha_id,
            "name": str(item.get("name") or item.get("title") or campanha_id).strip(),
            "title": str(item.get("title") or item.get("name") or campanha_id).strip(),
            "status": status,
            "type": tipo,
            "promotion_type": tipo,
            "selection_group": _grupo_promocao(item),
            "start_date": item.get("start_date") or item.get("date_start") or item.get("begin_date"),
            "finish_date": item.get("finish_date") or item.get("end_date") or item.get("date_end"),
            "active_count": active_count,
            "eligible_count": eligible_count,
        })

    payload = {
        "success": True,
        "loja": nome_loja,
        "campaigns": campanhas,
        "total": len(campanhas),
    }
    _ml_cache_set(cache_key, payload)
    return payload


def _ml_extrair_contagem_campanha(campanha: dict, chaves: list[str]):
    if not isinstance(campanha, dict):
        return None

    candidatos = []
    for chave in chaves:
        candidatos.append(campanha.get(chave))
    for grupo in ("summary", "totals", "paging", "items"):
        obj = campanha.get(grupo)
        if isinstance(obj, dict):
            for chave in chaves:
                candidatos.append(obj.get(chave))

    for valor in candidatos:
        try:
            if valor in (None, ""):
                continue
            numero = int(float(str(valor).replace(",", ".")))
            if numero >= 0:
                return numero
        except Exception:
            continue
    return None


def _ml_contar_itens_promocao_status(
    client_id: str,
    loja: str,
    cfg: dict,
    campaign_id: str,
    promotion_type: str = "",
    status_item: str = "",
) -> tuple[Optional[int], dict]:
    campaign_id = str(campaign_id or "").strip()
    promotion_type = str(promotion_type or "").strip()
    status_item = str(status_item or "").strip()
    if not campaign_id:
        return None, cfg

    urls = []
    if promotion_type:
        urls.append(f"https://api.mercadolibre.com/seller-promotions/promotions/{campaign_id}/items")
    urls.extend([
        f"https://api.mercadolibre.com/seller-promotions/{campaign_id}/items",
    ])

    for url in urls:
        offset = 0
        limit = 50
        total_contado = 0
        paginas_lidas = 0
        endpoint_ok = False
        vistos = set()
        while True:
            paginas_lidas += 1
            if paginas_lidas > 120:
                logger.warning(f"[PROMO CONTAGENS] Interrompendo contagem da promocao {campaign_id}: limite de paginas atingido")
                break

            params = {"app_version": "v2", "offset": offset, "limit": limit}
            if promotion_type and "/promotions/" in url:
                params["promotion_type"] = promotion_type
            if status_item:
                status_norm = status_item.lower()
                if status_norm in {"active", "started"}:
                    params["status"] = "started"
                elif status_norm in {"programmed", "scheduled", "pending"}:
                    params["status"] = "pending"
                elif status_norm in {"eligible", "candidate"}:
                    params["status"] = "candidate"
                elif status_norm == "paused":
                    params["status_item"] = "paused"
                else:
                    params["status"] = status_item
            try:
                resp, cfg = _ml_api_request_com_retry(
                    client_id,
                    loja,
                    cfg,
                    "GET",
                    url,
                    params=params,
                    timeout=30,
                    max_attempts=3,
                )
            except Exception as exc:
                logger.warning(
                    "[PROMO CONTAGENS] Mercado Livre demorou para responder ao contar %s da promocao %s: %s",
                    status_item or "total",
                    campaign_id,
                    exc,
                )
                break
            if resp.status_code == 404:
                break
            if resp.status_code != 200:
                logger.warning(f"[PROMO CONTAGENS] Falha ao contar {status_item or 'total'} da promocao {campaign_id}: {resp.status_code}")
                break
            endpoint_ok = True
            try:
                data = resp.json() or {}
            except Exception:
                data = {}
            paging = data.get("paging") if isinstance(data, dict) else {}
            total = _parse_float_flex((paging or {}).get("total")) if isinstance(paging, dict) else None
            if total is not None:
                return max(0, int(total)), cfg

            entries = (data.get("results") or data.get("items") or []) if isinstance(data, dict) else []
            for entry in entries:
                if isinstance(entry, dict):
                    raw_item = entry.get("item")
                    item_obj_id = raw_item.get("id") if isinstance(raw_item, dict) else raw_item
                    item_id = str(entry.get("item_id") or entry.get("itemId") or item_obj_id or entry.get("id") or "").strip()
                else:
                    item_id = str(entry or "").strip()
                chave = item_id or f"row:{offset}:{total_contado}"
                if chave not in vistos:
                    vistos.add(chave)
                    total_contado += 1

            offset += limit
            if not entries or len(entries) < limit:
                break
        if endpoint_ok:
            return total_contado, cfg
    return None, cfg


@app.get("/api/mercadolivre/promocoes")
def mercadolivre_listar_promocoes_ativas(
    loja: str,
    client_id: str = Depends(get_tenant_id),
):
    return _ml_listar_promocoes_ativas_payload(client_id, loja)


@app.get("/api/mercadolivre/promocoes/contagens")
def mercadolivre_listar_promocoes_contagens(
    loja: str,
    client_id: str = Depends(get_tenant_id),
):
    payload = _ml_listar_promocoes_ativas_payload(client_id, loja)
    loja_nome = payload.get("loja") or str(loja or "").strip()
    cache_key = f"camp_contagens:{client_id}:{loja_nome}:ativos_elegiveis_v3"
    cached = _ml_cache_get(cache_key, _ML_CACHE_TTL_CONTAGENS)
    if isinstance(cached, dict):
        return cached

    cfg = _obter_cfg_ml(client_id, loja_nome)
    counts = {}
    for campanha in payload.get("campaigns") or []:
        if not isinstance(campanha, dict):
            continue
        campanha_id = str(campanha.get("id") or "").strip()
        if not campanha_id:
            continue
        promotion_type = str(campanha.get("type") or campanha.get("promotion_type") or "").strip()
        active_count = _ml_extrair_contagem_campanha(campanha, ["active_count", "active_items_count", "active_item_count"])
        eligible_count = _ml_extrair_contagem_campanha(campanha, ["eligible_count", "eligible_items_count", "eligible_item_count", "candidate_items_count", "candidate_count", "items_count", "item_count", "total_items"])

        if active_count is None:
            active_count, cfg = _ml_contar_itens_promocao_status(client_id, loja_nome, cfg, campanha_id, promotion_type, "active")

        if eligible_count is None:
            for status_item in ("candidate", "pending", "eligible", ""):
                eligible_count, cfg = _ml_contar_itens_promocao_status(client_id, loja_nome, cfg, campanha_id, promotion_type, status_item)
                if eligible_count is not None:
                    break

        counts[campanha_id] = {
            "active": active_count,
            "active_count": active_count,
            "eligible": eligible_count,
            "eligible_count": eligible_count,
        }

    resultado = {
        "success": True,
        "loja": loja_nome,
        "counts": counts,
    }
    _ml_cache_set(cache_key, resultado)
    return resultado


@app.get("/api/favoritos/ml/promocoes")
def favoritos_ml_listar_promocoes_ativas(
    loja: str,
    client_id: str = Depends(get_tenant_id),
):
    return _ml_listar_promocoes_ativas_payload(client_id, loja)


def _favoritos_ml_float_close(valor, esperado, tolerancia: float = 0.08) -> bool:
    valor_num = _parse_float_flex(valor)
    esperado_num = _parse_float_flex(esperado)
    if valor_num is None or esperado_num is None:
        return False
    return abs(float(valor_num) - float(esperado_num)) <= float(tolerancia)


def _favoritos_ml_preco_ranking_simulado(req: FavoritosEfetivarPromocaoRequest) -> Optional[float]:
    sim = req.simulacao if isinstance(req.simulacao, dict) else {}
    for campo in ("precoRanking", "preco_ranking", "ranking_price"):
        valor = _parse_float_flex(sim.get(campo))
        if valor is not None and valor > 0:
            return float(valor)

    preco_competitivo = _parse_float_flex(
        sim.get("precoCompetitivo")
        if isinstance(sim, dict)
        else None
    )
    if preco_competitivo is None:
        preco_competitivo = _parse_float_flex(req.preco_competitivo)
    desconto_sorteado = _parse_float_flex(sim.get("descontoSorteado")) if isinstance(sim, dict) else None
    if preco_competitivo is not None and desconto_sorteado is not None:
        estimado = float(preco_competitivo) + float(desconto_sorteado)
        if estimado > 0:
            return estimado
    return None


def _favoritos_ml_preco_minimo_margem_simulado(req: FavoritosEfetivarPromocaoRequest) -> Optional[float]:
    sim = req.simulacao if isinstance(req.simulacao, dict) else {}
    for campo in (
        "precoMinimoMargem",
        "preco_minimo_margem",
        "minimum_margin_price",
        "preco_minimo_15",
    ):
        valor = _parse_float_flex(sim.get(campo))
        if valor is not None and valor > 0:
            return math.ceil(float(valor) * 100.0) / 100.0
    return None


def _favoritos_ml_preco_final_verificacao(verificacao: Optional[dict]) -> Optional[float]:
    if not isinstance(verificacao, dict):
        return None
    price_info = verificacao.get("price_info") if isinstance(verificacao.get("price_info"), dict) else {}
    for valor in (
        verificacao.get("promotion_price_raw"),
        price_info.get("price"),
        price_info.get("sale_price"),
        price_info.get("promotional_price"),
        verificacao.get("item_price"),
    ):
        preco = _parse_float_flex(valor)
        if preco is not None and preco > 0:
            return float(preco)
    return None


def _favoritos_ml_margem_estimada(req: FavoritosEfetivarPromocaoRequest, preco_venda: Optional[float]) -> Optional[float]:
    preco = _parse_float_flex(preco_venda)
    if preco is None or preco <= 0:
        return None
    sim = req.simulacao if isinstance(req.simulacao, dict) else {}
    custo = _parse_float_flex(sim.get("custo"))
    frete = _parse_float_flex(sim.get("frete"))
    tarifa_ref = _parse_float_flex(sim.get("tarifa"))
    imposto_ref = _parse_float_flex(sim.get("impostoValor") or sim.get("imposto_valor"))
    preco_ref = _parse_float_flex(
        sim.get("precoCompetitivo")
        or sim.get("precoPromocionalCalculado")
        or sim.get("precoPromocional")
        or req.preco_promocional
        or req.preco_competitivo
    )
    if custo is None or preco_ref is None or preco_ref <= 0:
        return None
    frete = frete or 0.0
    taxa_tarifa = max(0.0, float(tarifa_ref or 0.0)) / float(preco_ref)
    taxa_imposto = max(0.0, float(imposto_ref or 0.0)) / float(preco_ref)
    liquido = float(preco) - float(custo) - float(frete) - (float(preco) * taxa_tarifa) - (float(preco) * taxa_imposto)
    return (liquido * 100.0) / float(preco)


def _favoritos_ml_preco_contingencia_sem_promocao(
    req: FavoritosEfetivarPromocaoRequest,
    desconto_maximo: float = 1.5,
) -> Optional[float]:
    preco_ranking = _favoritos_ml_preco_ranking_simulado(req)
    if preco_ranking is None or preco_ranking <= 0:
        return None
    preco_teto = math.floor((float(preco_ranking) - 0.01) * 100.0) / 100.0
    if preco_teto <= 0:
        return None
    preco_piso_competitivo = math.ceil(max(0.01, float(preco_ranking) - float(desconto_maximo)) * 100.0) / 100.0
    preco_minimo_margem = _favoritos_ml_preco_minimo_margem_simulado(req)
    preco_contingencia = max(preco_piso_competitivo, preco_minimo_margem or 0.01)
    preco_contingencia = math.ceil(preco_contingencia * 100.0) / 100.0
    if preco_contingencia > preco_teto:
        return None
    return round(float(preco_contingencia), 2)


def _favoritos_ml_verificacao_exige_contingencia_por_margem(
    req: FavoritosEfetivarPromocaoRequest,
    verificacao: Optional[dict],
) -> tuple[bool, str, dict]:
    preco_final = _favoritos_ml_preco_final_verificacao(verificacao)
    preco_simulado = _parse_float_flex(req.preco_promocional)
    if preco_simulado is None:
        preco_simulado = _parse_float_flex(req.preco_competitivo)
    preco_minimo_margem = _favoritos_ml_preco_minimo_margem_simulado(req)
    margem = _favoritos_ml_margem_estimada(req, preco_final)
    preco_proximo = bool(
        (isinstance(verificacao, dict) and verificacao.get("preco_promocional_ok"))
        or _favoritos_ml_float_close(preco_final, preco_simulado)
    )
    margem_baixa = bool(margem is not None and margem < 15.0)
    abaixo_minimo = bool(
        preco_final is not None
        and preco_minimo_margem is not None
        and float(preco_final) + 0.005 < float(preco_minimo_margem)
    )
    detalhes = {
        "preco_final_verificado": round(float(preco_final), 2) if preco_final is not None else None,
        "preco_promocional_simulado": round(float(preco_simulado), 2) if preco_simulado is not None else None,
        "preco_minimo_margem": round(float(preco_minimo_margem), 2) if preco_minimo_margem is not None else None,
        "margem_estimada": round(float(margem), 2) if margem is not None else None,
        "preco_proximo_simulado": preco_proximo,
    }
    if margem_baixa or abaixo_minimo:
        motivo = (
            "Preco final aplicado ficou com margem abaixo de 15% "
            f"(preco final {detalhes['preco_final_verificado']}, "
            f"margem estimada {detalhes['margem_estimada']}, "
            f"minimo seguro {detalhes['preco_minimo_margem']})."
        )
        return True, motivo, detalhes
    if not preco_proximo and (margem_baixa or abaixo_minimo):
        motivo = (
            "Preco final aplicado nao ficou proximo do simulado e entrou em faixa de margem insegura. "
            f"Detalhes: {detalhes}"
        )
        return True, motivo, detalhes
    return False, "", detalhes


def _favoritos_ml_falha_por_percentual_promocao(
    erro_texto: str = "",
    verificacao: Optional[dict] = None,
) -> bool:
    erro_norm = normalizar_texto(erro_texto or "")
    gatilhos = (
        "error_credibility_discounted_price",
        "error_credibility_price",
        "final_price_lower_than_zero",
        "discounted price is not credible",
        "new deal_price must be lower than current deal_price",
        "new top_deal_price must be lower than current top_deal_price",
    )
    if any(g in erro_norm for g in gatilhos):
        return True

    if isinstance(verificacao, dict):
        if verificacao.get("preco_anuncio_ok") and (
            not verificacao.get("promocao_ok")
            or not verificacao.get("promocao_por_preco_ok")
            or not verificacao.get("preco_promocional_ok")
            or not verificacao.get("desconto_ok")
        ):
            return True

        info_preco = verificacao.get("price_info") if isinstance(verificacao.get("price_info"), dict) else {}
        desconto_info = _parse_float_flex((info_preco or {}).get("discount_pct") or verificacao.get("desconto_info"))
        desconto_esperado = _parse_float_flex(verificacao.get("desconto_esperado"))
        if desconto_info is not None and desconto_esperado is not None:
            if abs(float(desconto_info) - float(desconto_esperado)) > 0.25:
                return True
    return False


def _favoritos_ml_aplicar_contingencia_sem_promocao(
    client_id: str,
    loja: str,
    cfg: dict,
    item_id: str,
    req: FavoritosEfetivarPromocaoRequest,
    motivo: str,
) -> tuple[dict, dict]:
    preco_ranking = _favoritos_ml_preco_ranking_simulado(req)
    preco_contingencia = _favoritos_ml_preco_contingencia_sem_promocao(req)
    if preco_contingencia is None:
        preco_ranking_txt = round(float(preco_ranking), 2) if preco_ranking is not None else None
        preco_minimo_txt = _favoritos_ml_preco_minimo_margem_simulado(req)
        preco_piso_txt = None
        preco_teto_txt = None
        if preco_ranking is not None and preco_ranking > 0:
            preco_piso_txt = round(math.ceil(max(0.01, float(preco_ranking) - 1.5) * 100.0) / 100.0, 2)
            preco_teto_txt = round(math.floor((float(preco_ranking) - 0.01) * 100.0) / 100.0, 2)
        raise HTTPException(
            status_code=409,
            detail=(
                "A campanha foi recusada pelo Mercado Livre ou o preco final ficou abaixo da margem minima, "
                "mas nao existe preco de contingencia seguro: o anuncio precisa ficar abaixo do concorrente "
                "com diferenca maxima de R$ 1,50 e margem minima de 15%. "
                f"Preco concorrente: {preco_ranking_txt}. Faixa aceita sem campanha: {preco_piso_txt} a {preco_teto_txt}. "
                f"Preco minimo para margem: {preco_minimo_txt}. Motivo original: "
                f"{motivo}"
            ),
        )
    margem_contingencia = _favoritos_ml_margem_estimada(req, preco_contingencia)
    if margem_contingencia is not None and margem_contingencia < 15.0:
        raise HTTPException(
            status_code=409,
            detail=(
                "Contingencia sem promocao bloqueada: o preco calculado ficaria com margem abaixo de 15%. "
                f"Preco calculado: {preco_contingencia}. Margem estimada: {round(float(margem_contingencia), 2)}%. "
                f"Motivo original: {motivo}"
            ),
        )

    removidas, cfg = _favoritos_ml_remover_promocoes_atuais(client_id, loja, cfg, item_id, req)
    if removidas:
        time.sleep(1.0)

    preco_update, cfg = _favoritos_ml_atualizar_preco_item(client_id, loja, cfg, item_id, preco_contingencia)
    preco_confirmacao, cfg = _favoritos_ml_aguardar_preco_anuncio(
        client_id,
        loja,
        cfg,
        item_id,
        float(preco_contingencia),
        tentativas=8,
    )
    if not preco_confirmacao.get("success"):
        raise HTTPException(
            status_code=409,
            detail=(
                "A campanha foi recusada e o fallback sem campanha tambem nao confirmou o preco final. "
                f"Motivo original: {motivo} | Conferencia fallback: {preco_confirmacao}"
            ),
        )

    return {
        "fallback_sem_promocao_aplicado": True,
        "fallback_motivo": motivo,
        "preco_ranking_referencia": round(float(preco_ranking), 2) if preco_ranking is not None else None,
        "preco_anuncio_contingencia": round(float(preco_contingencia), 2),
        "margem_estimada_contingencia": round(float(margem_contingencia), 2) if margem_contingencia is not None else None,
        "promocoes_removidas_fallback": removidas,
        "preco_update_fallback": preco_update,
        "preco_confirmacao_fallback": preco_confirmacao,
    }, cfg


def _favoritos_ml_texto_promocao(entry: dict, chaves: tuple[str, ...]) -> str:
    texto = _ml_promocao_raw_texto(entry, chaves)
    if texto:
        return texto
    if not isinstance(entry, dict):
        return ""
    for _caminho, valor in _ml_iterar_campos_payload_limitado(entry, max_depth=5, max_nodes=900):
        chave = str(_caminho or "").rsplit(".", 1)[-1].strip().lower()
        if chave in {str(c or "").strip().lower() for c in chaves}:
            valor_txt = str(valor or "").strip()
            if valor_txt and valor_txt.lower() not in {"none", "null", "-"}:
                return valor_txt
    return ""


def _favoritos_ml_promocao_para_remocao(entry: dict, item_id: str) -> dict | None:
    if not isinstance(entry, dict):
        return None
    status = _ml_classificar_status_promocao_entry(entry)
    if status not in {"", "Ativo", "Programado"}:
        return None

    promotion_type = (
        _favoritos_ml_texto_promocao(entry, ("promotion_type", "promotionType", "type", "campaign_type", "campaignType"))
        or "SELLER_CAMPAIGN"
    )
    promotion_id = _favoritos_ml_texto_promocao(
        entry,
        ("promotion_id", "promotionId", "campaign_id", "campaignId", "deal_id", "dealId"),
    )
    if not promotion_id:
        candidato_id = _favoritos_ml_texto_promocao(entry, ("id",))
        if candidato_id and candidato_id.upper() != str(item_id or "").upper():
            promotion_id = candidato_id
    offer_id = _favoritos_ml_texto_promocao(entry, ("offer_id", "offerId", "ref_id", "refId"))

    if not promotion_type and not promotion_id:
        return None
    return {
        "promotion_id": promotion_id,
        "promotion_type": promotion_type or "SELLER_CAMPAIGN",
        "offer_id": offer_id,
        "status": status or "Ativo",
    }


def _favoritos_ml_promocoes_remocao_fallback(req: FavoritosEfetivarPromocaoRequest, item_id: str) -> list[dict]:
    anuncio = req.anuncio if isinstance(req.anuncio, dict) else {}
    promotion_type = str(
        anuncio.get("promotion_type")
        or anuncio.get("promotionType")
        or req.promotion_type
        or "SELLER_CAMPAIGN"
    ).strip() or "SELLER_CAMPAIGN"
    candidatos = []
    for valor in [
        anuncio.get("promotion_id"),
        anuncio.get("promotionId"),
        anuncio.get("campaign_id"),
        anuncio.get("deal_id"),
    ]:
        texto = str(valor or "").strip()
        if texto:
            candidatos.append(texto)
    deal_ids = anuncio.get("deal_ids") or anuncio.get("dealIds") or []
    if isinstance(deal_ids, str):
        deal_ids = [deal_ids]
    if isinstance(deal_ids, (list, tuple, set)):
        for valor in deal_ids:
            texto = str(valor or "").strip()
            if texto:
                candidatos.append(texto)

    retorno = []
    vistos = set()
    for promotion_id in candidatos:
        chave = (promotion_id.lower(), promotion_type.lower())
        if chave in vistos:
            continue
        vistos.add(chave)
        retorno.append({
            "promotion_id": promotion_id,
            "promotion_type": promotion_type,
        "offer_id": str(
            anuncio.get("offer_id")
            or anuncio.get("offerId")
            or anuncio.get("ref_id")
            or anuncio.get("refId")
            or ""
        ).strip(),
            "status": "Ativo",
        })
    return retorno


def _favoritos_ml_remocao_max_attempts() -> int:
    try:
        tentativas = int(float(str(os.getenv("ML_PROMO_REMOVE_MAX_ATTEMPTS", "4") or "4").replace(",", ".")))
    except Exception:
        tentativas = 4
    return max(1, min(tentativas, 6))


def _favoritos_ml_textos_resposta_remocao(resp, body_resp: Any, erros_payload: Optional[list[str]] = None) -> list[str]:
    textos = list(erros_payload or [])
    if isinstance(body_resp, dict):
        for chave in ("message", "error", "detail", "warning"):
            valor = body_resp.get(chave)
            if valor not in (None, ""):
                textos.append(str(valor))
    if not textos:
        try:
            textos.append(resp.text or "")
        except Exception:
            pass
    return textos


def _favoritos_ml_remocao_erro_transitorio(resp, textos_resposta: list[str]) -> bool:
    status_code = getattr(resp, "status_code", None)
    if status_code in (408, 429, 500, 502, 503, 504):
        return True

    texto = " ".join(str(t or "") for t in (textos_resposta or []))
    texto_norm = normalizar_texto(texto).replace("_", " ")
    gatilhos = (
        "service temporarily overloaded",
        "temporarily overloaded",
        "please try again later",
        "temporarily unavailable",
        "temporary unavailable",
        "upstream request timeout",
        "gateway timeout",
        "read timed out",
    )
    return any(gatilho in texto_norm for gatilho in gatilhos)


def _favoritos_ml_remocao_retry_delay(resp, tentativa: int) -> float:
    padrao = min(16.0, 1.5 * (2 ** max(0, int(tentativa) - 1)))
    if resp is not None:
        padrao = _ml_retry_after_seconds(resp, padrao=padrao)
    return min(18.0, max(1.0, float(padrao)) + random.uniform(0.2, 1.0))


def _favoritos_ml_remover_promocoes_atuais(
    client_id: str,
    loja: str,
    cfg: dict,
    item_id: str,
    req: FavoritosEfetivarPromocaoRequest,
) -> tuple[list[dict], dict]:
    promocoes_item = []
    try:
        promocoes_item, cfg = _ml_obter_promocoes_item(client_id, loja, cfg, item_id)
    except Exception as exc:
        logger.warning("[Favoritos ML] Falha ao listar promocoes atuais de %s: %s", item_id, exc)

    remover = []
    vistos = set()
    for raw in promocoes_item if isinstance(promocoes_item, list) else []:
        info = _favoritos_ml_promocao_para_remocao(raw, item_id)
        if not info:
            continue
        chave = (
            str(info.get("promotion_id") or "").lower(),
            str(info.get("promotion_type") or "").lower(),
            str(info.get("offer_id") or "").lower(),
        )
        if chave in vistos:
            continue
        vistos.add(chave)
        remover.append(info)

    for fallback in _favoritos_ml_promocoes_remocao_fallback(req, item_id):
        chave = (
            str(fallback.get("promotion_id") or "").lower(),
            str(fallback.get("promotion_type") or "").lower(),
            str(fallback.get("offer_id") or "").lower(),
        )
        if chave not in vistos:
            vistos.add(chave)
            remover.append(fallback)

    resultados = []
    max_attempts = _favoritos_ml_remocao_max_attempts()
    for promo in remover:
        params = {"app_version": "v2"}
        if promo.get("promotion_type"):
            params["promotion_type"] = promo["promotion_type"]
        if promo.get("promotion_id"):
            params["promotion_id"] = promo["promotion_id"]
        if promo.get("offer_id"):
            params["offer_id"] = promo["offer_id"]

        for tentativa in range(1, max_attempts + 1):
            try:
                resp, cfg = _ml_api_request(
                    client_id,
                    loja,
                    cfg,
                    "DELETE",
                    f"https://api.mercadolibre.com/seller-promotions/items/{item_id}",
                    params=params,
                    timeout=20,
                )
            except (requests.exceptions.ConnectTimeout, requests.exceptions.ReadTimeout, requests.exceptions.Timeout, requests.exceptions.ConnectionError) as exc:
                if tentativa < max_attempts:
                    espera = _favoritos_ml_remocao_retry_delay(None, tentativa)
                    logger.warning(
                        "[Favoritos ML] Falha transitoria ao sair da promocao atual de %s (%s/%s): %s. Nova tentativa em %.1fs.",
                        item_id,
                        tentativa,
                        max_attempts,
                        exc,
                        espera,
                    )
                    time.sleep(espera)
                    continue
                raise HTTPException(
                    status_code=503,
                    detail=f"Erro ao sair da promocao atual: Mercado Livre nao respondeu ao remover promocao atual: {exc}",
                )

            body_resp = {}
            try:
                body_resp = resp.json() or {}
            except Exception:
                body_resp = {}
            erros_payload = []
            if isinstance(body_resp, dict):
                for erro in body_resp.get("errors") or []:
                    if isinstance(erro, dict):
                        erros_payload.append(str(erro.get("error") or erro.get("message") or erro))
                    else:
                        erros_payload.append(str(erro))
                for item_sucesso in body_resp.get("successful_ids") or []:
                    if isinstance(item_sucesso, dict) and item_sucesso.get("error"):
                        erros_payload.append(str(item_sucesso.get("error")))
            textos_resposta = _favoritos_ml_textos_resposta_remocao(resp, body_resp, erros_payload)
            textos_normalizados = [normalizar_texto(e).replace("_", " ") for e in textos_resposta]
            erro_sem_oferta = any("no offers found" in e for e in textos_normalizados)
            erro_tipo_promocao_invalido = any("invalid promotion type" in e for e in textos_normalizados)
            erro_promocao_invalida = any("invalid promotion id" in e for e in textos_normalizados)
            ok_status = resp.status_code in (200, 202, 204, 404)
            if erro_sem_oferta or erro_tipo_promocao_invalido or erro_promocao_invalida:
                erros_payload = []
                ok_status = True
                if erro_sem_oferta:
                    aviso = "No offers found for item"
                elif erro_tipo_promocao_invalido:
                    aviso = "Invalid promotion type ignored while removing stale promotion reference"
                else:
                    aviso = "Invalid promotion id ignored while removing stale promotion reference"
                if not body_resp:
                    body_resp = {"warning": aviso}
                elif isinstance(body_resp, dict):
                    body_resp["warning"] = aviso
            ok = ok_status and not erros_payload
            detalhe = ""
            if not ok:
                detalhe = " | ".join([e for e in erros_payload if e][:5]) or _ml_parse_error_detail(resp, "Erro ao remover promocao atual")

            if not ok and tentativa < max_attempts and _favoritos_ml_remocao_erro_transitorio(resp, textos_resposta):
                espera = _favoritos_ml_remocao_retry_delay(resp, tentativa)
                logger.warning(
                    "[Favoritos ML] Mercado Livre falhou ao sair da promocao atual de %s (%s/%s, HTTP %s): %s. Nova tentativa em %.1fs.",
                    item_id,
                    tentativa,
                    max_attempts,
                    resp.status_code,
                    detalhe,
                    espera,
                )
                time.sleep(espera)
                continue

            resultados.append({
                **promo,
                "success": ok,
                "status_code": resp.status_code,
                "detail": detalhe,
                "response": body_resp,
                "attempts": tentativa,
            })
            if not ok:
                raise HTTPException(status_code=resp.status_code, detail=f"Erro ao sair da promocao atual: {detalhe}")
            break

    return resultados, cfg


def _favoritos_ml_atualizar_preco_item(client_id: str, loja: str, cfg: dict, item_id: str, preco: float) -> tuple[dict, dict]:
    preco_num = round(float(preco), 2)
    ultimo_resp = None
    erro_api_precos = None

    def _json_response(resp) -> Any:
        try:
            return resp.json() or {}
        except Exception:
            return {}

    def _preco_no_payload(data: Any) -> Optional[float]:
        if not isinstance(data, dict):
            return None
        return _parse_float_flex(
            data.get("price")
            or data.get("base_price")
            or data.get("amount")
            or data.get("standard_price")
        )

    def _resposta_indica_preco_ignorado(resp, data: Any) -> bool:
        preco_retornado = _preco_no_payload(data)
        if preco_retornado is not None and _favoritos_ml_float_close(preco_retornado, preco_num):
            return False

        partes_risco = []
        if isinstance(data, dict):
            for chave in ("warnings", "warning", "errors", "error", "message", "cause", "detail"):
                valor = data.get(chave)
                if valor:
                    try:
                        partes_risco.append(json.dumps(valor, ensure_ascii=False))
                    except Exception:
                        partes_risco.append(str(valor))
        if not partes_risco:
            return False

        try:
            texto = " ".join(partes_risco)
        except Exception:
            texto = " ".join(str(p) for p in partes_risco)
        texto_norm = normalizar_texto(texto)
        termos_preco = ("price", "preco", "amount")
        termos_ignorado = ("ignored", "ignore", "not modifiable", "not_modifiable", "automat", "readonly", "read only")
        if any(t in texto_norm for t in termos_preco) and any(t in texto_norm for t in termos_ignorado):
            return True
        return False

    def _normalizar_contextos_standard(contextos: Any) -> list[str]:
        if isinstance(contextos, str):
            contextos = [contextos]
        if not isinstance(contextos, list):
            return []
        vistos = set()
        saida = []
        for contexto in contextos:
            ctx = str(contexto or "").strip()
            if not ctx or ctx in vistos:
                continue
            vistos.add(ctx)
            saida.append(ctx)
        return saida

    def _montar_payload_preco_standard() -> tuple[Optional[dict], dict, dict]:
        details = {"source": "prices"}
        currency_id = None
        prices_payload = []

        prices_resp, cfg_local = _ml_api_request(
            client_id,
            loja,
            cfg,
            "GET",
            f"https://api.mercadolibre.com/items/{item_id}/prices",
            timeout=15,
        )
        if prices_resp.status_code == 200:
            prices_data = _json_response(prices_resp)
            details["prices_response"] = prices_data
            for price_obj in (prices_data.get("prices") or []):
                if not isinstance(price_obj, dict):
                    continue
                if str(price_obj.get("type") or "").lower() != "standard":
                    continue
                currency_id = price_obj.get("currency_id") or currency_id
                conditions = price_obj.get("conditions") if isinstance(price_obj.get("conditions"), dict) else {}
                contexts = _normalizar_contextos_standard(conditions.get("context_restrictions"))
                prices_payload.append({
                    "conditions": {"context_restrictions": contexts},
                    "amount": preco_num,
                    "currency_id": currency_id or "BRL",
                })
        else:
            details["prices_status_code"] = prices_resp.status_code
            details["prices_error"] = _ml_parse_error_detail(prices_resp, "Nao foi possivel consultar /prices")

        if prices_payload:
            return {"prices": prices_payload}, details, cfg_local

        item_resp, cfg_local = _ml_api_request(
            client_id,
            loja,
            cfg_local,
            "GET",
            f"https://api.mercadolibre.com/items/{item_id}",
            timeout=15,
        )
        item_data = _json_response(item_resp) if item_resp.status_code == 200 else {}
        details["source"] = "item_fallback"
        details["item_status_code"] = item_resp.status_code
        currency_id = item_data.get("currency_id") or currency_id or "BRL"
        canais = item_data.get("channels") if isinstance(item_data.get("channels"), list) else []
        contextos = []
        for canal in canais:
            canal_norm = str(canal or "").strip().lower()
            if canal_norm in {"marketplace", "channel_marketplace"}:
                contextos.append("channel_marketplace")
            elif canal_norm in {"mshops", "channel_mshops"}:
                contextos.append("channel_mshops")
        if not contextos:
            contextos = ["channel_marketplace"]
        prices_payload = [
            {
                "conditions": {"context_restrictions": [ctx]},
                "amount": preco_num,
                "currency_id": currency_id,
            }
            for ctx in dict.fromkeys(contextos)
        ]
        return {"prices": prices_payload}, details, cfg_local

    payload_standard, detalhes_standard, cfg = _montar_payload_preco_standard()
    if payload_standard:
        resp_standard, cfg = _ml_api_request(
            client_id,
            loja,
            cfg,
            "POST",
            f"https://api.mercadolibre.com/items/{item_id}/prices/standard",
            json=payload_standard,
            timeout=25,
        )
        if resp_standard.status_code in (200, 201, 202, 204):
            return {
                "method": "prices_standard",
                "payload": payload_standard,
                "response": _json_response(resp_standard),
                "details": detalhes_standard,
            }, cfg
        erro_api_precos = _ml_parse_error_detail(resp_standard, "Erro ao atualizar preco pela API de precos")

    for tentativa in range(3):
        if tentativa:
            time.sleep(1.2 * tentativa)
        resp, cfg = _ml_api_request(
            client_id,
            loja,
            cfg,
            "PUT",
            f"https://api.mercadolibre.com/items/{item_id}",
            json={"price": preco_num},
            timeout=25,
        )
        ultimo_resp = resp
        if resp.status_code in (200, 201):
            data = _json_response(resp)
            if _resposta_indica_preco_ignorado(resp, data):
                detalhe = (
                    "Mercado Livre respondeu ao PUT /items, mas o retorno nao refletiu o preco cheio simulado. "
                    f"Preco esperado: {preco_num}. Retorno: {data}"
                )
                if erro_api_precos:
                    detalhe = f"{detalhe} | API de precos: {erro_api_precos}"
                raise HTTPException(status_code=409, detail=detalhe)
            return {
                "method": "items_put",
                "payload": {"price": preco_num},
                "response": data,
                "prices_standard_error": erro_api_precos,
            }, cfg
        if resp.status_code != 409:
            break

    detalhe = _ml_parse_error_detail(ultimo_resp, "Erro ao atualizar preco do anuncio no Mercado Livre")
    if erro_api_precos:
        detalhe = f"{detalhe} | API de precos: {erro_api_precos}"
    raise HTTPException(status_code=getattr(ultimo_resp, "status_code", 500) or 500, detail=detalhe)


def _favoritos_ml_aguardar_preco_anuncio(
    client_id: str,
    loja: str,
    cfg: dict,
    item_id: str,
    preco_anuncio: float,
    tentativas: int = 8,
) -> tuple[dict, dict]:
    ultimo = {}
    preco_alvo = round(float(preco_anuncio), 2)
    for tentativa in range(max(1, tentativas)):
        if tentativa:
            time.sleep(1.5)

        item = {}
        resp_item, cfg = _ml_api_request(
            client_id,
            loja,
            cfg,
            "GET",
            f"https://api.mercadolibre.com/items/{item_id}",
            timeout=15,
        )
        if resp_item.status_code == 200:
            try:
                item = resp_item.json() or {}
            except Exception:
                item = {}

        price_info, cfg = _ml_obter_preco_detalhado(
            client_id,
            loja,
            cfg,
            item_id,
            fallback_price=item.get("price"),
            request_fn=_ml_api_request,
            consultar_sale_price_sempre=True,
        )

        candidatos = [
            price_info.get("standard_price"),
            price_info.get("original_price"),
            item.get("price"),
            item.get("base_price"),
        ]
        ok = any(_favoritos_ml_float_close(v, preco_alvo) for v in candidatos)
        ultimo = {
            "success": ok,
            "attempt": tentativa + 1,
            "preco_alvo": preco_alvo,
            "item_price": item.get("price"),
            "base_price": item.get("base_price"),
            "standard_price": price_info.get("standard_price"),
            "original_price": price_info.get("original_price"),
            "price_info": price_info,
        }
        if ok:
            return ultimo, cfg

    ultimo["success"] = False
    return ultimo, cfg


def _favoritos_ml_verificar_efetivacao(
    client_id: str,
    loja: str,
    cfg: dict,
    item_id: str,
    campanha_id: str,
    promotion_type: str,
    preco_anuncio: float,
    preco_promocional: Optional[float],
) -> tuple[dict, dict]:
    ultimo = {}
    for tentativa in range(6):
        if tentativa:
            time.sleep(1.8)

        item = {}
        resp_item, cfg = _ml_api_request(
            client_id,
            loja,
            cfg,
            "GET",
            f"https://api.mercadolibre.com/items/{item_id}",
            timeout=15,
        )
        if resp_item.status_code == 200:
            try:
                item = resp_item.json() or {}
            except Exception:
                item = {}

        price_info, cfg = _ml_obter_preco_detalhado(
            client_id,
            loja,
            cfg,
            item_id,
            fallback_price=item.get("price"),
            request_fn=_ml_api_request,
            consultar_sale_price_sempre=True,
        )
        promocoes_item, cfg = _ml_obter_promocoes_item(client_id, loja, cfg, item_id)
        raw_promocao = _ml_encontrar_promocao_raw_item(promocoes_item, campanha_id)
        ids_promocoes = _ml_extrair_ids_promocoes_item(promocoes_item)
        promocao_ok = bool(
            raw_promocao
            or str(campanha_id or "").strip().lower() in {str(v).strip().lower() for v in ids_promocoes}
        )

        preco_standard = (
            price_info.get("standard_price")
            or price_info.get("original_price")
            or item.get("price")
            or item.get("base_price")
        )
        preco_final = price_info.get("price")
        preco_raw_promocao, desconto_raw = _ml_extrair_preco_promocao_raw(raw_promocao or {})

        preco_anuncio_ok = (
            _favoritos_ml_float_close(preco_standard, preco_anuncio)
            or _favoritos_ml_float_close(item.get("price"), preco_anuncio)
            or _favoritos_ml_float_close(price_info.get("original_price"), preco_anuncio)
        )
        preco_promocional_ok = True
        if preco_promocional is not None:
            preco_promocional_ok = (
                _favoritos_ml_float_close(preco_final, preco_promocional)
                or _favoritos_ml_float_close(preco_raw_promocao, preco_promocional)
            )
        desconto_esperado = None
        desconto_info = _parse_float_flex(price_info.get("discount_pct"))
        if desconto_info is None:
            desconto_info = _parse_float_flex(desconto_raw)
        try:
            if preco_anuncio and preco_promocional:
                desconto_esperado = max(0.0, ((float(preco_anuncio) - float(preco_promocional)) / float(preco_anuncio)) * 100.0)
        except Exception:
            desconto_esperado = None
        desconto_ok = True
        if desconto_esperado is not None and desconto_info is not None:
            desconto_ok = abs(float(desconto_info) - float(desconto_esperado)) <= 0.35
        promocao_por_preco_ok = bool(
            not promocao_ok
            and price_info.get("has_promotion")
            and preco_anuncio_ok
            and preco_promocional_ok
            and desconto_ok
        )

        ultimo = {
            "promotion_id": campanha_id,
            "promotion_type": promotion_type,
            "promocao_ok": promocao_ok,
            "promocao_por_preco_ok": promocao_por_preco_ok,
            "preco_anuncio_ok": preco_anuncio_ok,
            "preco_promocional_ok": preco_promocional_ok,
            "desconto_ok": desconto_ok,
            "desconto_esperado": desconto_esperado,
            "desconto_info": desconto_info,
            "price_info": price_info,
            "item_price": item.get("price"),
            "standard_price": preco_standard,
            "promotion_price_raw": preco_raw_promocao,
            "promotion_discount_raw": desconto_raw,
            "attempt": tentativa + 1,
        }
        if (promocao_ok or promocao_por_preco_ok) and preco_anuncio_ok and preco_promocional_ok and desconto_ok:
            ultimo["success"] = True
            return ultimo, cfg

    ultimo["success"] = False
    return ultimo, cfg


@app.post("/api/favoritos/ml/efetivar-promocao")
def favoritos_ml_efetivar_promocao(
    req: FavoritosEfetivarPromocaoRequest,
    client_id: str = Depends(get_tenant_id),
):
    loja = str(req.loja or "").strip()
    item_id = _promo_normalizar_mlb(req.item_id)
    campanha_id = str(req.campanha_id or "").strip()
    promotion_type = str(req.promotion_type or "SELLER_CAMPAIGN").strip() or "SELLER_CAMPAIGN"
    preco_anuncio = _parse_float_flex(req.preco_anuncio)
    preco_promocional = _parse_float_flex(req.preco_promocional)
    if preco_promocional is None:
        preco_promocional = _parse_float_flex(req.preco_competitivo)
    percentual = _parse_float_flex(req.percentual_promocao)

    if not loja:
        raise HTTPException(status_code=400, detail="Informe a loja do Mercado Livre.")
    if not item_id:
        raise HTTPException(status_code=400, detail="Informe o MLB do anuncio.")
    if not campanha_id:
        raise HTTPException(status_code=400, detail="Informe a campanha de promocao selecionada.")
    if preco_anuncio is None or preco_anuncio <= 0:
        raise HTTPException(status_code=400, detail="Preco cheio do anuncio invalido.")
    if preco_promocional is None or preco_promocional <= 0:
        raise HTTPException(status_code=400, detail="Preco promocional simulado invalido.")

    cfg = _obter_cfg_ml(client_id, loja)
    removidas, cfg = _favoritos_ml_remover_promocoes_atuais(client_id, loja, cfg, item_id, req)
    if removidas:
        time.sleep(1.5)

    preco_update, cfg = _favoritos_ml_atualizar_preco_item(client_id, loja, cfg, item_id, preco_anuncio)
    preco_confirmacao, cfg = _favoritos_ml_aguardar_preco_anuncio(
        client_id,
        loja,
        cfg,
        item_id,
        float(preco_anuncio),
        tentativas=8,
    )
    if not preco_confirmacao.get("success"):
        raise HTTPException(
            status_code=409,
            detail=(
                "O preco cheio do anuncio ainda nao ficou igual ao simulado no Mercado Livre. "
                "A promocao nao foi aplicada para evitar margem errada. "
                f"Conferencia: {preco_confirmacao}"
            ),
        )

    ok, erro, cfg = _promo_aplicar_item_participacao_ml(
        client_id,
        loja,
        cfg,
        item_id=item_id,
        promotion_id=campanha_id,
        promotion_type=promotion_type,
        deal_price=preco_promocional,
        discount_percentage=percentual,
    )
    if not ok:
        motivo = f"Preco atualizado, mas falhou ao aplicar a promocao: {erro}"
        if _favoritos_ml_falha_por_percentual_promocao(motivo):
            fallback, cfg = _favoritos_ml_aplicar_contingencia_sem_promocao(
                client_id,
                loja,
                cfg,
                item_id,
                req,
                motivo,
            )
            _cache_invalidar_loja(client_id, loja)
            return {
                "success": True,
                "message": "Campanha recusada pelo Mercado Livre; aplicado fallback sem campanha.",
                "loja": loja,
                "sku": req.sku,
                "item_id": item_id,
                "promotion_id": campanha_id,
                "promotion_type": promotion_type,
                "campanha_nome": req.campanha_nome,
                "campanha_aplicada": False,
                "preco_anuncio": round(float(fallback.get("preco_anuncio_contingencia")), 2),
                "preco_promocional": None,
                "percentual_promocao": percentual,
                "promocoes_removidas": removidas,
                "preco_update": preco_update,
                "preco_confirmacao": preco_confirmacao,
                "verificacao": None,
                **fallback,
            }
        raise HTTPException(status_code=409, detail=motivo)

    verificacao, cfg = _favoritos_ml_verificar_efetivacao(
        client_id,
        loja,
        cfg,
        item_id,
        campanha_id,
        promotion_type,
        float(preco_anuncio),
        float(preco_promocional),
    )
    if not verificacao.get("success"):
        motivo_verificacao = (
            "Mercado Livre recebeu as alteracoes, mas a conferencia ainda nao bateu com o simulado. "
            f"Verificacao: {verificacao}"
        )
        exige_fallback_margem, motivo_margem, detalhes_margem = _favoritos_ml_verificacao_exige_contingencia_por_margem(req, verificacao)
        if _favoritos_ml_falha_por_percentual_promocao(motivo_verificacao, verificacao) or exige_fallback_margem:
            fallback, cfg = _favoritos_ml_aplicar_contingencia_sem_promocao(
                client_id,
                loja,
                cfg,
                item_id,
                req,
                motivo_margem or motivo_verificacao,
            )
            _cache_invalidar_loja(client_id, loja)
            return {
                "success": True,
                "message": "Campanha recusada/nao conferida pelo Mercado Livre; aplicado fallback sem campanha e com margem segura.",
                "loja": loja,
                "sku": req.sku,
                "item_id": item_id,
                "promotion_id": campanha_id,
                "promotion_type": promotion_type,
                "campanha_nome": req.campanha_nome,
                "campanha_aplicada": False,
                "preco_anuncio": round(float(fallback.get("preco_anuncio_contingencia")), 2),
                "preco_promocional": None,
                "percentual_promocao": percentual,
                "promocoes_removidas": removidas,
                "preco_update": preco_update,
                "preco_confirmacao": preco_confirmacao,
                "verificacao": verificacao,
                "verificacao_margem": detalhes_margem,
                **fallback,
            }
        raise HTTPException(status_code=409, detail=motivo_verificacao)

    exige_fallback_margem, motivo_margem, detalhes_margem = _favoritos_ml_verificacao_exige_contingencia_por_margem(req, verificacao)
    if exige_fallback_margem:
        fallback, cfg = _favoritos_ml_aplicar_contingencia_sem_promocao(
            client_id,
            loja,
            cfg,
            item_id,
            req,
            motivo_margem,
        )
        _cache_invalidar_loja(client_id, loja)
        return {
            "success": True,
            "message": "Preco promocional aplicado ficou abaixo da margem minima; aplicado fallback sem campanha e com margem segura.",
            "loja": loja,
            "sku": req.sku,
            "item_id": item_id,
            "promotion_id": campanha_id,
            "promotion_type": promotion_type,
            "campanha_nome": req.campanha_nome,
            "campanha_aplicada": False,
            "preco_anuncio": round(float(fallback.get("preco_anuncio_contingencia")), 2),
            "preco_promocional": None,
            "percentual_promocao": percentual,
            "promocoes_removidas": removidas,
            "preco_update": preco_update,
            "preco_confirmacao": preco_confirmacao,
            "verificacao": verificacao,
            "verificacao_margem": detalhes_margem,
            **fallback,
        }

    _cache_invalidar_loja(client_id, loja)
    return {
        "success": True,
        "message": "Favorito feito no Mercado Livre.",
        "loja": loja,
        "sku": req.sku,
        "item_id": item_id,
        "promotion_id": campanha_id,
        "promotion_type": promotion_type,
        "campanha_nome": req.campanha_nome,
        "campanha_aplicada": True,
        "preco_anuncio": round(float(preco_anuncio), 2),
        "preco_promocional": round(float(preco_promocional), 2),
        "percentual_promocao": percentual,
        "promocoes_removidas": removidas,
        "preco_update": preco_update,
        "preco_confirmacao": preco_confirmacao,
        "verificacao": verificacao,
        "verificacao_margem": detalhes_margem,
    }


def _favoritos_taxa_padrao_por_tipo_anuncio(anuncio: dict) -> float | None:
    tipo_raw = str(
        (anuncio or {}).get("listing_type_id")
        or (anuncio or {}).get("listing_type_name")
        or (anuncio or {}).get("tipo_anuncio")
        or ""
    ).strip().lower()
    if not tipo_raw:
        return None
    if "gold_pro" in tipo_raw or "premium" in tipo_raw or tipo_raw == "pro":
        return 0.17
    if (
        "gold_special" in tipo_raw
        or "classico" in tipo_raw
        or "classic" in tipo_raw
        or tipo_raw in {"gold", "silver", "bronze"}
    ):
        return 0.12
    if "free" in tipo_raw or "grat" in tipo_raw:
        return 0.0
    return None


def _favoritos_resolver_sku_para_margem(anuncio: dict, sku_hint: str = "") -> str:
    candidatos = [
        sku_hint,
        (anuncio or {}).get("sku"),
        (anuncio or {}).get("sku_display"),
        (anuncio or {}).get("seller_sku"),
        (anuncio or {}).get("seller_custom_field"),
        (anuncio or {}).get("SELLER_SKU"),
    ]
    for candidato in candidatos:
        texto = str(candidato or "").strip()
        if texto:
            return texto
    return ""


def _favoritos_frete_existente_anuncio(anuncio: dict) -> float | None:
    if not isinstance(anuncio, dict):
        return None
    for campo in (
        "shipping_seller_cost",
        "shipping_cost",
        "frete_ml",
        "shipping_list_cost",
        "shipping_base_cost",
        "frete",
        "custo_frete",
    ):
        valor = _to_float_safe(anuncio.get(campo))
        if valor is not None:
            return valor
    shipping_info = anuncio.get("shipping") if isinstance(anuncio.get("shipping"), dict) else {}
    for campo in ("seller_cost", "shipping_cost", "base_cost", "list_cost"):
        valor = _to_float_safe((shipping_info or {}).get(campo))
        if valor is not None:
            return valor
    return None


def _favoritos_anuncio_tem_frete_gratis(anuncio: dict) -> bool:
    if not isinstance(anuncio, dict):
        return False
    shipping_info = anuncio.get("shipping") if isinstance(anuncio.get("shipping"), dict) else {}
    return bool(
        anuncio.get("free_shipping") is True
        or anuncio.get("frete_gratis") is True
        or _flag_frete_gratis(anuncio.get("Frete Gratis"))
        or _flag_frete_gratis(anuncio.get("Frete GrÃƒÂ¡tis"))
        or (shipping_info or {}).get("free_shipping") is True
    )


def _favoritos_chaves_frete_anuncio(anuncio: dict, sku_hint: str = "") -> list[str]:
    if not isinstance(anuncio, dict):
        return []

    shipping_info = anuncio.get("shipping") if isinstance(anuncio.get("shipping"), dict) else {}
    logistic_type = str(anuncio.get("logistic_type") or (shipping_info or {}).get("logistic_type") or "").strip().lower()
    shipping_mode = str(anuncio.get("shipping_mode") or (shipping_info or {}).get("mode") or "").strip().lower()
    listing_type = str(
        anuncio.get("listing_type_id")
        or anuncio.get("listing_type_name")
        or anuncio.get("tipo_anuncio")
        or ""
    ).strip().lower()
    sku_base = _favoritos_resolver_sku_para_margem(anuncio, sku_hint)
    skus = _extrair_skus_para_custo(
        sku_base,
        anuncio.get("sku"),
        anuncio.get("sku_display"),
        anuncio.get("seller_sku"),
        anuncio.get("seller_custom_field"),
        anuncio.get("SELLER_SKU"),
    )

    chaves = []
    vistos = set()
    niveis = (
        (logistic_type, shipping_mode, listing_type),
        (logistic_type, shipping_mode, ""),
        (logistic_type, "", listing_type),
        ("", "", listing_type),
        (logistic_type, "", ""),
        ("", "", ""),
    )
    for sku in skus:
        sku_norm = _normalizar_sku_mes(sku).upper()
        if not sku_norm:
            continue
        for logistica, modo, tipo in niveis:
            chave = f"{sku_norm}|{logistica}|{modo}|{tipo}"
            if chave in vistos:
                continue
            vistos.add(chave)
            chaves.append(chave)
    return chaves


def _favoritos_completar_frete_pausados_por_sku(anuncios: list[dict], sku_hint: str = "") -> None:
    if not isinstance(anuncios, list) or not anuncios:
        return

    fretes_por_chave: dict[str, dict] = {}
    for anuncio in anuncios:
        if not _favoritos_anuncio_tem_frete_gratis(anuncio):
            continue
        frete = _favoritos_frete_existente_anuncio(anuncio)
        if frete is None:
            continue
        texto = (
            anuncio.get("frete_ml_text")
            or anuncio.get("shipping_text")
            or formatar_moeda_br(frete)
        )
        info = {"frete": float(frete), "texto": texto, "item_id": anuncio.get("id") or anuncio.get("mlb") or ""}
        for chave in _favoritos_chaves_frete_anuncio(anuncio, sku_hint):
            fretes_por_chave.setdefault(chave, info)

    if not fretes_por_chave:
        return

    for anuncio in anuncios:
        if not isinstance(anuncio, dict):
            continue
        if not _favoritos_anuncio_tem_frete_gratis(anuncio):
            continue
        if _favoritos_frete_existente_anuncio(anuncio) is not None:
            continue

        frete_info = None
        for chave in _favoritos_chaves_frete_anuncio(anuncio, sku_hint):
            frete_info = fretes_por_chave.get(chave)
            if frete_info:
                break
        if not frete_info:
            continue

        frete = float(frete_info.get("frete") or 0.0)
        texto = frete_info.get("texto") or formatar_moeda_br(frete)
        anuncio["shipping_cost"] = round(frete, 2)
        anuncio["shipping_seller_cost"] = round(frete, 2)
        anuncio["frete_ml"] = round(frete, 2)
        anuncio["shipping_text"] = texto
        anuncio["frete_ml_text"] = texto
        anuncio["shipping_cost_fallback_source"] = "outro_anuncio_mesmo_sku"
        origem = frete_info.get("item_id") or "mesmo SKU"
        detalhe = f"Frete reaproveitado do anuncio {origem} do mesmo SKU para calcular margem."
        breakdown_atual = str(anuncio.get("shipping_breakdown") or "").strip()
        anuncio["shipping_breakdown"] = f"{breakdown_atual} | {detalhe}" if breakdown_atual else detalhe


def _favoritos_aplicar_margem_anuncio_ml(
    anuncio: dict,
    sku_hint: str,
    custos_por_sku: dict,
    impostos_por_sku: dict,
) -> dict:
    if not isinstance(anuncio, dict):
        return anuncio

    sku_margem = _favoritos_resolver_sku_para_margem(anuncio, sku_hint)
    preco_final = None
    for campo in (
        "preco_promocional",
        "promotional_price",
        "promotion_price",
        "sale_price",
        "price",
        "preco",
        "valor",
    ):
        preco_final = _to_float_safe(anuncio.get(campo))
        if preco_final is not None and preco_final > 0:
            break

    custo = _resolver_custo_por_sku(custos_por_sku or {}, sku_margem)
    imposto_rate = _resolver_imposto_rate_por_sku(impostos_por_sku or {}, sku_margem)

    tarifa = None
    for campo in ("ad_cost", "tarifa", "tarifa_ml", "fee_per_sale", "sale_fee_amount"):
        tarifa = _to_float_safe(anuncio.get(campo))
        if tarifa is not None:
            break

    taxa_pct = _to_rate_safe(anuncio.get("sale_fee_pct"))
    if taxa_pct is None:
        taxa_pct = _favoritos_taxa_padrao_por_tipo_anuncio(anuncio)
    if tarifa is None and preco_final is not None and taxa_pct is not None:
        tarifa = round(float(preco_final) * float(taxa_pct), 2)

    frete = None
    for campo in (
        "shipping_seller_cost",
        "shipping_cost",
        "frete_ml",
        "shipping_list_cost",
        "shipping_base_cost",
        "frete",
        "custo_frete",
    ):
        frete = _to_float_safe(anuncio.get(campo))
        if frete is not None:
            break
    free_shipping = bool(
        anuncio.get("free_shipping") is True
        or anuncio.get("frete_gratis") is True
        or _flag_frete_gratis(anuncio.get("Frete Gratis"))
        or _flag_frete_gratis(anuncio.get("Frete GrÃ¡tis"))
    )
    if frete is None and isinstance(anuncio.get("shipping"), dict):
        shipping_info = anuncio.get("shipping") or {}
        free_shipping = free_shipping or bool(shipping_info.get("free_shipping") is True)
        campos_frete_shipping = ("seller_cost", "shipping_cost", "base_cost", "list_cost")
        if not free_shipping:
            campos_frete_shipping = campos_frete_shipping + ("cost",)
        for campo in campos_frete_shipping:
            frete = _to_float_safe(shipping_info.get(campo))
            if frete is not None:
                break

    anuncio["sku_margem"] = sku_margem
    if custo is not None:
        anuncio["custo"] = float(custo)
        anuncio["custo_text"] = formatar_moeda_br(custo)
    if imposto_rate is not None:
        anuncio["imposto_percentual"] = round(float(imposto_rate) * 100.0, 4)
    if taxa_pct is not None:
        anuncio["taxa_ml_percentual"] = round(float(taxa_pct) * 100.0, 4)
    if tarifa is not None:
        anuncio["tarifa_ml"] = round(float(tarifa), 2)
        anuncio["tarifa_ml_text"] = formatar_moeda_br(tarifa)
    if frete is not None:
        anuncio["frete_ml"] = round(float(frete), 2)
        anuncio["frete_ml_text"] = formatar_moeda_br(frete)

    faltando = []
    if preco_final is None or preco_final <= 0:
        faltando.append("preco")
    if custo is None:
        faltando.append("custo")
    if imposto_rate is None:
        faltando.append("imposto")
    if frete is None and free_shipping:
        faltando.append("frete")
    if faltando:
        anuncio["margem_status"] = "Faltando " + ", ".join(faltando)
        return anuncio

    frete_calc = float(frete or 0.0)
    tarifa_calc = float(tarifa or 0.0)
    imposto_valor = round(float(preco_final) * float(imposto_rate), 2)
    valor_liquido = round(float(preco_final) - float(custo) - frete_calc - imposto_valor - tarifa_calc, 2)
    margem_pct = round((valor_liquido * 100.0) / float(preco_final), 2)

    anuncio.update({
        "preco_final_margem": round(float(preco_final), 2),
        "imposto_valor": imposto_valor,
        "imposto_valor_text": formatar_moeda_br(imposto_valor),
        "valor_liquido": valor_liquido,
        "valor_liquido_text": formatar_moeda_br(valor_liquido),
        "margem_percentual": margem_pct,
        "margem": margem_pct,
        "margem_text": f"{margem_pct:.2f}%".replace(".", ","),
        "margem_status": "ok",
    })
    return anuncio


@app.get("/api/favoritos/ml/anuncios-sku")
def favoritos_ml_listar_anuncios_sku(
    sku: str,
    loja: Optional[str] = None,
    compartilhar_sku: bool = False,
    todas_contas: bool = False,
    mlbs: Optional[str] = None,
    client_id: str = Depends(get_tenant_id),
):
    sku_norm = _normalizar_sku_match_favoritos(sku)
    if not sku_norm:
        raise HTTPException(status_code=400, detail="SKU invalido.")

    lojas_validas = _lojas_favoritos_com_ml(client_id)
    lojas_payload = [
        {"nome": str(item.get("nome") or "").strip()}
        for item in lojas_validas
        if str(item.get("nome") or "").strip()
    ]
    if not lojas_payload:
        return {
            "success": True,
            "lojas": [],
            "loja": "",
            "sku": sku_norm,
            "anuncios": [],
            "total": 0,
            "warning": "Nenhuma loja com Mercado Livre conectado foi encontrada em IntegraÃ§Ãµes.",
        }

    loja_chave = _chave_loja_favoritos(loja)
    loja_info = None
    if loja_chave:
        for candidata in lojas_validas:
            if _chave_loja_favoritos(candidata.get("nome")) == loja_chave:
                loja_info = candidata
                break
    if loja_info is None:
        loja_info = lojas_validas[0]

    nome_loja = str(loja_info.get("nome") or "").strip()
    ids_forcados = []
    for parte in re.split(r"[,;|\s]+", str(mlbs or "")):
        item_id = re.sub(r"[^A-Z0-9]", "", str(parte or "").upper())
        if item_id.startswith("MLB") and item_id not in ids_forcados:
            ids_forcados.append(item_id)
        if len(ids_forcados) >= 80:
            break
    ids_forcados_key = ",".join(ids_forcados)
    compartilhar_efetivo = bool(compartilhar_sku and todas_contas)
    cache_key_endpoint = (
        f"favoritos:anuncios_sku:v3:{client_id}:"
        f"{_chave_loja_favoritos(nome_loja)}:{sku_norm}:{int(compartilhar_efetivo)}:{ids_forcados_key}"
    )
    cached_endpoint = _ml_cache_get(cache_key_endpoint, ttl=90)
    if cached_endpoint is not None:
        return cached_endpoint

    def _resumir_item_ml(
        item: dict,
        price_info: Optional[dict] = None,
        shipping_data: Optional[dict] = None,
        fee_data: Optional[dict] = None,
    ) -> dict:
        item = item or {}
        price_info = price_info or _ml_montar_preco_listagem(item)
        shipping_data = shipping_data or {}
        fee_data = fee_data or {}
        item_id = str(item.get("id") or "").strip()
        permalink = str(item.get("permalink") or "").strip()
        preco_atual = price_info.get("price")
        if preco_atual in (None, ""):
            preco_atual = item.get("price")
        preco_original = price_info.get("original_price")
        standard_price = price_info.get("standard_price") or item.get("base_price") or item.get("price")
        has_promotion = bool(
            price_info.get("has_promotion")
            or price_info.get("promotion_id")
            or fee_data.get("promotion_id")
            or fee_data.get("promotion_fee_discount_applied")
            or item.get("deal_ids")
        )
        if not has_promotion:
            sale_price = item.get("sale_price")
            if isinstance(sale_price, dict):
                preco_original = preco_original or sale_price.get("regular_amount")
                preco_atual = sale_price.get("amount") or sale_price.get("price") or preco_atual
                has_promotion = bool(preco_original)
            elif sale_price not in (None, ""):
                preco_atual = sale_price
                has_promotion = True
        preco_promocional = preco_atual if has_promotion else None
        try:
            if preco_original not in (None, "", 0) and preco_atual not in (None, "") and float(preco_original) > float(preco_atual):
                has_promotion = True
                preco_promocional = preco_atual
            elif not has_promotion:
                preco_original = None
                preco_promocional = None
        except Exception:
            pass
        listing_type_id = item.get("listing_type_id") or ""
        listing_type_name = fee_data.get("listing_type_name") or _ml_nome_tipo_anuncio(listing_type_id)
        shipping_info = item.get("shipping") if isinstance(item.get("shipping"), dict) else {}
        shipping_info = dict(shipping_info or {})
        shipping_seller_cost = _to_float_safe(shipping_data.get("shipping_seller_cost"))
        shipping_cost = shipping_seller_cost
        if shipping_cost is None:
            shipping_cost = _to_float_safe(shipping_data.get("shipping_cost"))
        if shipping_cost is not None:
            shipping_info.setdefault("seller_cost", shipping_cost)
            shipping_info.setdefault("shipping_cost", shipping_cost)
        shipping_list_cost = _to_float_safe(shipping_data.get("shipping_list_cost"))
        if shipping_list_cost is not None:
            shipping_info.setdefault("list_cost", shipping_list_cost)
        elif shipping_cost is not None:
            shipping_info.setdefault("list_cost", shipping_cost)
        logistic_type = str(shipping_data.get("logistic_type") or shipping_info.get("logistic_type") or "").strip()
        shipping_mode = str(shipping_data.get("shipping_mode") or shipping_info.get("mode") or "").strip()
        desconto_pct = price_info.get("discount_pct", 0) or 0
        try:
            preco_final = preco_promocional if preco_promocional not in (None, "") else preco_atual
            if not desconto_pct and preco_original not in (None, "", 0) and preco_final not in (None, "") and float(preco_original) > float(preco_final):
                desconto_pct = round(((float(preco_original) - float(preco_final)) / float(preco_original)) * 100, 1)
        except Exception:
            desconto_pct = 0
        preco_base_exibicao = preco_original if has_promotion and preco_original not in (None, "") else (standard_price or preco_atual)
        deal_ids_raw = item.get("deal_ids") or []
        if isinstance(deal_ids_raw, str):
            deal_ids = [deal_ids_raw]
        elif isinstance(deal_ids_raw, (list, tuple, set)):
            deal_ids = [str(valor).strip() for valor in deal_ids_raw if str(valor or "").strip()]
        else:
            deal_ids = []
        promotion_id = price_info.get("promotion_id") or fee_data.get("promotion_id") or (deal_ids[0] if deal_ids else None)
        promotion_type = price_info.get("promotion_type") or fee_data.get("promotion_type")
        return {
            "id": item_id,
            "mlb": item_id,
            "titulo": str(item.get("title") or "").strip(),
            "status": str(item.get("status") or "").strip(),
            "category_id": item.get("category_id"),
            "domain_id": item.get("domain_id"),
            "preco": preco_base_exibicao,
            "price": preco_atual,
            "preco_original": preco_original,
            "original_price": preco_original,
            "standard_price": standard_price or preco_base_exibicao,
            "preco_promocional": preco_promocional,
            "promotional_price": preco_promocional,
            "sale_price": preco_promocional,
            "discount_pct": desconto_pct,
            "has_promotion": has_promotion,
            "promotion_id": promotion_id,
            "promotion_type": promotion_type,
            "promotion_name": fee_data.get("promotion_name"),
            "deal_ids": deal_ids,
            "fonte_preco": price_info.get("price_source") or "api_item",
            "estoque": item.get("available_quantity"),
            "vendidos": item.get("sold_quantity"),
            "data_criacao": item.get("date_created"),
            "link": permalink,
            "url": permalink,
            "imagem": item.get("secure_thumbnail") or item.get("thumbnail"),
            "thumbnail": item.get("secure_thumbnail") or item.get("thumbnail"),
            "seller_id": item.get("seller_id"),
            "listing_type_id": listing_type_id,
            "listing_type_name": listing_type_name,
            "tipo_anuncio": listing_type_name,
            "shipping": shipping_info,
            "shipping_cost": shipping_cost,
            "shipping_text": shipping_data.get("shipping_text"),
            "shipping_buyer_cost": shipping_data.get("shipping_buyer_cost"),
            "shipping_buyer_text": shipping_data.get("shipping_buyer_text"),
            "shipping_list_cost": shipping_data.get("shipping_list_cost"),
            "shipping_base_cost": shipping_data.get("shipping_base_cost"),
            "shipping_seller_cost": shipping_seller_cost,
            "shipping_breakdown": shipping_data.get("shipping_breakdown"),
            "free_shipping": shipping_data.get("free_shipping", shipping_info.get("free_shipping")),
            "frete_ml": shipping_cost,
            "frete_ml_text": shipping_data.get("shipping_text") if shipping_cost is not None else None,
            "ad_cost": fee_data.get("ad_cost"),
            "ad_cost_text": fee_data.get("ad_cost_text"),
            "tarifa_ml": fee_data.get("ad_cost"),
            "tarifa_ml_text": fee_data.get("ad_cost_text"),
            "ad_cost_original": fee_data.get("ad_cost_original"),
            "ad_cost_original_text": fee_data.get("ad_cost_original_text"),
            "promotion_fee_discount": fee_data.get("promotion_fee_discount"),
            "promotion_fee_discount_text": fee_data.get("promotion_fee_discount_text"),
            "promotion_fee_discount_applied": fee_data.get("promotion_fee_discount_applied"),
            "promotion_fee_charged": fee_data.get("promotion_fee_charged"),
            "promotion_fee_charged_text": fee_data.get("promotion_fee_charged_text"),
            "promotion_fee_discount_source": fee_data.get("promotion_fee_discount_source"),
            "promotion_fee_base": fee_data.get("promotion_fee_base"),
            "promotion_fee_base_text": fee_data.get("promotion_fee_base_text"),
            "promotion_fee_ml": fee_data.get("promotion_fee_ml"),
            "promotion_fee_ml_text": fee_data.get("promotion_fee_ml_text"),
            "fixed_fee_amount": fee_data.get("fixed_fee_amount"),
            "fixed_fee_text": fee_data.get("fixed_fee_text"),
            "listing_fee_amount": fee_data.get("listing_fee_amount"),
            "listing_fee_text": fee_data.get("listing_fee_text"),
            "sale_fee_pct": fee_data.get("sale_fee_pct"),
            "meli_fee_pct": fee_data.get("meli_fee_pct"),
            "financing_fee_pct": fee_data.get("financing_fee_pct"),
            "fee_breakdown": fee_data.get("fee_breakdown"),
            "logistic_type": logistic_type,
            "shipping_mode": shipping_mode,
            "is_full": logistic_type.lower() == "fulfillment",
            "sku": ", ".join(sorted(_ml_favoritos_extrair_skus_item(item))) or sku_norm,
        }

    def _carregar_anuncios_sku_loja(nome_loja_consulta: str, ids_diretos: Optional[list[str]] = None) -> dict:
        cfg = _obter_cfg_ml(client_id, nome_loja_consulta)
        ids_diretos = list(dict.fromkeys([
            str(item_id or "").strip().upper()
            for item_id in (ids_diretos or [])
            if str(item_id or "").strip().upper().startswith("MLB")
        ]))
        if ids_diretos:
            itens, cfg = _ml_favoritos_buscar_itens_batch(client_id, nome_loja_consulta, cfg, ids_diretos)
            if not itens:
                itens, cfg = _ml_favoritos_buscar_itens_por_sku(client_id, nome_loja_consulta, cfg, sku_norm)
        else:
            itens, cfg = _ml_favoritos_buscar_itens_por_sku(client_id, nome_loja_consulta, cfg, sku_norm)
        custos_por_sku, impostos_por_sku = _carregar_custos_impostos_cadastro_por_sku_loja(client_id, nome_loja_consulta)

        def _montar_anuncio_item(item: dict) -> dict | None:
            if not isinstance(item, dict):
                return None
            item_id = str(item.get("id") or "").strip()
            price_info = _ml_montar_preco_listagem(item)
            shipping_data = {}
            fee_data = {}
            cfg_item = dict(cfg or {})
            if item_id:
                try:
                    price_info, cfg_item = _ml_obter_preco_detalhado(
                        client_id,
                        nome_loja_consulta,
                        cfg_item,
                        item_id,
                        fallback_price=item.get("price"),
                        request_fn=_ml_favoritos_api_request,
                        consultar_sale_price_sempre=True,
                    )
                except Exception as exc:
                    logger.warning("[Favoritos ML] Falha ao buscar preco detalhado do item %s: %s", item_id, exc)
                try:
                    shipping_data, cfg_item = _ml_obter_frete_detalhado(
                        client_id,
                        nome_loja_consulta,
                        cfg_item,
                        item_id,
                        item.get("shipping") or {},
                        request_fn=_ml_favoritos_api_request,
                    )
                except Exception as exc:
                    logger.warning("[Favoritos ML] Falha ao buscar frete detalhado do item %s: %s", item_id, exc)
                try:
                    item_fee = dict(item)
                    if price_info.get("price") not in (None, ""):
                        item_fee["price"] = price_info.get("price")
                    fee_data, cfg_item = _ml_obter_taxas_anuncio(
                        client_id,
                        nome_loja_consulta,
                        cfg_item,
                        item_fee,
                        request_fn=_ml_favoritos_api_request,
                    )
                    promo_fee_info, cfg_item = _ml_obter_desconto_taxa_promocao_item(
                        client_id,
                        nome_loja_consulta,
                        cfg_item,
                        item_id,
                        item=item_fee,
                        price_info=price_info,
                        fee_data=fee_data,
                        deal_ids=item.get("deal_ids") or [],
                        request_fn=_ml_favoritos_api_request,
                    )
                    fee_data = _ml_aplicar_desconto_taxa_promocao_fee_data(fee_data, promo_fee_info)
                except Exception as exc:
                    logger.warning("[Favoritos ML] Falha ao buscar tarifa do item %s: %s", item_id, exc)
            anuncio = _resumir_item_ml(item, price_info=price_info, shipping_data=shipping_data, fee_data=fee_data)
            anuncio["loja"] = nome_loja_consulta
            anuncio["loja_sync"] = nome_loja_consulta
            anuncio["loja_conta"] = nome_loja_consulta
            return anuncio

        anuncios = []
        if len(itens) > 1:
            max_workers_itens = min(8, len(itens))
            with ThreadPoolExecutor(max_workers=max_workers_itens) as executor:
                futuros_itens = [executor.submit(_montar_anuncio_item, item) for item in itens]
                for futuro in as_completed(futuros_itens):
                    try:
                        anuncio = futuro.result()
                        if anuncio:
                            anuncios.append(anuncio)
                    except Exception as exc:
                        logger.warning("[Favoritos ML] Falha ao montar detalhe do SKU %s na loja %s: %s", sku_norm, nome_loja_consulta, exc)
        else:
            for item in itens:
                anuncio = _montar_anuncio_item(item)
                if anuncio:
                    anuncios.append(anuncio)

        _favoritos_completar_frete_pausados_por_sku(anuncios, sku_norm)
        for anuncio in anuncios:
            _favoritos_aplicar_margem_anuncio_ml(anuncio, sku_norm, custos_por_sku, impostos_por_sku)
        return {
            "loja": nome_loja_consulta,
            "anuncios": anuncios,
            "total_itens": len(itens),
        }

    try:
        lojas_para_consulta: list[str] = []
        if compartilhar_efetivo:
            candidatos = [loja_info] + [item for item in lojas_validas if item is not loja_info]
        else:
            candidatos = [loja_info]
        vistos_lojas: set[str] = set()
        for candidata in candidatos:
            nome_candidata = str((candidata or {}).get("nome") or "").strip()
            chave_candidata = _chave_loja_favoritos(nome_candidata)
            if not nome_candidata or chave_candidata in vistos_lojas:
                continue
            vistos_lojas.add(chave_candidata)
            lojas_para_consulta.append(nome_candidata)

        resultados: list[dict] = []
        avisos: list[str] = []
        loja_forcada_chave = _chave_loja_favoritos(nome_loja)
        if len(lojas_para_consulta) <= 1:
            nome_consulta = lojas_para_consulta[0] if lojas_para_consulta else nome_loja
            ids_consulta = ids_forcados if _chave_loja_favoritos(nome_consulta) == loja_forcada_chave else []
            resultados.append(_carregar_anuncios_sku_loja(nome_consulta, ids_consulta))
        else:
            max_workers = min(4, len(lojas_para_consulta))
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                futuros = {
                    executor.submit(
                        _carregar_anuncios_sku_loja,
                        nome,
                        ids_forcados if _chave_loja_favoritos(nome) == loja_forcada_chave else [],
                    ): nome
                    for nome in lojas_para_consulta
                }
                for futuro in as_completed(futuros):
                    nome_consulta = futuros[futuro]
                    try:
                        resultados.append(futuro.result() or {"loja": nome_consulta, "anuncios": [], "total_itens": 0})
                    except Exception as exc:
                        avisos.append(f"{nome_consulta}: {exc}")
                        logger.warning("[Favoritos ML] Falha ao compartilhar SKU %s com loja %s: %s", sku_norm, nome_consulta, exc)

        anuncios = []
        lojas_com_sku = []
        total_itens = 0
        for resultado in resultados:
            total_loja = int(resultado.get("total_itens") or 0)
            total_itens += total_loja
            anuncios_loja = [item for item in (resultado.get("anuncios") or []) if isinstance(item, dict)]
            if total_loja or anuncios_loja:
                loja_resultado = str(resultado.get("loja") or "").strip()
                if loja_resultado:
                    lojas_com_sku.append(loja_resultado)
            anuncios.extend(anuncios_loja)

        ordem_lojas = {nome: idx for idx, nome in enumerate(lojas_para_consulta)}
        lojas_com_sku = list(dict.fromkeys(sorted(lojas_com_sku, key=lambda nome: ordem_lojas.get(nome, 9999))))
        anuncios.sort(key=lambda item: (
            ordem_lojas.get(str(item.get("loja") or ""), 9999),
            str(item.get("titulo") or "").lower(),
            str(item.get("id") or ""),
        ))
        payload = {
            "success": True,
            "lojas": lojas_payload,
            "loja": nome_loja,
            "sku": sku_norm,
            "compartilhado_por_sku": bool(compartilhar_efetivo and len(lojas_com_sku) > 1),
            "lojas_com_sku": lojas_com_sku,
            "anuncios": anuncios,
            "total": len(anuncios),
            "total_itens_ml": total_itens,
            "warnings": avisos,
            "warning": " | ".join(avisos[:3]) if avisos else "",
        }
        _ml_cache_set(cache_key_endpoint, payload)
        return payload
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("[Favoritos ML] Falha ao listar anuncios do SKU %s loja %s: %s", sku_norm, nome_loja, exc)
        raise HTTPException(status_code=500, detail=f"Erro ao listar anÃºncios do SKU no Mercado Livre: {exc}")


@app.put("/api/favoritos/skus/pesquisas")
def favoritos_salvar_pesquisas_sku(
    req: FavoritosSkuPesquisaRequest,
    request: Request,
    client_id: str = Depends(get_tenant_id),
):
    sku_norm = _normalizar_sku_mes(req.sku)
    if not sku_norm:
        raise HTTPException(status_code=400, detail="SKU invalido.")

    loja_nome = str(req.loja or "").strip() or "Todas as lojas"

    try:
        atualizados = _favoritos_salvar_pesquisas_usuario_batch(
            client_id,
            _extrair_username_do_request(request),
            loja_nome,
            [{
                "sku": sku_norm,
                "produto": str(req.produto or "").strip(),
                "pesquisa_1": str(req.pesquisa_1 or "").strip(),
                "pesquisa_2": str(req.pesquisa_2 or "").strip(),
                "pesquisa_3": str(req.pesquisa_3 or "").strip(),
            }],
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Erro ao salvar pesquisas por SKU: {exc}")

    retorno = atualizados[0] if atualizados else {
        "sku": sku_norm,
        "pesquisa_1": str(req.pesquisa_1 or "").strip(),
        "pesquisa_2": str(req.pesquisa_2 or "").strip(),
        "pesquisa_3": str(req.pesquisa_3 or "").strip(),
    }

    return {
        "success": True,
        "sku": retorno.get("sku") or sku_norm,
        "loja": retorno.get("loja") or loja_nome,
        "pesquisa_1": retorno.get("pesquisa_1") or "",
        "pesquisa_2": retorno.get("pesquisa_2") or "",
        "pesquisa_3": retorno.get("pesquisa_3") or "",
    }


@app.post("/api/favoritos/skus/pesquisas/ia")
def favoritos_gerar_pesquisas_sku_ia(
    req: FavoritosSkusPesquisaIARequest,
    request: Request,
    client_id: str = Depends(get_tenant_id),
):
    if not req.itens:
        raise HTTPException(status_code=400, detail="Lista de itens vazia.")
    loja_nome = str(req.loja or "").strip() or "Todas as lojas"

    payload: list[dict] = []
    vistos: set[str] = set()
    for item in req.itens:
        item_dict = item.model_dump() if hasattr(item, "model_dump") else (item.dict() if hasattr(item, "dict") else (item or {}))
        sku_norm = _normalizar_sku_match_favoritos(str((item_dict or {}).get("sku") or "")).strip()
        if not sku_norm or sku_norm.lower() in vistos:
            continue
        vistos.add(sku_norm.lower())
        produto = str((item_dict or {}).get("produto") or "").strip()
        titulo = str((item_dict or {}).get("titulo") or produto).strip()
        descricao = str((item_dict or {}).get("descricao") or "").strip()
        payload.append({
            "sku": sku_norm,
            "titulo": titulo,
            "produto": titulo or produto,
            "descricao": descricao,
            "pesquisa_1": str((item_dict or {}).get("pesquisa_1") or "").strip(),
            "pesquisa_2": str((item_dict or {}).get("pesquisa_2") or "").strip(),
            "pesquisa_3": str((item_dict or {}).get("pesquisa_3") or "").strip(),
        })

    if not payload:
        raise HTTPException(status_code=400, detail="Nenhum SKU vÃ¡lido encontrado.")

    try:
        sugestoes = _favoritos_gerar_pesquisas_ia(
            client_id=client_id,
            itens=payload,
            limite_por_chamada=(req.chunk_tamanho or 24),
            model=_ia_modelo_favoritos_configurado(),
        )
    except Exception as exc:
        logger.exception("[Favoritos IA] Falha ao gerar pesquisas para lotes: %s", exc)
        raise HTTPException(status_code=500, detail=f"Erro ao gerar pesquisas com IA: {exc}")

    username = _extrair_username_do_request(request)
    pesquisas_salvas = (_favoritos_carregar_pesquisas_usuario(client_id, username).get("pesquisas") or {})
    for item in sugestoes:
        sku_norm = _normalizar_sku_match_favoritos(str(item.get("sku") or "")).strip()
        if not sku_norm:
            continue
        atual = pesquisas_salvas.get(_favoritos_chave_pesquisa_usuario("", sku_norm)) or {}
        pesquisa1_existente = str(atual.get("pesquisa_1") or "").strip()
        pesquisa2_existente = str(atual.get("pesquisa_2") or "").strip()
        pesquisa3_existente = str(atual.get("pesquisa_3") or "").strip()
        if pesquisa1_existente and (not req.sobrescrever or not str(item.get("pesquisa_1") or "").strip()):
            item["pesquisa_1"] = pesquisa1_existente
        if pesquisa2_existente and (not req.sobrescrever or not str(item.get("pesquisa_2") or "").strip()):
            item["pesquisa_2"] = pesquisa2_existente
        if pesquisa3_existente and (not req.sobrescrever or not str(item.get("pesquisa_3") or "").strip()):
            item["pesquisa_3"] = pesquisa3_existente

    sugestoes_para_salvar = [
        item for item in sugestoes
        if str(item.get("pesquisa_1") or "").strip()
        or str(item.get("pesquisa_2") or "").strip()
        or str(item.get("pesquisa_3") or "").strip()
    ]

    try:
        atualizados = _favoritos_salvar_pesquisas_usuario_batch(
            client_id=client_id,
            username=username,
            loja=loja_nome,
            itens=sugestoes_para_salvar,
        ) if sugestoes_para_salvar else []
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Erro ao salvar pesquisas por SKU: {exc}")

    return {
        "success": True,
        "loja": str(req.loja or "").strip() or None,
        "total": len(sugestoes),
        "resultados": atualizados,
        "erros": [
            {"sku": item.get("sku"), "erro": item.get("erro")}
            for item in sugestoes
            if str(item.get("erro") or "").strip()
        ],
    }


@app.post("/api/favoritos/ranking/filtrar-ia")
def favoritos_filtrar_ranking_ia(
    req: FavoritosRankingIARequest,
    client_id: str = Depends(get_tenant_id),
):
    sku_norm = _normalizar_sku_match_favoritos(str(req.sku or "")).strip()
    if not sku_norm:
        raise HTTPException(status_code=400, detail="SKU invalido.")

    anuncios = [item for item in (req.anuncios or []) if isinstance(item, dict)]
    if not anuncios:
        return {
            "success": True,
            "sku": sku_norm,
            "manter_ids": [],
            "remover_ids": [],
            "removidos": [],
        }

    limite = max(1, min(int(req.max_anuncios or 160), 220))
    try:
        resultado = _favoritos_ranking_filtrar_com_ia(
            client_id=client_id,
            sku=sku_norm,
            titulo=str(req.titulo or "").strip(),
            descricao=str(req.descricao or "").strip(),
            pesquisas=req.pesquisas or [],
            anuncios=anuncios[:limite],
            meus_anuncios=req.meus_anuncios or [],
            max_confirmados=req.max_confirmados,
            usar_imagem=req.usar_imagem,
            model=_ia_modelo_favoritos_configurado(),
        )
    except Exception as exc:
        logger.exception("[Favoritos IA] Falha ao filtrar ranking do SKU %s: %s", sku_norm, exc)
        raise HTTPException(status_code=500, detail=f"Erro ao filtrar ranking com IA: {exc}")

    return {
        "success": True,
        "sku": sku_norm,
        "max_confirmados": req.max_confirmados,
        **resultado,
    }


@app.get("/api/favoritos/skus/descricao")
def favoritos_buscar_descricao_sku(
    sku: str,
    loja: Optional[str] = None,
    client_id: str = Depends(get_tenant_id),
):
    sku_norm = _normalizar_sku_match_favoritos(sku)
    if not sku_norm:
        raise HTTPException(status_code=400, detail="SKU invalido.")

    lojas_validas = _lojas_favoritos_com_bling_ml(client_id)
    if not lojas_validas:
        raise HTTPException(status_code=400, detail="Nenhuma loja com Bling e Mercado Livre conectados foi encontrada.")

    loja_chave = _chave_loja_favoritos(loja)
    if loja_chave and loja_chave not in {"todas", "todasaslojas", "__todas"}:
        lojas_busca = [loja_info for loja_info in lojas_validas if _chave_loja_favoritos(loja_info.get("nome")) == loja_chave]
        if not lojas_busca:
            raise HTTPException(status_code=400, detail="A loja informada nÃ£o estÃƒÂ¡ com Bling e Mercado Livre conectados.")
    else:
        lojas_busca = lojas_validas

    melhor_resultado: dict | None = None
    encontrou_item = False
    erros: list[str] = []

    for loja_info in lojas_busca:
        nome_loja = str(loja_info.get("nome") or "").strip()
        if not nome_loja:
            continue
        try:
            cfg = _obter_cfg_ml(client_id, nome_loja)
            itens, cfg = _ml_favoritos_buscar_itens_por_sku(client_id, nome_loja, cfg, sku_norm)
            for item in itens:
                item_id = str(item.get("id") or "").strip()
                if not item_id:
                    continue
                descricao_info = _ml_favoritos_obter_descricao_item(client_id, nome_loja, cfg, item_id)
                descricao = str(descricao_info.get("descricao") or "").strip()
                erro = str(descricao_info.get("erro") or "").strip()
                if erro:
                    erros.append(erro)
                encontrou_item = True
                resultado_base = {
                    "success": bool(descricao) and not erro,
                    "sku": sku_norm,
                    "status": "ok" if descricao else ("erro" if erro else "sem_descricao"),
                    "loja": nome_loja,
                    "item_id": item_id,
                    "titulo": item.get("title") or "",
                    "permalink": item.get("permalink") or f"https://produto.mercadolivre.com.br/{item_id}",
                    "descricao": descricao,
                    "description_info": descricao_info.get("description_info", {}),
                    "erro": erro,
                    "fonte": "mercadolivre_api",
                }
                if descricao:
                    _favoritos_salvar_descricao_cadastro(client_id, sku_norm, descricao)
                    return resultado_base
                if melhor_resultado is None:
                    melhor_resultado = resultado_base
        except HTTPException as exc:
            erros.append(str(exc.detail or exc))
        except Exception as exc:
            logger.exception(f"[FAVORITOS SKU] Falha ao buscar descriÃƒÂ§ÃƒÂ£o do SKU {sku_norm} na loja {nome_loja}: {exc}")
            erros.append(str(exc))

    if melhor_resultado is not None:
        melhor_resultado["message"] = "AnÃƒÂºncio encontrado, mas sem descriÃƒÂ§ÃƒÂ£o cadastrada no Mercado Livre."
        return melhor_resultado

    if encontrou_item:
        detalhe = f"Nenhum anuncio com descriÃƒÂ§ÃƒÂ£o foi encontrado para o SKU {sku_norm} nas lojas conectadas."
    else:
        detalhe = f"Nenhum anuncio ativo com o SKU {sku_norm} foi encontrado nas lojas conectadas."
    if erros:
        detalhe += " Detalhes: " + " | ".join(erros[:3])
    raise HTTPException(status_code=404, detail=detalhe)


@app.post("/api/favoritos/skus/descricoes")

def favoritos_buscar_descricoes_skus(req: FavoritosSkuDescricoesRequest, client_id: str = Depends(get_tenant_id)):
    skus_originais = [str(sku or "").strip() for sku in (req.skus or []) if str(sku or "").strip()]
    skus_originais = list(dict.fromkeys(skus_originais))[:1000]
    if not skus_originais:
        raise HTTPException(status_code=400, detail="Nenhum SKU informado.")

    sku_original_por_norm: dict[str, str] = {}
    for sku in skus_originais:
        sku_norm = _normalizar_sku_match_favoritos(sku)
        if sku_norm and sku_norm not in sku_original_por_norm:
            sku_original_por_norm[sku_norm] = sku
    alvos_norm = set(sku_original_por_norm.keys())
    if not alvos_norm:
        raise HTTPException(status_code=400, detail="Nenhum SKU valido informado.")

    item_ids_por_sku_norm: dict[str, list[str]] = {}
    for sku_raw, ids_raw in (req.item_ids_por_sku or {}).items():
        sku_norm = _normalizar_sku_match_favoritos(str(sku_raw or ""))
        if not sku_norm or sku_norm not in alvos_norm:
            continue
        ids_limpos: list[str] = []
        for item_raw in ids_raw or []:
            item_id = _extrair_item_id(str(item_raw or "")) or str(item_raw or "").strip()
            if item_id and item_id not in ids_limpos:
                ids_limpos.append(item_id)
            if len(ids_limpos) >= 8:
                break
        if ids_limpos:
            item_ids_por_sku_norm[sku_norm] = ids_limpos

    lojas_validas = _lojas_favoritos_com_bling_ml(client_id)
    loja_chave = _chave_loja_favoritos(req.loja)
    if loja_chave and loja_chave not in {"todas", "todasaslojas", "__todas"}:
        lojas_busca = [loja_info for loja_info in lojas_validas if _chave_loja_favoritos(loja_info.get("nome")) == loja_chave]
    else:
        lojas_busca = lojas_validas
    if not lojas_busca:
        raise HTTPException(status_code=400, detail="Nenhuma loja conectada ao Mercado Livre encontrada para buscar descriÃƒÂ§ÃƒÂµes.")

    resultados: dict[str, dict] = {
        sku_original: {
            "success": False,
            "sku": sku_original,
            "status": "pendente",
            "descricao": "",
        }
        for sku_original in skus_originais
    }
    pendentes_norm = set(alvos_norm)
    candidatos_por_sku: dict[str, int] = {sku_norm: 0 for sku_norm in alvos_norm}
    erros: list[str] = []

    for loja_info in lojas_busca:
        if not pendentes_norm:
            break
        nome_loja = str(loja_info.get("nome") or "").strip()
        if not nome_loja:
            continue
        try:
            cfg = _obter_cfg_ml(client_id, nome_loja)
            item_para_skus_direto: dict[str, list[str]] = {}
            for sku_norm in list(pendentes_norm):
                for item_id in item_ids_por_sku_norm.get(sku_norm, []):
                    vinculados = item_para_skus_direto.setdefault(item_id, [])
                    if sku_norm not in vinculados:
                        vinculados.append(sku_norm)
                        candidatos_por_sku[sku_norm] = candidatos_por_sku.get(sku_norm, 0) + 1

            if item_para_skus_direto:
                with ThreadPoolExecutor(max_workers=min(8, max(1, len(item_para_skus_direto)))) as executor:
                    future_map = {
                        executor.submit(
                            _ml_favoritos_obter_descricao_item,
                            client_id,
                            nome_loja,
                            dict(cfg),
                            item_id,
                        ): (item_id, skus_vinculados)
                        for item_id, skus_vinculados in item_para_skus_direto.items()
                    }
                    for future in as_completed(future_map):
                        item_id, skus_vinculados = future_map[future]
                        try:
                            desc_info = future.result() or {}
                        except Exception as exc:
                            desc_info = {"descricao": "", "description_info": {}, "erro": str(exc)}

                        descricao = str(desc_info.get("descricao") or "").strip()
                        erro = str(desc_info.get("erro") or "").strip()
                        payload_base = {
                            "success": bool(descricao) and not erro,
                            "status": "ok" if descricao else ("erro" if erro else "sem_descricao"),
                            "loja": nome_loja,
                            "item_id": item_id,
                            "titulo": "",
                            "permalink": f"https://produto.mercadolivre.com.br/{item_id}",
                            "descricao": descricao,
                            "erro": erro,
                            "fonte": "mercadolivre_api_item_id",
                        }

                        for sku_norm in skus_vinculados:
                            if sku_norm not in pendentes_norm:
                                continue
                            sku_original = sku_original_por_norm.get(sku_norm)
                            if not sku_original:
                                continue
                            if descricao:
                                _favoritos_salvar_descricao_cadastro(client_id, sku_norm, descricao)
                                resultados[sku_original] = {"sku": sku_original, **payload_base}
                                pendentes_norm.discard(sku_norm)

            if not pendentes_norm:
                break

            usou_mapa_ativo = len(pendentes_norm) >= 20
            if usou_mapa_ativo:
                itens_por_sku, cfg = _ml_favoritos_mapear_itens_ativos_por_skus(
                    client_id,
                    nome_loja,
                    cfg,
                    pendentes_norm,
                    max_por_sku=3,
                )
            else:
                itens_por_sku, cfg = _ml_favoritos_buscar_primeiros_itens_por_skus(
                    client_id,
                    nome_loja,
                    cfg,
                    pendentes_norm,
                    max_por_sku=3,
                )

            # A varredura em lote Ã© rÃ¡pida, mas nem sempre cobre todos os resultados
            # (o ML limita a janela de busca). Para nÃ£o marcar falso "nÃ£o encontrado",
            # completa os SKUs restantes com busca direta por seller_sku.
            if usou_mapa_ativo:
                sem_match = {sku_norm for sku_norm in pendentes_norm if not itens_por_sku.get(sku_norm)}
                if sem_match:
                    itens_diretos, cfg = _ml_favoritos_buscar_primeiros_itens_por_skus(
                        client_id,
                        nome_loja,
                        cfg,
                        sem_match,
                        max_por_sku=3,
                    )
                    for sku_norm, itens in (itens_diretos or {}).items():
                        if itens and not itens_por_sku.get(sku_norm):
                            itens_por_sku[sku_norm] = itens
            if not itens_por_sku:
                continue

            item_para_skus: dict[str, list[str]] = {}
            item_por_id: dict[str, dict] = {}
            for sku_norm, itens in itens_por_sku.items():
                if sku_norm not in pendentes_norm:
                    continue
                for item in itens:
                    item_id = str(item.get("id") or "").strip()
                    if not item_id:
                        continue
                    skus_vinculados = item_para_skus.setdefault(item_id, [])
                    if sku_norm not in skus_vinculados:
                        skus_vinculados.append(sku_norm)
                        item_por_id[item_id] = item
                        candidatos_por_sku[sku_norm] = candidatos_por_sku.get(sku_norm, 0) + 1

            # Completa skus sem match inicial com busca direcionada por SKU.
            if not usou_mapa_ativo:
                for sku_norm in list(pendentes_norm):
                    if sku_norm in itens_por_sku:
                        continue
                    try:
                        itens_direto, cfg = _ml_favoritos_buscar_itens_por_sku(client_id, nome_loja, cfg, sku_norm)
                    except HTTPException:
                        continue
                    for item in itens_direto:
                        item_id = str(item.get("id") or "").strip()
                        if not item_id:
                            continue
                        item_para_skus.setdefault(item_id, [])
                        if sku_norm in item_para_skus[item_id]:
                            continue
                        item_para_skus[item_id].append(sku_norm)
                        item_por_id[item_id] = item
                        candidatos_por_sku[sku_norm] = candidatos_por_sku.get(sku_norm, 0) + 1
                        break

            if not item_para_skus:
                continue

            with ThreadPoolExecutor(max_workers=min(8, max(1, len(item_para_skus)))) as executor:
                future_map = {
                    executor.submit(
                        _ml_favoritos_obter_descricao_item_rapida,
                        client_id,
                        nome_loja,
                        dict(cfg),
                        item_id,
                    ): (item_id, skus_vinculados)
                    for item_id, skus_vinculados in item_para_skus.items()
                }
                for future in as_completed(future_map):
                    item_id, skus_vinculados = future_map[future]
                    try:
                        desc_info = future.result() or {}
                    except Exception as exc:
                        desc_info = {"descricao": "", "description_info": {}, "erro": str(exc)}

                    descricao = str(desc_info.get("descricao") or "").strip()
                    erro = str(desc_info.get("erro") or "").strip()
                    item = item_por_id.get(item_id, {})
                    item_titulo = item.get("title") or item.get("name") or ""
                    item_permalink = item.get("permalink") or f"https://produto.mercadolivre.com.br/{item_id}"
                    payload_base = {
                        "success": bool(descricao) and not erro,
                        "status": "ok" if descricao else ("erro" if erro else "sem_descricao"),
                        "loja": nome_loja,
                        "item_id": item_id,
                        "titulo": item_titulo,
                        "permalink": item_permalink,
                        "descricao": descricao,
                        "erro": erro,
                        "fonte": "mercadolivre_api",
                    }

                    for sku_norm in skus_vinculados:
                        if sku_norm not in pendentes_norm:
                            continue
                        sku_original = sku_original_por_norm.get(sku_norm)
                        if not sku_original:
                            continue
                        if descricao:
                            _favoritos_salvar_descricao_cadastro(client_id, sku_norm, descricao)
                            resultados[sku_original] = {"sku": sku_original, **payload_base}
                            pendentes_norm.discard(sku_norm)
        except HTTPException as exc:
            erros.append(f"{nome_loja}: {exc.detail}")
        except Exception as exc:
            logger.exception(f"[FAVORITOS SKU] Falha ao buscar descriÃƒÂ§ÃƒÂµes em lote na loja {nome_loja}: {exc}")
            erros.append(f"{nome_loja}: {exc}")
    for sku_norm in pendentes_norm:
        sku_original = sku_original_por_norm.get(sku_norm)
        if sku_original and resultados.get(sku_original, {}).get("status") == "pendente":
            if candidatos_por_sku.get(sku_norm, 0) > 0:
                resultados[sku_original] = {
                    "success": False,
                    "sku": sku_original,
                    "status": "sem_descricao",
                    "descricao": "",
                    "erro": "AnÃƒÂºncio encontrado, mas sem descriÃƒÂ§ÃƒÂ£o cadastrada no Mercado Livre.",
                }
            else:
                resultados[sku_original] = {
                    "success": False,
                    "sku": sku_original,
                    "status": "nao_encontrado",
                    "descricao": "",
                    "erro": "Nenhum anuncio ativo encontrado para este SKU.",
                }

    return {
        "success": True,
        "results": list(resultados.values()),
        "total": len(resultados),
        "erros": erros[:5],
    }


def _ml_headers():
    return {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
    }

def _normalize_text(text: str) -> str:
    if not isinstance(text, str):
        return ""
    norm = unicodedata.normalize("NFKD", text)
    norm = "".join([c for c in norm if not unicodedata.combining(c)])
    return norm.lower().strip()

def _normalizar_termo_busca_ml(termo: str) -> str:
    texto = _normalize_text(termo)
    texto = re.sub(r"""[.,;:()\[\]{}"'^~!?|\\/_+=*\-]+""", " ", texto)
    texto = re.sub(r"\s+", " ", texto).strip()
    return texto

def _termos_busca_ml(termo: str, extras: list[str] | None = None) -> list[str]:
    candidatos = [
        _normalizar_termo_busca_ml(termo),
        str(termo or "").strip(),
    ]
    for extra in extras or []:
        candidatos.extend([
            _normalizar_termo_busca_ml(str(extra or "")),
            str(extra or "").strip(),
        ])
    vistos: set[str] = set()
    saida: list[str] = []
    for candidato in candidatos:
        if not candidato:
            continue
        chave = candidato.lower()
        if chave in vistos:
            continue
        vistos.add(chave)
        saida.append(candidato)
    return saida

def _extrair_item_id(url: str) -> str | None:
    texto = unquote(str(url or ""))
    match = re.search(r"MLB-?(\d+)", texto, re.IGNORECASE)
    return f"MLB{match.group(1)}" if match else None

def _extrair_catalog_id(url: str) -> str | None:
    match = re.search(r"MLBU\d+", url or "")
    return match.group(0) if match else None

def _ml_api_get(url: str, params: dict | None = None, max_retries: int = 3, delay: int = 1):
    headers = {
        **_ml_headers(),
        "Accept": "application/json, text/plain, */*",
        "Referer": "https://www.mercadolivre.com.br/"
    }
    for tentativa in range(max_retries):
        try:
            resp = requests.get(url, params=params, headers=headers, timeout=10, verify=False)
            if resp.status_code == 200:
                return resp.json()
            logger.warning("ML API erro %s: status %s. Tentativa %s/%s", url, resp.status_code, tentativa + 1, max_retries)
            time.sleep(delay)
        except Exception:
            logger.exception("ML API erro %s. Tentativa %s/%s", url, tentativa + 1, max_retries)
            time.sleep(delay)
    return None

@functools.lru_cache(maxsize=1000)
def _ml_api_item(item_id: str):
    item_id = _extrair_item_id(item_id) or str(item_id or "").strip().upper().replace("-", "")
    if not item_id:
        return None
    return _ml_api_get(f"https://api.mercadolibre.com/items/{item_id}")

def _ml_api_item_com_oauth_tenant(client_id: str | None, item_id: str):
    item_id = _extrair_item_id(item_id) or str(item_id or "").strip().upper().replace("-", "")
    if not client_id or not item_id:
        return None
    try:
        lojas = carregar_lojas(client_id)
    except Exception:
        lojas = []

    for loja in lojas or []:
        nome_loja = str((loja or {}).get("nome") or "").strip()
        integracoes = (loja or {}).get("integracoes") or {}
        cfg = dict(integracoes.get("mercadolivre") or {})
        if not nome_loja or not cfg.get("access_token"):
            continue
        cfg["app_id"] = cfg.get("app_id") or cfg.get("id") or cfg.get("client_id")
        cfg["client_secret"] = cfg.get("client_secret") or cfg.get("secret")
        try:
            resp, _cfg = _ml_api_request(
                client_id,
                nome_loja,
                cfg,
                "GET",
                f"https://api.mercadolibre.com/items/{item_id}",
                timeout=12,
            )
            if resp.status_code == 200:
                data = resp.json() or {}
                if isinstance(data, dict) and data.get("id"):
                    return data
            logger.info("[Favoritos][Datas] ML OAuth loja=%s item=%s status=%s", nome_loja, item_id, resp.status_code)
        except Exception as exc:
            logger.warning("[Favoritos][Datas] Falha OAuth loja=%s item=%s: %s", nome_loja, item_id, exc)
    return None

@functools.lru_cache(maxsize=1000)
def _ml_api_user(user_id: str):
    if not user_id:
        return None
    return _ml_api_get(f"https://api.mercadolibre.com/users/{user_id}")

def _ml_api_user_com_oauth_tenant(client_id: str | None, user_id: str | None):
    user_id = str(user_id or "").strip()
    if not client_id or not user_id:
        return None
