def _ml_api_search(termo: str, limit: int = 50, offset: int = 0):
    params = {
        "q": termo,
        "limit": limit,
        "offset": offset
    }
    return _ml_api_get("https://api.mercadolibre.com/sites/MLB/search", params=params)

def _ml_api_search_paginated(termo: str, limit: int = 60) -> list[dict]:
    limite = max(1, min(int(limit or 60), 100))
    resultados: list[dict] = []
    vistos: set[str] = set()
    offset = 0

    while len(resultados) < limite:
        page_limit = min(50, limite - len(resultados))
        if page_limit <= 0:
            break
        api_data = _ml_api_search(termo, limit=page_limit, offset=offset) or {}
        pagina = api_data.get("results") or []
        if not pagina:
            break

        adicionados = 0
        for item in pagina:
            if not isinstance(item, dict):
                continue
            chave = str(item.get("id") or item.get("permalink") or "").strip()
            if chave and chave in vistos:
                continue
            if chave:
                vistos.add(chave)
            resultados.append(item)
            adicionados += 1
            if len(resultados) >= limite:
                break

        if len(pagina) < page_limit or adicionados <= 0:
            break
        offset += page_limit

    return resultados[:limite]

def _ml_parcelamento_sem_juros_api(item: dict | None):
    if not isinstance(item, dict):
        return None
    installments = item.get("installments") if isinstance(item.get("installments"), dict) else None
    if not installments:
        return None
    try:
        raw_rate = installments.get("rate", installments.get("interest_rate", installments.get("interestRate")))
        rate = float(str(raw_rate).replace("%", "").replace(",", ".")) if raw_rate not in (None, "") else None
    except Exception:
        rate = None
    try:
        quantity = int(float(str(installments.get("quantity") or installments.get("installments") or 0).replace(",", ".")))
    except Exception:
        quantity = 0
    if rate is not None:
        return rate == 0 and quantity > 1
    if installments.get("no_interest") is True or installments.get("noInterest") is True:
        return True
    return False

def _ml_parcelamento_sem_juros_texto(texto: str) -> bool:
    normalizado = unicodedata.normalize("NFKD", str(texto or ""))
    normalizado = "".join(c for c in normalizado if not unicodedata.combining(c)).lower()
    normalizado = re.sub(r"\s+", " ", normalizado)
    return bool(re.search(r"\bsem\s+juros\b|\b0\s*%?\s*de?\s*juros\b", normalizado))

def _normalizar_data_ml(valor):
    if not valor:
        return None
    texto = str(valor).strip()
    if not texto:
        return None
    texto = texto.replace("\\/", "/")
    try:
        # Mantem ISO quando possÃƒÂ­vel; o frontend jÃƒÂ¡ formata para pt-BR.
        datetime.fromisoformat(texto.replace("Z", "+00:00"))
        return texto
    except Exception:
        return texto

def _extrair_data_criacao_codigo_fonte(html_text: str):
    if not html_text:
        return None

    def _normalizar_codigo_texto(texto: str) -> str:
        texto = str(texto or "")
        texto = html_lib.unescape(texto)
        texto = texto.replace("\\u002F", "/").replace("\\/", "/")
        texto = texto.replace("\\n", " ").replace("\\t", " ").replace("\\r", " ")
        texto = texto.replace('\\"', '"').replace("\\'", "'")
        return texto

    def _procurar_em_objeto(root):
        date_keys = {
            "dateCreated",
            "date_created",
            "releaseDate",
            "start_time",
            "startTime",
            "item_date_created",
            "creation_date",
            "creationDate",
            "listing_start_time",
            "start_date",
            "itemStartTime",
        }
        stack = [root]
        seen = set()
        while stack:
            cur = stack.pop()
            if isinstance(cur, dict):
                obj_id = id(cur)
                if obj_id in seen:
                    continue
                seen.add(obj_id)
                for key, value in cur.items():
                    if key in date_keys:
                        found = _normalizar_data_ml(value)
                        if found:
                            return found
                    if key == "date_created" and isinstance(value, dict):
                        found = _normalizar_data_ml(value.get("value"))
                        if found:
                            return found
                    if isinstance(value, (dict, list)):
                        stack.append(value)
            elif isinstance(cur, list):
                stack.extend(cur)
        return None

    textos_para_busca = [html_text, _normalizar_codigo_texto(html_text)]
    patterns = [
        r'"date_created"\s*:\s*"([^"]+)"',
        r'"dateCreated"\s*:\s*"([^"]+)"',
        r'"date_created"\s*:\s*{\s*"value"\s*:\s*"([^"]+)"',
        r'"start_time"\s*:\s*"([^"]+)"',
        r'"startTime"\s*:\s*"([^"]+)"',
        r'"item_date_created"\s*:\s*"([^"]+)"',
        r'"creation_date"\s*:\s*"([^"]+)"',
        r'"creationDate"\s*:\s*"([^"]+)"',
        r'"listing_start_time"\s*:\s*"([^"]+)"',
        r'"start_date"\s*:\s*"([^"]+)"',
        r'"itemStartTime"\s*:\s*"([^"]+)"',
    ]
    for texto in textos_para_busca:
        for pattern in patterns:
            match = re.search(pattern, texto, flags=re.IGNORECASE)
            if match:
                data = _normalizar_data_ml(match.group(1))
                if data:
                    return data

    try:
        soup = BeautifulSoup(html_text, "lxml")
        for script in soup.find_all("script"):
            script_text = _normalizar_codigo_texto(script.get_text() or "")
            if not script_text:
                continue
            for pattern in patterns:
                match = re.search(pattern, script_text, flags=re.IGNORECASE)
                if match:
                    data = _normalizar_data_ml(match.group(1))
                    if data:
                        return data
            stripped = script_text.strip()
            if not stripped or stripped[0] not in "[{":
                continue
            try:
                data = json.loads(stripped)
            except Exception:
                continue
            found = _procurar_em_objeto(data)
            if found:
                return found
    except Exception:
        logger.debug("Falha ao analisar scripts para data de criacao", exc_info=True)

    return None

def _extrair_vendedor_codigo_fonte(html_text: str):
    if not html_text:
        return None

    patterns = [
        r'"seller_name"\s*:\s*"([^"]+)"',
        r'"sellerName"\s*:\s*"([^"]+)"',
        r'"nickname"\s*:\s*"([^"]+)"',
        r'"official_store_name"\s*:\s*"([^"]+)"',
        r'"officialStoreName"\s*:\s*"([^"]+)"',
        r'"official_store"\s*:\s*\{[^{}]*"nickname"\s*:\s*"([^"]+)"',
        r'"official_store"\s*:\s*\{[^{}]*"name"\s*:\s*"([^"]+)"',
        r'"seller"\s*:\s*\{[^{}]*"nickname"\s*:\s*"([^"]+)"',
    ]
    for pattern in patterns:
        match = re.search(pattern, html_text, flags=re.IGNORECASE | re.DOTALL)
        if match:
            vendedor = str(match.group(1) or "").strip()
            if vendedor:
                return vendedor

    try:
        soup = BeautifulSoup(html_text, "lxml")
        selectors = [
            ".ui-pdp-seller__header__title",
            ".ui-pdp-seller__link-trigger",
            ".ui-pdp-seller__nickname",
            ".ui-pdp-official-store-label",
            "[data-testid='seller-info']",
            "[data-testid='official-store-info']",
        ]
        for selector in selectors:
            tag = soup.select_one(selector)
            if tag:
                texto = " ".join(tag.get_text(" ", strip=True).split())
                texto = re.sub(r"^(vendido por|loja oficial)\s+", "", texto, flags=re.IGNORECASE).strip()
                if texto:
                    return texto
    except Exception:
        logger.debug("Falha ao extrair vendedor do codigo-fonte", exc_info=True)

    return None

def _extrair_info_anuncio(url: str, item_id: str | None = None, client_id: str | None = None):
    item_id = _extrair_item_id(item_id or "") or _extrair_item_id(url) or item_id
    info = {
        "data_criacao": None,
        "fonte": None,
        "vendedor": None,
        "fonte_vendedor": None,
        "vendas": None,
        "fonte_vendas": None,
        "sku": None,
        "listing_type_id": None,
        "listing_type_name": None,
        "tipo_anuncio": None,
        "parcelamento_sem_juros": None,
        "shipping": None,
        "logistic_type": None,
        "shipping_mode": None,
        "is_full": None,
        "condicao": None,
        "condition": None,
        "item_condition": None,
    }

    def _vendas_da_api(dados: dict | None):
        if not isinstance(dados, dict):
            return None
        for campo in ("sold_quantity", "soldQuantity", "sold", "sold_quantity_by_state", "sold_quantity_by_country", "ventas", "quantidade_vendida"):
            if campo not in dados:
                continue
            valor = _parse_vendas_ml(dados.get(campo))
            if valor is not None:
                return valor
        return None

    def _vendedor_da_api(dados: dict | None):
        if not isinstance(dados, dict):
            return None
        seller = dados.get("seller") if isinstance(dados.get("seller"), dict) else {}
        vendedor_api = _normalizar_nome_vendedor_ml(dados)
        seller_id = dados.get("seller_id") or seller.get("id")
        if vendedor_api:
            return str(vendedor_api).strip(), seller_id
        if seller_id:
            user_data = _ml_api_user_com_oauth_tenant(client_id, str(seller_id)) or _ml_api_user(str(seller_id))
            if isinstance(user_data, dict):
                nome = (
                    user_data.get("nickname")
                    or user_data.get("official_store_name")
                    or (user_data.get("official_store") or {}).get("name")
                )
                if nome:
                    return str(nome).strip(), seller_id
        return None, seller_id

    if item_id:
        api_data = _ml_api_item_com_oauth_tenant(client_id, item_id) or _ml_api_item(item_id)
        if isinstance(api_data, dict):
            data_api = _normalizar_data_ml(api_data.get("date_created") or api_data.get("start_time"))
            if data_api:
                info["data_criacao"] = data_api
                info["fonte"] = "api_item"
            vendedor_api, seller_id = _vendedor_da_api(api_data)
            if vendedor_api:
                info["vendedor"] = vendedor_api
                info["fonte_vendedor"] = "api_item"
            if seller_id:
                info["seller_id"] = str(seller_id).strip()
            sku_api = _ml_extrair_sku(api_data)
            if sku_api:
                info["sku"] = sku_api
            item_condition = _ml_extrair_item_condition(api_data)
            if item_condition:
                info["condicao"] = item_condition
                info["condition"] = item_condition
                info["item_condition"] = item_condition
            shipping_info = api_data.get("shipping") if isinstance(api_data.get("shipping"), dict) else {}
            if shipping_info:
                logistic_type = str(shipping_info.get("logistic_type") or "").strip()
                info["shipping"] = shipping_info
                info["logistic_type"] = logistic_type
                info["shipping_mode"] = str(shipping_info.get("mode") or "").strip()
                info["is_full"] = logistic_type.lower() == "fulfillment"
            listing_type_id = str(api_data.get("listing_type_id") or "").strip()
            if listing_type_id:
                info["listing_type_id"] = listing_type_id
                info["listing_type_name"] = _ml_nome_tipo_anuncio(listing_type_id)
                info["tipo_anuncio"] = info["listing_type_name"]
            sem_juros_api = _ml_parcelamento_sem_juros_api(api_data)
            if sem_juros_api is not None:
                info["parcelamento_sem_juros"] = bool(sem_juros_api)
                info["tipo_anuncio"] = "Premium" if info["parcelamento_sem_juros"] else "Classico"
            vendas_api = _vendas_da_api(api_data)
            if vendas_api is not None:
                info["vendas"] = vendas_api
                info["fonte_vendas"] = "api_item_vendas"

            if info["data_criacao"] and info["vendedor"] and info["vendas"] is not None and info["parcelamento_sem_juros"] is not None:
                return info

    if not url:
        return info

    try:
        headers = {
            **_ml_headers(),
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "pt-BR,pt;q=0.9,en;q=0.7",
        }
        resp = requests.get(url, headers=headers, timeout=12, allow_redirects=True, verify=False)
        if resp.status_code != 200:
            logger.warning("[Favoritos][Datas] Erro ao abrir %s: status %s", url, resp.status_code)
            return info

        if not info["data_criacao"]:
            data_html = _extrair_data_criacao_codigo_fonte(resp.text)
            if data_html:
                info["data_criacao"] = data_html
                info["fonte"] = "codigo_fonte"

        if not info["vendedor"]:
            vendedor_html = _extrair_vendedor_codigo_fonte(resp.text)
            if vendedor_html:
                info["vendedor"] = vendedor_html
                info["fonte_vendedor"] = "codigo_fonte"

        if info["vendas"] is None:
            vendas_match = re.search(
                r"\\b([\\d\\.]+\\,?\\d*)\\s*(?:mil|k)?\\s+vendid[oa]s?",
                resp.text,
                flags=re.IGNORECASE,
            )
            if vendas_match:
                info["vendas"] = _parse_vendas_ml(vendas_match.group(0))
                info["fonte_vendas"] = "html_text"

        if info["parcelamento_sem_juros"] is None:
            info["parcelamento_sem_juros"] = _ml_parcelamento_sem_juros_texto(resp.text)
            info["tipo_anuncio"] = "Premium" if info["parcelamento_sem_juros"] else "Classico"

        redirected_id = _extrair_item_id(resp.url)
        if redirected_id and redirected_id != item_id and (not info["data_criacao"] or not info["vendedor"] or info["vendas"] is None):
            api_data = _ml_api_item_com_oauth_tenant(client_id, redirected_id) or _ml_api_item(redirected_id)
            if isinstance(api_data, dict):
                if not info["data_criacao"]:
                    data_api = _normalizar_data_ml(api_data.get("date_created") or api_data.get("start_time"))
                    if data_api:
                        info["data_criacao"] = data_api
                        info["fonte"] = "api_item_redirect"
                if not info["vendedor"]:
                    vendedor_api, seller_id = _vendedor_da_api(api_data)
                    if vendedor_api:
                        info["vendedor"] = vendedor_api
                        info["fonte_vendedor"] = "api_item_redirect"
                    if seller_id:
                        info["seller_id"] = str(seller_id).strip()
                if not info["sku"]:
                    sku_api = _ml_extrair_sku(api_data)
                    if sku_api:
                        info["sku"] = sku_api
                if not info["condicao"]:
                    item_condition = _ml_extrair_item_condition(api_data)
                    if item_condition:
                        info["condicao"] = item_condition
                        info["condition"] = item_condition
                        info["item_condition"] = item_condition
                if not info.get("shipping"):
                    shipping_info = api_data.get("shipping") if isinstance(api_data.get("shipping"), dict) else {}
                    if shipping_info:
                        logistic_type = str(shipping_info.get("logistic_type") or "").strip()
                        info["shipping"] = shipping_info
                        info["logistic_type"] = logistic_type
                        info["shipping_mode"] = str(shipping_info.get("mode") or "").strip()
                        info["is_full"] = logistic_type.lower() == "fulfillment"
                if not info["listing_type_id"]:
                    listing_type_id = str(api_data.get("listing_type_id") or "").strip()
                    if listing_type_id:
                        info["listing_type_id"] = listing_type_id
                        info["listing_type_name"] = _ml_nome_tipo_anuncio(listing_type_id)
                        info["tipo_anuncio"] = info["listing_type_name"]
                sem_juros_api = _ml_parcelamento_sem_juros_api(api_data)
                if info["parcelamento_sem_juros"] is None and sem_juros_api is not None:
                    info["parcelamento_sem_juros"] = bool(sem_juros_api)
                    info["tipo_anuncio"] = "Premium" if info["parcelamento_sem_juros"] else "Classico"
                if info["vendas"] is None:
                    vendas_api = _vendas_da_api(api_data)
                    if vendas_api is not None:
                        info["vendas"] = vendas_api
                        info["fonte_vendas"] = "api_item_redirect"
    except Exception:
        logger.exception("[Favoritos][Datas] Erro ao consultar codigo-fonte de %s", url)

    return info

@app.post("/api/favoritos/ml/primeira-pagina")
async def favoritos_ml_primeira_pagina(req: FavoritosPrimeiraPaginaRequest, client_id: str = Depends(get_tenant_id)):
    termo = (req.termo or "").strip()
    if not termo:
        raise HTTPException(status_code=400, detail="Termo de pesquisa vazio.")
    termos_consulta = _termos_busca_ml(termo, req.termos_busca)
    termo_usado = termos_consulta[0] if termos_consulta else termo

    def _parse_vendas(v):
        return _parse_vendas_ml(v)

    try:
        # Usa primeiro a API oficial (ordem da pÃƒÂ¡gina de busca).
        limite = min(max(int(req.max_anuncios or 60), 1), 100)
        base_resultados = []
        for termo_consulta in termos_consulta:
            base_resultados = _ml_api_search_paginated(termo_consulta, limit=limite)
            termo_usado = termo_consulta
            if base_resultados:
                break

        # Fallback para HTML se API falhar ou o Mercado Livre bloquear a API.
        if not base_resultados and bool(req.usar_automatico):
            url_busca = f"https://lista.mercadolivre.com.br/?q={quote_plus(termo_usado)}"
            html_resultados = _buscar_anuncios_mercadolivre_html(url_busca, max_retries=2, delay=1) or []
            for r in html_resultados:
                base_resultados.append({
                    "id": _extrair_item_id(r.get("url") or r.get("link") or ""),
                    "title": r.get("titulo") or "",
                    "permalink": r.get("url") or r.get("link") or "",
                    "sold_quantity": _parse_vendas(r.get("vendas")),
                    "date_created": r.get("data_criacao")
                })

        if not base_resultados:
            for termo_consulta in termos_consulta:
                url_busca = f"https://lista.mercadolivre.com.br/?q={quote_plus(termo_consulta)}"
                automaticos = _buscar_anuncios_mercadolivre_automatico(url_busca, max_anuncios=limite) or []
                termo_usado = termo_consulta
                for r in automaticos:
                    base_resultados.append({
                        "id": _extrair_item_id(r.get("url") or r.get("link") or ""),
                        "title": r.get("titulo") or "",
                        "permalink": r.get("url") or r.get("link") or "",
                        "sold_quantity": _parse_vendas(r.get("vendas")),
                        "date_created": r.get("data_criacao")
                    })
                if base_resultados:
                    break

        anuncios = []
        for idx, item in enumerate(base_resultados, start=1):
            seller = item.get("seller") if isinstance(item.get("seller"), dict) else {}
            seller_id = item.get("seller_id") or seller.get("id")
            vendedor = _normalizar_nome_vendedor_ml(item)
            sem_juros = _ml_parcelamento_sem_juros_api(item)
            sem_juros = bool(sem_juros) if sem_juros is not None else False
            item_condition = _ml_extrair_item_condition(item)
            anuncios.append({
                "posicao": idx,
                "id": item.get("id"),
                "sku": _ml_extrair_sku(item),
                "titulo": item.get("title") or item.get("titulo") or "",
                "url": item.get("permalink") or item.get("url") or item.get("link") or "",
                "vendas": _parse_vendas_ml(item.get("sold_quantity") if "sold_quantity" in item else item.get("vendas")),
                "data_criacao": item.get("date_created") or item.get("start_time"),
                "vendedor": vendedor or "",
                "seller_id": seller_id,
                "installments": item.get("installments") if isinstance(item.get("installments"), dict) else None,
                "parcelamento_sem_juros": sem_juros,
                "tipo_anuncio": "Premium" if sem_juros else "Classico",
                "condicao": item_condition,
                "condition": item_condition,
                "item_condition": item_condition,
            })

        if anuncios:
            _enriquecer_vendas_com_api(anuncios, max_workers=min(10, len(anuncios)), client_id=client_id)

        return {
            "success": True,
            "termo": termo,
            "termo_usado": termo_usado,
            "total": len(anuncios),
            "anuncios": anuncios,
            "warning": None if anuncios else "O Mercado Livre nao retornou anuncios para esta consulta ou bloqueou a consulta automatica."
        }
    except Exception as e:
        logger.exception("[Favoritos][PrimeiraPagina] Erro ao consultar ML: %s", e)
        return {
            "success": True,
            "termo": termo,
            "termo_usado": termo_usado,
            "total": 0,
            "anuncios": [],
            "warning": "NÃƒÂ£o foi possÃƒÂ­vel consultar anuncios agora."
        }

@app.post("/api/favoritos/ml/enriquecer-datas")
async def favoritos_ml_enriquecer_datas(req: FavoritosEnriquecerDatasRequest, client_id: str = Depends(get_tenant_id)):
    anuncios_req = req.anuncios or []
    limite = req.max_anuncios or len(anuncios_req) or 50
    limite = min(max(limite, 1), 200)

    tarefas = []
    vistos = set()

    for anuncio in anuncios_req[:limite]:
        if not isinstance(anuncio, dict):
            continue
        url = str(anuncio.get("url") or "").strip()
        raw_item_id = str(anuncio.get("id") or "").strip()
        item_id = _extrair_item_id(raw_item_id) or _extrair_item_id(url) or raw_item_id.upper().replace("-", "")
        chave = item_id or url
        if not chave or chave in vistos:
            continue
        vistos.add(chave)
        tarefas.append({"url": url, "item_id": item_id})

    def _processar(tarefa: dict):
        url = tarefa.get("url") or ""
        item_id = tarefa.get("item_id") or None
        info = _extrair_info_anuncio(url, item_id, client_id=client_id)
        return {
            "url": url,
            "id": item_id,
            "data_criacao": info.get("data_criacao"),
            "fonte": info.get("fonte"),
            "vendedor": info.get("vendedor"),
            "fonte_vendedor": info.get("fonte_vendedor"),
            "vendas": info.get("vendas"),
            "fonte_vendas": info.get("fonte_vendas"),
            "listing_type_id": info.get("listing_type_id"),
            "listing_type_name": info.get("listing_type_name"),
            "tipo_anuncio": info.get("tipo_anuncio"),
            "parcelamento_sem_juros": info.get("parcelamento_sem_juros"),
            "shipping": info.get("shipping"),
            "logistic_type": info.get("logistic_type"),
            "shipping_mode": info.get("shipping_mode"),
            "is_full": info.get("is_full"),
            "condicao": info.get("condicao"),
            "condition": info.get("condition"),
            "item_condition": info.get("item_condition"),
        }

    resultados = []
    if tarefas:
        max_workers = min(18, len(tarefas))
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futuros = [executor.submit(_processar, tarefa) for tarefa in tarefas]
            for futuro in as_completed(futuros):
                try:
                    resultados.append(futuro.result(timeout=20))
                except Exception:
                    logger.exception("[Favoritos][Datas] Falha ao enriquecer anuncio")

    return {
        "success": True,
        "total": len(resultados),
        "resultados": resultados
    }

def _meses_desde_date(date_str: str | None):
    if not date_str:
        return None
    try:
        safe = date_str.replace("Z", "+00:00")
        dt = datetime.fromisoformat(safe)
        dias = max(1, (datetime.now(dt.tzinfo) - dt).days)
        return max(1, dias // 30)
    except Exception:
        return None

def _estimar_meses_anuncio(url_anuncio: str, max_retries: int = 3, delay: int = 2):
    for tentativa in range(max_retries):
        try:
            resp = requests.get(url_anuncio, headers=_ml_headers(), timeout=10)
            if resp.status_code != 200:
                logger.warning("Erro ao buscar %s: status %s. Tentativa %s/%s", url_anuncio, resp.status_code, tentativa + 1, max_retries)
                time.sleep(delay)
                continue

            soup = BeautifulSoup(resp.text, "lxml")
            datas = []
            for tag in soup.find_all("span"):
                texto = _normalize_text(tag.text)
                if texto.startswith("ha "):
                    datas.append(texto)

            if datas:
                texto = datas[-1]
                if "ano" in texto:
                    anos = int(texto.split("ha")[1].split("ano")[0].strip())
                    meses = anos * 12
                    if "mes" in texto:
                        meses += int(texto.split("ano")[1].split("mes")[0].strip())
                    return meses
                if "mes" in texto:
                    return int(texto.split("ha")[1].split("mes")[0].strip())
                if "dia" in texto:
                    dias = int(texto.split("ha")[1].split("dia")[0].strip())
                    return max(1, dias // 30)

            perguntas = soup.find_all("div", {"class": "questions__item"})
            datas_perg = []
            for pergunta in perguntas:
                data_tag = pergunta.find("span", {"class": "questions__item-date"})
                if data_tag:
                    datas_perg.append(_normalize_text(data_tag.text))

            if datas_perg:
                texto = datas_perg[-1]
                if "ano" in texto:
                    anos = int(texto.split("ha")[1].split("ano")[0].strip())
                    meses = anos * 12
                    if "mes" in texto:
                        meses += int(texto.split("ano")[1].split("mes")[0].strip())
                    return meses
                if "mes" in texto:
                    return int(texto.split("ha")[1].split("mes")[0].strip())
                if "dia" in texto:
                    dias = int(texto.split("ha")[1].split("dia")[0].strip())
                    return max(1, dias // 30)

            logger.warning("Nenhuma data encontrada para %s", url_anuncio)
            return None
        except Exception:
            logger.exception("Erro ao processar %s. Tentativa %s/%s", url_anuncio, tentativa + 1, max_retries)
            time.sleep(delay)
    return None

def _buscar_anuncios_mercadolivre(termo: str, max_retries: int = 3, delay: int = 2):
    if termo.startswith("http"):
        url = termo
        if "lista.mercadolivre.com.br" not in url:
            return _buscar_anuncios_por_link(url, max_retries=max_retries, delay=delay)
    termos = _deduplicar_lista([termo, _simplificar_termo_busca(termo)])
    if len(termos) <= 1:
        return _buscar_anuncios_por_termo(termo, max_retries=max_retries, delay=delay)
    return _deduplicar_anuncios(_buscar_anuncios_paralelo(termos, max_retries=max_retries, delay=delay, max_workers=BUSCAS_PARALLELAS_FAVORITOS))

BUSCAS_PARALLELAS_FAVORITOS = 8

def _deduplicar_lista(valores):
    vistos = set()
    saida = []
    for valor in valores:
        if not valor:
            continue
        texto = str(valor).strip()
        if not texto or texto in vistos:
            continue
        vistos.add(texto)
        saida.append(texto)
    return saida

def _buscar_anuncios_paralelo(termos, max_retries: int = 3, delay: int = 2, max_workers: int = BUSCAS_PARALLELAS_FAVORITOS):
    if not termos:
        return []
    termos = _deduplicar_lista(termos)
    workers = min(max_workers or 1, len(termos))
    resultados = []

    def _executar_busca(termo_local: str):
        return _buscar_anuncios_por_termo(termo_local, max_retries=max_retries, delay=delay)

    with ThreadPoolExecutor(max_workers=workers) as executor:
        futuros = {executor.submit(_executar_busca, termo): termo for termo in termos}
        for futuro in as_completed(futuros):
            try:
                lote = futuro.result()
                if lote:
                    resultados.extend(lote)
            except Exception:
                logger.exception("[Favoritos] Falha em busca paralela para '%s'.", futuros[futuro])
    return resultados

def _buscar_anuncios_por_link(url: str, max_retries: int = 3, delay: int = 2):
    dados = _extrair_dados_produto_html(url, max_retries=max_retries, delay=delay)

    termos = []
    item_id = _extrair_item_id(url)
    if item_id:
        termos.append(item_id)

    codigo = (dados or {}).get("codigo")
    if codigo:
        termos.append(codigo)

    titulo = (dados or {}).get("titulo")
    if titulo:
        termos.append(titulo)

    veiculo = (dados or {}).get("veiculo")
    anos = (dados or {}).get("anos") or []
    if veiculo:
        if anos:
            for ano in anos[:3]:
                termos.append(f"{veiculo} {ano}")
        else:
            termos.append(veiculo)

    termo_tecnico = _gerar_termo_tecnico(dados)
    if termo_tecnico:
        termos.append(termo_tecnico)

    termo_limpo = _simplificar_termo_busca((dados or {}).get("titulo") or "")
    if termo_limpo:
        termos.append(termo_limpo)

    if not termos:
        anuncio = _extrair_anuncio_produto(url, max_retries=max_retries, delay=delay)
        termo_busca = (anuncio or {}).get("titulo") or ""
        if termo_busca:
            termos.append(termo_busca)

    # EstratÃƒÂ©gia 1: CatÃƒÂ¡logo (agrupa vendedores do MESMO produto)
    catalog_id = _extrair_catalog_id(url)
    if catalog_id:
        resultados_catalogo = _buscar_ofertas_catalogo(url, catalog_id, max_retries=max_retries, delay=delay)
        if resultados_catalogo:
            if len(resultados_catalogo) >= 3:
                return resultados_catalogo

    # EstratÃƒÂ©gia 2: montando termos para busca paralela em lotes (5 por vez)
    codigos = []
    if (dados or {}).get("codigo"):
        codigos.append((dados or {}).get("codigo"))
    termo_tecnico = _gerar_termo_tecnico(dados)
    termos_paralelos = codigos + ([termo_tecnico] if termo_tecnico else [])
    veiculo = (dados or {}).get("veiculo")
    anos = (dados or {}).get("anos") or []
    if veiculo and anos:
        termos_paralelos.extend([f"{veiculo} {ano}" for ano in anos[:2]])
    if veiculo:
        termos_paralelos.append(veiculo)
    termos_paralelos.extend(termos)

    termos_paralelos = _deduplicar_lista(termos_paralelos)
    resultados = []
    if resultados_catalogo:
        resultados.extend(resultados_catalogo)

    lote_size = BUSCAS_PARALLELAS_FAVORITOS
    for idx in range(0, len(termos_paralelos), lote_size):
        lote = termos_paralelos[idx: idx + lote_size]
        if not lote:
            continue
        resultados.extend(_buscar_anuncios_paralelo(lote, max_retries=max_retries, delay=delay, max_workers=BUSCAS_PARALLELAS_FAVORITOS))
        if len(resultados) >= 10:
            break

    return _deduplicar_anuncios(resultados)

def _buscar_anuncios_por_termo(termo: str, max_retries: int = 3, delay: int = 2):
    termo_original = termo
    termo_url = quote_plus(termo)
    url = f"https://lista.mercadolivre.com.br/{termo_url}"

    api_data = _ml_api_search(termo, limit=50)
    if api_data and "results" in api_data:
        anuncios = []
        for item in api_data.get("results", []):
            anuncios.append({
                "url": item.get("permalink"),
                "titulo": item.get("title"),
                "preco": item.get("price"),
                "vendas": item.get("sold_quantity"),
                "data_criacao": item.get("date_created")
            })
        return anuncios

    html_anuncios = _buscar_anuncios_mercadolivre_html(url, max_retries=max_retries, delay=delay)
    if html_anuncios and len(html_anuncios) >= 10:
        return html_anuncios

    termo_limpo = _simplificar_termo_busca(termo_original)
    if termo_limpo and termo_limpo != termo:
        termo_url_limpo = quote_plus(termo_limpo)
        url_limpo = f"https://lista.mercadolivre.com.br/{termo_url_limpo}"
        html_anuncios_limpo = _buscar_anuncios_mercadolivre_html(url_limpo, max_retries=max_retries, delay=delay)
        if html_anuncios_limpo:
            return _deduplicar_anuncios(html_anuncios + html_anuncios_limpo)

    return html_anuncios

def _buscar_anuncios_mercadolivre_html(url: str, max_retries: int = 3, delay: int = 2):
    for tentativa in range(max_retries):
        try:
            resp = requests.get(url, headers=_ml_headers(), timeout=10, verify=False)
            if resp.status_code != 200:
                logger.warning("Erro ao buscar %s: status %s. Tentativa %s/%s", url, resp.status_code, tentativa + 1, max_retries)
                time.sleep(delay)
                continue

            soup = BeautifulSoup(resp.text, "lxml")
            anuncios = []

            preloaded = _extrair_preloaded_results(resp.text)
            if preloaded:
                return preloaded

            ldjson = _extrair_links_ld_json(resp.text)
            if ldjson:
                return ldjson

            items = soup.select("li.ui-search-layout__item, div.poly-card, section.poly-card")
            if not items:
                items = soup.select("div.ui-search-result__content-wrapper")

            for item in items:
                link_tag = item.select_one("a.poly-component__title, h2.poly-component__title-wrapper a, a.ui-search-link")
                if not link_tag:
                    link_tag = item.select_one("a[href*='/MLB-'], a[href*='/p/MLB']")

                titulo_tag = item.select_one("a.poly-component__title, h2.poly-component__title-wrapper a, h2.ui-search-item__title")
                if not titulo_tag:
                    titulo_tag = item.select_one("span.ui-search-item__group__element.ui-search-item__title")

                preco_tag = item.select_one("span.ui-search-price__part")
                if not preco_tag:
                    preco_tag = item.select_one("span.andes-money-amount__fraction")

                vendas_tag = item.select_one("span.ui-search-item__group__element.ui-search-item__variations-text")
                if not vendas_tag:
                    vendas_tag = item.find("span", string=lambda t: t and ("vendido" in t or "vendidos" in t))

                if link_tag:
                    anuncios.append({
                        "url": link_tag.get("href"),
                        "titulo": titulo_tag.text.strip() if titulo_tag else "",
                        "preco": preco_tag.text.strip() if preco_tag else "",
                        "vendas": vendas_tag.text.strip() if vendas_tag else None
                    })

            if anuncios:
                return anuncios

            links_soup = []
            for a in soup.select("a[href*='/MLB-'], a[href*='/p/MLB']"):
                href = a.get("href")
                if not href:
                    continue
                if "mercadolivre.com.br" not in href:
                    continue
                if href not in links_soup:
                    links_soup.append(href)

            if links_soup:
                return [
                    {"url": link, "titulo": "", "preco": "", "vendas": None}
                    for link in links_soup
                ]

            # Fallback por regex quando os seletores falham
            links = re.findall(r"https?://[^\s\"']+?/(?:MLB-\d+|p/MLB\d+)[^\s\"']*", resp.text)
            links_unicos = []
            for link in links:
                if link not in links_unicos:
                    links_unicos.append(link)

            if links_unicos:
                return [
                    {"url": link, "titulo": "", "preco": "", "vendas": None}
                    for link in links_unicos
                ]

            logger.warning("Nenhum item encontrado para %s", url)
            return []
        except Exception:
            logger.exception("Erro ao processar busca HTML em %s. Tentativa %s/%s", url, tentativa + 1, max_retries)
            time.sleep(delay)
    return []

def _extrair_preloaded_results(html_text: str):
    if not html_text:
        return []
    match = re.search(r"__PRELOADED_STATE__\s*=\s*(\{.*?\})\s*;", html_text, re.DOTALL)
    raw = None
    if match:
        raw = match.group(1)
    else:
        match = re.search(r"__PRELOADED_STATE__\s*=\s*JSON\.parse\(\"(.*?)\"\)", html_text, re.DOTALL)
        if match:
            raw = match.group(1)

    if not raw:
        return []

    try:
        data = json.loads(raw)
    except Exception:
        try:
            unescaped = bytes(raw, "utf-8").decode("unicode_escape")
            data = json.loads(unescaped)
        except Exception:
            return []

    resultados = _buscar_lista_resultados(data)
    if not resultados:
        return []

    anuncios = []
    for item in resultados:
        if not isinstance(item, dict):
            continue
        url = item.get("permalink") or item.get("url")
        titulo = item.get("title") or ""
        preco = item.get("price")
        vendas = item.get("sold_quantity")
        data_criacao = item.get("date_created")
        if url:
            anuncios.append({
                "url": url,
                "titulo": titulo,
                "preco": preco,
                "vendas": vendas,
                "data_criacao": data_criacao
            })
    return anuncios

def _extrair_links_ld_json(html_text: str):
    if not html_text:
        return []
    try:
        soup = BeautifulSoup(html_text, "lxml")
        scripts = soup.find_all("script", {"type": "application/ld+json"})
        anuncios = []
        for script in scripts:
            try:
                data = json.loads(script.text)
            except Exception:
                continue
            if isinstance(data, dict) and data.get("@type") == "ItemList":
                items = data.get("itemListElement") or []
                for item in items:
                    if isinstance(item, dict):
                        url = item.get("url") or (item.get("item") or {}).get("@id")
                        if url:
                            anuncios.append({
                                "url": url,
                                "titulo": "",
                                "preco": "",
                                "vendas": None
                            })
        if anuncios:
            return anuncios
    except Exception:
        logger.exception("Erro ao extrair links ld+json")
    return []

def _simplificar_termo_busca(termo: str) -> str:
    texto = _normalize_text(termo)
    if not texto:
        return ""
    texto = re.sub(r"""[.,;:()\[\]{}"'^~!?|\\/_+=*\-]+""", " ", texto)
    texto = re.sub(r"\s+", " ", texto).strip()

    stopwords = {
        "de", "da", "do", "das", "dos", "para", "com", "sem", "e", "ou", "em",
        "novo", "nova", "original", "gen", "universal", "kit", "peca", "peÃƒÂ§a",
        "sensor", "cebolao", "cebolinha", "temperatura", "radiador"
    }

    tokens = [t for t in re.split(r"\s+", texto) if t]
    filtrados = []
    for t in tokens:
        if t in stopwords:
            continue
        if len(t) >= 3 or t.isdigit():
            filtrados.append(t)

    termo_final = " ".join(filtrados[:6])
    return termo_final.strip()

def _deduplicar_anuncios(anuncios: list):
    vistos = set()
    unicos = []
    for item in anuncios:
        url = (item or {}).get("url") or (item or {}).get("link") or (item or {}).get("permalink")
        if not url or url in vistos:
            continue
        vistos.add(url)
        normalizado = dict(item or {})
        normalizado["url"] = url
        unicos.append(normalizado)
    
    # Ordena por relevÃƒÂ¢ncia: itens com tÃƒÂ­tulo > sem tÃƒÂ­tulo
    com_titulo = [a for a in unicos if (a or {}).get("titulo")]
    sem_titulo = [a for a in unicos if not (a or {}).get("titulo")]
    
    return com_titulo + sem_titulo

def _parse_vendas_ml(v: object) -> int | None:
    if v is None:
        return None
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        try:
            return int(v)
        except Exception:
            return None
    texto = html_lib.unescape(str(v)).strip().lower()
    if not texto:
        return None

    match = re.search(r"(\d[\d\.,]*)\s*(k|mil)?\b", texto, flags=re.IGNORECASE)
    if not match:
        return None

    valor_raw = (match.group(1) or "").strip()
    sufixo = (match.group(2) or "").strip().lower()
    if not valor_raw:
        return None
    if "." in valor_raw and "," in valor_raw:
        if valor_raw.rfind(".") > valor_raw.rfind(","):
            valor_raw = re.sub(r"[^\d.,-]", "", valor_raw).replace(",", "")
        else:
            valor_raw = re.sub(r"[^\d.,-]", "", valor_raw).replace(".", "").replace(",", ".")
    elif "," in valor_raw:
        if re.fullmatch(r"\d{1,3}(?:,\d{3})+", valor_raw):
            valor_raw = re.sub(r",", "", valor_raw)
        else:
            valor_raw = valor_raw.replace(",", ".")
    elif "." in valor_raw:
        if re.fullmatch(r"\d{1,3}(?:\.\d{3})+", valor_raw):
            valor_raw = valor_raw.replace(".", "")

    try:
        valor = float(re.sub(r"[^\d.\-]", "", valor_raw))
    except Exception:
        digitos = re.findall(r"\d+", valor_raw)
        if not digitos:
            return None
        try:
            valor = float(digitos[0])
        except Exception:
            return None

    if sufixo in ("k", "mil"):
        valor *= 1000

    try:
        return int(round(valor))
    except Exception:
        return None


def _normalizar_nome_vendedor_ml(dados: object) -> str:
    if not isinstance(dados, dict):
        return ""
    seller = dados.get("seller") if isinstance(dados.get("seller"), dict) else {}
    official_store = dados.get("official_store") if isinstance(dados.get("official_store"), dict) else {}
    vendedor = (
        seller.get("nickname")
        or dados.get("seller_name")
        or official_store.get("nickname")
        or dados.get("official_store_name")
        or official_store.get("name")
        or dados.get("official_store", {}).get("name")
        or dados.get("official_store", {}).get("nickname")
    )
    # Mantemos somente identificadores de loja/vendedor publicados no anuncio ou loja oficial.
    if isinstance(vendedor, str):
        vendedor = vendedor.strip()
    if isinstance(vendedor, str):
        vendedor = vendedor.strip().strip('"').strip("'")
    return vendedor if vendedor else ""


@functools.lru_cache(maxsize=256)
def _obter_info_anuncio_api(item_id: str, client_id: str = ""):
    item_id = str(item_id or "").strip().upper().replace("-", "")
    if not item_id.startswith("MLB") or len(item_id) < 7:
        return None

    api_data = _ml_api_item_com_oauth_tenant(client_id, item_id) if client_id else None
    if not isinstance(api_data, dict):
        api_data = _ml_api_item(item_id)
    if not isinstance(api_data, dict):
        return None

    data_criacao = _normalizar_data_ml(
        api_data.get("date_created")
        or api_data.get("start_time")
        or api_data.get("start_date")
        or api_data.get("creation_date")
    )

    seller = api_data.get("seller") if isinstance(api_data.get("seller"), dict) else {}
    seller_id = api_data.get("seller_id") or seller.get("id")
    vendedor = _normalizar_nome_vendedor_ml(api_data)

    if not vendedor and seller_id:
        user_data = _ml_api_user_com_oauth_tenant(client_id, str(seller_id)) if client_id else None
        if not isinstance(user_data, dict):
            user_data = _ml_api_user(str(seller_id))
        if isinstance(user_data, dict):
            vendedor = (
                user_data.get("nickname")
                or user_data.get("official_store_name")
                or (user_data.get("official_store") or {}).get("name")
            )

    # Usa mÃƒÂºltiplos campos comuns para evitar divergÃƒÂªncia entre payloads.
    vendas = None
    for campo in ("sold_quantity", "soldQuantity", "sold", "sold_quantity_by_state", "sold_quantity_by_country", "ventas", "quantidade_vendida"):
        if campo not in api_data:
            continue
        vendas_api = _parse_vendas_ml(api_data.get(campo))
        if vendas_api is not None:
            vendas = vendas_api
            break

    item_condition = _ml_extrair_item_condition(api_data) or None

    return {
        "vendas": vendas,
        "vendedor": str(vendedor).strip() if vendedor else None,
        "seller_id": str(seller_id).strip() if seller_id else None,
        "data_criacao": data_criacao,
        "parcelamento_sem_juros": _ml_parcelamento_sem_juros_api(api_data),
        "sku": _ml_extrair_sku(api_data) or None,
        "condicao": item_condition,
        "condition": item_condition,
        "item_condition": item_condition,
    }


def _enriquecer_vendas_com_api(anuncios: list, max_workers: int = 8, client_id: str = ""):
    if not anuncios:
        return

    tarefas = []
    indice_por_id = {}

    for idx, anuncio in enumerate(anuncios):
        if not isinstance(anuncio, dict):
            continue
        item_id = _extrair_item_id(anuncio.get("url") or anuncio.get("link") or anuncio.get("permalink") or anuncio.get("id") or "")
        if not item_id:
            continue
        if item_id in indice_por_id:
            continue
        indice_por_id[item_id] = idx
        tarefas.append(item_id)

    if not tarefas:
        return

    workers = min(max_workers or 1, len(tarefas))
    with ThreadPoolExecutor(max_workers=workers) as executor:
        futuros = {
            executor.submit(_obter_info_anuncio_api, item_id, client_id or ""): item_id
            for item_id in tarefas
        }
        for futuro in as_completed(futuros):
            item_id = futuros[futuro]
            try:
                info_api = futuro.result()
            except Exception:
                logger.exception("[Favoritos] Falha ao buscar sold_quantity API para %s", item_id)
                continue
            if not info_api:
                continue
            indice = indice_por_id.get(item_id)
            if indice is None or indice >= len(anuncios):
                continue
            anuncio = anuncios[indice]
            if isinstance(anuncio, dict):
                if info_api.get("vendedor"):
                    anuncio["vendedor"] = info_api["vendedor"]
                if info_api.get("seller_id"):
                    anuncio["seller_id"] = info_api["seller_id"]
                if info_api.get("data_criacao") and not anuncio.get("data_criacao"):
                    anuncio["data_criacao"] = info_api["data_criacao"]
                if info_api.get("vendas") is not None:
                    anuncio["vendas"] = info_api["vendas"]
                if info_api.get("parcelamento_sem_juros") is not None:
                    anuncio["parcelamento_sem_juros"] = bool(info_api["parcelamento_sem_juros"])
                    anuncio["tipo_anuncio"] = "Premium" if anuncio["parcelamento_sem_juros"] else "Classico"
                if info_api.get("sku") and not anuncio.get("sku"):
                    anuncio["sku"] = info_api["sku"]
                item_condition = info_api.get("item_condition") or info_api.get("condition") or info_api.get("condicao")
                if item_condition:
                    anuncio["condicao"] = item_condition
                    anuncio["condition"] = item_condition
                    anuncio["item_condition"] = item_condition

def _normalizar_anuncio_favoritos(item: dict) -> dict:
    item = item or {}
    preco = item.get("preco")
    if preco is None:
        preco = item.get("price")
    if isinstance(preco, (int, float)):
        preco = f"R$ {float(preco):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    vendas = item.get("vendas")
    if vendas is None:
        vendas = item.get("sold_quantity")
    seller = item.get("seller") if isinstance(item.get("seller"), dict) else {}
    official_store = item.get("official_store") if isinstance(item.get("official_store"), dict) else {}
    vendedor = (
        item.get("vendedor")
        or _normalizar_nome_vendedor_ml(item)
    )

    return {
        "url": item.get("url") or item.get("link") or item.get("permalink") or "",
        "titulo": item.get("titulo") or item.get("title") or "",
        "preco": preco if preco not in (None, "") else "N/A",
        "vendas": _parse_vendas_ml(vendas),
        "data_criacao": item.get("data_criacao") or item.get("date_created") or item.get("start_time"),
        "vendedor": vendedor or "",
        "seller_id": item.get("seller_id") or item.get("seller_id") or seller.get("id"),
    }

def _buscar_lista_resultados(data):
    if isinstance(data, dict):
        if "results" in data and isinstance(data["results"], list):
            return data["results"]
        for value in data.values():
            found = _buscar_lista_resultados(value)
            if found:
                return found
    elif isinstance(data, list):
        for item in data:
            found = _buscar_lista_resultados(item)
            if found:
                return found
    return []

    for tentativa in range(max_retries):
        try:
            resp = requests.get(url, headers=_ml_headers(), timeout=10)
            if resp.status_code != 200:
                logger.warning("Erro ao buscar %s: status %s. Tentativa %s/%s", url, resp.status_code, tentativa + 1, max_retries)
                time.sleep(delay)
                continue

            soup = BeautifulSoup(resp.text, "lxml")
            anuncios = []

            items = soup.select("li.ui-search-layout__item")
            if not items:
                items = soup.select("div.ui-search-result__content-wrapper")

            if not items:
                logger.warning("Nenhum item encontrado para %s", url)
                return []

            for item in items:
                link_tag = item.select_one("a.ui-search-link")
                if not link_tag:
                    link_tag = item.select_one("a[href*='/MLB-']")

                titulo_tag = item.select_one("h2.ui-search-item__title")
                if not titulo_tag:
                    titulo_tag = item.select_one("span.ui-search-item__group__element.ui-search-item__title")

                preco_tag = item.select_one("span.ui-search-price__part")
                if not preco_tag:
                    preco_tag = item.select_one("span.andes-money-amount__fraction")

                vendas_tag = item.select_one("span.ui-search-item__group__element.ui-search-item__variations-text")
                if not vendas_tag:
                    vendas_tag = item.find("span", string=lambda t: t and ("vendido" in t or "vendidos" in t))

                if link_tag and titulo_tag and preco_tag:
                    anuncios.append({
                        "url": link_tag["href"],
                        "titulo": titulo_tag.text.strip(),
                        "preco": preco_tag.text.strip(),
                        "vendas": vendas_tag.text.strip() if vendas_tag else None
                    })
            return anuncios
        except Exception:
            logger.exception("Erro ao processar busca por '%s'. Tentativa %s/%s", termo, tentativa + 1, max_retries)
            time.sleep(delay)
    return []

def _extrair_anuncio_produto(url: str, max_retries: int = 3, delay: int = 2):
    for tentativa in range(max_retries):
        try:
            resp = requests.get(url, headers=_ml_headers(), timeout=10)
            if resp.status_code != 200:
                logger.warning("Erro ao buscar %s: status %s. Tentativa %s/%s", url, resp.status_code, tentativa + 1, max_retries)
                time.sleep(delay)
                continue

            soup = BeautifulSoup(resp.text, "lxml")

            titulo = None
            meta_title = soup.find("meta", {"property": "og:title"})
            if meta_title and meta_title.get("content"):
                titulo = meta_title.get("content").strip()
            if not titulo:
                h1_title = soup.select_one("h1.ui-pdp-title") or soup.find("h1")
                if h1_title:
                    titulo = h1_title.text.strip()

            preco = None
            meta_price = soup.find("meta", {"property": "product:price:amount"})
            if meta_price and meta_price.get("content"):
                preco = meta_price.get("content").strip()
            if not preco:
                meta_price_item = soup.find("meta", {"itemprop": "price"})
                if meta_price_item and meta_price_item.get("content"):
                    preco = meta_price_item.get("content").strip()
            if not preco:
                price_tag = soup.select_one("span.andes-money-amount__fraction")
                if price_tag:
                    preco = price_tag.text.strip()

            if not titulo and not preco:
                logger.warning("Nao foi possivel extrair dados do produto em %s", url)
                return None

            return {
                "url": url,
                "titulo": titulo or "",
                "preco": preco or "",
                "vendas": None
            }
        except Exception:
            logger.exception("Erro ao processar produto %s. Tentativa %s/%s", url, tentativa + 1, max_retries)
            time.sleep(delay)
    return None

def _extrair_dados_produto_html(url: str, max_retries: int = 3, delay: int = 2):
    for tentativa in range(max_retries):
        try:
            resp = requests.get(url, headers=_ml_headers(), timeout=10)
            if resp.status_code != 200:
                logger.warning("Erro ao buscar %s: status %s. Tentativa %s/%s", url, resp.status_code, tentativa + 1, max_retries)
                time.sleep(delay)
                continue

            soup = BeautifulSoup(resp.text, "lxml")
            titulo = None
            meta_title = soup.find("meta", {"property": "og:title"})
            if meta_title and meta_title.get("content"):
                titulo = meta_title.get("content").strip()
            if not titulo:
                h1_title = soup.select_one("h1.ui-pdp-title") or soup.find("h1")
                if h1_title:
                    titulo = h1_title.text.strip()

            atributos = _extrair_atributos_produto(resp.text, soup)
            codigo = _extrair_codigo_produto(atributos)
            veiculo = _extrair_veiculo_produto(atributos, titulo)
            anos = _extrair_anos_produto(atributos, titulo)

            return {
                "url": url,
                "titulo": titulo or "",
                "codigo": codigo,
                "veiculo": veiculo,
                "anos": anos
            }
        except Exception:
            logger.exception("Erro ao extrair dados do produto %s. Tentativa %s/%s", url, tentativa + 1, max_retries)
            time.sleep(delay)
    return None

def _extrair_atributos_produto(html_text: str, soup: BeautifulSoup):
    atributos = {}

    preloaded = _extrair_preloaded_state(html_text)
    if preloaded:
        atributos_lista = _buscar_lista_atributos(preloaded)
        for item in atributos_lista:
            nome = _normalize_text(item.get("name") or item.get("label") or "")
            valor = item.get("value_name") or item.get("value") or ""
            if nome and valor:
                atributos[nome] = str(valor).strip()

    if soup:
        for row in soup.select("tr"):
            cols = row.find_all("th") + row.find_all("td")
            if len(cols) >= 2:
                nome = _normalize_text(cols[0].get_text(" ", strip=True))
                valor = cols[1].get_text(" ", strip=True)
                if nome and valor:
                    atributos.setdefault(nome, valor)

    return atributos

def _extrair_preloaded_state(html_text: str):
    if not html_text:
        return None
    match = re.search(r"__PRELOADED_STATE__\s*=\s*(\{.*?\})\s*;", html_text, re.DOTALL)
    raw = None
    if match:
        raw = match.group(1)
    else:
        match = re.search(r"__PRELOADED_STATE__\s*=\s*JSON\.parse\(\"(.*?)\"\)", html_text, re.DOTALL)
        if match:
            raw = match.group(1)

    if not raw:
        return None
    try:
        return json.loads(raw)
    except Exception:
        try:
            unescaped = bytes(raw, "utf-8").decode("unicode_escape")
            return json.loads(unescaped)
        except Exception:
            return None

def _buscar_lista_atributos(data):
    if isinstance(data, dict):
        if "attributes" in data and isinstance(data["attributes"], list):
            return data["attributes"]
        for value in data.values():
            found = _buscar_lista_atributos(value)
            if found:
                return found
    elif isinstance(data, list):
        for item in data:
            found = _buscar_lista_atributos(item)
            if found:
                return found
    return []

def _extrair_codigo_produto(atributos: dict):
    if not atributos:
        return None
    chaves = [
        "codigo", "codigo do produto", "codigo do fabricante", "codigo de fabrica",
        "sku", "mpn", "numero de peca", "numero da peca", "numero de parte"
    ]
    for chave in chaves:
        for nome, valor in atributos.items():
            if chave == nome:
                return str(valor).strip()
    for valor in atributos.values():
        codigo = _extrair_codigo_oem(str(valor))
        if codigo:
            return codigo
    return None

def _extrair_veiculo_produto(atributos: dict, titulo: str | None):
    candidatos = []
    for chave in ["veiculo", "veiculo compativel", "aplicacao", "compatibilidade", "modelo", "marca", "linha"]:
        valor = atributos.get(chave)
        if valor:
            candidatos.append(valor)

    if titulo:
        candidatos.append(titulo)

    texto = " ".join([str(c) for c in candidatos if c])
    texto = _normalize_text(texto)
    texto = re.sub(r"\b(ano|anos|para|compativel|compativel com)\b", " ", texto)
    texto = re.sub(r"\s+", " ", texto).strip()
    return texto or None

def _extrair_anos_produto(atributos: dict, titulo: str | None):
    texto = " ".join([str(v) for v in atributos.values() if v])
    if titulo:
        texto += " " + titulo
    anos = re.findall(r"\b(19\d{2}|20\d{2})\b", texto)
    anos_unicos = []
    for ano in anos:
        if ano not in anos_unicos:
            anos_unicos.append(ano)
    return anos_unicos

def _extrair_codigo_oem(texto: str) -> str | None:
    if not texto:
        return None
    match = re.search(r"\b[0-9A-Z]{3,6}-[0-9A-Z]{2,5}-[0-9A-Z]{3,5}\b", texto.upper())
    return match.group(0) if match else None

def _gerar_termo_tecnico(dados: dict | None):
    if not dados:
        return None
    titulo = (dados.get("titulo") or "").lower()
    veiculo = dados.get("veiculo")
    if not veiculo:
        return None
    if "cebola" in titulo or "cebolao" in titulo or "cebolinha" in titulo:
        return f"interruptor termico radiador {veiculo}"
    return None

def _buscar_ofertas_catalogo(url: str, catalog_id: str, max_retries: int = 3, delay: int = 2):
    for tentativa in range(max_retries):
        try:
            resp = requests.get(url, headers=_ml_headers(), timeout=10)
            if resp.status_code != 200:
                logger.warning("Erro ao buscar catalogo %s: status %s. Tentativa %s/%s", url, resp.status_code, tentativa + 1, max_retries)
                time.sleep(delay)
                continue

            data = _extrair_preloaded_state(resp.text)
            if not data:
                return []

            links = _coletar_permalinks(data)
            if links:
                anuncios = []
                for link in links:
                    item_id = _extrair_item_id(link)
                    if item_id:
                        item_data = _ml_api_item(item_id)
                        if item_data:
                            anuncios.append({
                                "url": link,
                                "titulo": item_data.get("title", ""),
                                "preco": item_data.get("price"),
                                "vendas": item_data.get("sold_quantity"),
                                "data_criacao": item_data.get("date_created")
                            })
                        else:
                            item_html = _enriquecer_link_html(link, max_retries=1, delay=0)
                            anuncios.append(item_html)
                    else:
                        item_html = _enriquecer_link_html(link, max_retries=1, delay=0)
                        anuncios.append(item_html)
                return anuncios

            return []
        except Exception:
            logger.exception("Erro ao processar catalogo %s. Tentativa %s/%s", catalog_id, tentativa + 1, max_retries)
            time.sleep(delay)
    return []

def _coletar_permalinks(data):
    links = []
    if isinstance(data, dict):
        permalink = data.get("permalink") or data.get("url")
        if isinstance(permalink, str) and "MLB-" in permalink:
            links.append(permalink)
        for value in data.values():
            links.extend(_coletar_permalinks(value))
    elif isinstance(data, list):
        for item in data:
            links.extend(_coletar_permalinks(item))
    # Dedup
    unique = []
    seen = set()
    for link in links:
        if link not in seen:
            seen.add(link)
            unique.append(link)
    return unique

def _montar_urls_busca_diretas(link_produto: str, dados: dict):
    urls = []

    item_id = _extrair_item_id(link_produto)
    if item_id:
        urls.append({
            "label": f"Link direto do produto: {item_id}",
            "url": link_produto,
            "tipo": "link_direto"
        })

    codigo = (dados or {}).get("codigo")
    if codigo:
        url_codigo = f"https://www.mercadolivre.com.br/jm/search?q={quote_plus(codigo)}"
        urls.append({
            "label": f"Pesquisar pelo cÃƒÂ³digo OEM: {codigo}",
            "url": url_codigo,
            "tipo": "codigo_oem"
        })

    veiculo = (dados or {}).get("veiculo")
    anos = (dados or {}).get("anos") or []

    if veiculo and anos:
        for ano in anos[:2]:
            termo = f"{veiculo} {ano}"
            url_veiculo_ano = f"https://www.mercadolivre.com.br/jm/search?q={quote_plus(termo)}"
            urls.append({
                "label": f"Pesquisar: {termo}",
                "url": url_veiculo_ano,
                "tipo": "veiculo_ano"
            })

    termo_tecnico = _gerar_termo_tecnico(dados)
    if termo_tecnico:
        url_tecnico = f"https://www.mercadolivre.com.br/jm/search?q={quote_plus(termo_tecnico)}"
        urls.append({
            "label": f"Pesquisar termo tÃƒÂ©cnico: {termo_tecnico}",
            "url": url_tecnico,
            "tipo": "termo_tecnico"
        })

    if veiculo:
        url_veiculo = f"https://www.mercadolivre.com.br/jm/search?q={quote_plus(veiculo)}"
        urls.append({
            "label": f"Pesquisar pelo veÃƒÂ­culo: {veiculo}",
            "url": url_veiculo,
            "tipo": "veiculo_generico"
        })

    return urls

def _buscar_anuncios_mercadolivre_automatico(url_busca: str, max_anuncios: int = 60):
    """
    Scraping com Selenium + Chrome headless para contornar proteÃƒÂ§ÃƒÂ£o do Mercado Livre.
    Com fallback para requests simples.
    """
    driver = None
    anuncios = []
    
    # Tentar com Selenium primeiro
    try:
        logger.info(f"[Selenium] Tentando buscar: {url_busca[:60]}")
        
        chrome_options = ChromeOptions()
        chrome_options.add_argument('--headless')
        chrome_options.add_argument('--no-sandbox')
        chrome_options.add_argument('--disable-dev-shm-usage')
        chrome_options.add_argument('--disable-blink-features=AutomationControlled')
        chrome_options.add_argument('user-agent=Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36')
        chrome_options.add_argument('--disable-gpu')
        chrome_options.add_argument('--window-size=1920,1080')
        chrome_options.add_experimental_option('excludeSwitches', ['enable-automation'])
        chrome_options.add_experimental_option('useAutomationExtension', False)
        chrome_options.set_capability('unhandledPromptBehavior', 'dismiss')
        
        try:
            service = Service(ChromeDriverManager().install())
            driver = webdriver.Chrome(service=service, options=chrome_options)
            logger.info("[Selenium] Navegador iniciado")
        except Exception as e:
            logger.warning(f"[Selenium] Erro ao iniciar Chrome: {e}. Usando fallback com requests...")
            driver = None
        
        if driver:
            try:
                driver.set_page_load_timeout(40)
                logger.info("[Selenium] Acessando pÃƒÂ¡gina...")
                driver.get(url_busca)
                
                # MÃƒÂºltiplas tentativas de espera com seletores diferentes
                wait = WebDriverWait(driver, 15)
                seletores_teste = [
                    "li.ui-search-layout__item",
                    "div.poly-card",
                    "section.poly-card",
                    "a.poly-component__title",
                    "[data-component-type='s-search-result']",
                    ".s-result-item",
                    "div[class*='item'][class*='result']",
                    "h2[class*='title']"
                ]
                
                encontrou = False
                for seletor in seletores_teste:
                    try:
                        logger.debug(f"[Selenium] Testando seletor: {seletor}")
                        wait.until(EC.presence_of_all_elements_located((By.CSS_SELECTOR, seletor)))
                        logger.info(f"[Selenium] Seletor encontrado: {seletor}")
                        encontrou = True
                        break
                    except Exception as e:
                        logger.debug(f"[Selenium] Seletor nÃ£o encontrado: {seletor}")
                        continue
                
                if not encontrou:
                    logger.warning("[Selenium] Nenhum seletor encontrou elementos. Continuando...")
                
                # Scroll
                logger.info("[Selenium] Fazendo scroll...")
                for i in range(3):
                    driver.execute_script("window.scrollBy(0, window.innerHeight);")
                    time.sleep(0.5)
                
                # Tentar extrair com mÃƒÂºltiplos seletores
                logger.info("[Selenium] Extraindo anuncios...")
                items = []
                
                for seletor in ["li.ui-search-layout__item", "div.poly-card", "section.poly-card", "div.ui-search-result__wrapper", "[data-component-type='s-search-result']", ".s-result-item", "div[class*='result']"]:
                    try:
                        items = driver.find_elements(By.CSS_SELECTOR, seletor)
                        if items:
                            logger.info(f"[Selenium] Encontrados {len(items)} itens com seletor: {seletor}")
                            break
                    except:
                        continue
                
                if items:
                    for idx, item in enumerate(items[:max_anuncios]):
                        try:
                            titulo = link = preco = vendas = None
                            
                            # TÃ­tulo
                            try:
                                for sel in ["a.poly-component__title", "h2.poly-component__title-wrapper a", "h2 a", "a[title]", ".s-item__title"]:
                                    elem = item.find_element(By.CSS_SELECTOR, sel)
                                    titulo = elem.get_attribute('title') or elem.text
                                    if titulo:
                                        break
                            except:
                                pass
                            
                            # Link
                            try:
                                for sel in ["a.poly-component__title", "h2.poly-component__title-wrapper a", "a[href*='/MLB-']", "a[href*='/p/MLB']", "a[href*='/item/MLB']", "a.s-item__link", "a[href*='mercadolivre']"]:
                                    elem = item.find_element(By.CSS_SELECTOR, sel)
                                    link = elem.get_attribute('href')
                                    if link:
                                        break
                            except:
                                pass
                            
                            # PreÃƒÂ§o
                            try:
                                elem = item.find_element(By.CSS_SELECTOR, ".s-item__price, .price, span[class*='price']")
                                preco = elem.text
                            except:
                                preco = 'N/A'
                            
                            # Vendas
                            try:
                                elem = item.find_element(By.CSS_SELECTOR, ".s-item__reviews, [class*='sold'], span[class*='review']")
                                vendas = elem.text
                            except:
                                pass
                            
                            if titulo and link:
                                anuncios.append({
                                    'titulo': str(titulo)[:120],
                                    'link': str(link).strip(),
                                    'preco': str(preco)[:50] if preco else 'N/A',
                                    'vendas': str(vendas)[:50] if vendas else None,
                                    'source': 'selenium'
                                })
                                logger.debug(f"[Selenium] Item {len(anuncios)}: {str(titulo)[:40]}")
                        except Exception as e:
                            logger.debug(f"[Selenium] Erro item {idx}: {str(e)[:60]}")
                            continue
                
                logger.info(f"[Selenium] ExtraÃƒÂ­dos {len(anuncios)} anuncios")
            
            except Exception as e:
                logger.warning(f"[Selenium] Erro durante extraÃƒÂ§ÃƒÂ£o: {e}")
            
            finally:
                try:
                    driver.quit()
                except:
                    pass
    
    except Exception as e:
        logger.warning(f"[Selenium] Erro geral: {e}")
    
    # Se Selenium nÃ£o conseguiu, usar fallback com requests + BeautifulSoup
    if not anuncios:
        logger.info("[Fallback] Tentando com requests + BeautifulSoup...")
        try:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language': 'pt-BR,pt;q=0.9',
            }
            
            response = requests.get(url_busca, headers=headers, timeout=20, verify=False)
            if response.status_code == 200:
                soup = BeautifulSoup(response.text, 'html.parser')
                
                # EstratÃƒÂ©gia 1: Procurar por links diretos de produto
                logger.info("[Fallback] EstratÃƒÂ©gia 1: Procurando links /item/MLB...")
                for link_elem in soup.select("a.poly-component__title, h2.poly-component__title-wrapper a, a[href*='/MLB-'], a[href*='/p/MLB'], a[href*='/item/MLB']")[:max_anuncios]:
                    try:
                        link = link_elem.get('href', '').strip()
                        titulo = link_elem.get('title') or link_elem.get_text(strip=True)
                        
                        if link and titulo and len(titulo) > 5:
                            anuncios.append({
                                'titulo': str(titulo)[:120],
                                'link': link,
                                'preco': 'N/A',
                                'vendas': None,
                                'source': 'requests_fallback_v1'
                            })
                    except:
                        continue
                
                # EstratÃƒÂ©gia 2: Procurar por padrÃƒÂ£o de links com regex
                if not anuncios:
                    logger.info("[Fallback] EstratÃƒÂ©gia 2: Procurando com regex...")
                    import re as regex_module
                    links = regex_module.findall(r'href="(https://[^"]*?/(?:item/MLB|MLB-|p/MLB)[^"]*?)"', response.text)
                    
                    for link in links[:max_anuncios]:
                        try:
                            # Tentar extrair tÃƒÂ­tulo a partir do HTML prÃƒÂ³ximo
                            pattern = r'{}".*?<.*?>([^<]+)</.*?>'.format(regex_module.escape(link))
                            match = regex_module.search(pattern, response.text, regex_module.DOTALL)
                            titulo = match.group(1).strip() if match else f"Produto {len(anuncios)+1}"
                            
                            anuncios.append({
                                'titulo': str(titulo)[:120],
                                'link': link,
                                'preco': 'N/A',
                                'vendas': None,
                                'source': 'requests_fallback_v2'
                            })
                        except:
                            continue
                
                # EstratÃƒÂ©gia 3: Procurar por qualquer elemento com classe "item" ou "result"
                if not anuncios:
                    logger.info("[Fallback] EstratÃƒÂ©gia 3: Procurando por divs com classe item/result...")
                    for div in soup.select("div[class*='item'], div[class*='result']")[:max_anuncios]:
                        try:
                            # Procurar link dentro da div
                            link_elem = div.select_one("a[href*='mercadolivre']")
                            if link_elem:
                                link = link_elem.get('href', '').strip()
                                titulo = link_elem.get('title') or link_elem.get_text(strip=True)
                                
                                if link and titulo and len(titulo) > 5:
                                    anuncios.append({
                                        'titulo': str(titulo)[:120],
                                        'link': link,
                                        'preco': 'N/A',
                                        'vendas': None,
                                        'source': 'requests_fallback_v3'
                                    })
                        except:
                            continue
                
                # Remover duplicatas por link
                unique_links = {}
                for ann in anuncios:
                    if ann['link'] not in unique_links:
                        unique_links[ann['link']] = ann
                anuncios = list(unique_links.values())[:max_anuncios]
                
                logger.info(f"[Fallback] Encontrados {len(anuncios)} anuncios via requests")
        
        except Exception as e:
            logger.warning(f"[Fallback] Erro: {e}")
    
    if anuncios:
        logger.info(f"[Busca ML] Ã¢Å“â€¦ Total Final: {len(anuncios)} anuncios")
    else:
        logger.warning("[Busca ML] Ã¢ÂÅ’ Nenhum anuncio encontrado")
    
    return anuncios

def _enriquecer_link_html(url: str, max_retries: int = 1, delay: int = 1):
    for tentativa in range(max_retries):
        try:
            resp = requests.get(url, headers=_ml_headers(), timeout=10, verify=False)
            if resp.status_code != 200:
                time.sleep(delay)
                continue
            
            soup = BeautifulSoup(resp.text, "lxml")
            
            titulo = None
            meta_title = soup.find("meta", {"property": "og:title"})
            if meta_title and meta_title.get("content"):
                titulo = meta_title.get("content").strip()
            
            preco = None
            meta_price = soup.find("meta", {"property": "product:price:amount"})
            if meta_price and meta_price.get("content"):
                preco = meta_price.get("content").strip()
            
            vendas = None
            
            return {
                "url": url,
                "titulo": titulo or "",
                "preco": preco or "",
                "vendas": vendas
            }
        except Exception:
            time.sleep(delay)
    
    return {"url": url, "titulo": "", "preco": "", "vendas": None}

@app.post("/api/favoritos/pesquisar")
async def favoritos_pesquisar(req: FavoritosSearchRequest):
    termo = (req.termo or "").strip()
    if not termo:
        raise HTTPException(status_code=400, detail="Termo de pesquisa vazio.")

    max_anuncios = req.max_anuncios or 60
    max_anuncios = min(max(max_anuncios, 1), 60)

    url_busca = termo if termo.startswith("http") else f"https://www.mercadolivre.com.br/jm/search?q={quote_plus(termo)}"
    logger.info(f"[Favoritos] Buscando em paralelo: {termo[:80]}")
    anuncios = _buscar_anuncios_mercadolivre(termo, max_retries=3, delay=2)
    if not anuncios:
        logger.warning("[Favoritos] Busca paralela sem resultados. Usando fallback com Selenium/HTML.")
        anuncios = _buscar_anuncios_mercadolivre_automatico(url_busca, max_anuncios)

    anuncios = _deduplicar_anuncios(anuncios or [])
    anuncios = anuncios[:max_anuncios]
    if anuncios:
        _enriquecer_vendas_com_api(anuncios, max_workers=8)

    if not anuncios:
        return {
            "success": True,
            "tipo": "busca_termo",
            "total": 0,
            "resultados": [],
            "top": []
        }

    # Processar anuncios para calcular mÃƒÂ©tricas
    resultados = []
    for anuncio in anuncios:
        anuncio = _normalizar_anuncio_favoritos(anuncio)
        url = anuncio.get("url", "")
        vendas_text = anuncio.get("vendas")
        vendas_num = _parse_vendas_ml(vendas_text)

        # Estimativa de meses
        meses = _estimar_meses_anuncio(url) if url else None
        media = vendas_num / meses if vendas_num and meses and meses > 0 else None

        resultados.append({
            "titulo": anuncio.get("titulo", "N/A"),
            "preco": anuncio.get("preco", "N/A"),
            "vendas": vendas_num,
            "meses": meses,
            "media_vendas": round(media, 2) if media else None,
            "url": url
        })

    # Top 7 por mÃƒÂ©dia de vendas
    resultados_ordenados = sorted(
        [r for r in resultados if r["media_vendas"] is not None],
        key=lambda x: x["media_vendas"],
        reverse=True
    )
    top7 = resultados_ordenados[:7]

    logger.info(f"[Favoritos] Total de anuncios encontrados: {len(anuncios)}")

    return {
        "success": True,
        "tipo": "busca_termo",
        "total": len(anuncios),
        "resultados": resultados,
        "top": top7
    }

