class _EtiquetasNoopProgress:
    def progress(self, *args, **kwargs):
        return self

    def empty(self):
        return None


class _EtiquetasNoopStreamlit:
    def progress(self, *args, **kwargs):
        return _EtiquetasNoopProgress()

    def error(self, mensagem, *args, **kwargs):
        logger.warning("[Etiquetas] %s", mensagem)

    def warning(self, mensagem, *args, **kwargs):
        logger.warning("[Etiquetas] %s", mensagem)

    def toast(self, mensagem, *args, **kwargs):
        logger.info("[Etiquetas] %s", mensagem)


def _executar_processador_etiquetas(nome_funcao: str, *arquivos_bytes):
    import etiquetas as etiquetas_mod

    funcao = getattr(etiquetas_mod, nome_funcao, None)
    if not callable(funcao):
        raise RuntimeError(f"Processador de etiquetas indisponivel: {nome_funcao}")

    arquivos = [io.BytesIO(data) if data is not None else None for data in arquivos_bytes]
    st_original = getattr(etiquetas_mod, "st", None)
    etiquetas_mod.st = _EtiquetasNoopStreamlit()
    try:
        return funcao(*arquivos)
    finally:
        if st_original is not None:
            etiquetas_mod.st = st_original


def _processar_mercado_livre_backend(bytes_etiquetas: bytes):
    return _executar_processador_etiquetas("processar_mercado_livre", bytes_etiquetas)


def _processar_tiktok_backend(bytes_etiquetas: bytes, bytes_lista: bytes | None):
    return _executar_processador_etiquetas("processar_tiktok", bytes_etiquetas, bytes_lista)


def _processar_shopee_backend(bytes_etiquetas: bytes):
    etiquetas_pdf, lista_pdf, qtd = _executar_processador_etiquetas("processar_shopee", bytes_etiquetas)
    return etiquetas_pdf, qtd, lista_pdf


def _quebrar_texto_pdf(texto, fonte, tamanho, largura_max, max_linhas):
    texto = re.sub(r"\s+", " ", str(texto or "")).strip()
    if not texto:
        return []
    palavras = texto.split(" ")
    linhas = []
    atual = ""
    for palavra in palavras:
        tentativa = f"{atual} {palavra}".strip()
        if stringWidth(tentativa, fonte, tamanho) <= largura_max:
            atual = tentativa
            continue
        if atual:
            linhas.append(atual)
        atual = palavra
        if len(linhas) >= max_linhas:
            break
    if atual and len(linhas) < max_linhas:
        linhas.append(atual)
    if len(linhas) == max_linhas and stringWidth(linhas[-1], fonte, tamanho) > largura_max:
        linha = linhas[-1]
        while linha and stringWidth(f"{linha}...", fonte, tamanho) > largura_max:
            linha = linha[:-1]
        linhas[-1] = f"{linha}..."
    return linhas


def _texto_item_avulso(valor):
    return re.sub(r"\s+", " ", str(valor or "")).strip()


def _normalizar_link_qrcode(valor):
    link = re.sub(r"\s+", "", str(valor or "").strip())
    if not link:
        raise ValueError("Informe o link para gerar o QR Code.")
    if len(link) > 2000:
        raise ValueError("O link informado e muito longo.")
    if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", link):
        link = f"https://{link}"
    return link


def _quebrar_texto_continuo_pdf(texto, fonte, tamanho, largura_max, max_linhas):
    texto = re.sub(r"\s+", " ", str(texto or "")).strip()
    if not texto:
        return []
    linhas = []
    atual = ""
    for char in texto:
        tentativa = f"{atual}{char}"
        if stringWidth(tentativa, fonte, tamanho) <= largura_max or not atual:
            atual = tentativa
            continue
        linhas.append(atual)
        atual = char
        if len(linhas) >= max_linhas:
            break
    if atual and len(linhas) < max_linhas:
        linhas.append(atual)
    if len(linhas) == max_linhas and sum(len(linha) for linha in linhas) < len(texto):
        linha = linhas[-1]
        while linha and stringWidth(f"{linha}...", fonte, tamanho) > largura_max:
            linha = linha[:-1]
        linhas[-1] = f"{linha}..."
    return linhas


def _fontes_etiqueta_avulsa():
    normal = "Helvetica"
    negrito = "Helvetica-Bold"
    try:
        arial = r"C:\Windows\Fonts\arial.ttf"
        arial_bold = r"C:\Windows\Fonts\arialbd.ttf"
        if os.path.exists(arial):
            if "JKArial" not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont("JKArial", arial))
            normal = "JKArial"
        if os.path.exists(arial_bold):
            if "JKArial-Bold" not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont("JKArial-Bold", arial_bold))
            negrito = "JKArial-Bold"
    except Exception:
        pass
    return normal, negrito


def _desenhar_texto_centralizado(c, texto, y, fonte="Helvetica", tamanho=28, largura=0, sublinhar=False):
    texto = str(texto or "")
    c.setFont(fonte, tamanho)
    x = largura / 2
    c.drawCentredString(x, y, texto)
    if sublinhar and texto:
        texto_w = stringWidth(texto, fonte, tamanho)
        c.setLineWidth(1.4)
        c.line(x - (texto_w / 2), y - 2, x + (texto_w / 2), y - 2)


def _gerar_pdf_impressao_avulsa_grande(itens):
    etiquetas = []
    for item in itens:
        dados = {
            "sequencia": _texto_item_avulso(item.sequencia),
            "sku": _texto_item_avulso(item.sku),
            "quantidade": _texto_item_avulso(item.quantidade),
            "caixa": _texto_item_avulso(item.caixa),
            "torre": _texto_item_avulso(item.torre),
            "paletes": _texto_item_avulso(item.paletes),
            "corredor": _texto_item_avulso(item.corredor),
            "conta": _texto_item_avulso(item.conta),
        }
        if any(dados.values()):
            etiquetas.append(dados)

    if not etiquetas:
        return None, 0
    if len(etiquetas) > 1000:
        raise ValueError("Limite mÃƒÂ¡ximo de 1000 etiquetas por PDF avulso.")

    page_w = 150 * mm
    page_h = 80 * mm
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=(page_w, page_h))
    fonte_normal, fonte_negrito = _fontes_etiqueta_avulsa()

    for idx, etiqueta in enumerate(etiquetas):
        if idx:
            c.showPage()

        sku = etiqueta["sku"]
        sequencia = etiqueta["sequencia"]
        quantidade = etiqueta["quantidade"]
        torre = etiqueta["torre"]
        paletes = etiqueta["paletes"]
        corredor = etiqueta["corredor"]
        caixa = etiqueta["caixa"]
        conta = etiqueta["conta"]

        _desenhar_texto_centralizado(c, f"SKU: {sku}" if sku else "SKU:", 63 * mm, fonte_negrito, 34, page_w)

        c.setFont(fonte_normal, 32)
        linha_y = 42 * mm
        x_seq = page_w * 0.34
        x_qtd = page_w * 0.64
        c.drawCentredString(x_seq, linha_y, sequencia)
        if sequencia:
            seq_w = stringWidth(sequencia, fonte_normal, 32)
            c.setLineWidth(1.4)
            c.line(x_seq - seq_w / 2, linha_y - 2, x_seq + seq_w / 2, linha_y - 2)
        c.drawCentredString(x_qtd, linha_y, f"QTD:{quantidade}" if quantidade else "QTD:")

        partes_local = []
        if torre:
            partes_local.append(f"T{torre}")
        if paletes:
            partes_local.append(f"P{paletes}")
        if corredor:
            partes_local.append(f"C{corredor}")
        if caixa:
            partes_local.append(f"CX{caixa}")
        _desenhar_texto_centralizado(c, " ".join(partes_local), 24 * mm, fonte_normal, 32, page_w)
        _desenhar_texto_centralizado(c, conta, 9 * mm, fonte_normal, 32, page_w)

    c.save()
    buffer.seek(0)
    return buffer.getvalue(), len(etiquetas)


def _gerar_pdf_impressao_avulsa_pequena(itens):
    etiquetas = []
    for item in itens:
        dados = {
            "sequencia": _texto_item_avulso(item.sequencia),
            "sku": _texto_item_avulso(item.sku),
            "quantidade": _texto_item_avulso(item.quantidade),
            "caixa": _texto_item_avulso(item.caixa),
            "torre": _texto_item_avulso(item.torre),
            "paletes": _texto_item_avulso(item.paletes),
            "corredor": _texto_item_avulso(item.corredor),
            "conta": _texto_item_avulso(item.conta),
        }
        if any(dados.values()):
            etiquetas.append(dados)

    if not etiquetas:
        return None, 0
    if len(etiquetas) > 1000:
        raise ValueError("Limite mÃƒÂ¡ximo de 1000 etiquetas por PDF avulso.")

    page_w = 80 * mm
    page_h = 25 * mm
    label_w = 40 * mm
    label_h = 25 * mm
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=(page_w, page_h))
    fonte_normal, fonte_negrito = _fontes_etiqueta_avulsa()

    def draw_center(texto, x0, y, fonte, tamanho):
        c.setFont(fonte, tamanho)
        c.drawCentredString(x0 + (label_w / 2), y, str(texto or ""))

    for idx, etiqueta in enumerate(etiquetas):
        pos = idx % 2
        if idx and pos == 0:
            c.showPage()
        x0 = pos * label_w

        c.setStrokeColorRGB(0.86, 0.86, 0.86)
        c.rect(x0, 0, label_w, label_h, stroke=1, fill=0)
        if pos == 0:
            c.setDash(1, 2)
            c.line(label_w, 0, label_w, page_h)
            c.setDash()

        sku = etiqueta["sku"]
        sequencia = etiqueta["sequencia"]
        quantidade = etiqueta["quantidade"]
        torre = etiqueta["torre"]
        paletes = etiqueta["paletes"]
        corredor = etiqueta["corredor"]
        caixa = etiqueta["caixa"]
        conta = etiqueta["conta"]

        # Mantem a mesma hierarquia visual da etiqueta grande, reduzida para 4 x 2,5 cm.
        draw_center(f"SKU: {sku}" if sku else "SKU:", x0, 18.9 * mm, fonte_negrito, 10.6)

        c.setFont(fonte_normal, 9.8)
        linha_y = 12.9 * mm
        x_seq = x0 + (label_w * 0.34)
        x_qtd = x0 + (label_w * 0.64)
        c.drawCentredString(x_seq, linha_y, sequencia)
        if sequencia:
            seq_w = stringWidth(sequencia, fonte_normal, 9.8)
            c.setLineWidth(0.5)
            c.line(x_seq - seq_w / 2, linha_y - 1, x_seq + seq_w / 2, linha_y - 1)
        c.drawCentredString(x_qtd, linha_y, f"QTD:{quantidade}" if quantidade else "QTD:")

        partes_local = []
        if torre:
            partes_local.append(f"T{torre}")
        if paletes:
            partes_local.append(f"P{paletes}")
        if corredor:
            partes_local.append(f"C{corredor}")
        if caixa:
            partes_local.append(f"CX{caixa}")
        draw_center(" ".join(partes_local), x0, 7.2 * mm, fonte_normal, 9.8)
        draw_center(conta, x0, 2.4 * mm, fonte_normal, 9.8)

    c.save()
    buffer.seek(0)
    return buffer.getvalue(), len(etiquetas)


def gerar_pdf_impressao_avulsa(itens, formato="grande"):
    formato = str(formato or "grande").strip().lower()
    usa_layout_planilha = any(bool(getattr(item, "layout_planilha", False)) for item in itens)
    if formato == "grande":
        return _gerar_pdf_impressao_avulsa_grande(itens)
    if formato == "pequena" or usa_layout_planilha:
        return _gerar_pdf_impressao_avulsa_pequena(itens)

    etiquetas = []
    for item in itens:
        sku = (item.sku or "").strip()
        descricao = (item.descricao or "").strip()
        quantidade = max(1, min(int(item.quantidade or 1), 500))
        if not sku and not descricao:
            continue
        etiquetas.extend([{"sku": sku, "descricao": descricao}] * quantidade)

    if not etiquetas:
        return None, 0
    if len(etiquetas) > 1000:
        raise ValueError("Limite mÃƒÂ¡ximo de 1000 etiquetas por PDF avulso.")

    formato = str(formato or "grande").strip().lower()
    if formato not in {"grande", "pequena"}:
        formato = "grande"

    etiqueta_w = 80 * mm
    etiqueta_h = 25 * mm if formato == "pequena" else 150 * mm
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=(etiqueta_w, etiqueta_h))

    for idx, etiqueta in enumerate(etiquetas):
        if idx:
            c.showPage()
        x = 0
        y = 0

        c.setStrokeColorRGB(0.80, 0.86, 0.92)
        c.roundRect(x, y, etiqueta_w, etiqueta_h, 4, stroke=1, fill=0)

        pad = 3 * mm if formato == "pequena" else 6 * mm
        text_x = x + pad
        top_y = y + etiqueta_h - pad
        largura_texto = etiqueta_w - (2 * pad)

        sku = etiqueta["sku"]
        descricao = etiqueta["descricao"]
        if sku:
            fonte_sku = 13 if formato == "pequena" else 18
            max_linhas_sku = 1 if formato == "pequena" else 3
            c.setFont("Helvetica-Bold", fonte_sku)
            for linha in _quebrar_texto_pdf(sku, "Helvetica-Bold", fonte_sku, largura_texto, max_linhas_sku):
                c.drawString(text_x, top_y, linha)
                top_y -= (5 * mm if formato == "pequena" else 8 * mm)

        if descricao:
            top_y -= 1 * mm
            fonte_desc = 8 if formato == "pequena" else 12
            max_linhas_desc = 2 if formato == "pequena" else 12
            c.setFont("Helvetica", fonte_desc)
            for linha in _quebrar_texto_pdf(descricao, "Helvetica", fonte_desc, largura_texto, max_linhas_desc):
                if top_y <= (5 * mm if formato == "pequena" else 12 * mm):
                    break
                c.drawString(text_x, top_y, linha)
                top_y -= (3.5 * mm if formato == "pequena" else 5.5 * mm)

        c.setFont("Helvetica", 6 if formato == "pequena" else 8)
        c.setFillColorRGB(0.45, 0.45, 0.45)
        c.drawRightString(x + etiqueta_w - pad, y + (2 * mm if formato == "pequena" else 4 * mm), f"#{idx + 1}")
        c.setFillColorRGB(0, 0, 0)

    c.save()
    buffer.seek(0)
    return buffer.getvalue(), len(etiquetas)


def gerar_pdf_editor_livre(etiquetas_html, tamanho="grande"):
    etiquetas = [str(html or "").strip() for html in etiquetas_html if str(html or "").strip()]
    if not etiquetas:
        return None, 0
    if len(etiquetas) > 100:
        raise ValueError("Limite mÃƒÂ¡ximo de 100 etiquetas livres por PDF.")

    tamanho = str(tamanho or "grande").strip().lower()
    tamanho = "pequena" if tamanho.startswith("p") else "grande"

    def _sanitize_editor_html(html):
        html = re.sub(r"<script[\s\S]*?</script>", "", html, flags=re.IGNORECASE)
        html = re.sub(r"\son\w+\s*=\s*(['\"]).*?\1", "", html, flags=re.IGNORECASE)
        return html

    fonte_normal, fonte_negrito = _fontes_etiqueta_avulsa()

    def _style_value_px(tag, prop, default_px):
        for node in [tag] + list(tag.find_all(True)):
            style = str(node.get("style") or "")
            match = re.search(rf"{prop}\s*:\s*([\d.]+)px", style, flags=re.IGNORECASE)
            if match:
                return max(6, min(96, float(match.group(1))))
        return default_px

    def _line_align(tag):
        style = str(tag.get("style") or "")
        match = re.search(r"text-align\s*:\s*(left|center|right)", style, flags=re.IGNORECASE)
        return (match.group(1).lower() if match else "center")

    def _draw_editor_label(c, html, x0, y0, w, h, scale=1.0):
        soup = BeautifulSoup(_sanitize_editor_html(html), "html.parser")
        linhas = [node for node in soup.find_all(["div", "p"], recursive=False)]
        if not linhas:
            linhas = [soup]

        css_w = 720.0
        css_h = 384.0
        css_padding = 18.0
        point_per_px = min(w / css_w, h / css_h)
        draw_w = css_w * point_per_px
        draw_h = css_h * point_per_px
        offset_x = (w - draw_w) / 2
        offset_y = (h - draw_h) / 2

        c.saveState()
        c.translate(x0, y0)
        c.scale(scale, scale)
        default_px = 36.0
        cursor_y_px = css_padding
        for idx, linha in enumerate(linhas[:40]):
            font_size_px = _style_value_px(linha, "font-size", default_px)
            line_height_px = max(font_size_px * 1.35, _style_value_px(linha, "line-height", font_size_px * 1.35))
            texto = linha.get_text(" ", strip=True)
            if not texto:
                cursor_y_px += line_height_px
                continue
            bold = bool(linha.find(["b", "strong"])) or "font-weight: bold" in str(linha).lower()
            underline = bool(linha.find("u")) or "text-decoration-line: underline" in str(linha).lower() or "text-decoration: underline" in str(linha).lower()
            font_name = fonte_negrito if bold else fonte_normal
            font_size = font_size_px * point_per_px
            baseline_px = cursor_y_px + ((line_height_px - font_size_px) / 2) + (font_size_px * 0.82)
            y = offset_y + draw_h - (baseline_px * point_per_px)
            align = _line_align(linha)
            c.setFont(font_name, font_size)
            text_w = stringWidth(texto, font_name, font_size)
            if align == "left":
                x = offset_x + (css_padding * point_per_px)
                c.drawString(x, y, texto)
            elif align == "right":
                x = offset_x + draw_w - (css_padding * point_per_px)
                c.drawRightString(x, y, texto)
                x = x - text_w
            else:
                x_center = offset_x + (draw_w / 2)
                c.drawCentredString(x_center, y, texto)
                x = x_center - (text_w / 2)
            if underline:
                c.setLineWidth(max(0.5, 1.2 * point_per_px))
                c.line(x, y - (3 * point_per_px), x + text_w, y - (3 * point_per_px))
            cursor_y_px += line_height_px
        c.restoreState()

    if tamanho == "pequena":
        page_w, page_h = 80 * mm, 25 * mm
        label_w, label_h = 40 * mm, 25 * mm
    else:
        page_w, page_h = 150 * mm, 80 * mm
        label_w, label_h = page_w, page_h

    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=(page_w, page_h))

    for idx, html in enumerate(etiquetas):
        if tamanho == "pequena":
            pos = idx % 2
            if idx and pos == 0:
                c.showPage()
            x0 = pos * label_w
            c.setStrokeColorRGB(0.86, 0.86, 0.86)
            c.rect(x0, 0, label_w, label_h, stroke=1, fill=0)
            if pos == 0:
                c.setDash(1, 2)
                c.line(label_w, 0, label_w, page_h)
                c.setDash()
            scale = min(label_w / (150 * mm), label_h / (80 * mm))
            _draw_editor_label(c, html, x0, 0, 150 * mm, 80 * mm, scale)
        else:
            if idx:
                c.showPage()
            _draw_editor_label(c, html, 0, 0, page_w, page_h, 1.0)

    c.save()
    buffer.seek(0)
    return buffer.getvalue(), len(etiquetas)


def _desenhar_qrcode_widget(c, link, x, y, tamanho):
    from reportlab.graphics import renderPDF
    from reportlab.graphics.barcode import qr
    from reportlab.graphics.shapes import Drawing

    qr_widget = qr.QrCodeWidget(link)
    bounds = qr_widget.getBounds()
    qr_w = bounds[2] - bounds[0]
    qr_h = bounds[3] - bounds[1]
    drawing = Drawing(tamanho, tamanho, transform=[tamanho / qr_w, 0, 0, tamanho / qr_h, 0, 0])
    drawing.add(qr_widget)
    renderPDF.draw(drawing, c, x, y)


def _desenhar_icone_celular_leitor(c, x, y, tamanho):
    largura = tamanho * 0.66
    altura = tamanho
    raio = min(1.5 * mm, tamanho * 0.18)
    brilho = tamanho * 0.08

    c.setStrokeColorRGB(0.16, 0.26, 0.40)
    c.setLineWidth(max(1.0, tamanho * 0.055))
    c.roundRect(x, y, largura, altura, raio, stroke=1, fill=0)

    c.setFillColorRGB(0.96, 0.99, 1.0)
    c.roundRect(
        x + brilho,
        y + brilho,
        largura - (2 * brilho),
        altura - (2 * brilho),
        raio / 1.5,
        stroke=0,
        fill=1,
    )

    c.setFillColorRGB(0.16, 0.26, 0.40)
    c.roundRect(
        x + brilho,
        y + brilho,
        largura - (2 * brilho),
        altura - (2 * brilho),
        raio / 1.5,
        stroke=0,
        fill=0,
    )

    c.setFillColorRGB(0.16, 0.26, 0.40)
    c.setLineWidth(max(0.8, tamanho * 0.038))
    c.circle(x + largura / 2, y + (altura * 0.5), tamanho * 0.08, stroke=1, fill=0)

    olho_x0 = x + (largura * 0.16)
    olho_x1 = x + (largura * 0.84)
    linha_y = y + (altura * 0.30)
    c.line(olho_x0, linha_y, olho_x1, linha_y)
    linha_y2 = y + (altura * 0.20)
    c.line(olho_x0 + (largura * 0.1), linha_y2, olho_x1 - (largura * 0.12), linha_y2)


def _desenhar_etiqueta_qrcode(c, link, titulo, x0, y0, label_w, label_h, idx, total, fonte_normal, fonte_negrito):
    c.saveState()
    c.translate(x0, y0)

    pequena = label_h <= 32 * mm
    pad = 2.5 * mm if pequena else 6 * mm
    raio = 3.5 if pequena else 7

    c.setFillColorRGB(1, 1, 1)
    if pequena:
        pad = 0.05 * mm
        qr_size = label_h - (2 * pad)
        qr_x = pad
        qr_y = (label_h - qr_size) / 2
        text_x = qr_x + qr_size + (0.8 * mm)
        text_w = label_w - text_x - pad

        _desenhar_qrcode_widget(c, link, qr_x, qr_y, qr_size)

        titulo_final = str(titulo or "").strip()
        y = label_h - pad - 3.2 * mm
        if titulo_final:
            c.setFillColorRGB(0.04, 0.12, 0.24)
            c.setFont(fonte_negrito, 7.2)
            for linha in _quebrar_texto_pdf(titulo_final, fonte_negrito, 7.2, text_w, 1):
                c.drawString(text_x, y, linha)
                y -= 3.6 * mm
            y -= 0.8 * mm
        c.setFillColorRGB(0.20, 0.25, 0.32)
        c.setFont(fonte_normal, 5.3)
        for linha in _quebrar_texto_continuo_pdf(link, fonte_normal, 5.3, text_w, 3):
            if y < pad:
                break
            c.drawString(text_x, y, linha)
            y -= 2.9 * mm
    else:
        qr_box = min(label_h - (2.2 * pad), label_w * 0.45)
        qr_x = pad
        qr_y = (label_h - qr_box) / 2
        qr_size = qr_box - (5 * mm)
        _desenhar_qrcode_widget(c, link, qr_x + 2.5 * mm, qr_y + 2.5 * mm, qr_size)

        text_x = qr_x + qr_box + 6 * mm
        text_w = label_w - text_x - pad
        if text_w > 20 * mm:
            icone_tamanho = 11 * mm
            icon_x = text_x
            icon_y = label_h - pad - icone_tamanho - 1 * mm
            _desenhar_icone_celular_leitor(c, icon_x, icon_y, icone_tamanho)
            text_x += icone_tamanho + 2.0 * mm
            text_w = text_w - (icone_tamanho + 2.0 * mm)
        y = label_h - pad - 10 * mm
        titulo_final = str(titulo or "").strip()
        if titulo_final:
            c.setFillColorRGB(0.04, 0.12, 0.24)
            c.setFont(fonte_negrito, 27)
            for linha in _quebrar_texto_pdf(titulo_final, fonte_negrito, 27, text_w, 2):
                c.drawString(text_x, y, linha)
                y -= 11 * mm
            y -= 4 * mm

        c.setFillColorRGB(0.20, 0.25, 0.32)
        c.setFont(fonte_normal, 14)
        for linha in _quebrar_texto_continuo_pdf(link, fonte_normal, 14, text_w, 4):
            if y < pad + 6 * mm:
                break
            c.drawString(text_x, y, linha)
            y -= 6.5 * mm

    c.setFillColorRGB(0, 0, 0)
    c.restoreState()


def _desenhar_qrcode_compacto(c, link, titulo, x0, y0, w, h, numero, total, fonte_normal, fonte_negrito):
    c.saveState()
    c.translate(x0, y0)
    pad = 2 * mm

    qr_size = min(w - (2 * pad), h - (20 * mm))
    qr_size = max(16 * mm, qr_size)
    qr_x = (w - qr_size) / 2
    qr_y = h - pad - qr_size

    _desenhar_qrcode_widget(c, link, qr_x, qr_y, qr_size)

    texto = str(titulo or "").strip()
    if texto:
        c.setFillColorRGB(0.04, 0.12, 0.24)
        fonte_titulo = 12
        icon_size = 8 * mm
        icon_gap = 2 * mm
        y = qr_y - 5.5 * mm
        linhas = _quebrar_texto_pdf(texto, fonte_negrito, fonte_titulo, w - (2 * pad) - icon_size - icon_gap, 2)
        largura_texto = max((c.stringWidth(linha, fonte_negrito, fonte_titulo) for linha in linhas), default=0)
        largura_total = icon_size + icon_gap + largura_texto
        start_x = max(pad, (w - largura_total) / 2)
        _desenhar_icone_celular_leitor(c, start_x, y - (icon_size * 0.45), icon_size)
        text_x = start_x + icon_size + icon_gap
        for linha in linhas:
            c.setFillColorRGB(0.04, 0.12, 0.24)
            c.setFont(fonte_negrito, fonte_titulo)
            c.drawString(text_x, y, linha)
            y -= 7 * mm
    c.setFillColorRGB(0, 0, 0)
    c.restoreState()


def _gerar_pdf_qrcode_grade_15x8(link, titulo, quantidade, fonte_normal, fonte_negrito):
    page_w, page_h = 150 * mm, 100 * mm
    margem = 5 * mm
    gap = 3 * mm
    max_por_etiqueta = 8
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=(page_w, page_h))

    for inicio in range(0, quantidade, max_por_etiqueta):
        if inicio:
            c.showPage()
        qtd_pagina = min(max_por_etiqueta, quantidade - inicio)
        if qtd_pagina <= 2:
            cols, rows = qtd_pagina, 1
        elif qtd_pagina <= 4:
            cols, rows = 2, 2
        elif qtd_pagina <= 6:
            cols, rows = 3, 2
        else:
            cols, rows = 4, 2

        area_x = margem
        area_y = margem
        area_w = page_w - (2 * margem)
        area_h = page_h - (2 * margem)
        cell_w = (area_w - ((cols - 1) * gap)) / cols
        cell_h = (area_h - ((rows - 1) * gap)) / rows

        for pos in range(qtd_pagina):
            row = pos // cols
            col = pos % cols
            x = area_x + (col * (cell_w + gap))
            y = area_y + ((rows - 1 - row) * (cell_h + gap))
            numero = inicio + pos + 1
            _desenhar_qrcode_compacto(c, link, titulo, x, y, cell_w, cell_h, numero, quantidade, fonte_normal, fonte_negrito)

    c.save()
    buffer.seek(0)
    return buffer.getvalue(), quantidade


def _desenhar_qrcode_mini(c, link, titulo, x0, y0, w, h, numero, total, fonte_normal, fonte_negrito):
    c.saveState()
    c.translate(x0, y0)
    pad = 0.05 * mm
    titulo_txt = str(titulo or "").strip()

    qr_size = min(h - (2 * pad), w * 0.82)
    qr_x = pad
    qr_y = (h - qr_size) / 2

    _desenhar_qrcode_widget(c, link, qr_x, qr_y, qr_size)

    text_x = qr_x + qr_size + (0.35 * mm)
    text_w = w - text_x - pad
    y = h - pad - 3.6 * mm
    c.setFillColorRGB(0.04, 0.12, 0.24)
    c.setFont(fonte_negrito, 5.0)
    texto_base = titulo_txt or "QR Code"
    for linha in _quebrar_texto_pdf(texto_base, fonte_negrito, 5.0, text_w, 3):
        if y < pad + 5 * mm:
            break
        c.drawString(text_x, y, linha)
        y -= 3 * mm

    c.setFillColorRGB(0.20, 0.25, 0.32)
    c.setFont(fonte_normal, 3.9)
    for linha in _quebrar_texto_continuo_pdf(link, fonte_normal, 3.9, text_w, 2):
        if y < pad + 2 * mm:
            break
        c.drawString(text_x, y, linha)
        y -= 2.2 * mm

    c.setFillColorRGB(0, 0, 0)
    c.restoreState()


def _gerar_pdf_qrcode_grade_pequena(link, titulo, quantidade, fonte_normal, fonte_negrito):
    page_w, page_h = 80 * mm, 25 * mm
    margem = 0.5 * mm
    gap = 1 * mm
    max_por_etiqueta = 2
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=(page_w, page_h))

    for inicio in range(0, quantidade, max_por_etiqueta):
        if inicio:
            c.showPage()
        qtd_pagina = min(max_por_etiqueta, quantidade - inicio)
        cols = max(1, qtd_pagina)
        cell_w = (page_w - (2 * margem) - ((cols - 1) * gap)) / cols
        cell_h = page_h - (2 * margem)

        for pos in range(qtd_pagina):
            x = margem + (pos * (cell_w + gap))
            y = margem
            numero = inicio + pos + 1
            _desenhar_qrcode_mini(c, link, titulo, x, y, cell_w, cell_h, numero, quantidade, fonte_normal, fonte_negrito)

    c.save()
    buffer.seek(0)
    return buffer.getvalue(), quantidade


def gerar_pdf_qrcode_link(link, titulo="", quantidade=1, tamanho="grande", layout="a4"):
    link_normalizado = _normalizar_link_qrcode(link)
    titulo = re.sub(r"\s+", " ", str(titulo or "").strip())[:120]
    quantidade = max(1, min(int(quantidade or 1), 500))
    tamanho = str(tamanho or "grande").strip().lower()
    tamanho = "pequena" if tamanho.startswith("p") else "grande"
    layout = str(layout or "a4").strip().lower()
    fonte_normal, fonte_negrito = _fontes_etiqueta_avulsa()

    if tamanho == "grande" and layout in {"grade_15x8", "15x8", "varios_15x8", "multiplos_15x8"}:
        return _gerar_pdf_qrcode_grade_15x8(link_normalizado, titulo, quantidade, fonte_normal, fonte_negrito)
    if tamanho == "pequena" and layout in {"grade_8x25", "8x25", "varios_8x25", "multiplos_8x25"}:
        return _gerar_pdf_qrcode_grade_pequena(link_normalizado, titulo, quantidade, fonte_normal, fonte_negrito)

    if tamanho == "pequena":
        label_w, label_h = 80 * mm, 25 * mm
    else:
        label_w, label_h = 150 * mm, 100 * mm

    usa_a4 = layout in {"a4", "folha", "folha_a4", "varias", "multipla", "multiplas"}
    if usa_a4:
        page_w, page_h = A4
        margem = 8 * mm
        gap = 3 * mm
        cols = max(1, int((page_w - (2 * margem) + gap) // (label_w + gap)))
        rows = max(1, int((page_h - (2 * margem) + gap) // (label_h + gap)))
        por_pagina = max(1, cols * rows)
        total_w = (cols * label_w) + ((cols - 1) * gap)
        total_h = (rows * label_h) + ((rows - 1) * gap)
        start_x = (page_w - total_w) / 2
        start_y = (page_h - total_h) / 2
    else:
        page_w, page_h = label_w, label_h
        cols = rows = por_pagina = 1
        gap = 0
        start_x = start_y = 0

    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=(page_w, page_h))

    for idx in range(quantidade):
        if idx and idx % por_pagina == 0:
            c.showPage()
        pos = idx % por_pagina
        row = pos // cols
        col = pos % cols
        x = start_x + (col * (label_w + gap))
        y = start_y + ((rows - 1 - row) * (label_h + gap))
        _desenhar_etiqueta_qrcode(
            c,
            link_normalizado,
            titulo,
            x,
            y,
            label_w,
            label_h,
            idx,
            quantidade,
            fonte_normal,
            fonte_negrito,
        )

    c.save()
    buffer.seek(0)
    return buffer.getvalue(), quantidade


