        bytes_nf = await file_nota_fiscal.read() if file_nota_fiscal else None
        
        out_etiquetas = None
        out_lista = None
        qtd = 0
        
        if store == "Mercado Livre":
            if not bytes_etiquetas:
                return {"success": False, "message": "Arquivo principal de etiquetas ÃƒÂ© obrigatÃƒÂ³rio para Mercado Livre."}
            out_etiquetas, qtd, out_lista = _processar_mercado_livre_backend(bytes_etiquetas)
        elif store == "Shopee":
            if not bytes_etiquetas:
                return {"success": False, "message": "Arquivo principal de etiquetas ÃƒÂ© obrigatÃƒÂ³rio para Shopee."}
            out_etiquetas, qtd, out_lista = _processar_shopee_backend(bytes_etiquetas)
        elif store == "TikTok":
            if not bytes_etiquetas:
                return {"success": False, "message": "Arquivo principal de etiquetas ÃƒÂ© obrigatÃƒÂ³rio para TikTok."}
            out_etiquetas, qtd, out_lista = _processar_tiktok_backend(bytes_etiquetas, bytes_lista)
        elif store == "Amazon":
            if not bytes_nf:
                return {"success": False, "message": "Para Amazon, o arquivo de Nota Fiscal ÃƒÂ© obrigatÃƒÂ³rio."}
            return {"success": False, "message": "Processamento Amazon ainda nao esta disponivel neste backend."}
        else:
            return {"success": False, "message": "Loja invÃƒÆ’Ã‚Â¡lida."}
            
        id_etiquetas = None
        id_lista = None
        
        if out_etiquetas:
            id_etiquetas = str(uuid.uuid4())
            TEMP_FILES_STORAGE[id_etiquetas] = out_etiquetas
            
        if out_lista:
            id_lista = str(uuid.uuid4())
            TEMP_FILES_STORAGE[id_lista] = out_lista
            
        return {"success": True, "qtd": qtd, "id_etiquetas": id_etiquetas, "id_lista": id_lista}
        
