def _pis_cofins_importacao_por_ncm(ncm: str, descricao: str = "") -> dict:
    ncm_norm = _normalizar_codigo_fiscal(ncm)
    override = ALIQUOTAS_IMPORTACAO_OVERRIDES.get(ncm_norm)
    if isinstance(override, dict):
        return {
            "pis": _to_float(override.get("pis"), 0.0),
            "cofins": _to_float(override.get("cofins"), 0.0),
            "fonte_pis": str(override.get("fonte_pis") or "CorreÃƒÂ§ÃƒÂ£o validada"),
            "fonte_cofins": str(override.get("fonte_cofins") or "CorreÃƒÂ§ÃƒÂ£o validada"),
            "observacao": str(override.get("observacao") or "CorreÃƒÂ§ÃƒÂ£o exata validada."),
            "regra": "override_exato",
        }
    autopeca_por_ncm = (
        ncm_norm in _PIS_COFINS_AUTOPECAS_NCM_EXATOS
        or any(ncm_norm.startswith(prefixo) for prefixo in _PIS_COFINS_AUTOPECAS_PREFIXOS_SEGUROS)
    )

    if autopeca_por_ncm:
        return {
            "pis": 3.12,
            "cofins": 14.37,
            "fonte_pis": "Lei 10.865/2004 art. 8Ã‚Âº, Ã‚Â§ 9Ã‚Âº-A Ã¢â‚¬â€ autopeÃƒÂ§as",
            "fonte_cofins": "Lei 10.865/2004 art. 8Ã‚Âº, Ã‚Â§ 9Ã‚Âº-A Ã¢â‚¬â€ autopeÃƒÂ§as",
            "observacao": (
                "Regra majorada de autopeÃƒÂ§as aplicada por NCM explÃƒÂ­cito/conservador para importador nÃ£o fabricante. "
                "Confirmar descriÃƒÂ§ÃƒÂ£o/destinaÃƒÂ§ÃƒÂ£o nos Anexos I/II da Lei 10.485/2002 e eventual adicional de COFINS."
            ),
            "regra": "autopecas_3_12_14_37",
        }

    return {
        "pis": 2.1,
        "cofins": 10.25,
        "fonte_pis": "Regra geral PIS-ImportaÃƒÂ§ÃƒÂ£o",
        "fonte_cofins": "Regra geral COFINS-ImportaÃƒÂ§ÃƒÂ£o 2026 Ã¢â‚¬â€ Siscomex ImportaÃƒÂ§ÃƒÂ£o nÃ‚Âº 025/2026",
        "observacao": "Regra geral 2026; confirmar exceÃƒÂ§ÃƒÂµes legais por NCM, destinaÃƒÂ§ÃƒÂ£o e perfil do importador.",
        "regra": "geral_2_10_10_25",
    }


def _aplicar_overrides_aliquotas_importacao(registro: dict) -> dict:
    ncm_norm = _normalizar_codigo_fiscal((registro or {}).get("ncm", ""))
    override = ALIQUOTAS_IMPORTACAO_OVERRIDES.get(ncm_norm)
    if not isinstance(override, dict):
        return registro

    saida = dict(registro or {})
    for chave in ("ii", "ipi", "pis", "cofins"):
        if chave in override:
            saida[chave] = _normalizar_aliquota_percentual(override.get(chave))
    if override.get("descricao"):
        saida["descricao"] = str(override.get("descricao") or "").strip()
    obs = str(saida.get("observacoes") or "").strip()
    obs_override = str(override.get("observacao") or "").strip()
    saida["observacoes"] = f"{obs} {obs_override}".strip()
    extras = dict(saida.get("dados_extras") or {})
    for chave in ("fonte_ii", "fonte_ipi", "fonte_pis", "fonte_cofins"):
        if override.get(chave):
            extras[chave] = str(override.get(chave) or "").strip()
    extras["override_exato"] = True
    extras["override_version"] = PIS_COFINS_IMPORTACAO_RULE_VERSION
    extras["pis_cofins_rule_version"] = PIS_COFINS_IMPORTACAO_RULE_VERSION
    saida["dados_extras"] = extras
    return saida


def _obter_aliquotas_importacao_atualizavel(client_id: str, ncm: str, *, forcar_atualizacao: bool = False) -> dict:
    ncm_norm = _normalizar_codigo_fiscal(ncm)
    if not ncm_norm or len(ncm_norm) != 8:
        raise HTTPException(status_code=400, detail="Informe um NCM com 8 dÃƒÂ­gitos.")
    if not forcar_atualizacao:
        local = _buscar_aliquotas_importacao_local(client_id, ncm_norm)
        if local:
            hoje = datetime.now().strftime("%Y-%m-%d")
            atualizado_hoje = str(local.get("updated_at") or "").startswith(hoje)
            extras = local.get("dados_extras") if isinstance(local.get("dados_extras"), dict) else {}
            ipi_oficial = "TIPI oficial" in str(extras.get("fonte_ipi") or "")
            pis_cofins_atual = str(extras.get("pis_cofins_rule_version") or "") == PIS_COFINS_IMPORTACAO_RULE_VERSION
            override = ALIQUOTAS_IMPORTACAO_OVERRIDES.get(ncm_norm)
            override_atual = not override or str(extras.get("override_version") or "") == PIS_COFINS_IMPORTACAO_RULE_VERSION
            if atualizado_hoje and ipi_oficial and pis_cofins_atual and override_atual:
                local["origem"] = "base_local"
                return local
    try:
        novo = _buscar_aliquotas_buscador_ncm(ncm_norm)
        ipi_oficial = _buscar_ipi_tipi_oficial_receita(ncm_norm)
        if ipi_oficial:
            novo["ipi"] = ipi_oficial["ipi"]
            if ipi_oficial.get("descricao"):
                novo["descricao"] = novo.get("descricao") or ipi_oficial["descricao"]
            extras = dict(novo.get("dados_extras") or {})
            extras["fonte_ipi"] = ipi_oficial["fonte"]
            extras["fonte_ipi_url"] = ipi_oficial["fonte_url"]
            extras["tipi_raw"] = ipi_oficial.get("raw", "")
            novo["dados_extras"] = extras
        novo = _aplicar_overrides_aliquotas_importacao(novo)
        salvo = _salvar_aliquotas_importacao_local(client_id, novo)
        registro = _row_aliquota_importacao_para_dict(salvo) or novo
        registro["origem"] = "fonte_gratuita_atualizada"
        return registro
    except Exception as e:
        logger.warning("[IMPOSTOS][ALIQUOTAS IMPORTAÃƒâ€¡ÃƒÆ’O] Falha ao atualizar NCM %s: %s", ncm_norm, e)
        local = _buscar_aliquotas_importacao_local(client_id, ncm_norm)
        if local:
            local["origem"] = "base_local_fallback"
            local["aviso_atualizacao"] = str(e)
            return local
        raise HTTPException(status_code=502, detail=f"NÃƒÂ£o foi possÃƒÂ­vel obter alÃƒÂ­quotas gratuitas para o NCM {ncm_norm}: {e}")


def _aliquotas_importacao_para_cards(registro: dict) -> dict:
    fonte = str((registro or {}).get("fonte") or "Base local de alÃƒÂ­quotas de importaÃƒÂ§ÃƒÂ£o")
    fonte_url = str((registro or {}).get("fonte_url") or "")
    extras = (registro or {}).get("dados_extras") if isinstance((registro or {}).get("dados_extras"), dict) else {}
    def _item(chave: str) -> dict:
        fonte_chave = str(extras.get(f"fonte_{chave}") or fonte)
        fonte_url_chave = str(extras.get(f"fonte_{chave}_url") or fonte_url)
        return {
            "percentual": _to_float((registro or {}).get(chave), 0.0),
            "fonte": fonte_chave,
            "fonte_url": fonte_url_chave,
            "origem": str((registro or {}).get("origem") or "base_local"),
            "erro": None,
        }
    return {
        "ii": _item("ii"),
        "ipi": _item("ipi"),
        "pis": _item("pis"),
        "cofins": _item("cofins"),
    }


def _to_float(valor, padrao: float = 0.0) -> float:
    txt = str(valor if valor is not None else "").strip()
    if not txt:
        return float(padrao)
    txt = txt.replace("R$", "").replace(" ", "")
    if "," in txt and "." in txt:
        txt = txt.replace(".", "").replace(",", ".")
    elif "," in txt:
        txt = txt.replace(",", ".")
    try:
        return float(txt)
    except Exception:
        return float(padrao)


def _normalizar_codigo_fiscal(valor: str) -> str:
    return re.sub(r"\D", "", str(valor or "").strip())


def _normalizar_regra_imposto(item: dict) -> dict:
    ncm = _normalizar_codigo_fiscal(item.get("ncm", ""))
    cest = _normalizar_codigo_fiscal(item.get("cest", ""))
    aliquota_federal = max(0.0, _to_float(item.get("aliquota_federal", 0.0)))
    aliquota_estadual = max(0.0, _to_float(item.get("aliquota_estadual", 0.0)))
    aliquota_municipal = max(0.0, _to_float(item.get("aliquota_municipal", 0.0)))
    return {
        "id": str(item.get("id") or uuid.uuid4().hex),
        "ncm": ncm,
        "cest": cest,
        "descricao": str(item.get("descricao") or "").strip(),
        "aliquota_federal": round(aliquota_federal, 4),
        "aliquota_estadual": round(aliquota_estadual, 4),
        "aliquota_municipal": round(aliquota_municipal, 4),
        "observacoes": str(item.get("observacoes") or "").strip(),
        "updated_at": str(item.get("updated_at") or datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
    }


def _aliquota_total_regra(regra: dict) -> float:
    return round(
        max(0.0, _to_float(regra.get("aliquota_federal", 0.0)))
        + max(0.0, _to_float(regra.get("aliquota_estadual", 0.0)))
        + max(0.0, _to_float(regra.get("aliquota_municipal", 0.0))),
        4,
    )


def _carregar_regras_impostos(client_id: str) -> list[dict]:
    arquivo = _arquivo_regras_impostos(client_id)
    if not os.path.exists(arquivo):
        return []
    try:
        with open(arquivo, "r", encoding="utf-8") as f:
            payload = json.load(f)
        if isinstance(payload, dict):
            payload = payload.get("regras", [])
        if not isinstance(payload, list):
            return []
        regras = [_normalizar_regra_imposto(item if isinstance(item, dict) else {}) for item in payload]
        regras.sort(key=lambda x: (x.get("ncm", ""), x.get("cest", ""), x.get("id", "")))
        return regras
    except Exception as e:
        logger.warning(f"[IMPOSTOS] Falha ao carregar regras do cliente {client_id}: {e}")
        return []


def _salvar_regras_impostos(client_id: str, regras: list[dict]) -> None:
    arquivo = _arquivo_regras_impostos(client_id)
    os.makedirs(os.path.dirname(arquivo), exist_ok=True)
    with open(arquivo, "w", encoding="utf-8") as f:
        json.dump(regras, f, ensure_ascii=False, indent=2)


def _arquivo_db_ncm_impostos(client_id: str) -> str:
    return os.path.join(get_tenant_path(client_id), "impostos_ncm.db")


def _conexao_db_ncm_impostos(client_id: str) -> sqlite3.Connection:
    db_path = _arquivo_db_ncm_impostos(client_id)
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS ncm_referencia (
            ncm TEXT PRIMARY KEY,
            ncm_original TEXT,
            descricao TEXT,
            descricao_completa TEXT,
            cest TEXT,
            ii REAL,
            ipi REAL,
            pis REAL,
            cofins REAL,
            dados_extras_json TEXT,
            fonte_arquivo TEXT,
            updated_at TEXT
        )
        """
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_ncm_referencia_cest ON ncm_referencia(cest)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_ncm_referencia_descricao ON ncm_referencia(descricao)")
    conn.commit()
    return conn


def _normalizar_coluna_ncm_excel(nome_coluna: Any) -> str:
    base = unicodedata.normalize("NFKD", str(nome_coluna or ""))
    base = "".join(ch for ch in base if not unicodedata.combining(ch))
    return re.sub(r"[^a-z0-9]+", "", base.lower())


def _normalizar_aliquota_percentual(valor: Any) -> float:
    txt = str(valor if valor is not None else "").strip()
    tem_percentual = "%" in txt
    if tem_percentual:
        txt = txt.replace("%", "")

    n = _to_float(txt, 0.0)

    # Sem sÃƒÂ­mbolo de percentual, valores fracionÃƒÂ¡rios sÃƒÂ£o tratados como proporÃƒÂ§ÃƒÂ£o.
    # Ex.: 0.0325 -> 3.25%
    if 0 < n <= 1:
        if not tem_percentual:
            n *= 100.0
    return round(max(0.0, n), 6)


def _ler_registros_ncm_excel(caminho_excel: str) -> list[dict]:
    if not caminho_excel or not os.path.exists(caminho_excel):
        raise HTTPException(status_code=404, detail="Arquivo NCM.xlsx nÃ£o encontrado na pasta do projeto.")

    try:
        df = pd.read_excel(caminho_excel, dtype=str)
    except Exception as e:
        logger.exception("[IMPOSTOS][NCM] Falha ao ler Excel de NCM: %s", e)
        raise HTTPException(status_code=400, detail="Falha ao ler o Excel de NCM.")

    if df.empty:
        return []

    # Algumas versÃƒÂµes do arquivo trazem uma linha repetindo os cabeÃƒÂ§alhos dentro dos dados.
    for col in ["NCM_Clean", "ncm_clean", "NCM", "ncm"]:
        if col in df.columns:
            serie = df[col].astype(str).str.strip()
            df = df[~serie.str.lower().isin({"ncm_clean", "ncm"})]
            break

    colunas = list(df.columns)
    mapa_colunas = {_normalizar_coluna_ncm_excel(c): c for c in colunas}

    col_ncm = mapa_colunas.get("ncmclean") or mapa_colunas.get("ncm")
    col_ncm_original = mapa_colunas.get("unnamed0") if "unnamed0" in mapa_colunas else None
    col_desc = mapa_colunas.get("descricao")
    col_desc_completa = mapa_colunas.get("descricaocompleta")
    col_cest = mapa_colunas.get("cest")
    col_ii = mapa_colunas.get("ii")
    col_ipi = mapa_colunas.get("ipi")
    col_pis = mapa_colunas.get("pis")
    col_cofins = mapa_colunas.get("cofins")

    if not col_ncm:
        raise HTTPException(status_code=400, detail="Excel NCM sem coluna NCM/NCM_Clean.")

    registros: list[dict] = []
    for _, row in df.iterrows():
        ncm = _normalizar_codigo_fiscal(row.get(col_ncm, ""))
        if not ncm:
            continue

        extras = {}
        for c in colunas:
            chave = _normalizar_coluna_ncm_excel(c)
            if chave.startswith("unnamed"):
                continue
            valor = row.get(c, "")
            txt = "" if pd.isna(valor) else str(valor).strip()
            if txt:
                extras[str(c)] = txt

        registros.append({
            "ncm": ncm,
            "ncm_original": str(row.get(col_ncm_original, "") or "").strip() if col_ncm_original else "",
            "descricao": str(row.get(col_desc, "") or "").strip() if col_desc else "",
            "descricao_completa": str(row.get(col_desc_completa, "") or "").strip() if col_desc_completa else "",
            "cest": _normalizar_codigo_fiscal(row.get(col_cest, "")) if col_cest else "",
            "ii": _normalizar_aliquota_percentual(row.get(col_ii, 0)) if col_ii else 0.0,
            "ipi": _normalizar_aliquota_percentual(row.get(col_ipi, 0)) if col_ipi else 0.0,
            "pis": _normalizar_aliquota_percentual(row.get(col_pis, 0)) if col_pis else 0.0,
            "cofins": _normalizar_aliquota_percentual(row.get(col_cofins, 0)) if col_cofins else 0.0,
            "dados_extras_json": json.dumps(extras, ensure_ascii=False),
        })

    return registros


def _importar_ncm_excel_para_db(client_id: str, caminho_excel: str) -> dict:
    registros = _ler_registros_ncm_excel(caminho_excel)
    if not registros:
        return {"importados": 0, "arquivo": os.path.basename(caminho_excel)}

    conn = _conexao_db_ncm_impostos(client_id)
    try:
        agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        payload = [
            (
                r["ncm"],
                r["ncm_original"],
                r["descricao"],
                r["descricao_completa"],
                r["cest"],
                r["ii"],
                r["ipi"],
                r["pis"],
                r["cofins"],
                r["dados_extras_json"],
                os.path.basename(caminho_excel),
                agora,
            )
            for r in registros
        ]
        conn.executemany(
            """
            INSERT OR REPLACE INTO ncm_referencia (
                ncm, ncm_original, descricao, descricao_completa, cest,
                ii, ipi, pis, cofins, dados_extras_json, fonte_arquivo, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            payload,
        )
        conn.commit()
        return {"importados": len(payload), "arquivo": os.path.basename(caminho_excel)}
    finally:
        conn.close()


def _garantir_base_ncm_populada(client_id: str) -> None:
    conn = _conexao_db_ncm_impostos(client_id)
    try:
        total = int(conn.execute("SELECT COUNT(1) FROM ncm_referencia").fetchone()[0] or 0)
    finally:
        conn.close()

    if total == 0 and os.path.exists(ARQUIVO_NCM_XLSX):
        try:
            _importar_ncm_excel_para_db(client_id, ARQUIVO_NCM_XLSX)
        except Exception as e:
            logger.warning("[IMPOSTOS][NCM] NÃƒÂ£o foi possÃƒÂ­vel autoimportar NCM.xlsx: %s", e)


def _buscar_ncm_referencia(client_id: str, ncm: str) -> dict | None:
    ncm_norm = _normalizar_codigo_fiscal(ncm)
    if not ncm_norm:
        return None

    _garantir_base_ncm_populada(client_id)
    conn = _conexao_db_ncm_impostos(client_id)
    try:
        row = conn.execute(
            """
            SELECT ncm, ncm_original, descricao, descricao_completa, cest,
                   ii, ipi, pis, cofins, dados_extras_json, fonte_arquivo, updated_at
            FROM ncm_referencia
            WHERE ncm = ?
            LIMIT 1
            """,
            (ncm_norm,),
        ).fetchone()
        if not row:
            return None

        extras = {}
        try:
            extras = json.loads(str(row["dados_extras_json"] or "{}"))
        except Exception:
            extras = {}

        return {
            "ncm": str(row["ncm"] or ""),
            "ncm_original": str(row["ncm_original"] or ""),
            "descricao": str(row["descricao"] or ""),
            "descricao_completa": str(row["descricao_completa"] or ""),
            "cest": str(row["cest"] or ""),
            "ii": float(row["ii"] or 0),
            "ipi": float(row["ipi"] or 0),
            "pis": float(row["pis"] or 0),
            "cofins": float(row["cofins"] or 0),
            "extras": extras,
            "fonte_arquivo": str(row["fonte_arquivo"] or ""),
            "updated_at": str(row["updated_at"] or ""),
        }
    finally:
        conn.close()


def _normalizar_valor_str_excel(valor: Any) -> str:
    if valor is None:
        return ""
    try:
        if pd.isna(valor):
            return ""
    except Exception:
        pass
    return str(valor).strip()


def _arquivo_db_convenio_mg(client_id: str) -> str:
    return os.path.join(get_tenant_path(client_id), "impostos_convenio_mg.db")


def _conexao_db_convenio_mg(client_id: str) -> sqlite3.Connection:
    db_path = _arquivo_db_convenio_mg(client_id)
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS convenio_mg_referencia (
            chave TEXT PRIMARY KEY,
            item TEXT,
            cest TEXT,
            cest_original TEXT,
            nbm_sh TEXT,
            nbm_sh_original TEXT,
            descricao TEXT,
            ambito_aplicacao TEXT,
            mva REAL,
            st_paraiba TEXT,
            st_minas TEXT,
            dados_extras_json TEXT,
            fonte_arquivo TEXT,
            updated_at TEXT
        )
        """
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_convenio_mg_cest ON convenio_mg_referencia(cest)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_convenio_mg_nbmsh ON convenio_mg_referencia(nbm_sh)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_convenio_mg_desc ON convenio_mg_referencia(descricao)")
    conn.commit()
    return conn


def _ler_registros_convenio_mg_excel(caminho_excel: str) -> list[dict]:
    if not caminho_excel or not os.path.exists(caminho_excel):
        raise HTTPException(status_code=404, detail="Arquivo NCM1.xlsx nÃ£o encontrado na pasta do projeto.")

    try:
        df = pd.read_excel(caminho_excel, dtype=str)
    except Exception as e:
        logger.exception("[IMPOSTOS][CONVENIO_MG] Falha ao ler Excel NCM1: %s", e)
        raise HTTPException(status_code=400, detail="Falha ao ler o Excel NCM1.")

    if df.empty:
        return []

    colunas = list(df.columns)
    mapa_colunas = {_normalizar_coluna_ncm_excel(c): c for c in colunas}

    col_item = mapa_colunas.get("item")
    col_cest = mapa_colunas.get("cest")
    col_nbm = mapa_colunas.get("nbmsh")
    col_desc = mapa_colunas.get("descricao")
    col_ambito = mapa_colunas.get("ambitodeaplicacao")
    col_mva = mapa_colunas.get("mva")
    col_st_pb = mapa_colunas.get("stparaiba")
    col_st_mg = mapa_colunas.get("stminas")

    if not col_cest:
        raise HTTPException(status_code=400, detail="Excel NCM1 sem coluna CEST.")

    registros: list[dict] = []
    for _, row in df.iterrows():
        cest_original = _normalizar_valor_str_excel(row.get(col_cest, ""))
        cest = _normalizar_codigo_fiscal(cest_original)
        if not cest:
            continue

        item = _normalizar_valor_str_excel(row.get(col_item, "")) if col_item else ""
        nbm_original = _normalizar_valor_str_excel(row.get(col_nbm, "")) if col_nbm else ""
        nbm_sh = _normalizar_codigo_fiscal(nbm_original)
        descricao = _normalizar_valor_str_excel(row.get(col_desc, "")) if col_desc else ""
        ambito_aplicacao = _normalizar_valor_str_excel(row.get(col_ambito, "")) if col_ambito else ""
        mva = _to_float(row.get(col_mva, 0), 0.0) if col_mva else 0.0
        st_paraiba = _normalizar_valor_str_excel(row.get(col_st_pb, "")) if col_st_pb else ""
        st_minas = _normalizar_valor_str_excel(row.get(col_st_mg, "")) if col_st_mg else ""

        chave = f"{item}|{cest}|{nbm_sh}|{descricao}".strip("|")

        extras = {}
        for c in colunas:
            chave_col = _normalizar_coluna_ncm_excel(c)
            if chave_col.startswith("unnamed"):
                continue
            val = _normalizar_valor_str_excel(row.get(c, ""))
            if val:
                extras[str(c)] = val

        registros.append({
            "chave": chave or uuid.uuid4().hex,
            "item": item,
            "cest": cest,
            "cest_original": cest_original,
            "nbm_sh": nbm_sh,
            "nbm_sh_original": nbm_original,
            "descricao": descricao,
            "ambito_aplicacao": ambito_aplicacao,
            "mva": round(max(0.0, mva), 6),
            "st_paraiba": st_paraiba,
            "st_minas": st_minas,
            "dados_extras_json": json.dumps(extras, ensure_ascii=False),
        })

    return registros


def _importar_convenio_mg_excel_para_db(client_id: str, caminho_excel: str) -> dict:
    registros = _ler_registros_convenio_mg_excel(caminho_excel)
